__bundle_register("Audio/AacPcmDecoder", function(require, _LOADED, __bundle_register, __bundle_modules)
-- AAC PCM decoder module.
local AacPcmDecoder = {}
local AdtsStream = {}
AdtsStream.__index = AdtsStream

---@module Audio.AacTables
local AacTables = require("Audio/AacTables")

-- Defaults.
local DefaultFrameLimit = math.huge

local ZeroHcb = 0
local NoiseHcb = 13
local IntensityHcbTwo = 14
local IntensityHcb = 15
local FrameLen = 1024
local SampleRate = 44100
local Channels = 2
local DefaultYieldAfterSeconds = 0.006
local DefaultYieldEveryFrames = 1


---Load table data.
---@return table
local function LoadTables()
	return AacTables
end

---Read unsigned 8-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU8(Data, Position)
	return Data:byte(Position, Position) or 0
end

---Create bit reader.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@return table
local function CreateBitReader(Data, StartPosition, EndPosition)
	return {
		Data = Data,
		BytePosition = StartPosition,
		BitPosition = 0,
		EndPosition = EndPosition,
	}
end

---Read bits.
---@param Reader table
---@param Count number
---@return number
local function ReadBits(Reader, Count)
	local Value = 0

	for BitIndex = 1, Count do
		if Reader.BytePosition > Reader.EndPosition then
			error("bitreader: out of bits")
		end

		local Byte = ReadU8(Reader.Data, Reader.BytePosition)
		local Bit = math.floor(Byte / (2 ^ (7 - Reader.BitPosition))) % 2
		Value = Value * 2 + Bit

		Reader.BitPosition = Reader.BitPosition + 1
		if Reader.BitPosition == 8 then
			Reader.BitPosition = 0
			Reader.BytePosition = Reader.BytePosition + 1
		end
	end

	return Value
end

---Read bit.
---@param Reader table
---@return boolean
local function ReadBit(Reader)
	return ReadBits(Reader, 1) == 1
end

---Build Huffman lookup.
---@param Codes table
---@param Bits table
---@return table
local function BuildLookup(Codes, Bits)
	local Lookup = {
		MaxBits = 0,
		Buckets = {},
	}

	for Index = 1, #Codes do
		local BitLength = Bits[Index]
		if BitLength > 0 then
			Lookup.MaxBits = math.max(Lookup.MaxBits, BitLength)
			Lookup.Buckets[BitLength] = Lookup.Buckets[BitLength] or {}
			Lookup.Buckets[BitLength][Codes[Index]] = Index - 1
		end
	end

	return Lookup
end

---Prepare lookups.
---@param Tables table
local function PrepareLookups(Tables)
	if Tables.__Prepared then return end

	for Index = 1, #Tables.SpectralBooks do
		local Book = Tables.SpectralBooks[Index]
		Book.Lookup = BuildLookup(Book.Codes, Book.Bits)
	end

	Tables.ScaleFactorLookup = BuildLookup(Tables.ScaleFactorCodes, Tables.ScaleFactorBits)
	Tables.__Prepared = true
end

---Decode Huffman index.
---@param Reader table
---@param Lookup table
---@return number
local function DecodeIndex(Reader, Lookup)
	local Accumulator = 0

	for BitLength = 1, Lookup.MaxBits do
		Accumulator = Accumulator * 2 + ReadBits(Reader, 1)

		local Bucket = Lookup.Buckets[BitLength]
		if Bucket then
			local Index = Bucket[Accumulator]
			if Index then
				return Index
			end
		end
	end

	error("aac huffman: code not found")
end

---Read escape amplitude.
---@param Reader table
---@return number
local function ReadEscape(Reader)
	local Prefix = 0

	while ReadBit(Reader) do
		Prefix = Prefix + 1
		if Prefix > 24 then
			error("aac huffman: escape prefix too long")
		end
	end

	return (2 ^ (Prefix + 4)) + ReadBits(Reader, Prefix + 4)
end

---Decode spectral values.
---@param Reader table
---@param Book table
---@return table
local function DecodeSpectral(Reader, Book)
	local SymbolIndex = DecodeIndex(Reader, Book.Lookup)
	local Dim = Book.Dim
	local Lav = Book.Lav
	local Output = { 0, 0, 0, 0 }

	if Book.Signed then
		local Modulo = Lav * 2 + 1

		for Index = Dim, 1, -1 do
			Output[Index] = (SymbolIndex % Modulo) - Lav
			SymbolIndex = math.floor(SymbolIndex / Modulo)
		end
	else
		local Modulo = Lav + 1

		for Index = Dim, 1, -1 do
			Output[Index] = SymbolIndex % Modulo
			SymbolIndex = math.floor(SymbolIndex / Modulo)
		end

		for Index = 1, Dim do
			if Output[Index] ~= 0 and ReadBit(Reader) then
				Output[Index] = -Output[Index]
			end
		end
	end

	if Book.Escape then
		for Index = 1, Dim do
			if math.abs(Output[Index]) == 16 then
				local Amplitude = ReadEscape(Reader)
				if Output[Index] < 0 then
					Output[Index] = -Amplitude
				else
					Output[Index] = Amplitude
				end
			end
		end
	end

	return Output
end

---Decode scalefactor delta.
---@param Reader table
---@param Tables table
---@return number
local function DecodeScaleFactorDelta(Reader, Tables)
	return DecodeIndex(Reader, Tables.ScaleFactorLookup) - 60
end

---Parse ADTS header.
---@param Data string
---@param Position number
---@return table
local function ParseAdtsHeader(Data, Position)
	local B1 = ReadU8(Data, Position)
	local B2 = ReadU8(Data, Position + 1)
	local B3 = ReadU8(Data, Position + 2)
	local B4 = ReadU8(Data, Position + 3)
	local B5 = ReadU8(Data, Position + 4)
	local B6 = ReadU8(Data, Position + 5)
	local B7 = ReadU8(Data, Position + 6)

	if B1 ~= 0xFF or math.floor(B2 / 16) ~= 0x0F then
		error("ADTS: missing syncword")
	end

	return {
		ObjectType = math.floor(B3 / 64) + 1,
		FrequencyIndex = math.floor((B3 % 64) / 4),
		ChannelConfig = (B3 % 4) * 4 + math.floor(B4 / 64),
		FrameLength = (B4 % 4) * 2048 + B5 * 8 + math.floor(B6 / 32),
		HeaderLength = (B2 % 2 == 1) and 7 or 9,
		RawBlocks = B7 % 4,
	}
end

---Parse ICS info.
---@param Reader table
---@param FrequencyIndex number
---@return table
local function ParseIcsInfo(Reader, FrequencyIndex)
	ReadBits(Reader, 1)

	local WindowSequence = ReadBits(Reader, 2)
	local WindowShape = ReadBits(Reader, 1)
	local Info = {
		WindowSequence = WindowSequence,
		WindowShape = WindowShape,
		FrequencyIndex = FrequencyIndex,
		WindowGroupLength = { 0, 0, 0, 0, 0, 0, 0, 0 },
	}

	if WindowSequence == 2 then
		Info.MaxSfb = ReadBits(Reader, 4)
		Info.ScaleFactorGrouping = ReadBits(Reader, 7)

		local Groups = 1
		local CurrentLength = 1

		for Window = 1, 7 do
			local Bit = math.floor(Info.ScaleFactorGrouping / (2 ^ (7 - Window))) % 2
			if Bit == 1 then
				CurrentLength = CurrentLength + 1
			else
				Info.WindowGroupLength[Groups] = CurrentLength
				Groups = Groups + 1
				CurrentLength = 1
			end
		end

		Info.WindowGroupLength[Groups] = CurrentLength
		Info.NumWindowGroups = Groups
	else
		Info.MaxSfb = ReadBits(Reader, 6)
		Info.PredictorDataPresent = ReadBit(Reader)
		if Info.PredictorDataPresent then
			error("AAC: predictor_data_present in LC stream")
		end

		Info.NumWindowGroups = 1
		Info.WindowGroupLength[1] = 1
	end

	return Info
end

---Parse section data.
---@param Reader table
---@param Info table
---@return table
local function ParseSectionData(Reader, Info)
	local MaxSfb = Info.MaxSfb
	local Groups = Info.NumWindowGroups
	local SectionEscapeValue = Info.WindowSequence == 2 and 7 or 31
	local SectionBits = Info.WindowSequence == 2 and 3 or 5
	local SfbCodebooks = {}

	for Group = 1, Groups do
		local Band = 1

		while Band <= MaxSfb do
			local Codebook = ReadBits(Reader, 4)
			local Length = 0

			while true do
				local Increment = ReadBits(Reader, SectionBits)
				Length = Length + Increment
				if Increment ~= SectionEscapeValue then
					break
				end
			end

			for SectionIndex = 1, Length do
				if Band > MaxSfb then
					error("AAC: section overruns max_sfb")
				end

				SfbCodebooks[(Group - 1) * MaxSfb + Band] = Codebook
				Band = Band + 1
			end
		end
	end

	return {
		SfbCodebooks = SfbCodebooks,
	}
end

---Parse scalefactors.
---@param Reader table
---@param Tables table
---@param Info table
---@param SectionData table
---@param GlobalGain number
---@return table
local function ParseScaleFactors(Reader, Tables, Info, SectionData, GlobalGain)
	local MaxSfb = Info.MaxSfb
	local Groups = Info.NumWindowGroups
	local ScaleFactors = {}
	local Gain = GlobalGain
	local NoiseGain = GlobalGain - 90
	local IntensityGain = 0
	local NoiseSeedSet = false

	for Group = 1, Groups do
		for Band = 1, MaxSfb do
			local Position = (Group - 1) * MaxSfb + Band
			local Codebook = SectionData.SfbCodebooks[Position]

			if Codebook == ZeroHcb then
				ScaleFactors[Position] = 0
			elseif Codebook == IntensityHcb or Codebook == IntensityHcbTwo then
				IntensityGain = IntensityGain + DecodeScaleFactorDelta(Reader, Tables)
				ScaleFactors[Position] = IntensityGain
			elseif Codebook == NoiseHcb then
				if not NoiseSeedSet then
					NoiseGain = NoiseGain + ReadBits(Reader, 9) - 256
					NoiseSeedSet = true
				else
					NoiseGain = NoiseGain + DecodeScaleFactorDelta(Reader, Tables)
				end

				ScaleFactors[Position] = NoiseGain
			else
				Gain = Gain + DecodeScaleFactorDelta(Reader, Tables)
				ScaleFactors[Position] = Gain
			end
		end
	end

	return ScaleFactors
end

---Inverse quantize.
---@param Value number
---@return number
local function InverseQuantize(Value)
	if Value == 0 then
		return 0
	end

	local Result = math.abs(Value) ^ (4 / 3)
	if Value < 0 then
		return -Result
	end

	return Result
end

---Convert scalefactor to gain.
---@param ScaleFactor number
---@return number
local function ScaleFactorToGain(ScaleFactor)
	return 2 ^ ((ScaleFactor - 100) / 4)
end

---Create zero vector.
---@param Length number
---@return table
local function ZeroVector(Length)
	local Values = {}

	for Index = 1, Length do
		Values[Index] = 0
	end

	return Values
end

---Decode long spectrum.
---@param Reader table
---@param Tables table
---@param Info table
---@param SectionData table
---@param ScaleFactors table
---@return table
local function DecodeSpectrumLong(Reader, Tables, Info, SectionData, ScaleFactors)
	local Spectrum = ZeroVector(FrameLen)
	local Swb = Tables.SwbLong[Info.FrequencyIndex + 1]

	for Band = 1, Info.MaxSfb do
		local Codebook = SectionData.SfbCodebooks[Band]
		local Start = Swb[Band] + 1
		local Stop = Swb[Band + 1]

		if Codebook ~= ZeroHcb and Codebook ~= NoiseHcb and Codebook ~= IntensityHcb and Codebook ~= IntensityHcbTwo then
			local Book = Tables.SpectralBooks[Codebook]
			if not Book then
				error("AAC: invalid spectral codebook")
			end

			local Gain = ScaleFactorToGain(ScaleFactors[Band])
			local Position = Start

			while Position <= Stop do
				local Values = DecodeSpectral(Reader, Book)
				for Offset = 1, Book.Dim do
					local Target = Position + Offset - 1
					if Target <= Stop then
						Spectrum[Target] = InverseQuantize(Values[Offset]) * Gain
					end
				end

				Position = Position + Book.Dim
			end
		end
	end

	return Spectrum
end

---Group starts.
---@param Info table
---@return table
local function GroupStarts(Info)
	local Starts = { 0 }
	local Sum = 0

	for Group = 1, Info.NumWindowGroups do
		Sum = Sum + Info.WindowGroupLength[Group]
		Starts[#Starts + 1] = Sum
	end

	return Starts
end

---Decode short spectrum.
---@param Reader table
---@param Tables table
---@param Info table
---@param SectionData table
---@param ScaleFactors table
---@return table
local function DecodeSpectrumShort(Reader, Tables, Info, SectionData, ScaleFactors)
	local Spectrum = ZeroVector(FrameLen)
	local Swb = Tables.SwbShort[Info.FrequencyIndex + 1]
	local Starts = GroupStarts(Info)

	for Group = 1, Info.NumWindowGroups do
		local GroupLength = Info.WindowGroupLength[Group]
		local WindowStartOffset = Starts[Group] * 128

		for Band = 1, Info.MaxSfb do
			local PositionIndex = (Group - 1) * Info.MaxSfb + Band
			local Codebook = SectionData.SfbCodebooks[PositionIndex]
			local BandStart = Swb[Band]
			local BandStop = Swb[Band + 1]
			local BandLength = BandStop - BandStart
			local Count = GroupLength * BandLength

			if Codebook ~= ZeroHcb and Codebook ~= NoiseHcb and Codebook ~= IntensityHcb and Codebook ~= IntensityHcbTwo then
				local Book = Tables.SpectralBooks[Codebook]
				if not Book then
					error("AAC: invalid spectral codebook")
				end

				local Gain = ScaleFactorToGain(ScaleFactors[PositionIndex])
				local Local = {}
				local Position = 1

				while Position <= Count do
					local Values = DecodeSpectral(Reader, Book)
					for Offset = 1, Book.Dim do
						local Target = Position + Offset - 1
						if Target <= Count then
							Local[Target] = InverseQuantize(Values[Offset]) * Gain
						end
					end

					Position = Position + Book.Dim
				end

				for Window = 0, GroupLength - 1 do
					for Offset = 0, BandLength - 1 do
						local Destination = WindowStartOffset + Window * 128 + BandStart + Offset + 1
						local Source = Window * BandLength + Offset + 1
						Spectrum[Destination] = Local[Source] or 0
					end
				end
			end
		end
	end

	return Spectrum
end

---Parse pulse data.
---@param Reader table
local function ParsePulseData(Reader)
	local PulseCount = ReadBits(Reader, 2) + 1
	ReadBits(Reader, 6)

	for PulseIndex = 1, PulseCount do
		ReadBits(Reader, 5)
		ReadBits(Reader, 4)
	end
end

---Parse TNS data.
---@param Reader table
---@param WindowSequence number
---@param NumWindows number
local function ParseTnsData(Reader, WindowSequence, NumWindows)
	local IsShort = WindowSequence == 2
	local FilterBits = IsShort and 1 or 2
	local LengthBits = IsShort and 4 or 6
	local OrderBits = IsShort and 3 or 5
	local MaxOrder = IsShort and 7 or 12

	for WindowIndex = 1, NumWindows do
		local FilterCount = ReadBits(Reader, FilterBits)
		if FilterCount > 0 then
			local CoefficientResolution = ReadBits(Reader, 1)

			for FilterIndex = 1, FilterCount do
				ReadBits(Reader, LengthBits)
				local Order = ReadBits(Reader, OrderBits)

				if Order > MaxOrder then
					error("AAC: TNS order exceeds max")
				end

				if Order > 0 then
					ReadBits(Reader, 1)
					local CoefficientCompress = ReadBits(Reader, 1)
					local CoefficientBits = 3 + CoefficientResolution - CoefficientCompress

					for CoefficientIndex = 1, Order do
						ReadBits(Reader, CoefficientBits)
					end
				end
			end
		end
	end
end

---Parse channel payload.
---@param Reader table
---@param Tables table
---@param Info table?
---@param FrequencyIndex number
---@return table
---@return table
---@return table
local function ParseChannelPayload(Reader, Tables, Info, FrequencyIndex)
	local GlobalGain = ReadBits(Reader, 8)
	Info = Info or ParseIcsInfo(Reader, FrequencyIndex)

	local SectionData = ParseSectionData(Reader, Info)
	local ScaleFactors = ParseScaleFactors(Reader, Tables, Info, SectionData, GlobalGain)

	local PulsePresent = ReadBit(Reader)
	if PulsePresent then
		ParsePulseData(Reader)
		error("AAC: pulse data is not implemented in PCM probe")
	end

	local TnsPresent = ReadBit(Reader)
	if TnsPresent then
		ParseTnsData(Reader, Info.WindowSequence, Info.WindowSequence == 2 and 8 or 1)
	end

	local GainControl = ReadBit(Reader)
	if GainControl then
		error("AAC: gain_control_data_present in LC stream")
	end

	if Info.WindowSequence == 2 then
		return DecodeSpectrumShort(Reader, Tables, Info, SectionData, ScaleFactors), SectionData, Info
	end

	return DecodeSpectrumLong(Reader, Tables, Info, SectionData, ScaleFactors), SectionData, Info
end

---Apply M/S stereo.
---@param Tables table
---@param Info table
---@param Sections table
---@param MsUsed table
---@param Spectra table
local function ApplyMsStereo(Tables, Info, Sections, MsUsed, Spectra)
	local MaxSfb = Info.MaxSfb

	if Info.WindowSequence ~= 2 then
		local Swb = Tables.SwbLong[Info.FrequencyIndex + 1]

		for Band = 1, MaxSfb do
			if MsUsed[Band] then
				local LeftCodebook = Sections[1].SfbCodebooks[Band]
				local RightCodebook = Sections[2].SfbCodebooks[Band]
				local Skip = RightCodebook == IntensityHcb
					or RightCodebook == IntensityHcbTwo
					or LeftCodebook == NoiseHcb
					or RightCodebook == NoiseHcb

				if not Skip then
					local Start = Swb[Band] + 1
					local Stop = Swb[Band + 1]

					for Index = Start, Stop do
						local Middle = Spectra[1][Index]
						local Side = Spectra[2][Index]
						Spectra[1][Index] = Middle + Side
						Spectra[2][Index] = Middle - Side
					end
				end
			end
		end

		return
	end

	local Swb = Tables.SwbShort[Info.FrequencyIndex + 1]
	local Starts = GroupStarts(Info)

	for Group = 1, Info.NumWindowGroups do
		local GroupStart = Starts[Group] * 128
		local GroupLength = Info.WindowGroupLength[Group]

		for Band = 1, MaxSfb do
			local PositionIndex = (Group - 1) * MaxSfb + Band
			if MsUsed[PositionIndex] then
				local LeftCodebook = Sections[1].SfbCodebooks[PositionIndex]
				local RightCodebook = Sections[2].SfbCodebooks[PositionIndex]
				local Skip = RightCodebook == IntensityHcb
					or RightCodebook == IntensityHcbTwo
					or LeftCodebook == NoiseHcb
					or RightCodebook == NoiseHcb

				if not Skip then
					local BandStart = Swb[Band]
					local BandStop = Swb[Band + 1]

					for Window = 0, GroupLength - 1 do
						local WindowOffset = GroupStart + Window * 128
						for Offset = BandStart, BandStop - 1 do
							local Index = WindowOffset + Offset + 1
							local Middle = Spectra[1][Index]
							local Side = Spectra[2][Index]
							Spectra[1][Index] = Middle + Side
							Spectra[2][Index] = Middle - Side
						end
					end
				end
			end
		end
	end
end

---Build sine window.
---@param Length number
---@return table
local function BuildSineWindow(Length)
	local Window = {}

	for Index = 0, Length - 1 do
		Window[Index + 1] = math.sin((math.pi / (2 * Length)) * (Index + 0.5))
	end

	return Window
end

---Bessel I0.
---@param Value number
---@return number
local function BesselI0(Value)
	local Sum = 1
	local Term = 1
	local K = 1

	while Term > 1e-15 * Sum do
		Term = Term * ((Value / (2 * K)) ^ 2)
		Sum = Sum + Term
		K = K + 1

		if K > 200 then
			break
		end
	end

	return Sum
end

---Build KBD window.
---@param Length number
---@param Alpha number
---@return table
local function BuildKbdWindow(Length, Alpha)
	local AlphaPi = Alpha * math.pi
	local Denominator = BesselI0(AlphaPi)
	local Kaiser = {}
	local Cumulative = {}
	local Accumulator = 0

	for Index = 0, Length do
		local T = (2 * Index / Length) - 1
		local Argument = AlphaPi * math.sqrt(1 - T * T)
		Kaiser[Index + 1] = BesselI0(Argument) / Denominator
		Accumulator = Accumulator + Kaiser[Index + 1]
		Cumulative[Index + 1] = Accumulator
	end

	local Window = {}
	local Total = Cumulative[Length + 1]
	for Index = 0, Length - 1 do
		Window[Index + 1] = math.sqrt(Cumulative[Index + 1] / Total)
	end

	return Window
end

local WindowCache = nil
local LongWindowFullCache = {}

---Get window cache.
---@return table
local function GetWindowCache()
	if WindowCache then
		return WindowCache
	end

	WindowCache = {
		Long = {
			[0] = BuildSineWindow(1024),
			[1] = BuildKbdWindow(1024, 4),
		},
		Short = {
			[0] = BuildSineWindow(128),
			[1] = BuildKbdWindow(128, 6),
		},
	}

	return WindowCache
end

---Build full long window.
---@param Sequence number
---@param Shape number
---@param PreviousShape number
---@return table
local function BuildLongWindowFull(Sequence, Shape, PreviousShape)
	local CacheKey = Sequence * 100 + Shape * 10 + PreviousShape
	local CachedWindow = LongWindowFullCache[CacheKey]
	if CachedWindow then
		return CachedWindow
	end

	local Cache = GetWindowCache()
	local Window = ZeroVector(2048)
	local PreviousWindow = Cache.Long[PreviousShape]
	local CurrentWindow = Cache.Long[Shape]

	if Sequence == 0 or Sequence == 2 then
		for Index = 1, 1024 do
			Window[Index] = PreviousWindow[Index]
			Window[1024 + Index] = CurrentWindow[1025 - Index]
		end
	elseif Sequence == 1 then
		local ShortWindow = Cache.Short[Shape]
		for Index = 1, 1024 do
			Window[Index] = PreviousWindow[Index]
		end
		for Index = 1, 448 do
			Window[1024 + Index] = 1
		end
		for Index = 1, 128 do
			Window[1024 + 448 + Index] = ShortWindow[129 - Index]
		end
	elseif Sequence == 3 then
		local ShortWindow = Cache.Short[PreviousShape]
		for Index = 1, 128 do
			Window[448 + Index] = ShortWindow[Index]
		end
		for Index = 577, 1024 do
			Window[Index] = 1
		end
		for Index = 1, 1024 do
			Window[1024 + Index] = CurrentWindow[1025 - Index]
		end
	end

	LongWindowFullCache[CacheKey] = Window
	return Window
end

---Create channel state.
---@return table
local function CreateChannelState()
	return {
		Previous = ZeroVector(FrameLen),
		PreviousShape = 0,
	}
end

local TransformCaches = {}

---Build bit-reversal table.
---@param Length number
---@return table
local function BuildBitReverse(Length)
	local Bits = 0
	local Size = Length

	while Size > 1 do
		Bits = Bits + 1
		Size = Size / 2
	end

	local Reverse = {}
	for Index = 0, Length - 1 do
		local Value = Index
		local Result = 0

		for BitIndex = 1, Bits do
			Result = Result * 2 + (Value % 2)
			Value = math.floor(Value / 2)
		end

		Reverse[Index + 1] = Result + 1
	end

	return Reverse
end

---Build transform cache.
---@param InputLength number
---@return table
local function BuildTransformCache(InputLength)
	local FftLength = InputLength * 2
	local Cache = {
		InputLength = InputLength,
		FftLength = FftLength,
		HalfLength = InputLength / 2,
		BitReverse = BuildBitReverse(FftLength),
		PreCos = {},
		PreSin = {},
		PostCos = {},
		PostSin = {},
		StageCos = {},
		StageSin = {},
	}

	for Index = 0, InputLength - 1 do
		local PreAngle = math.pi * Index / (2 * InputLength)
		local PostAngle = math.pi * (Index + 0.5) / (2 * InputLength)

		Cache.PreCos[Index + 1] = math.cos(PreAngle)
		Cache.PreSin[Index + 1] = math.sin(PreAngle)
		Cache.PostCos[Index + 1] = math.cos(PostAngle)
		Cache.PostSin[Index + 1] = math.sin(PostAngle)
	end

	local Stage = 1
	local Size = 2
	while Size <= FftLength do
		local Angle = 2 * math.pi / Size
		Cache.StageCos[Stage] = math.cos(Angle)
		Cache.StageSin[Stage] = math.sin(Angle)

		Stage = Stage + 1
		Size = Size * 2
	end

	return Cache
end

---Get transform cache.
---@param InputLength number
---@return table
local function GetTransformCache(InputLength)
	local Cache = TransformCaches[InputLength]
	if Cache then
		return Cache
	end

	Cache = BuildTransformCache(InputLength)
	TransformCaches[InputLength] = Cache
	return Cache
end

---Create transform work buffers.
---@param InputLength number
---@return table
local function CreateTransformWork(InputLength)
	local Cache = GetTransformCache(InputLength)
	local Real = {}
	local Imag = {}
	local Coefficients = {}

	for Index = 1, Cache.FftLength do
		Real[Index] = 0
		Imag[Index] = 0
	end

	for Index = 1, Cache.InputLength do
		Coefficients[Index] = 0
	end

	return {
		Cache = Cache,
		Real = Real,
		Imag = Imag,
		Coefficients = Coefficients,
	}
end

---Create transform state.
---@return table
local function CreateTransformState()
	return {
		Long = CreateTransformWork(FrameLen),
		Short = CreateTransformWork(128),
	}
end

---Run positive unscaled FFT.
---@param Work table
local function RunPositiveFft(Work)
	local Cache = Work.Cache
	local Real = Work.Real
	local Imag = Work.Imag
	local Reverse = Cache.BitReverse
	local FftLength = Cache.FftLength

	for Index = 1, FftLength do
		local ReverseIndex = Reverse[Index]
		if Index < ReverseIndex then
			Real[Index], Real[ReverseIndex] = Real[ReverseIndex], Real[Index]
			Imag[Index], Imag[ReverseIndex] = Imag[ReverseIndex], Imag[Index]
		end
	end

	local Stage = 1
	local Size = 2
	while Size <= FftLength do
		local HalfSize = Size / 2
		local StepCos = Cache.StageCos[Stage]
		local StepSin = Cache.StageSin[Stage]

		for Start = 1, FftLength, Size do
			local TwiddleReal = 1
			local TwiddleImag = 0

			for Offset = 0, HalfSize - 1 do
				local EvenIndex = Start + Offset
				local OddIndex = EvenIndex + HalfSize
				local OddReal = Real[OddIndex] * TwiddleReal - Imag[OddIndex] * TwiddleImag
				local OddImag = Real[OddIndex] * TwiddleImag + Imag[OddIndex] * TwiddleReal
				local EvenReal = Real[EvenIndex]
				local EvenImag = Imag[EvenIndex]

				Real[EvenIndex] = EvenReal + OddReal
				Imag[EvenIndex] = EvenImag + OddImag
				Real[OddIndex] = EvenReal - OddReal
				Imag[OddIndex] = EvenImag - OddImag

				local NextReal = TwiddleReal * StepCos - TwiddleImag * StepSin
				TwiddleImag = TwiddleReal * StepSin + TwiddleImag * StepCos
				TwiddleReal = NextReal
			end
		end

		Stage = Stage + 1
		Size = Size * 2
	end
end

---Run DCT-IV.
---@param Spectrum table
---@param Work table
---@return table
local function RunDctFour(Spectrum, Work)
	local Cache = Work.Cache
	local Real = Work.Real
	local Imag = Work.Imag
	local Coefficients = Work.Coefficients
	local InputLength = Cache.InputLength
	local FftLength = Cache.FftLength

	for Index = 1, InputLength do
		local Value = Spectrum[Index] or 0
		Real[Index] = Value * Cache.PreCos[Index]
		Imag[Index] = Value * Cache.PreSin[Index]
	end

	for Index = InputLength + 1, FftLength do
		Real[Index] = 0
		Imag[Index] = 0
	end

	RunPositiveFft(Work)

	for Index = 1, InputLength do
		Coefficients[Index] = Real[Index] * Cache.PostCos[Index] - Imag[Index] * Cache.PostSin[Index]
	end

	return Coefficients
end

---Run fast IMDCT.
---@param Spectrum table
---@param InputLength number
---@param TransformState table
---@return table
local function ImdctFast(Spectrum, InputLength, TransformState)
	local Work = InputLength == FrameLen and TransformState.Long or TransformState.Short
	local Coefficients = RunDctFour(Spectrum, Work)
	local Output = {}
	local HalfLength = InputLength / 2
	local Scale = 2 / InputLength

	for Index = 1, HalfLength do
		Output[Index] = Coefficients[HalfLength + Index] * Scale
	end

	for Index = HalfLength + 1, InputLength + HalfLength do
		Output[Index] = -Coefficients[InputLength - Index + HalfLength + 1] * Scale
	end

	for Index = InputLength + HalfLength + 1, InputLength * 2 do
		Output[Index] = -Coefficients[Index - InputLength - HalfLength] * Scale
	end

	return Output
end

---Check if spectrum is all zero.
---@param Spectrum table
---@return boolean
local function IsAllZero(Spectrum)
	for Index = 1, #Spectrum do
		if Spectrum[Index] ~= 0 then
			return false
		end
	end

	return true
end

---Synthesize one channel.
---@param Spectrum table
---@param Info table
---@param State table
---@param TransformState table
---@return table
local function SynthesizeChannel(Spectrum, Info, State, TransformState)
	local Pcm = {}

	if Info.WindowSequence ~= 2 then
		local Temp = IsAllZero(Spectrum) and ZeroVector(2048) or ImdctFast(Spectrum, 1024, TransformState)
		local Window = BuildLongWindowFull(Info.WindowSequence, Info.WindowShape, State.PreviousShape)

		for Index = 1, 2048 do
			Temp[Index] = Temp[Index] * Window[Index]
		end

		for Index = 1, 1024 do
			Pcm[Index] = State.Previous[Index] + Temp[Index]
			State.Previous[Index] = Temp[1024 + Index]
		end
	else
		local Cache = GetWindowCache()
		local Shorts = {}
		local CurrentShort = Cache.Short[Info.WindowShape]
		local PreviousShort = Cache.Short[State.PreviousShape]

		for Window = 0, 7 do
			local Chunk = {}
			for Index = 1, 128 do
				Chunk[Index] = Spectrum[Window * 128 + Index] or 0
			end

			Shorts[Window + 1] = IsAllZero(Chunk) and ZeroVector(256) or ImdctFast(Chunk, 128, TransformState)
		end

		for Index = 1, 128 do
			Shorts[1][Index] = Shorts[1][Index] * PreviousShort[Index]
			Shorts[1][128 + Index] = Shorts[1][128 + Index] * CurrentShort[129 - Index]
		end

		for Window = 2, 8 do
			for Index = 1, 128 do
				Shorts[Window][Index] = Shorts[Window][Index] * CurrentShort[Index]
				Shorts[Window][128 + Index] = Shorts[Window][128 + Index] * CurrentShort[129 - Index]
			end
		end

		for Index = 1, 448 do
			Pcm[Index] = State.Previous[Index]
		end

		for Index = 1, 128 do
			Pcm[448 + Index] = State.Previous[448 + Index] + Shorts[1][Index]
			Pcm[576 + Index] = Shorts[1][128 + Index] + Shorts[2][Index]
			Pcm[704 + Index] = Shorts[2][128 + Index] + Shorts[3][Index]
			Pcm[832 + Index] = Shorts[3][128 + Index] + Shorts[4][Index]
		end

		for Index = 1, 64 do
			Pcm[960 + Index] = Shorts[4][128 + Index]
		end

		for Index = 1, 64 do
			State.Previous[Index] = Shorts[4][192 + Index] + Shorts[5][Index]
		end
		for Index = 1, 128 do
			State.Previous[64 + Index] = Shorts[5][128 + Index] + Shorts[6][Index]
			State.Previous[192 + Index] = Shorts[6][128 + Index] + Shorts[7][Index]
			State.Previous[320 + Index] = Shorts[7][128 + Index] + Shorts[8][Index]
			State.Previous[448 + Index] = Shorts[8][128 + Index]
		end
		for Index = 577, 1024 do
			State.Previous[Index] = 0
		end
	end

	State.PreviousShape = Info.WindowShape
	return Pcm
end

---Skip fill element.
---@param Reader table
local function SkipFillElement(Reader)
	local Count = ReadBits(Reader, 4)
	if Count == 15 then
		Count = 14 + ReadBits(Reader, 8)
	end

	for ByteIndex = 1, Count do
		ReadBits(Reader, 8)
	end
end

---Decode raw data block.
---@param Reader table
---@param Tables table
---@param Header table
---@param States table
---@param TransformState table
---@return table?
local function DecodeRawDataBlock(Reader, Tables, Header, States, TransformState)
	while true do
		local ElementId = ReadBits(Reader, 3)

		if ElementId == 1 then
			ReadBits(Reader, 4)

			local CommonWindow = ReadBit(Reader)
			local Spectra = {}
			local Sections = {}
			local Infos = {}

			if CommonWindow then
				local Info = ParseIcsInfo(Reader, Header.FrequencyIndex)
				local MsMaskPresent = ReadBits(Reader, 2)
				local MsBands = Info.NumWindowGroups * Info.MaxSfb
				local MsUsed = {}

				if MsMaskPresent == 1 then
					for Band = 1, MsBands do
						MsUsed[Band] = ReadBit(Reader)
					end
				elseif MsMaskPresent == 2 then
					for Band = 1, MsBands do
						MsUsed[Band] = true
					end
				elseif MsMaskPresent == 3 then
					error("AAC: reserved ms_mask_present=3")
				end

				Spectra[1], Sections[1], Infos[1] = ParseChannelPayload(Reader, Tables, Info, Header.FrequencyIndex)
				Spectra[2], Sections[2], Infos[2] = ParseChannelPayload(Reader, Tables, Info, Header.FrequencyIndex)
				ApplyMsStereo(Tables, Info, Sections, MsUsed, Spectra)
			else
				Spectra[1], Sections[1], Infos[1] = ParseChannelPayload(Reader, Tables, nil, Header.FrequencyIndex)
				Spectra[2], Sections[2], Infos[2] = ParseChannelPayload(Reader, Tables, nil, Header.FrequencyIndex)
			end


			return {
				SynthesizeChannel(Spectra[1], Infos[1], States[1], TransformState),
				SynthesizeChannel(Spectra[2], Infos[2], States[2], TransformState),
			}
		elseif ElementId == 6 then
			SkipFillElement(Reader)
		elseif ElementId == 7 then
			break
		else
			error("AAC: unsupported element id " .. tostring(ElementId))
		end
	end

	return nil
end

---Write unsigned 16-bit integer.
---@param Value number
---@return string
local function WriteU16(Value)
	local Lo = Value % 256
	local Hi = math.floor(Value / 256) % 256
	return string.char(Lo, Hi)
end

---Write unsigned 32-bit integer.
---@param Value number
---@return string
local function WriteU32(Value)
	local B1 = Value % 256
	local B2 = math.floor(Value / 256) % 256
	local B3 = math.floor(Value / 65536) % 256
	local B4 = math.floor(Value / 16777216) % 256
	return string.char(B1, B2, B3, B4)
end

---Round sample.
---@param Value number
---@return number
local function RoundSample(Value)
	if Value >= 0 then
		return math.floor(Value + 0.5)
	end

	return math.ceil(Value - 0.5)
end

---Clamp sample.
---@param Value number
---@return number
local function ClampSample(Value)
	local Sample = RoundSample(Value * 0.5)

	if Sample > 32767 then
		Sample = 32767
	elseif Sample < -32768 then
		Sample = -32768
	end

	return Sample
end

---Build WAV header.
---@param DataBytes number
---@return string
local function BuildWavHeader(DataBytes)
	local Chunks = {}

	Chunks[#Chunks + 1] = "RIFF"
	Chunks[#Chunks + 1] = WriteU32(36 + DataBytes)
	Chunks[#Chunks + 1] = "WAVEfmt "
	Chunks[#Chunks + 1] = WriteU32(16)
	Chunks[#Chunks + 1] = WriteU16(1)
	Chunks[#Chunks + 1] = WriteU16(Channels)
	Chunks[#Chunks + 1] = WriteU32(SampleRate)
	Chunks[#Chunks + 1] = WriteU32(SampleRate * Channels * 2)
	Chunks[#Chunks + 1] = WriteU16(Channels * 2)
	Chunks[#Chunks + 1] = WriteU16(16)
	Chunks[#Chunks + 1] = "data"
	Chunks[#Chunks + 1] = WriteU32(DataBytes)

	return table.concat(Chunks)
end

---Build frame PCM body.
---@param LeftSamples table
---@param RightSamples table
---@return string
---@return number
---@return number
local function BuildFramePcm(LeftSamples, RightSamples)
	local Chunks = {}
	local Sum = 0
	local Count = 0

	for Index = 1, FrameLen do
		local LeftSample = ClampSample(LeftSamples[Index] or 0)
		local RightSample = ClampSample(RightSamples[Index] or 0)
		local Left = LeftSample < 0 and LeftSample + 65536 or LeftSample
		local Right = RightSample < 0 and RightSample + 65536 or RightSample

		Chunks[#Chunks + 1] = string.char(
			Left % 256,
			math.floor(Left / 256) % 256,
			Right % 256,
			math.floor(Right / 256) % 256
		)

		Sum = Sum + LeftSample * LeftSample + RightSample * RightSample
		Count = Count + 2
	end

	return table.concat(Chunks), Sum, Count
end

---Build WAV.
---@param FrameChunks table
---@param FrameCount number
---@return string
local function BuildWav(FrameChunks, FrameCount)
	local DataBytes = FrameCount * FrameLen * Channels * 2
	local Chunks = {
		BuildWavHeader(DataBytes),
		table.concat(FrameChunks),
	}

	return table.concat(Chunks)
end

---Validate an ADTS header.
---@param Header table
---@return boolean
---@return string?
local function ValidateAdtsHeader(Header)
	if Header.ObjectType ~= 2 then
		return false, string.format("Unsupported AAC object type %s. Only AAC-LC is supported.", tostring(Header.ObjectType))
	end

	if Header.FrequencyIndex ~= 4 or Header.ChannelConfig ~= 2 then
		return false, "Unsupported AAC stream. Only 44.1 kHz stereo AAC-LC is supported."
	end

	if Header.RawBlocks ~= 0 then
		return false, "Unsupported AAC stream. Multiple raw blocks per ADTS frame are not supported."
	end

	return true, nil
end

---Build segment decode options.
---@param Self table
---@param Options table?
---@return number
---@return number
local function BuildSegmentDecodeOptions(Self, Options)
	Options = Options or {}

	local YieldAfterSeconds = Options.YieldAfterSeconds
	if YieldAfterSeconds == nil then
		YieldAfterSeconds = Self.YieldAfterSeconds
	end

	local YieldEveryFrames = Options.YieldEveryFrames
	if YieldEveryFrames == nil then
		YieldEveryFrames = Self.YieldEveryFrames
	end

	YieldAfterSeconds = tonumber(YieldAfterSeconds) or DefaultYieldAfterSeconds
	YieldEveryFrames = tonumber(YieldEveryFrames) or DefaultYieldEveryFrames

	if YieldAfterSeconds < 0 then
		YieldAfterSeconds = 0
	end

	if YieldEveryFrames < 1 then
		YieldEveryFrames = 1
	else
		YieldEveryFrames = math.floor(YieldEveryFrames)
	end

	return YieldAfterSeconds, YieldEveryFrames
end

---Yield during segment decode if needed.
---@param YieldAfterSeconds number
---@param LastYieldAt number
---@return number
local function YieldSegmentDecode(YieldAfterSeconds, LastYieldAt)
	if YieldAfterSeconds <= 0 then
		return LastYieldAt
	end

	if os.clock() - LastYieldAt < YieldAfterSeconds then
		return LastYieldAt
	end

	task.wait()
	return os.clock()
end

---Read a WAV segment from the stream.
---@param FrameLimit number?
---@param Options table?
---@return boolean
---@return table|string
function AdtsStream:ReadSegment(FrameLimit, Options)
	FrameLimit = tonumber(FrameLimit) or DefaultFrameLimit
	if FrameLimit <= 0 then
		FrameLimit = DefaultFrameLimit
	elseif FrameLimit ~= DefaultFrameLimit then
		FrameLimit = math.floor(FrameLimit)
	end

	local YieldAfterSeconds, YieldEveryFrames = BuildSegmentDecodeOptions(self, Options)
	local FrameCount = 0
	local FrameChunks = {}
	local RmsSum = 0
	local RmsCount = 0
	local StartFrame = self.FrameCount + 1
	local DecodeStartedAt = os.clock()
	local LastYieldAt = DecodeStartedAt
	local FramesSinceYield = 0

	while self.Position + 6 <= #self.Body and FrameCount < FrameLimit do
		local HeaderOk, Header = pcall(ParseAdtsHeader, self.Body, self.Position)
		if not HeaderOk then
			return false, tostring(Header)
		end

		local ValidHeader, HeaderErr = ValidateAdtsHeader(Header)
		if not ValidHeader then
			return false, HeaderErr
		end

		local PayloadStart = self.Position + Header.HeaderLength
		local PayloadEnd = self.Position + Header.FrameLength - 1

		if PayloadEnd > #self.Body then
			self.Done = true
			break
		end

		local Reader = CreateBitReader(self.Body, PayloadStart, PayloadEnd)
		local DecodeOk, Pcm = pcall(DecodeRawDataBlock, Reader, self.Tables, Header, self.States, self.TransformState)
		if not DecodeOk then
			return false, tostring(Pcm)
		end

		if Pcm then
			local FrameBody, FrameSum, FrameRmsCount = BuildFramePcm(Pcm[1], Pcm[2])
			FrameChunks[#FrameChunks + 1] = FrameBody
			RmsSum = RmsSum + FrameSum
			RmsCount = RmsCount + FrameRmsCount
			FrameCount = FrameCount + 1
			self.FrameCount = self.FrameCount + 1
			FramesSinceYield = FramesSinceYield + 1
		end

		self.Position = self.Position + Header.FrameLength

		if FramesSinceYield >= YieldEveryFrames then
			LastYieldAt = YieldSegmentDecode(YieldAfterSeconds, LastYieldAt)
			FramesSinceYield = 0
		end
	end

	if self.Position + 6 > #self.Body then
		self.Done = true
	end

	local DecodeSeconds = os.clock() - DecodeStartedAt
	local WavStartedAt = os.clock()
	local WavBody = BuildWav(FrameChunks, FrameCount)
	local WavSeconds = os.clock() - WavStartedAt
	local SamplesPerChannel = FrameCount * FrameLen
	local Rms = RmsCount > 0 and math.sqrt(RmsSum / RmsCount) or 0

	return true, {
		Frames = FrameCount,
		Bytes = #self.Body,
		WavBody = WavBody,
		WavBytes = #WavBody,
		SampleRate = SampleRate,
		Channels = Channels,
		SamplesPerChannel = SamplesPerChannel,
		Duration = SamplesPerChannel / SampleRate,
		Rms = Rms,
		DecodeSeconds = DecodeSeconds,
		WavSeconds = WavSeconds,
		StartFrame = StartFrame,
		EndFrame = self.FrameCount,
		Done = self.Done,
	}
end

---Create an ADTS stream decoder.
---@param Body string
---@return boolean
---@return table|string
function AacPcmDecoder.CreateAdtsStream(Body)
	local Tables = LoadTables()
	PrepareLookups(Tables)

	if type(Body) ~= "string" or Body == "" then
		return false, "Missing AAC body."
	end

	return true, setmetatable({
		Body = Body,
		Position = 1,
		FrameCount = 0,
		Done = false,
		Tables = Tables,
		States = { CreateChannelState(), CreateChannelState() },
		TransformState = CreateTransformState(),
	}, AdtsStream)
end

---Decode ADTS to WAV.
---@param Body string
---@param Options table?
---@return boolean
---@return table|string
function AacPcmDecoder.DecodeAdts(Body, Options)
	Options = Options or {}
	local FrameLimit = tonumber(Options.FrameLimit) or DefaultFrameLimit
	local StreamOk, Stream = AacPcmDecoder.CreateAdtsStream(Body)
	if not StreamOk then
		return false, Stream
	end

	return Stream:ReadSegment(FrameLimit, Options)
end

-- Return AAC PCM decoder module.
return AacPcmDecoder
end)
