	[13] = {
		0, 4, 8, 12, 16, 20, 24, 28, 36, 44, 52, 60, 72, 88, 108, 128,
},
}

-- Return AAC table data.
return AacTables
end)
__bundle_register("Audio/Mp4Aac", function(require, _LOADED, __bundle_register, __bundle_modules)
-- MP4 AAC remux module.
local Mp4Aac = {}

---Read an unsigned 8-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU8(Data, Position)
	return Data:byte(Position, Position) or 0
end

---Read an unsigned 16-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU16(Data, Position)
	local A, B = Data:byte(Position, Position + 1)
	return (A or 0) * 256 + (B or 0)
end

---Read an unsigned 24-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU24(Data, Position)
	local A, B, C = Data:byte(Position, Position + 2)
	return (A or 0) * 65536 + (B or 0) * 256 + (C or 0)
end

---Read an unsigned 32-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU32(Data, Position)
	local A, B, C, D = Data:byte(Position, Position + 3)
	return (A or 0) * 16777216 + (B or 0) * 65536 + (C or 0) * 256 + (D or 0)
end

---Read an unsigned 64-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU64(Data, Position)
	return ReadU32(Data, Position) * 4294967296 + ReadU32(Data, Position + 4)
end

---Read string.
---@param Data string
---@param Position number
---@param Length number
---@return string
local function ReadString(Data, Position, Length)
	return Data:sub(Position, Position + Length - 1)
end

---Read descriptor size.
---@param Data string
---@param Position number
---@return number
---@return number
local function ReadDescriptorSize(Data, Position)
	local Size = 0
	local Count = 0

	for Index = 1, 4 do
		local Byte = ReadU8(Data, Position)
		Position = Position + 1
		Count = Count + 1
		Size = Size * 128 + (Byte % 128)

		if Byte < 128 then
			break
		end
	end

	return Size, Count
end

---Decode AAC audio specific config.
---@param Bytes string
---@return table
local function DecodeAudioSpecificConfig(Bytes)
	local First = ReadU8(Bytes, 1)
	local Second = ReadU8(Bytes, 2)
	local ObjectType = math.floor(First / 8)
	local FrequencyIndex = ((First % 8) * 2) + math.floor(Second / 128)
	local ChannelConfig = math.floor((Second % 128) / 8)
	local Rates = {
		96000,
		88200,
		64000,
		48000,
		44100,
		32000,
		24000,
		22050,
		16000,
		12000,
		11025,
		8000,
		7350,
	}

	return {
		ObjectType = ObjectType,
		FrequencyIndex = FrequencyIndex,
		SampleRate = Rates[FrequencyIndex + 1] or 0,
		ChannelConfig = ChannelConfig,
		Hex = Bytes:gsub(".", function(Char)
			return string.format("%02X", Char:byte())
		end),
	}
end

---Check a fullbox flag.
---@param Flags number
---@param Flag number
---@return boolean
local function HasFlag(Flags, Flag)
	return math.floor(Flags / Flag) % 2 == 1
end

---Write ADTS header.
---@param PayloadLength number
---@param FrequencyIndex number
---@param ChannelConfig number
---@return string
local function WriteAdtsHeader(PayloadLength, FrequencyIndex, ChannelConfig)
	local FrameLength = PayloadLength + 7
	local Profile = 1

	local ByteThree = Profile * 64 + FrequencyIndex * 4 + math.floor(ChannelConfig / 4)
	local ByteFour = (ChannelConfig % 4) * 64 + math.floor(FrameLength / 2048)
	local ByteFive = math.floor(FrameLength / 8) % 256
	local ByteSix = (FrameLength % 8) * 32 + 31

	return string.char(0xFF, 0xF1, ByteThree, ByteFour, ByteFive, ByteSix, 0xFC)
end

---Parse ESDS descriptors.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseDescriptors(Data, StartPosition, EndPosition, State)
	local Position = StartPosition

	while Position + 1 <= EndPosition do
		local Tag = ReadU8(Data, Position)
		Position = Position + 1

		local Size, SizeBytes = ReadDescriptorSize(Data, Position)
		Position = Position + SizeBytes

		local DescriptorEnd = Position + Size - 1
		if DescriptorEnd > EndPosition then
			return
		end

		if Tag == 0x03 then
			local Flags = ReadU8(Data, Position + 2)
			local ChildPosition = Position + 3

			if math.floor(Flags / 128) % 2 == 1 then
				ChildPosition = ChildPosition + 2
			end

			if math.floor(Flags / 64) % 2 == 1 then
				ChildPosition = ChildPosition + ReadU8(Data, ChildPosition) + 1
			end

			if math.floor(Flags / 32) % 2 == 1 then
				ChildPosition = ChildPosition + 2
			end

			ParseDescriptors(Data, ChildPosition, DescriptorEnd, State)
		elseif Tag == 0x04 then
			State.ObjectTypeIndication = ReadU8(Data, Position)
			State.StreamType = math.floor(ReadU8(Data, Position + 1) / 4)
			State.BufferSizeDb = ReadU24(Data, Position + 2)
			State.MaxBitrate = ReadU32(Data, Position + 5)
			State.AvgBitrate = ReadU32(Data, Position + 9)
			ParseDescriptors(Data, Position + 13, DescriptorEnd, State)
		elseif Tag == 0x05 then
			local ConfigBytes = ReadString(Data, Position, Size)
			State.AudioSpecificConfig = DecodeAudioSpecificConfig(ConfigBytes)
		end

		Position = DescriptorEnd + 1
	end
end

---Parse ESDS box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseEsds(Data, StartPosition, EndPosition, State)
	ParseDescriptors(Data, StartPosition + 4, EndPosition, State)
end

---Parse MP4A sample entry.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseMp4a(Data, StartPosition, EndPosition, State)
	State.ChannelCount = ReadU16(Data, StartPosition + 16)
	State.SampleSizeBits = ReadU16(Data, StartPosition + 18)
	State.SampleRateFixed = ReadU32(Data, StartPosition + 24)
	State.SampleRate = math.floor(State.SampleRateFixed / 65536)

	local Position = StartPosition + 28
	while Position + 8 <= EndPosition do
		local Size = ReadU32(Data, Position)
		local BoxType = ReadString(Data, Position + 4, 4)
		if Size < 8 then return end

		local BoxEnd = Position + Size - 1
		if BoxEnd > EndPosition then return end

		if BoxType == "esds" then
			ParseEsds(Data, Position + 8, BoxEnd, State)
		end

		Position = BoxEnd + 1
	end
end

---Parse STSD box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseStsd(Data, StartPosition, EndPosition, State)
	local EntryCount = ReadU32(Data, StartPosition + 4)
	local Position = StartPosition + 8
	State.SampleDescriptions = EntryCount

	for Index = 1, EntryCount do
		if Position + 8 > EndPosition then return end

		local Size = ReadU32(Data, Position)
		local BoxType = ReadString(Data, Position + 4, 4)
		local BoxEnd = Position + Size - 1
		if Size < 8 or BoxEnd > EndPosition then return end

		if BoxType == "mp4a" then
			State.Codec = "mp4a"
			ParseMp4a(Data, Position + 8, BoxEnd, State)
		end

		Position = BoxEnd + 1
	end
end

---Parse STSZ box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseStsz(Data, StartPosition, EndPosition, State)
	local SampleSize = ReadU32(Data, StartPosition + 4)
	local SampleCount = ReadU32(Data, StartPosition + 8)
	local Sizes = {}
	State.SampleSize = SampleSize
	State.SampleCount = SampleCount

	if SampleSize ~= 0 then
		for Index = 1, SampleCount do
			Sizes[Index] = SampleSize
		end
	else
		local Position = StartPosition + 12
		for Index = 1, SampleCount do
			if Position + 4 > EndPosition then break end
			Sizes[Index] = ReadU32(Data, Position)
			Position = Position + 4
		end
	end

	State.SampleSizes = Sizes
end

---Parse STCO box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseStco(Data, StartPosition, EndPosition, State)
	local Count = ReadU32(Data, StartPosition + 4)
	local Offsets = {}
	local Position = StartPosition + 8

	for Index = 1, Count do
		if Position + 4 > EndPosition then break end
		Offsets[Index] = ReadU32(Data, Position)
		Position = Position + 4
	end

	State.ChunkOffsets = Offsets
end

---Parse CO64 box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseCo64(Data, StartPosition, EndPosition, State)
	local Count = ReadU32(Data, StartPosition + 4)
	local Offsets = {}
	local Position = StartPosition + 8

	for Index = 1, Count do
		if Position + 8 > EndPosition then break end
		Offsets[Index] = ReadU64(Data, Position)
		Position = Position + 8
	end

	State.ChunkOffsets = Offsets
end

---Parse STSC box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseStsc(Data, StartPosition, EndPosition, State)
	local Count = ReadU32(Data, StartPosition + 4)
	local Entries = {}
	local Position = StartPosition + 8

	for Index = 1, Count do
		if Position + 12 > EndPosition then break end
		Entries[Index] = {
			FirstChunk = ReadU32(Data, Position),
			SamplesPerChunk = ReadU32(Data, Position + 4),
			SampleDescriptionIndex = ReadU32(Data, Position + 8),
		}
		Position = Position + 12
	end

	State.SampleToChunk = Entries
end

---Parse STTS box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseStts(Data, StartPosition, EndPosition, State)
	local Count = ReadU32(Data, StartPosition + 4)
	local Entries = {}
	local Position = StartPosition + 8

	for Index = 1, Count do
		if Position + 8 > EndPosition then break end
		Entries[Index] = {
			SampleCount = ReadU32(Data, Position),
			SampleDelta = ReadU32(Data, Position + 4),
		}
		Position = Position + 8
	end

	State.TimeToSample = Entries
end

---Parse MDHD box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseMdhd(Data, StartPosition, EndPosition, State)
	local Version = ReadU8(Data, StartPosition)
	if Version == 1 then
		State.MediaTimescale = ReadU32(Data, StartPosition + 20)
		State.MediaDuration = ReadU64(Data, StartPosition + 24)
	else
		State.MediaTimescale = ReadU32(Data, StartPosition + 12)
		State.MediaDuration = ReadU32(Data, StartPosition + 16)
	end
end

---Parse HDLR box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseHdlr(Data, StartPosition, EndPosition, State)
	if StartPosition + 12 <= EndPosition then
		local HandlerType = ReadString(Data, StartPosition + 8, 4)
		if HandlerType == "soun" then
			State.HandlerType = HandlerType
		elseif not State.HandlerType then
			State.HandlerType = HandlerType
		end
	end
end

---Parse TFHD box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseTfhd(Data, StartPosition, EndPosition, State)
	local Flags = ReadU24(Data, StartPosition + 1)
	local Position = StartPosition + 8
	local Fragment = {
		TrackId = ReadU32(Data, StartPosition + 4),
		Flags = Flags,
		BaseDataOffset = nil,
		DefaultSampleDuration = nil,
		DefaultSampleSize = nil,
		DefaultSampleFlags = nil,
	}

	if HasFlag(Flags, 0x000001) and Position + 8 <= EndPosition then
		Fragment.BaseDataOffset = ReadU64(Data, Position)
		Position = Position + 8
	end

	if HasFlag(Flags, 0x000002) and Position + 4 <= EndPosition then
		Fragment.SampleDescriptionIndex = ReadU32(Data, Position)
		Position = Position + 4
	end

	if HasFlag(Flags, 0x000008) and Position + 4 <= EndPosition then
		Fragment.DefaultSampleDuration = ReadU32(Data, Position)
		Position = Position + 4
	end

	if HasFlag(Flags, 0x000010) and Position + 4 <= EndPosition then
		Fragment.DefaultSampleSize = ReadU32(Data, Position)
		Position = Position + 4
	end

	if HasFlag(Flags, 0x000020) and Position + 4 <= EndPosition then
		Fragment.DefaultSampleFlags = ReadU32(Data, Position)
		Position = Position + 4
	end

	State.CurrentFragment = Fragment
	State.Fragments[#State.Fragments + 1] = Fragment
end

---Parse TFDT box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseTfdt(Data, StartPosition, EndPosition, State)
	if not State.CurrentFragment then return end

	local Version = ReadU8(Data, StartPosition)
	if Version == 1 and StartPosition + 12 <= EndPosition then
		State.CurrentFragment.BaseMediaDecodeTime = ReadU64(Data, StartPosition + 4)
	elseif StartPosition + 8 <= EndPosition then
		State.CurrentFragment.BaseMediaDecodeTime = ReadU32(Data, StartPosition + 4)
	end
end

---Parse TRUN box.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param State table
local function ParseTrun(Data, StartPosition, EndPosition, State)
	local Fragment = State.CurrentFragment
	if not Fragment then return end

	local Version = ReadU8(Data, StartPosition)
	local Flags = ReadU24(Data, StartPosition + 1)
	local SampleCount = ReadU32(Data, StartPosition + 4)
	local Position = StartPosition + 8
	local DataOffset = nil

	if HasFlag(Flags, 0x000001) and Position + 3 <= EndPosition then
		DataOffset = ReadU32(Data, Position)
		Position = Position + 4
	end

	if HasFlag(Flags, 0x000004) and Position + 3 <= EndPosition then
		Fragment.FirstSampleFlags = ReadU32(Data, Position)
		Position = Position + 4
	end

	local DataStart = nil
	if DataOffset then
		if Fragment.BaseDataOffset then
			DataStart = Fragment.BaseDataOffset + 1 + DataOffset
		elseif State.CurrentMoofStart then
			DataStart = State.CurrentMoofStart + DataOffset
		end
	end

	local Cursor = DataStart
	local Samples = {}

	for SampleIndex = 1, SampleCount do
		local Duration = Fragment.DefaultSampleDuration or 0
		local Size = Fragment.DefaultSampleSize or 0

		if HasFlag(Flags, 0x000100) and Position + 3 <= EndPosition then
			Duration = ReadU32(Data, Position)
			Position = Position + 4
		end

		if HasFlag(Flags, 0x000200) and Position + 3 <= EndPosition then
			Size = ReadU32(Data, Position)
			Position = Position + 4
		end

		if HasFlag(Flags, 0x000400) and Position + 3 <= EndPosition then
			Position = Position + 4
		end

		if HasFlag(Flags, 0x000800) and Position + 3 <= EndPosition then
			if Version == 1 then
				-- Signed value is not needed for audio sample boundaries.
				Position = Position + 4
			else
				Position = Position + 4
			end
		end

		Samples[SampleIndex] = {
			Duration = Duration,
			Size = Size,
			Offset = Cursor,
		}

		if Cursor and Size then
			if #State.FirstFragmentSamples < 12 then
				State.FirstFragmentSamples[#State.FirstFragmentSamples + 1] = {
					Index = State.FragmentSampleCount + SampleIndex,
					Offset = Cursor,
					Size = Size,
					Duration = Duration,
				}
			end

			Cursor = Cursor + Size
		end
	end

	Fragment.Truns = Fragment.Truns or {}
	Fragment.Truns[#Fragment.Truns + 1] = {
		Flags = Flags,
		SampleCount = SampleCount,
		DataOffset = DataOffset,
		DataStart = DataStart,
		Samples = Samples,
	}

	State.FragmentSampleCount = State.FragmentSampleCount + SampleCount
end

---Check if box is a container.
---@param BoxType string
---@return boolean
local function IsContainer(BoxType)
	return BoxType == "moov"
		or BoxType == "moof"
		or BoxType == "trak"
		or BoxType == "traf"
		or BoxType == "mdia"
		or BoxType == "minf"
		or BoxType == "stbl"
		or BoxType == "dinf"
		or BoxType == "edts"
		or BoxType == "udta"
end

---Parse MP4 boxes.
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param Path string
---@param State table
local function ParseBoxes(Data, StartPosition, EndPosition, Path, State)
	local Position = StartPosition

	while Position + 8 <= EndPosition do
		local Size = ReadU32(Data, Position)
		local BoxType = ReadString(Data, Position + 4, 4)
		local HeaderSize = 8

		if Size == 1 then
			Size = ReadU64(Data, Position + 8)
			HeaderSize = 16
		elseif Size == 0 then
			Size = EndPosition - Position + 1
		end

		if Size < HeaderSize then
			return
		end

		local BoxStart = Position + HeaderSize
		local BoxEnd = Position + Size - 1
		if BoxEnd > EndPosition then
			return
		end

		State.Boxes[#State.Boxes + 1] = {
			Path = Path .. "/" .. BoxType,
			Type = BoxType,
			Offset = Position,
			Size = Size,
		}

		if BoxType == "stsd" then
			ParseStsd(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "stsz" then
			ParseStsz(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "stco" then
			ParseStco(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "co64" then
			ParseCo64(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "stsc" then
			ParseStsc(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "stts" then
			ParseStts(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "mdhd" then
			ParseMdhd(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "hdlr" then
			ParseHdlr(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "tfhd" then
			ParseTfhd(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "tfdt" then
			ParseTfdt(Data, BoxStart, BoxEnd, State)
		elseif BoxType == "trun" then
			ParseTrun(Data, BoxStart, BoxEnd, State)
		elseif IsContainer(BoxType) then
			local PreviousMoofStart = State.CurrentMoofStart
			local PreviousFragment = State.CurrentFragment
			if BoxType == "moof" then
				State.CurrentMoofStart = Position
				State.CurrentFragment = nil
			elseif BoxType == "traf" then
				State.CurrentFragment = nil
			end

			ParseBoxes(Data, BoxStart, BoxEnd, Path .. "/" .. BoxType, State)

			if BoxType == "moof" then
				State.CurrentMoofStart = PreviousMoofStart
				State.CurrentFragment = PreviousFragment
			elseif BoxType == "traf" then
				State.CurrentFragment = PreviousFragment
			end
		elseif BoxType == "meta" then
			ParseBoxes(Data, BoxStart + 4, BoxEnd, Path .. "/" .. BoxType, State)
		end

		Position = BoxEnd + 1
	end
end

---Get sample-to-chunk entry.
---@param Entries table
---@param ChunkIndex number
---@return table?
local function GetSampleToChunkEntry(Entries, ChunkIndex)
	local Found = nil

	for Index = 1, #Entries do
		local Entry = Entries[Index]
		local NextEntry = Entries[Index + 1]

		if ChunkIndex >= Entry.FirstChunk and (not NextEntry or ChunkIndex < NextEntry.FirstChunk) then
			Found = Entry
			break
		end
	end

	return Found
end

---Build sample boundaries.
---@param State table
local function BuildSampleBoundaries(State)
	local Sizes = State.SampleSizes or {}
	local Offsets = State.ChunkOffsets or {}
	local Entries = State.SampleToChunk or {}
	local Boundaries = {}
	local SampleIndex = 1

	for ChunkIndex = 1, #Offsets do
		local Entry = GetSampleToChunkEntry(Entries, ChunkIndex)
		if not Entry then break end

		local Cursor = Offsets[ChunkIndex] + 1
		for LocalSampleIndex = 1, Entry.SamplesPerChunk do
			local Size = Sizes[SampleIndex]
			if not Size then break end

			if #Boundaries < 12 then
				Boundaries[#Boundaries + 1] = {
					Index = SampleIndex,
					Offset = Cursor,
					Size = Size,
					Chunk = ChunkIndex,
				}
			end

			Cursor = Cursor + Size
			SampleIndex = SampleIndex + 1
		end
	end

	State.FirstSamples = Boundaries
	State.BoundarySampleCount = SampleIndex - 1
end

---Build ADTS body.
---@param State table
---@param Data string
---@return string?
---@return number
local function BuildAdtsBody(State, Data)
	local Config = State.AudioSpecificConfig
	if not Config then
		return nil, 0
	end

	local Chunks = {}
	local Count = 0

	for FragmentIndex = 1, #State.Fragments do
		local Fragment = State.Fragments[FragmentIndex]
		local Truns = Fragment.Truns or {}

		for TrunIndex = 1, #Truns do
			local Trun = Truns[TrunIndex]
			local Samples = Trun.Samples or {}

			for SampleIndex = 1, #Samples do
				local Sample = Samples[SampleIndex]
				if Sample.Offset and Sample.Size and Sample.Size > 0 then
					Chunks[#Chunks + 1] = WriteAdtsHeader(Sample.Size, Config.FrequencyIndex, Config.ChannelConfig)
					Chunks[#Chunks + 1] = Data:sub(Sample.Offset, Sample.Offset + Sample.Size - 1)
					Count = Count + 1
				end
			end
		end
	end

	return table.concat(Chunks), Count
end


---Build ADTS from M4A data.
---@param Data string
---@return boolean
---@return table|string
function Mp4Aac.BuildAdts(Data)
	if type(Data) ~= "string" or Data == "" then
		return false, "Missing M4A body."
	end

	local State = {
		Boxes = {},
		Fragments = {},
		FirstFragmentSamples = {},
		FragmentSampleCount = 0,
	}

	local ParseStartedAt = os.clock()
	ParseBoxes(Data, 1, #Data, "", State)
	BuildSampleBoundaries(State)
	local ParseSeconds = os.clock() - ParseStartedAt

	local AdtsStartedAt = os.clock()
	local AdtsBody, AdtsSamples = BuildAdtsBody(State, Data)
	local AdtsSeconds = os.clock() - AdtsStartedAt

	if not AdtsBody or AdtsSamples <= 0 then
		return false, "Could not extract AAC samples from M4A."
	end

	return true, {
		AdtsBody = AdtsBody,
		AdtsBytes = #AdtsBody,
		AdtsSamples = AdtsSamples,
		ParseSeconds = ParseSeconds,
		AdtsBuildSeconds = AdtsSeconds,
		BoxCount = #State.Boxes,
		Codec = State.Codec,
		HandlerType = State.HandlerType,
		ChannelCount = State.ChannelCount,
		SampleRate = State.SampleRate,
		AudioSpecificConfig = State.AudioSpecificConfig,
		FragmentCount = State.Fragments and #State.Fragments or 0,
		FragmentSampleCount = State.FragmentSampleCount,
	}
end

-- Return MP4 AAC remux module.
return Mp4Aac
end)
__bundle_register("Audio/Music/SnoozeMusic", function(require, _LOADED, __bundle_register, __bundle_modules)
return ""
end)
__bundle_register("Audio/MusicResolver", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Music resolver module.
local MusicResolver = {}
local YoutubeStream = {}
YoutubeStream.__index = YoutubeStream

---@module Audio.YoutubeExtractor
local YoutubeExtractor = require("Audio/YoutubeExtractor")

---@module Audio.Mp4Aac
local Mp4Aac = require("Audio/Mp4Aac")

---@module Audio.AacPcmDecoder
local AacPcmDecoder = require("Audio/AacPcmDecoder")

---@module Audio.OpusPcmDecoder
local OpusPcmDecoder = require("Audio/OpusPcmDecoder")

---@module Audio.WebmOpus
local WebmOpus = require("Audio/WebmOpus")

-- Services.
local HttpService = game:GetService("HttpService")

-- Constants.
local DirectAudioExtensions = {
	["mp3"] = true,
	["ogg"] = true,
	["wav"] = true,
}

local DefaultYoutubeInitialSegmentFrames = 216
local DefaultYoutubeSegmentFrames = 216
local DefaultYoutubeInitialYieldAfterSeconds = 0.006
local DefaultYoutubeYieldAfterSeconds = 0.002
local DefaultYoutubeYieldEveryFrames = 1
local DefaultYoutubeWholeFile = false

local AudioContentTypes = {
	["audio/mpeg"] = "mp3",
	["audio/mp3"] = "mp3",
	["audio/ogg"] = "ogg",
	["audio/wav"] = "wav",
	["audio/x-wav"] = "wav",
	["audio/wave"] = "wav",
}

local MusicCacheExtensions = {
	["aac"] = true,
	["m4a"] = true,
	["mp3"] = true,
	["ogg"] = true,
	["wav"] = true,
	["webm"] = true,
}

local ProtectedMusicCacheFiles = {
	["snooze.mp3"] = true,
}

---Trim text.
---@param Text string
---@return string
local function Trim(Text)
	return tostring(Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

---Check if text starts with prefix.
---@param Text string
---@param Prefix string
---@return boolean
local function StartsWith(Text, Prefix)
	return Text:sub(1, #Prefix) == Prefix
end

---Check if text is an HTTP URL.
---@param Text string
---@return boolean
local function IsHttpUrl(Text)
	local Lower = Text:lower()
	return StartsWith(Lower, "http://") or StartsWith(Lower, "https://")
end

---Check if text is a Roblox asset URL.
---@param Text string
---@return boolean
local function IsRobloxAsset(Text)
	local Lower = Text:lower()
	return StartsWith(Lower, "rbxasset://") or StartsWith(Lower, "rbxassetid://")
end

---Check if text is a YouTube URL.
---@param Text string
---@return boolean
local function IsYoutubeUrl(Text)
	local Lower = Text:lower()
	return Lower:find("youtube.com", 1, true) ~= nil
		or Lower:find("youtu.be", 1, true) ~= nil
		or Lower:find("music.youtube.com", 1, true) ~= nil
end

---Extract YouTube ID from URL.
---@param Text string
---@return string?
local function ExtractYoutubeId(Text)
	local Id = Text:match("[?&]v=([%w_%-]+)")
		or Text:match("youtu%.be/([%w_%-]+)")
		or Text:match("/shorts/([%w_%-]+)")
		or Text:match("/embed/([%w_%-]+)")

	if Id and #Id > 0 then
		return Id:sub(1, 32)
	end

	return nil
end

---Sanitize a filename.
---@param Text string
---@return string
local function SanitizeFileName(Text)
	local Clean = Trim(Text):gsub("[/\\:*?\"<>|]", "_"):gsub("%s+", "_")
	if Clean == "" then
		return "audio"
	end

	return Clean:sub(1, 64)
end

---Build a deterministic small hash.
---@param Text string
---@return string
local function HashText(Text)
	local Hash = 0

	for Index = 1, #Text do
		Hash = (Hash * 131 + Text:byte(Index)) % 2147483647
	end

	return tostring(Hash)
end

---Get file extension from path.
---@param Path string
---@return string?
local function GetPathExtension(Path)
	local Clean = tostring(Path or ""):gsub("[?#].*", "")
	local Extension = Clean:match("%.([%w]+)$")
	if not Extension then return nil end

	Extension = Extension:lower()
	if DirectAudioExtensions[Extension] then
		return Extension
	end

	return nil
end

---Check if a path points to a cached music file.
---@param Path string
---@return boolean
local function IsMusicCacheFile(Path)
	local Clean = tostring(Path or ""):gsub("[?#].*", "")
	local FileName = Clean:gsub("\\", "/"):match("[^/]+$") or Clean
	if ProtectedMusicCacheFiles[FileName:lower()] then
		return false
	end

	local Extension = Clean:match("%.([%w]+)$")
	return Extension and MusicCacheExtensions[Extension:lower()] == true or false
end

---Get response body.
---@param Response table
---@return string?
local function GetResponseBody(Response)
	return rawget(Response, "Body") or rawget(Response, "body")
end

---Get status code.
---@param Response table
---@return number
local function GetStatusCode(Response)
	return tonumber(rawget(Response, "StatusCode") or rawget(Response, "status_code") or rawget(Response, "Status") or rawget(Response, "status")) or 0
end

---Get a response header.
---@param Response table
---@param Name string
---@return string?
local function GetResponseHeader(Response, Name)
	local Headers = rawget(Response, "Headers") or rawget(Response, "headers")
	if type(Headers) ~= "table" then return nil end

	local LowerName = Name:lower()
	for HeaderName, HeaderValue in next, Headers do
		if tostring(HeaderName):lower() == LowerName then
			return tostring(HeaderValue)
		end
	end

	return nil
end

---Check if status code is successful.
---@param StatusCode number
---@return boolean
local function IsSuccessStatus(StatusCode)
	return StatusCode == 0 or (StatusCode >= 200 and StatusCode < 300)
end

---Get request function.
---@return function?
local function GetRequestFunction()
	return request
		or http_request
		or (syn and syn.request)
		or (http and http.request)
		or (fluxus and fluxus.request)
end

---Run an HTTP request.
---@param Options table
---@return boolean
---@return table|string
local function Request(Options)
	local RequestFunction = GetRequestFunction()
	if not RequestFunction then
		return false, "Executor does not support request()."
	end

	local Success, Response = pcall(RequestFunction, Options)
	if not Success then
		return false, tostring(Response)
	end

	if type(Response) ~= "table" then
		return false, "Request returned an invalid response."
	end

	return true, Response
end

---Check whether a resolve request should continue.
---@param Options table
---@return boolean
local function ShouldContinueRequest(Options)
	local Callback = Options.ShouldContinue
	if type(Callback) ~= "function" then
		return true
	end

	local Success, Result = pcall(Callback)
	return Success and Result ~= false
end

---Stop when a resolve request was cancelled.
---@param Options table
---@return boolean
---@return string?
local function CheckRequestActive(Options)
	if ShouldContinueRequest(Options) then
		return true, nil
	end

	return false, "Music request was cancelled."
end

---Ensure a folder path exists.
---@param Path string
---@return boolean
---@return string?
local function EnsureFolder(Path)
	if not isfolder or not makefolder then
		return false, "Executor does not support workspace folders."
	end

	local Current = ""

	for Part in tostring(Path or ""):gmatch("[^/\\]+") do
		if Current == "" then
			Current = Part
		else
			Current = Current .. "/" .. Part
		end

		if not isfolder(Current) then
			local Success, Err = pcall(makefolder, Current)
			if not Success then
				return false, tostring(Err)
			end
		end
	end

	return true, nil
end

---Clear cached music files from a folder.
---@param CachePath string
---@return number
local function ClearMusicCachePath(CachePath)
	if not listfiles or not isfile or not isfolder or not delfile then
		return 0
	end

	if not isfolder(CachePath) then
		return 0
	end

	local FileListOk, FileList = pcall(listfiles, CachePath)
	if not FileListOk or type(FileList) ~= "table" then
		return 0
	end

	local Removed = 0
	for Index, FilePath in next, FileList do
		FilePath = tostring(FilePath)

		if isfolder(FilePath) then
			Removed = Removed + ClearMusicCachePath(FilePath)
		elseif isfile(FilePath) and IsMusicCacheFile(FilePath) then
			local DeleteOk = pcall(delfile, FilePath)
			if DeleteOk then
				Removed = Removed + 1
			end
		end
	end

	return Removed
end

---Check whether a YouTube stream should continue.
---@param Stream table
---@return boolean
local function ShouldContinueYoutubeStream(Stream)
	local Callback = Stream.ShouldContinue
	if type(Callback) ~= "function" then
		return true
	end

	local Success, Result = pcall(Callback)
	return Success and Result ~= false
end

---Build asset from a file path.
---@param Path string
---@return boolean
---@return string
local function BuildAsset(Path)
	if not getcustomasset then
		return false, "Executor does not support getcustomasset()."
	end

	local Success, Asset = pcall(getcustomasset, Path)
	if not Success then
		return false, tostring(Asset)
	end

	return true, Asset
end

---Write body into cache and build asset.
---@param CachePath string
---@param CacheName string
---@param Extension string
---@param Body string
---@return boolean
---@return table|string
local function CacheAudio(CachePath, CacheName, Extension, Body)
	if not writefile or not isfile then
		return false, "Executor does not support writefile/isfile."
	end

	local FolderOk, FolderErr = EnsureFolder(CachePath)
	if not FolderOk then
		return false, FolderErr or "Failed to create music cache folder."
	end

	local FilePath = CachePath .. "/" .. SanitizeFileName(CacheName) .. "." .. Extension
	if not isfile(FilePath) then
		local WriteOk, WriteErr = pcall(writefile, FilePath, Body)
		if not WriteOk then
			return false, tostring(WriteErr)
		end
	end

	local AssetOk, Asset = BuildAsset(FilePath)
	if not AssetOk then
		return false, Asset
	end

	return true, {
		Path = FilePath,
		Asset = Asset,
		Cached = true,
		SourceType = "File",
	}
end

---Get cached audio if it already exists.
---@param CachePath string
---@param CacheName string
---@param Extension string
---@return boolean
---@return table|string
local function GetCachedAudio(CachePath, CacheName, Extension)
	if not isfile then
		return false, "Executor does not support isfile."
	end

	local FilePath = CachePath .. "/" .. SanitizeFileName(CacheName) .. "." .. Extension
	if not isfile(FilePath) then
		return false, "Cached audio does not exist."
	end

	local AssetOk, Asset = BuildAsset(FilePath)
	if not AssetOk then
		return false, Asset
	end

	return true, {
		Path = FilePath,
		Asset = Asset,
		Cached = true,
		SourceType = "File",
	}
end

---Decode JSON body.
---@param Body string
---@return boolean
---@return table|string
local function DecodeJson(Body)
	local Success, Data = pcall(HttpService.JSONDecode, HttpService, Body)
	if not Success then
		return false, tostring(Data)
	end

	if type(Data) ~= "table" then
		return false, "JSON response was not an object."
	end

	return true, Data
end

---Get audio extension from response.
---@param Response table
---@param Url string
---@param DefaultExtension string?
---@return string?
local function GetAudioExtension(Response, Url, DefaultExtension)
	local ContentType = GetResponseHeader(Response, "Content-Type")
	if ContentType then
		ContentType = ContentType:lower():match("^[^;]+")
		if ContentType and AudioContentTypes[ContentType] then
			return AudioContentTypes[ContentType]
		end
	end

	local Extension = GetPathExtension(Url)
	if Extension then
		return Extension
	end

	if DefaultExtension and DirectAudioExtensions[DefaultExtension] then
		return DefaultExtension
	end

	return nil
end

---Resolve relative URL.
---@param Url string
---@param BaseUrl string
---@return string
local function ResolveRelativeUrl(Url, BaseUrl)
	if StartsWith(Url, "//") then
		return "https:" .. Url
	end

	if StartsWith(Url, "/") then
		local Root = BaseUrl:match("^(https?://[^/]+)")
		if Root then
			return Root .. Url
		end
	end

	return Url
end

---Find media URL in picker data.
---@param Picker table
---@return string?
local function FindPickerUrl(Picker)
	for Index = 1, #Picker do
		local Item = Picker[Index]
		if type(Item) == "table" then
			local ItemType = tostring(rawget(Item, "type") or rawget(Item, "format") or ""):lower()
			local Url = rawget(Item, "url") or rawget(Item, "href")
			if type(Url) == "string" and IsHttpUrl(Url) and ItemType:find("audio", 1, true) then
				return Url
			end
		end
	end

	for Index = 1, #Picker do
		local Item = Picker[Index]
		if type(Item) == "table" then
			local Url = rawget(Item, "url") or rawget(Item, "href")
			if type(Url) == "string" and IsHttpUrl(Url) then
				return Url
			end
		end
	end

	return nil
end

---Find media URL in response data.
---@param Data table
---@return string?
local function FindMediaUrl(Data)
	local Url = rawget(Data, "url") or rawget(Data, "href")
	if type(Url) == "string" and Url ~= "" then
		return Url
	end

	local Audio = rawget(Data, "audio")
	if type(Audio) == "string" and Audio ~= "" then
		return Audio
	elseif type(Audio) == "table" then
		Url = rawget(Audio, "url") or rawget(Audio, "href")
		if type(Url) == "string" and Url ~= "" then
			return Url
		end
	end

	local File = rawget(Data, "file")
	if type(File) == "string" and File ~= "" then
		return File
	elseif type(File) == "table" then
		Url = rawget(File, "url") or rawget(File, "href")
		if type(Url) == "string" and Url ~= "" then
			return Url
		end
	end

	local Picker = rawget(Data, "picker")
	if type(Picker) == "table" then
		return FindPickerUrl(Picker)
	end

	return nil
end

---Build converter error string.
---@param Data table
---@return string
local function BuildConverterError(Data)
	local ErrorData = rawget(Data, "error")
	if type(ErrorData) == "string" then
		return ErrorData
	end

	if type(ErrorData) == "table" then
		local Code = rawget(ErrorData, "code") or rawget(ErrorData, "message") or rawget(ErrorData, "reason")
		if Code then
			return tostring(Code)
		end
	end

	local Message = rawget(Data, "message") or rawget(Data, "text")
	if Message then
		return tostring(Message)
	end

	return "Converter failed to resolve the source."
end

---Build converter request headers.
---@param ApiKey string?
---@return table
local function BuildConverterHeaders(ApiKey)
	local Headers = {
		["Accept"] = "application/json",
		["Content-Type"] = "application/json",
		["User-Agent"] = "Epiphyllum/1.0",
	}

	ApiKey = Trim(ApiKey or "")
	if ApiKey ~= "" then
		if ApiKey:find("^Bearer%s+") or ApiKey:find("^Api%-Key%s+") then
			Headers["Authorization"] = ApiKey
		else
			Headers["Authorization"] = "Api-Key " .. ApiKey
		end
	end

	return Headers
end

---Build converter URLs.
---@param Endpoint string
---@return table
local function BuildConverterUrls(Endpoint)
	local Base = Trim(Endpoint):gsub("/+$", "")
	local Lower = Base:lower()
	local Urls = { Base }

	if Lower:find("/api", 1, true) == nil then
		Urls[#Urls + 1] = Base .. "/api/json"
	end

	return Urls
end

---Build converter payload.
---@param Source string
---@param Options table
---@param Legacy boolean
---@return string
local function BuildConverterPayload(Source, Options, Legacy)
	local AudioFormat = Options.AudioFormat or "mp3"
	local AudioBitrate = Options.AudioBitrate or "128"

	if Legacy then
		return HttpService:JSONEncode({
			["url"] = Source,
			["isAudioOnly"] = true,
			["aFormat"] = AudioFormat,
			["filenamePattern"] = "basic",
		})
	end

	return HttpService:JSONEncode({
		["url"] = Source,
		["downloadMode"] = "audio",
		["audioFormat"] = AudioFormat,
		["audioBitrate"] = AudioBitrate,
		["filenameStyle"] = "basic",
		["disableMetadata"] = true,
		["alwaysProxy"] = true,
		["localProcessing"] = "disabled",
	})
end

---Download an audio URL into cache.
---@param Url string
---@param Options table
---@param Title string?
---@param DefaultExtension string?
---@return boolean
---@return table|string
local function DownloadAudioUrl(Url, Options, Title, DefaultExtension)
	local RequestOk, Response = Request({
		Url = Url,
		Method = "GET",
		Headers = {
			["Accept"] = "audio/*,*/*",
			["User-Agent"] = "Epiphyllum/1.0",
		},
	})

	if not RequestOk then
		return false, Response
	end

	local StatusCode = GetStatusCode(Response)
	if not IsSuccessStatus(StatusCode) then
		return false, string.format("Audio download failed with HTTP %d.", StatusCode)
	end

	local Body = GetResponseBody(Response)
	if not Body or Body == "" then
		return false, "Audio download returned an empty body."
	end

	local Extension = GetAudioExtension(Response, Url, DefaultExtension)
	if not Extension then
		return false, "Downloaded source is not a supported Roblox audio file. Use MP3, OGG, or WAV."
	end

	local ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local CachePath = Options.CachePath or "Epiphyllum/Music"
	local CacheName = Title or ExtractYoutubeId(Options.Source or Url) or ("audio_" .. HashText(Url))
	local CacheOk, Result = CacheAudio(CachePath, CacheName .. "_" .. HashText(Url), Extension, Body)
	if not CacheOk then
		return false, Result
	end

	Result.Title = Title or CacheName
	Result.SourceType = "Remote"
	return true, Result
end

---Post to converter.
---@param EndpointUrl string
---@param Source string
---@param Options table
---@param Legacy boolean
---@return boolean
---@return table|string
---@return number
local function PostConverter(EndpointUrl, Source, Options, Legacy)
	local RequestOk, Response = Request({
		Url = EndpointUrl,
		Method = "POST",
		Headers = BuildConverterHeaders(Options.ConverterApiKey),
		Body = BuildConverterPayload(Source, Options, Legacy),
	})

	if not RequestOk then
		return false, Response, 0
	end

	local StatusCode = GetStatusCode(Response)
	local Body = GetResponseBody(Response)
	if not Body or Body == "" then
		return false, string.format("Converter returned HTTP %d with no body.", StatusCode), StatusCode
	end

	local Extension = GetAudioExtension(Response, EndpointUrl, Options.AudioFormat)
	local ContentType = GetResponseHeader(Response, "Content-Type")
	if IsSuccessStatus(StatusCode) and ContentType and ContentType:lower():find("audio/", 1, true) and Extension then
		local ActiveOk, ActiveErr = CheckRequestActive(Options)
		if not ActiveOk then
			return false, ActiveErr, StatusCode
		end

		local CacheOk, Result = CacheAudio(Options.CachePath or "Epiphyllum/Music", ExtractYoutubeId(Source) or ("audio_" .. HashText(Source)), Extension, Body)
		if not CacheOk then
			return false, Result, StatusCode
		end

		Result.Title = Source
		Result.SourceType = "Converter"
		return true, Result, StatusCode
	end

	local DecodeOk, Data = DecodeJson(Body)
	if not DecodeOk then
		if IsSuccessStatus(StatusCode) then
			return false, "Converter returned a non-audio response.", StatusCode
		end

		return false, string.format("Converter failed with HTTP %d.", StatusCode), StatusCode
	end

	local Status = tostring(rawget(Data, "status") or ""):lower()
	if Status == "error" or Status == "rate-limit" or Status == "local-processing" then
		return false, BuildConverterError(Data), StatusCode
	end

	if not IsSuccessStatus(StatusCode) then
		return false, BuildConverterError(Data), StatusCode
	end

	local Url = FindMediaUrl(Data)
	if not Url or Url == "" then
		return false, "Converter response did not include an audio URL.", StatusCode
	end

	Url = ResolveRelativeUrl(Url, EndpointUrl)
	local Title = rawget(Data, "filename") or rawget(Data, "title") or ExtractYoutubeId(Source)
	local DownloadOk, Result = DownloadAudioUrl(Url, Options, tostring(Title or ""), Options.AudioFormat or "mp3")
	if not DownloadOk then
		return false, Result, StatusCode
	end

	Result.SourceType = "Converter"
	return true, Result, StatusCode
end

---Build YouTube native cache name.
---@param Source string
---@param Stream table
---@param Options table
---@return string
local function BuildYoutubeCacheName(Source, Stream, Options)
	local VideoId = Stream.VideoId or ExtractYoutubeId(Source) or HashText(Source)
	local CacheName = string.format("youtube_native_v1_%s_%s", VideoId, HashText(Stream.Url or Source))
	local FrameLimit = tonumber(Options.YoutubeFrameLimit)
	if FrameLimit and FrameLimit > 0 then
		CacheName = string.format("%s_frames_%d", CacheName, math.floor(FrameLimit))
	end

	return CacheName
end

---Build YouTube stream cache name.
---@param Source string
---@param Stream table
---@return string
local function BuildYoutubeStreamCacheName(Source, Stream)
	local VideoId = Stream.VideoId or ExtractYoutubeId(Source) or HashText(Source)
	return string.format("youtube_stream_v2_%s_%s", VideoId, HashText(Stream.Url or Source))
end

---Build YouTube watch source.
---@param VideoId string
---@return string
local function BuildYoutubeWatchSource(VideoId)
	return "https://www.youtube.com/watch?v=" .. VideoId
end

---Create a segment file result.
---@param Decoded table
---@return boolean
---@return table|string
function YoutubeStream:CreateSegment(Decoded)
	if not writefile or not isfile then
		return false, "Executor does not support writefile/isfile."
	end

	local FolderOk, FolderErr = EnsureFolder(self.CachePath)
	if not FolderOk then
		return false, FolderErr or "Failed to create music cache folder."
	end

	self.SegmentIndex = self.SegmentIndex + 1

	local SegmentName = string.format(
		"%s_segment_%04d_%d_%d",
		self.CacheName,
		self.SegmentIndex,
		Decoded.StartFrame,
		Decoded.EndFrame
	)
	local FilePath = self.CachePath .. "/" .. SanitizeFileName(SegmentName) .. ".wav"

	if not isfile(FilePath) then
		local WriteOk, WriteErr = pcall(writefile, FilePath, Decoded.WavBody)
		if not WriteOk then
			return false, tostring(WriteErr)
		end
	end

	local AssetOk, Asset = BuildAsset(FilePath)
	if not AssetOk then
		return false, Asset
	end

	return true, {
		Path = FilePath,
		Asset = Asset,
		Index = self.SegmentIndex,
		Frames = Decoded.Frames,
		Duration = Decoded.Duration,
		StartFrame = Decoded.StartFrame,
		EndFrame = Decoded.EndFrame,
		Done = Decoded.Done,
		DecodeSeconds = Decoded.DecodeSeconds,
		WavSeconds = Decoded.WavSeconds,
		WavBytes = Decoded.WavBytes,
	}
end

---Read a YouTube stream segment.
---@param FrameLimit number?
---@param Options table?
---@return boolean
---@return table|string|nil
function YoutubeStream:ReadSegment(FrameLimit, Options)
	if #self.PendingSegments > 0 then
		return true, table.remove(self.PendingSegments, 1)
	end

	if self.Done then
		return true, nil
	end

	if not ShouldContinueYoutubeStream(self) then
		return false, "Music request was cancelled."
	end

	Options = Options or {}
	local YieldAfterSeconds = Options.YieldAfterSeconds
	if YieldAfterSeconds == nil then
		YieldAfterSeconds = self.YieldAfterSeconds
	end

	local YieldEveryFrames = Options.YieldEveryFrames
	if YieldEveryFrames == nil then
		YieldEveryFrames = self.YieldEveryFrames
	end

	local DecodeOk, Decoded = self.Decoder:ReadSegment(FrameLimit or self.SegmentFrames, {
		YieldAfterSeconds = YieldAfterSeconds,
		YieldEveryFrames = YieldEveryFrames,
	})
	if not DecodeOk then
		return false, Decoded
	end

	if Decoded.Frames <= 0 then
		self.Done = true
		return true, nil
	end

	self.Done = Decoded.Done == true
	if not ShouldContinueYoutubeStream(self) then
		return false, "Music request was cancelled."
	end

	return self:CreateSegment(Decoded)
end

---Resolve YouTube natively.
---@param Source string
---@param Options table
---@return boolean
---@return table|string
local function ResolveYoutubeNative(Source, Options)
	local StreamOk, Stream = YoutubeExtractor.ResolveM4a(Source)
	if not StreamOk then
		return false, Stream
	end

	local ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local CachePath = Options.CachePath or "Epiphyllum/Music"
	local CacheName = BuildYoutubeCacheName(Source, Stream, Options)
	local CachedOk, Cached = GetCachedAudio(CachePath, CacheName, "wav")
	if CachedOk then
		Cached.Title = Stream.Title or Stream.VideoId or Source
		Cached.SourceType = "YouTube"
		return true, Cached
	end

	local DownloadOk, M4aBody = YoutubeExtractor.DownloadM4a(Stream)
	if not DownloadOk then
		return false, M4aBody
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local AdtsOk, Adts = Mp4Aac.BuildAdts(M4aBody)
	if not AdtsOk then
		return false, Adts
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local DecodeOptions = {}
	if Options.YoutubeFrameLimit then
		DecodeOptions.FrameLimit = Options.YoutubeFrameLimit
	end

	local DecodeOk, Decoded = AacPcmDecoder.DecodeAdts(Adts.AdtsBody, DecodeOptions)
	if not DecodeOk then
		return false, Decoded
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local CacheOk, Result = CacheAudio(CachePath, CacheName, "wav", Decoded.WavBody)
	if not CacheOk then
		return false, Result
	end

	Result.Title = Stream.Title or Stream.VideoId or Source
	Result.SourceType = "YouTube"
	Result.Debug = {
		Itag = Stream.Itag,
		MimeType = Stream.MimeType,
		M4aBytes = #M4aBody,
		AdtsBytes = Adts.AdtsBytes,
		AdtsSamples = Adts.AdtsSamples,
		Frames = Decoded.Frames,
		Duration = Decoded.Duration,
		DecodeSeconds = Decoded.DecodeSeconds,
		WavSeconds = Decoded.WavSeconds,
		WavBytes = Decoded.WavBytes,
	}
	return true, Result
end

---Resolve YouTube through converter.
---@param Source string
---@param Options table
---@return boolean
---@return table|string
local function ResolveYoutube(Source, Options)
	local NativeOk, NativeResult = ResolveYoutubeNative(Source, Options)
	if NativeOk then
		return true, NativeResult
	end

	local Endpoint = Trim(Options.ConverterEndpoint or "")
	if Endpoint == "" then
		return false, NativeResult
	end

	local Urls = BuildConverterUrls(Endpoint)
	local LastErr = NativeResult

	for UrlIndex = 1, #Urls do
		local EndpointUrl = Urls[UrlIndex]

		for ModeIndex = 1, 2 do
			local Legacy = ModeIndex == 2
			local ConvertOk, Result, StatusCode = PostConverter(EndpointUrl, Source, Options, Legacy)
			if ConvertOk then
				return true, Result
			end

			LastErr = Result
			if StatusCode ~= 400 and StatusCode ~= 404 and StatusCode ~= 405 then
				return false, string.format("Native YouTube failed: %s; converter failed: %s", tostring(NativeResult), tostring(Result))
			end
		end
	end

	return false, string.format("Native YouTube failed: %s; converter failed: %s", tostring(NativeResult), tostring(LastErr))
end

---Resolve a local file.
---@param Source string
---@return boolean
---@return table|string
local function ResolveLocal(Source)
	if IsRobloxAsset(Source) then
		return true, {
			Asset = Source,
			Path = Source,
			Cached = false,
			SourceType = "Asset",
			Title = Source,
		}
	end

	if isfile and isfile(Source) then
		local AssetOk, Asset = BuildAsset(Source)
		if not AssetOk then
			return false, Asset
		end

		return true, {
			Asset = Asset,
			Path = Source,
			Cached = false,
			SourceType = "File",
			Title = Source,
		}
	end

	return false, "Source is not a local file."
end

---Resolve a music source.
---@param Source string
---@param Options table?
---@return boolean
---@return table|string
function MusicResolver.Resolve(Source, Options)
	Options = Options or {}
	Source = Trim(Source)
	Options.Source = Source

	if Source == "" then
		return false, "Music source is empty."
	end

	local LocalOk, LocalResult = ResolveLocal(Source)
	if LocalOk then
		return true, LocalResult
	end

	if not IsHttpUrl(Source) then
		return false, "Music source must be a local file, Roblox asset, or URL."
	end

	if IsYoutubeUrl(Source) then
		return ResolveYoutube(Source, Options)
	end

	return DownloadAudioUrl(Source, Options, nil, nil)
end

---Resolve a YouTube M4A stream without a converter.
---@param Source string
---@return boolean
---@return table|string
function MusicResolver.ResolveYoutubeM4a(Source)
	return YoutubeExtractor.ResolveM4a(Source)
end

---Clear cached music files.
---@param CachePath string?
---@return number
function MusicResolver.ClearCache(CachePath)
	return ClearMusicCachePath(CachePath or "Epiphyllum/Music")
end

---Create a native YouTube Opus stream.
---@param Source string
---@param Options table
---@param TargetVideoId string
---@param PlaylistVideoIds table
---@param PlaylistIndex number
---@return boolean
---@return table|string
local function CreateYoutubeOpusStream(Source, Options, TargetVideoId, PlaylistVideoIds, PlaylistIndex)
	local StreamOk, Stream = YoutubeExtractor.ResolveOpusWebm(BuildYoutubeWatchSource(TargetVideoId))
	if not StreamOk then
		return false, Stream
	end

	local ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local DownloadOk, WebmBody = YoutubeExtractor.DownloadOpusWebm(Stream)
	if not DownloadOk then
		return false, WebmBody
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local ParseOk, Parsed = WebmOpus.Parse(WebmBody)
	if not ParseOk then
		return false, Parsed
	end
	Parsed.Bytes = #WebmBody

	local DecoderOk, Decoder = OpusPcmDecoder.CreateStream(Parsed)
	if not DecoderOk then
		return false, Decoder
	end

	local UseWholeFile = Options.YoutubeWholeFile
	if UseWholeFile == nil then
		UseWholeFile = DefaultYoutubeWholeFile
	end

	local Streamer = setmetatable({
		SourceType = "YouTubeOpusStream",
		Title = Stream.Title or Stream.VideoId or Source,
		VideoId = Stream.VideoId,
		PlaylistVideoIds = PlaylistVideoIds,
		PlaylistIndex = PlaylistIndex,
		PlaylistCount = #PlaylistVideoIds,
		Itag = Stream.Itag,
		MimeType = Stream.MimeType,
		CachePath = Options.CachePath or "Epiphyllum/Music",
		CacheName = BuildYoutubeStreamCacheName(Source, Stream),
		ShouldContinue = Options.ShouldContinue,
		Decoder = Decoder,
		SegmentFrames = tonumber(Options.YoutubeOpusSegmentFrames) or tonumber(Options.YoutubeSegmentFrames) or DefaultYoutubeSegmentFrames,
		InitialYieldAfterSeconds = tonumber(Options.YoutubeInitialYieldAfterSeconds) or DefaultYoutubeInitialYieldAfterSeconds,
		InitialYieldEveryFrames = tonumber(Options.YoutubeInitialYieldEveryFrames) or tonumber(Options.YoutubeYieldEveryFrames) or DefaultYoutubeYieldEveryFrames,
		YieldAfterSeconds = tonumber(Options.YoutubeBackgroundYieldAfterSeconds) or tonumber(Options.YoutubeYieldAfterSeconds) or DefaultYoutubeYieldAfterSeconds,
		YieldEveryFrames = tonumber(Options.YoutubeYieldEveryFrames) or DefaultYoutubeYieldEveryFrames,
		PendingSegments = {},
		SegmentIndex = 0,
		Done = false,
		Debug = {
			WebmBytes = #WebmBody,
			PacketCount = Parsed.PacketCount,
			TotalSamples = Parsed.TotalSamples,
			PreSkip = Decoder.SkipSamples,
			Duration = (Parsed.TotalSamples or 0) / 48000,
			WholeFile = UseWholeFile,
		},
	}, YoutubeStream)

	if UseWholeFile then
		local SegmentOk, Segment = Streamer:ReadSegment(#Parsed.Packets)
		if not SegmentOk then
			return false, Segment
		end

		if not Segment then
			return false, "YouTube Opus stream did not produce audio."
		end

		Segment.WholeFile = true
		Streamer.PendingSegments[#Streamer.PendingSegments + 1] = Segment
		return true, Streamer
	end

	local InitialFrames = tonumber(Options.YoutubeOpusInitialSegmentFrames)
		or tonumber(Options.YoutubeInitialSegmentFrames)
		or DefaultYoutubeInitialSegmentFrames
	local SegmentOk, Segment = Streamer:ReadSegment(InitialFrames, {
		YieldAfterSeconds = Streamer.InitialYieldAfterSeconds,
		YieldEveryFrames = Streamer.InitialYieldEveryFrames,
	})
	if not SegmentOk then
		return false, Segment
	end

	if not Segment then
		return false, "YouTube Opus stream did not produce audio."
	end

	Streamer.PendingSegments[#Streamer.PendingSegments + 1] = Segment
	return true, Streamer
end

---Create a native YouTube stream.
---@param Source string
---@param Options table?
---@return boolean
---@return table|string
function MusicResolver.CreateYoutubeStream(Source, Options)
	Options = Options or {}
	Source = Trim(Source)
	Options.Source = Source

	if Source == "" then
		return false, "Music source is empty."
	end

	if not IsYoutubeUrl(Source) then
		return false, "Music source is not a YouTube URL."
	end

	local PlaylistVideoIds = Options.YoutubePlaylistVideoIds
	local PlaylistIndex = tonumber(Options.YoutubePlaylistIndex) or 1

	if type(PlaylistVideoIds) ~= "table" or #PlaylistVideoIds <= 0 then
		local ResolveOk, Resolved = YoutubeExtractor.ResolveVideoIds(Source)
		if not ResolveOk then
			return false, Resolved
		end

		PlaylistVideoIds = Resolved.VideoIds
		PlaylistIndex = tonumber(Resolved.SelectedIndex) or 1
	end

	if PlaylistIndex < 1 or PlaylistIndex > #PlaylistVideoIds then
		PlaylistIndex = 1
	end

	local TargetVideoId = PlaylistVideoIds[PlaylistIndex]
	if type(TargetVideoId) ~= "string" or TargetVideoId == "" then
		return false, "YouTube playlist did not include a playable video."
	end

	local OpusOk, OpusStream = CreateYoutubeOpusStream(Source, Options, TargetVideoId, PlaylistVideoIds, PlaylistIndex)
	if OpusOk then
		return true, OpusStream
	end

	local StreamOk, Stream = YoutubeExtractor.ResolveM4a(BuildYoutubeWatchSource(TargetVideoId))
	if not StreamOk then
		return false, string.format("YouTube Opus failed: %s; AAC failed: %s", tostring(OpusStream), tostring(Stream))
	end

	local ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local DownloadOk, M4aBody = YoutubeExtractor.DownloadM4a(Stream)
	if not DownloadOk then
		return false, M4aBody
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local AdtsOk, Adts = Mp4Aac.BuildAdts(M4aBody)
	if not AdtsOk then
		return false, Adts
	end

	ActiveOk, ActiveErr = CheckRequestActive(Options)
	if not ActiveOk then
		return false, ActiveErr
	end

	local DecoderOk, Decoder = AacPcmDecoder.CreateAdtsStream(Adts.AdtsBody)
	if not DecoderOk then
		return false, Decoder
	end

	local Streamer = setmetatable({
		SourceType = "YouTubeStream",
		Title = Stream.Title or Stream.VideoId or Source,
		VideoId = Stream.VideoId,
		PlaylistVideoIds = PlaylistVideoIds,
		PlaylistIndex = PlaylistIndex,
		PlaylistCount = #PlaylistVideoIds,
		Itag = Stream.Itag,
		MimeType = Stream.MimeType,
		CachePath = Options.CachePath or "Epiphyllum/Music",
		CacheName = BuildYoutubeStreamCacheName(Source, Stream),
		ShouldContinue = Options.ShouldContinue,
		Decoder = Decoder,
		SegmentFrames = tonumber(Options.YoutubeSegmentFrames) or DefaultYoutubeSegmentFrames,
		InitialYieldAfterSeconds = tonumber(Options.YoutubeInitialYieldAfterSeconds) or DefaultYoutubeInitialYieldAfterSeconds,
		InitialYieldEveryFrames = tonumber(Options.YoutubeInitialYieldEveryFrames) or tonumber(Options.YoutubeYieldEveryFrames) or DefaultYoutubeYieldEveryFrames,
		YieldAfterSeconds = tonumber(Options.YoutubeBackgroundYieldAfterSeconds) or tonumber(Options.YoutubeYieldAfterSeconds) or DefaultYoutubeYieldAfterSeconds,
		YieldEveryFrames = tonumber(Options.YoutubeYieldEveryFrames) or DefaultYoutubeYieldEveryFrames,
		PendingSegments = {},
		SegmentIndex = 0,
		Done = false,
		Debug = {
			M4aBytes = #M4aBody,
			AdtsBytes = Adts.AdtsBytes,
			AdtsSamples = Adts.AdtsSamples,
			Duration = Adts.AdtsSamples * 1024 / 44100,
		},
	}, YoutubeStream)

	local InitialFrames = tonumber(Options.YoutubeInitialSegmentFrames) or DefaultYoutubeInitialSegmentFrames
	local SegmentOk, Segment = Streamer:ReadSegment(InitialFrames, {
		YieldAfterSeconds = Streamer.InitialYieldAfterSeconds,
		YieldEveryFrames = Streamer.InitialYieldEveryFrames,
	})
	if not SegmentOk then
		return false, Segment
	end

	if not Segment then
		return false, "YouTube stream did not produce audio."
	end

	Streamer.PendingSegments[#Streamer.PendingSegments + 1] = Segment
	return true, Streamer
end

---Check if a source is a YouTube URL.
---@param Source string
---@return boolean
function MusicResolver.IsYoutubeUrl(Source)
	return IsYoutubeUrl(Trim(Source))
end

---Resolve playable YouTube video IDs.
---@param Source string
---@return boolean
---@return table|string
function MusicResolver.ResolveYoutubeVideoIds(Source)
	return YoutubeExtractor.ResolveVideoIds(Source)
end

---Download a resolved YouTube M4A stream.
---@param Stream table
---@return boolean
---@return string
function MusicResolver.DownloadYoutubeM4a(Stream)
	return YoutubeExtractor.DownloadM4a(Stream)
end

---Resolve a YouTube Opus WebM stream without a converter.
---@param Source string
---@return boolean
---@return table|string
function MusicResolver.ResolveYoutubeOpusWebm(Source)
	return YoutubeExtractor.ResolveOpusWebm(Source)
end

---Download a resolved YouTube Opus WebM stream.
---@param Stream table
---@return boolean
---@return string
function MusicResolver.DownloadYoutubeOpusWebm(Stream)
	return YoutubeExtractor.DownloadOpusWebm(Stream)
end

---Parse WebM Opus packets.
---@param Body string
---@return boolean
---@return table|string
function MusicResolver.ParseYoutubeOpusWebm(Body)
	return WebmOpus.Parse(Body)
end

-- Return MusicResolver module.
return MusicResolver
end)
__bundle_register("Audio/OpusCeltAllocation", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus CELT allocation module.
local OpusCeltAllocation = {}

---@module Audio.OpusCeltTables
local Tables = require("Audio/OpusCeltTables")

-- Constants.
local AllocationSteps = 6
local MaxFineBits = 8
local FineOffset = 21
local BitResolution = Tables.BitResolution
local MaxBands = Tables.MaxBands
local DefaultAllocationTrim = Tables.DefaultAllocationTrim

---Minimum value.
---@param Left number
---@param Right number
---@return number
local function Min(Left, Right)
	if Left < Right then
		return Left
	end

	return Right
end

---Maximum value.
---@param Left number
---@param Right number
---@return number
local function Max(Left, Right)
	if Left > Right then
		return Left
	end

	return Right
end

---Boolean to numeric index.
---@param Value boolean
---@return number
local function BoolIndex(Value)
	return Value and 1 or 0
end

---Get band edge by zero-based band index.
---@param Band number
---@return number
local function BandEdge(Band)
	return Tables.BandEdges[Band + 1]
end

---Create zero-based vector.
---@param Length number
---@param Value any
---@return table
local function CreateVector(Length, Value)
	local Vector = {}

	for Index = 0, Length - 1 do
		Vector[Index] = Value or 0
	end

	return Vector
end

---Calculate allocation caps.
---@param Lm number
---@param ChannelCount number
---@return table
local function AllocationCaps(Lm, ChannelCount)
	local Caps = {}
	local IndexBase = MaxBands * (2 * Lm + ChannelCount - 1)

	for Band = 0, MaxBands - 1 do
		local Width = (BandEdge(Band + 1) - BandEdge(Band)) * (2 ^ Lm)
		Caps[Band] = math.floor(((Tables.BandCaps[IndexBase + Band + 1] + 64) * ChannelCount * Width) / 4)
	end

	return Caps
end

---Get compact pulse count.
---@param Index number
---@return number
local function GetPulses(Index)
	if Index < 8 then
		return Index
	end

	return (8 + (Index % 8)) * (2 ^ (math.floor(Index / 8) - 1))
end

---Convert bits to pulses.
---@param Band number
---@param Lm number
---@param Bits number
---@return number
local function BitsToPulses(Band, Lm, Bits)
	if Bits <= 0 then
		return 0
	end

	Lm = Lm + 1
	local CacheStart = Tables.PulseCacheIndex[Lm * MaxBands + Band + 1]
	if CacheStart < 0 then
		return 0
	end

	local Lo = 0
	local Hi = Tables.PulseCacheBits[CacheStart + 1]
	Bits = Bits - 1

	for Step = 1, 6 do
		local Mid = math.floor((Lo + Hi + 1) / 2)
		if Tables.PulseCacheBits[CacheStart + Mid + 1] >= Bits then
			Hi = Mid
		else
			Lo = Mid
		end
	end

	local LoBits = -1
	if Lo ~= 0 then
		LoBits = Tables.PulseCacheBits[CacheStart + Lo + 1]
	end

	if Bits - LoBits <= Tables.PulseCacheBits[CacheStart + Hi + 1] - Bits then
		return Lo
	end

	return Hi
end

---Convert pulses to bits.
---@param Band number
---@param Lm number
---@param Pulses number
---@return number
local function PulsesToBits(Band, Lm, Pulses)
	if Pulses == 0 then
		return 0
	end

	Lm = Lm + 1
	local CacheStart = Tables.PulseCacheIndex[Lm * MaxBands + Band + 1]
	return Tables.PulseCacheBits[CacheStart + Pulses + 1] + 1
end

---Interpolate bits to pulses.
---@param StartBand number
---@param EndBand number
---@param SkipStart number
---@param BitsOne table
---@param BitsTwo table
---@param Threshold table
---@param Caps table
---@param Total number
---@param SkipReserved number
---@param IntensityReserved number
---@param DualStereoReserved number
---@param Bits table
---@param FineQuant table
---@param FinePriority table
---@param ChannelCount number
---@param Lm number
---@param RangeDecoder table
---@return number
---@return number
---@return number
---@return number
local function InterpolateBitsToPulses(
	StartBand,
	EndBand,
	SkipStart,
	BitsOne,
	BitsTwo,
	Threshold,
	Caps,
	Total,
	SkipReserved,
	IntensityReserved,
	DualStereoReserved,
	Bits,
	FineQuant,
	FinePriority,
	ChannelCount,
	Lm,
	RangeDecoder
)
	local AllocationFloor = ChannelCount * (2 ^ BitResolution)
	local Stereo = BoolIndex(ChannelCount > 1)
	local Lo = 0
	local Hi = 2 ^ AllocationSteps

	for Step = 1, AllocationSteps do
		local Mid = math.floor((Lo + Hi) / 2)
		local Psum = 0
		local Done = false

		for Band = EndBand - 1, StartBand, -1 do
			local Tmp = BitsOne[Band] + math.floor(Mid * BitsTwo[Band] / (2 ^ AllocationSteps))
			if Tmp >= Threshold[Band] or Done then
				Done = true
				Psum = Psum + Min(Tmp, Caps[Band])
			elseif Tmp >= AllocationFloor then
				Psum = Psum + AllocationFloor
			end
		end

		if Psum > Total then
			Hi = Mid
		else
			Lo = Mid
		end
	end

	local Psum = 0
	local Done = false
	for Band = EndBand - 1, StartBand, -1 do
		local Tmp = BitsOne[Band] + math.floor(Lo * BitsTwo[Band] / (2 ^ AllocationSteps))
		if Tmp < Threshold[Band] and not Done then
			if Tmp >= AllocationFloor then
				Tmp = AllocationFloor
			else
				Tmp = 0
			end
		else
			Done = true
		end

		Tmp = Min(Tmp, Caps[Band])
		Bits[Band] = Tmp
		Psum = Psum + Tmp
	end

	local CodedBands = EndBand
	while true do
		CodedBands = CodedBands - 1
		local Band = CodedBands
		if Band <= SkipStart then
			Total = Total + SkipReserved
			CodedBands = CodedBands + 1
			break
		end

		local Left = Total - Psum
		local PerCoeff = math.floor(Left / (BandEdge(CodedBands + 1) - BandEdge(StartBand)))
		Left = Left - (BandEdge(CodedBands + 1) - BandEdge(StartBand)) * PerCoeff
		local Rem = Max(Left - (BandEdge(Band) - BandEdge(StartBand)), 0)
		local BandWidth = BandEdge(CodedBands + 1) - BandEdge(Band)
		local BandBits = Bits[Band] + PerCoeff * BandWidth + Rem

		if BandBits >= Max(Threshold[Band], AllocationFloor + (2 ^ BitResolution)) then
			if RangeDecoder:DecodeSymbolLogP(1) ~= 0 then
				CodedBands = CodedBands + 1
				break
			end

			Psum = Psum + (2 ^ BitResolution)
			BandBits = BandBits - (2 ^ BitResolution)
		end

		Psum = Psum - Bits[Band] - IntensityReserved
		if IntensityReserved > 0 then
			IntensityReserved = Tables.Log2FracTable[Band - StartBand + 1]
		end

		Psum = Psum + IntensityReserved
		if BandBits >= AllocationFloor then
			Psum = Psum + AllocationFloor
			Bits[Band] = AllocationFloor
		else
			Bits[Band] = 0
		end
	end

	local Intensity = 0
	if IntensityReserved > 0 then
		local Value = RangeDecoder:DecodeUniform(CodedBands + 1 - StartBand)
		Intensity = StartBand + Value
	end

	if Intensity <= StartBand then
		Total = Total + DualStereoReserved
		DualStereoReserved = 0
	end

	local DualStereo = 0
	if DualStereoReserved > 0 then
		DualStereo = RangeDecoder:DecodeSymbolLogP(1)
	end

	local Left = Total - Psum
	local PerCoeff = math.floor(Left / (BandEdge(CodedBands) - BandEdge(StartBand)))
	Left = Left - (BandEdge(CodedBands) - BandEdge(StartBand)) * PerCoeff

	for Band = StartBand, CodedBands - 1 do
		Bits[Band] = Bits[Band] + PerCoeff * (BandEdge(Band + 1) - BandEdge(Band))
	end

	for Band = StartBand, CodedBands - 1 do
		local Tmp = Min(Left, BandEdge(Band + 1) - BandEdge(Band))
		Bits[Band] = Bits[Band] + Tmp
		Left = Left - Tmp
	end

	local CurrentBalance = 0
	local Band = StartBand
	while Band < CodedBands do
		local Width = BandEdge(Band + 1) - BandEdge(Band)
		local N = Width * (2 ^ Lm)
		Bits[Band] = Bits[Band] + CurrentBalance
		local Excess = 0

		if N > 1 then
			Excess = Max(Bits[Band] - Caps[Band], 0)
			Bits[Band] = Bits[Band] - Excess
			local Den = ChannelCount * N
			if ChannelCount == 2 and N > 2 and DualStereo == 0 and Band < Intensity then
				Den = Den + 1
			end

			local NcLogN = Den * (Tables.LogN400[Band + 1] + Lm * (2 ^ BitResolution))
			local Offset = math.floor(NcLogN / 2) - Den * FineOffset
			if N == 2 then
				Offset = Offset + math.floor(Den * (2 ^ BitResolution) / 4)
			end

			if Bits[Band] + Offset < Den * 2 * (2 ^ BitResolution) then
				Offset = Offset + math.floor(NcLogN / 4)
			elseif Bits[Band] + Offset < Den * 3 * (2 ^ BitResolution) then
				Offset = Offset + math.floor(NcLogN / 8)
			end

			FineQuant[Band] = Max(0, math.floor((Bits[Band] + Offset + Den * (2 ^ (BitResolution - 1))) / (Den * (2 ^ BitResolution))))
			if ChannelCount * FineQuant[Band] > math.floor(Bits[Band] / (2 ^ BitResolution)) then
				FineQuant[Band] = math.floor(Bits[Band] / (2 ^ (Stereo + BitResolution)))
			end

			FineQuant[Band] = Min(FineQuant[Band], MaxFineBits)
			FinePriority[Band] = BoolIndex(FineQuant[Band] * Den * (2 ^ BitResolution) >= Bits[Band] + Offset)
			Bits[Band] = Bits[Band] - ChannelCount * FineQuant[Band] * (2 ^ BitResolution)
		else
			Excess = Max(0, Bits[Band] - ChannelCount * (2 ^ BitResolution))
			Bits[Band] = Bits[Band] - Excess
			FineQuant[Band] = 0
			FinePriority[Band] = 1
		end

		if Excess > 0 then
			local ExtraFine = Min(math.floor(Excess / (2 ^ (Stereo + BitResolution))), MaxFineBits - FineQuant[Band])
			FineQuant[Band] = FineQuant[Band] + ExtraFine
			local ExtraBits = ExtraFine * ChannelCount * (2 ^ BitResolution)
			FinePriority[Band] = BoolIndex(ExtraBits >= Excess - CurrentBalance)
			Excess = Excess - ExtraBits
		end

		CurrentBalance = Excess
		Band = Band + 1
	end

	while Band < EndBand do
		FineQuant[Band] = math.floor(Bits[Band] / (2 ^ (Stereo + BitResolution)))
		Bits[Band] = 0
		FinePriority[Band] = BoolIndex(FineQuant[Band] < 1)
		Band = Band + 1
	end

	return CodedBands, Intensity, DualStereo, CurrentBalance
end

---Compute CELT allocation.
---@param Info table
---@param TotalBits number
---@param RangeDecoder table
---@return table
function OpusCeltAllocation.Compute(Info, TotalBits, RangeDecoder)
	local StartBand = Info.StartBand
	local EndBand = Info.EndBand
	local Lm = Info.Lm
	local ChannelCount = Info.ChannelCount
	local AllocationTrim = Info.AllocationTrim or DefaultAllocationTrim
	local Offsets = Info.BandBoost or CreateVector(MaxBands, 0)
	local Total = Max(TotalBits, 0)
	local Caps = AllocationCaps(Lm, ChannelCount)
	local BitsOne = CreateVector(MaxBands, 0)
	local BitsTwo = CreateVector(MaxBands, 0)
	local Threshold = CreateVector(MaxBands, 0)
	local TrimOffset = CreateVector(MaxBands, 0)
	local Bits = CreateVector(MaxBands, 0)
	local FineQuant = CreateVector(MaxBands, 0)
	local FinePriority = CreateVector(MaxBands, 0)
	local Balance = 0

	local SkipReserved = 0
	if Total >= 2 ^ BitResolution then
		SkipReserved = 2 ^ BitResolution
	end

	Total = Total - SkipReserved

	local IntensityReserved = 0
	local DualStereoReserved = 0
	if ChannelCount == 2 then
		IntensityReserved = Tables.Log2FracTable[EndBand - StartBand + 1]
		if IntensityReserved > Total then
			IntensityReserved = 0
		else
			Total = Total - IntensityReserved
			if Total >= 2 ^ BitResolution then
				DualStereoReserved = 2 ^ BitResolution
			end
			Total = Total - DualStereoReserved
		end
	end

	for Band = StartBand, EndBand - 1 do
		local BandWidth = BandEdge(Band + 1) - BandEdge(Band)
		Threshold[Band] = Max(ChannelCount * (2 ^ BitResolution), math.floor((3 * BandWidth * (2 ^ Lm) * (2 ^ BitResolution)) / 16))
		TrimOffset[Band] = math.floor(ChannelCount * BandWidth * (AllocationTrim - DefaultAllocationTrim - Lm)
			* (EndBand - Band - 1) * (2 ^ (Lm + BitResolution)) / 64)
		if BandWidth * (2 ^ Lm) == 1 then
			TrimOffset[Band] = TrimOffset[Band] - ChannelCount * (2 ^ BitResolution)
		end
	end

	local Lo = 1
	local Hi = #Tables.BandAllocation - 1
	while Lo <= Hi do
		local Mid = math.floor((Lo + Hi) / 2)
		local Psum = 0
		local Done = false

		for Band = EndBand - 1, StartBand, -1 do
			local BandWidth = BandEdge(Band + 1) - BandEdge(Band)
			local BandBits = math.floor(ChannelCount * BandWidth * Tables.BandAllocation[Mid + 1][Band + 1] * (2 ^ Lm) / 4)
			if BandBits > 0 then
				BandBits = Max(0, BandBits + TrimOffset[Band])
			end

			BandBits = BandBits + (Offsets[Band] or 0)
			if BandBits >= Threshold[Band] or Done then
				Done = true
				Psum = Psum + Min(BandBits, Caps[Band])
			elseif BandBits >= ChannelCount * (2 ^ BitResolution) then
				Psum = Psum + ChannelCount * (2 ^ BitResolution)
			end
		end

		if Psum > Total then
			Hi = Mid - 1
		else
			Lo = Mid + 1
		end
	end

	Hi = Lo
	Lo = Lo - 1

	local SkipStart = StartBand
	for Band = StartBand, EndBand - 1 do
		local BandWidth = BandEdge(Band + 1) - BandEdge(Band)
		local BitsOneBand = math.floor(ChannelCount * BandWidth * Tables.BandAllocation[Lo + 1][Band + 1] * (2 ^ Lm) / 4)
		local BitsTwoBand = 0
		if Hi >= #Tables.BandAllocation then
			BitsTwoBand = Caps[Band]
		else
			BitsTwoBand = math.floor(ChannelCount * BandWidth * Tables.BandAllocation[Hi + 1][Band + 1] * (2 ^ Lm) / 4)
		end

		if BitsOneBand > 0 then
			BitsOneBand = Max(0, BitsOneBand + TrimOffset[Band])
		end

		if BitsTwoBand > 0 then
			BitsTwoBand = Max(0, BitsTwoBand + TrimOffset[Band])
		end

		if Lo > 0 then
			BitsOneBand = BitsOneBand + (Offsets[Band] or 0)
		end

		BitsTwoBand = BitsTwoBand + (Offsets[Band] or 0)
		if (Offsets[Band] or 0) > 0 then
			SkipStart = Band
		end

		BitsTwo[Band] = Max(0, BitsTwoBand - BitsOneBand)
		BitsOne[Band] = BitsOneBand
	end

	local CodedBands, Intensity, DualStereo
	CodedBands, Intensity, DualStereo, Balance = InterpolateBitsToPulses(
		StartBand,
		EndBand,
		SkipStart,
		BitsOne,
		BitsTwo,
		Threshold,
		Caps,
		Total,
		SkipReserved,
		IntensityReserved,
		DualStereoReserved,
		Bits,
		FineQuant,
		FinePriority,
		ChannelCount,
		Lm,
		RangeDecoder
	)

	return {
		Pulses = Bits,
		FineQuant = FineQuant,
		FinePriority = FinePriority,
		Intensity = Intensity,
		DualStereo = DualStereo,
		Balance = Balance,
		CodedBands = CodedBands,
		Bits = TotalBits,
	}
end

---Decode fine energy.
---@param Decoder table
---@param Info table
---@param FineQuant table
function OpusCeltAllocation.DecodeFineEnergy(Decoder, Info, FineQuant)
	for Band = Info.StartBand, Info.EndBand - 1 do
		if (FineQuant[Band] or 0) > 0 then
			for Channel = 0, Info.ChannelCount - 1 do
				local Quant = Decoder.RangeDecoder:DecodeRawBits(FineQuant[Band])
				local Offset = ((Quant + 0.5) * (2 ^ (14 - FineQuant[Band])) / 16384) - 0.5
				Decoder.PreviousLogE[Channel][Band] = Decoder.PreviousLogE[Channel][Band] + Offset
			end
		end
	end
end

---Finalize fine energy.
---@param Decoder table
---@param Info table
---@param FineQuant table
---@param FinePriority table
---@param BitsLeft number
function OpusCeltAllocation.FinalizeFineEnergy(Decoder, Info, FineQuant, FinePriority, BitsLeft)
	for Priority = 0, 1 do
		local Band = Info.StartBand
		while Band < Info.EndBand and BitsLeft >= Info.ChannelCount do
			if (FineQuant[Band] or 0) < MaxFineBits and (FinePriority[Band] or 0) == Priority then
				for Channel = 0, Info.ChannelCount - 1 do
					local Quant = Decoder.RangeDecoder:DecodeRawBits(1)
					local Offset = (Quant - 0.5) * (2 ^ (14 - FineQuant[Band] - 1)) / 16384
					Decoder.PreviousLogE[Channel][Band] = Decoder.PreviousLogE[Channel][Band] + Offset
					BitsLeft = BitsLeft - 1
				end
			end

			Band = Band + 1
		end
	end
end

OpusCeltAllocation.GetPulses = GetPulses
OpusCeltAllocation.BitsToPulses = BitsToPulses
OpusCeltAllocation.PulsesToBits = PulsesToBits
OpusCeltAllocation.AllocationCaps = AllocationCaps

-- Return Opus CELT allocation module.
return OpusCeltAllocation
end)
__bundle_register("Audio/OpusCeltBands", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus CELT band decoder module.
local OpusCeltBands = {}

---@module Audio.OpusCeltTables
local Tables = require("Audio/OpusCeltTables")

---@module Audio.OpusCeltAllocation
local Allocation = require("Audio/OpusCeltAllocation")

---@module Audio.OpusCeltPvq
local Pvq = require("Audio/OpusCeltPvq")

-- Constants.
local MaxBands = Tables.MaxBands
local BitResolution = Tables.BitResolution
local QThetaOffset = 4
local QThetaOffsetTwoPhase = 16

-- Tables.
local OrderYTable = {
	1, 0,
	3, 0, 2, 1,
	7, 0, 4, 3, 6, 1, 5, 2,
	15, 0, 8, 7, 12, 3, 11, 4, 14, 1, 9, 6, 13, 2, 10, 5,
}

---Bitwise and for small integer masks.
---@param Left number
---@param Right number
---@return number
local function BitAnd(Left, Right)
	local Result = 0
	local Bit = 1

	while Left > 0 or Right > 0 do
		local LeftBit = Left % 2
		local RightBit = Right % 2

		if LeftBit == 1 and RightBit == 1 then
			Result = Result + Bit
		end

		Left = math.floor(Left / 2)
		Right = math.floor(Right / 2)
		Bit = Bit * 2
	end

	return Result
end

---Bitwise or for small integer masks.
---@param Left number
---@param Right number
---@return number
local function BitOr(Left, Right)
	local Result = 0
	local Bit = 1

	while Left > 0 or Right > 0 do
		local LeftBit = Left % 2
		local RightBit = Right % 2

		if LeftBit == 1 or RightBit == 1 then
			Result = Result + Bit
		end

		Left = math.floor(Left / 2)
		Right = math.floor(Right / 2)
		Bit = Bit * 2
	end

	return Result
end

---Minimum value.
---@param Left number
---@param Right number
---@return number
local function Min(Left, Right)
	if Left < Right then
		return Left
	end

	return Right
end

---Maximum value.
---@param Left number
---@param Right number
---@return number
local function Max(Left, Right)
	if Left > Right then
		return Left
	end

	return Right
end

---Signed integer divide truncated toward zero.
---@param Numerator number
---@param Denominator number
---@return number
local function SignedDivide(Numerator, Denominator)
	if Numerator < 0 then
		return -math.floor((-Numerator) / Denominator)
	end

	return math.floor(Numerator / Denominator)
end

---Get band edge by zero-based band index.
---@param Band number
---@return number
local function BandEdge(Band)
	return Tables.BandEdges[Band + 1]
end

---Get the integer bit length.
---@param Value number
---@return number
local function BitLength(Value)
	local Length = 0

	while Value > 0 do
		Value = math.floor(Value / 2)
		Length = Length + 1
	end

	return Length
end

---Cast to signed 16-bit.
---@param Value number
---@return number
local function Int16(Value)
	Value = Value % 65536
	if Value >= 32768 then
		return Value - 65536
	end

	return Value
end

---Fixed-point fractional multiply.
---@param Left number
---@param Right number
---@return number
local function FracMul16(Left, Right)
	return math.floor((16384 + Int16(Left) * Int16(Right)) / 32768)
end

---Integer square root.
---@param Value number
---@return number
local function Isqrt32(Value)
	if Value == 0 then
		return 0
	end

	local Guess = 0
	local Shift = math.floor((BitLength(Value) - 1) / 2)
	local Bit = 2 ^ Shift

	while true do
		local Trial = ((Guess * 2) + Bit) * (2 ^ Shift)
		if Trial <= Value then
			Guess = Guess + Bit
			Value = Value - Trial
		end

		if Shift == 0 then
			break
		end

		Bit = math.floor(Bit / 2)
		Shift = Shift - 1
	end

	return Guess
end

---Reference linear congruential random step.
---@param Seed number
---@return number
local function LcgRand(Seed)
	return (1664525 * Seed + 1013904223) % 4294967296
end

---Bit-exact cosine approximation.
---@param Value number
---@return number
local function BitExactCos(Value)
	local Temp = math.floor((4096 + Value * Value) / 8192)
	local ValueSquared = Temp
	ValueSquared = (32767 - ValueSquared) + FracMul16(
		ValueSquared,
		-7651 + FracMul16(ValueSquared, 8277 + FracMul16(-626, ValueSquared))
	)

	return 1 + ValueSquared
end

---Bit-exact log2 tangent approximation.
---@param Sin number
---@param Cos number
---@return number
local function BitExactLog2Tan(Sin, Cos)
	local CosLength = BitLength(Cos)
	local SinLength = BitLength(Sin)

	Cos = Cos * (2 ^ (15 - CosLength))
	Sin = Sin * (2 ^ (15 - SinLength))

	return (SinLength - CosLength) * 2048
		+ FracMul16(Sin, FracMul16(Sin, -2597) + 7932)
		- FracMul16(Cos, FracMul16(Cos, -2597) + 7932)
end

---Interleave transient collapse bits.
---@param Fill number
---@return number
local function BitInterleave(Fill)
	local Table = { 0, 1, 1, 1, 2, 3, 3, 3, 2, 3, 3, 3, 2, 3, 3, 3 }
	local Low = Fill % 16
	local High = math.floor(Fill / 16)

	return Table[Low + 1] + Table[High + 1] * 4
end

---Deinterleave transient collapse bits.
---@param Fill number
---@return number
local function BitDeinterleave(Fill)
	local Table = {
		0x00, 0x03, 0x0C, 0x0F, 0x30, 0x33, 0x3C, 0x3F,
		0xC0, 0xC3, 0xCC, 0xCF, 0xF0, 0xF3, 0xFC, 0xFF,
	}

	return Table[(Fill % 16) + 1]
end

---Check whether a band needs recursive split decoding.
---@param Band number
---@param Lm number
---@param BandBits number
---@return boolean
local function ShouldSplitBand(Band, Lm, BandBits)
	local CacheStart = Tables.PulseCacheIndex[(Lm + 1) * MaxBands + Band + 1]
	if CacheStart < 0 then
		return false
	end

	return BandBits > Tables.PulseCacheBits[CacheStart + Tables.PulseCacheBits[CacheStart + 1] + 1] + 12
end

---Compute theta quantizer size.
---@param Count number
---@param BitsValue number
---@param Offset number
---@param PulseCap number
---@param Stereo boolean
---@return number
local function ComputeQN(Count, BitsValue, Offset, PulseCap, Stereo)
	local Exp2Table8 = { 16384, 17866, 19483, 21247, 23170, 25267, 27554, 30048 }
	local Count2 = 2 * Count - 1
	if Stereo and Count == 2 then
		Count2 = Count2 - 1
	end

	local Qb = Min(BitsValue - PulseCap - (4 * (2 ^ BitResolution)), SignedDivide(BitsValue + Count2 * Offset, Count2))
	Qb = Min(8 * (2 ^ BitResolution), Qb)
	if Qb < (2 ^ BitResolution) / 2 then
		return 1
	end

	return math.floor(((Exp2Table8[(Qb % 8) + 1] / (2 ^ (14 - math.floor(Qb / (2 ^ BitResolution))))) + 1) / 2) * 2
end

---Decode split-band theta.
---@param Qn number
---@param Count number
---@param Stereo boolean
---@param Blocks number
---@param RangeDecoder table
---@return number
local function DecodeBandTheta(Qn, Count, Stereo, Blocks, RangeDecoder)
	if Stereo and Count > 2 then
		local P0 = 3
		local X0 = math.floor(Qn / 2)
		local Total = P0 * (X0 + 1) + X0
		local Frequency = RangeDecoder:DecodeCumulative(Total)
		local X = 0

		if Frequency < (X0 + 1) * P0 then
			X = math.floor(Frequency / P0)
		else
			X = X0 + 1 + (Frequency - (X0 + 1) * P0)
		end

		local Low
		local High
		if X <= X0 then
			Low = P0 * X
			High = P0 * (X + 1)
		else
			Low = (X - 1 - X0) + (X0 + 1) * P0
			High = (X - X0) + (X0 + 1) * P0
		end

		RangeDecoder:UpdateCumulative(Low, High, Total)
		return X
	end

	if Blocks > 1 or Stereo then
		local Value = RangeDecoder:DecodeUniform(Qn + 1)
		return Value
	end

	local Half = math.floor(Qn / 2)
	local Total = (Half + 1) * (Half + 1)
	local Frequency = RangeDecoder:DecodeCumulative(Total)
	local ITheta
	local SymbolFrequency
	local Low

	if Frequency < math.floor(Half * (Half + 1) / 2) then
		ITheta = math.floor((Isqrt32(8 * Frequency + 1) - 1) / 2)
		SymbolFrequency = ITheta + 1
		Low = math.floor(ITheta * (ITheta + 1) / 2)
	else
		ITheta = math.floor((2 * (Qn + 1) - Isqrt32(8 * (Total - Frequency - 1) + 1)) / 2)
		SymbolFrequency = Qn + 1 - ITheta
		Low = Total - math.floor((Qn + 1 - ITheta) * (Qn + 2 - ITheta) / 2)
	end

	RangeDecoder:UpdateCumulative(Low, Low + SymbolFrequency, Total)
	return ITheta
end

---Merge stereo mid and side vectors.
---@param Left table
---@param Right table
---@param Mid number
---@param Count number
local function StereoMerge(Left, Right, Mid, Count)
	local Cross = 0
	local SideEnergy = 0

	for Index = 1, Count do
		Cross = Cross + Left[Index] * Right[Index]
		SideEnergy = SideEnergy + Right[Index] * Right[Index]
	end

	Cross = Cross * Mid
	local LeftEnergy = Mid * Mid + SideEnergy - 2 * Cross
	local RightEnergy = Mid * Mid + SideEnergy + 2 * Cross

	if LeftEnergy < 6e-4 or RightEnergy < 6e-4 then
		for Index = 1, Count do
			Right[Index] = Left[Index]
		end

		return
	end

	local LeftScale = 1 / math.sqrt(LeftEnergy)
	local RightScale = 1 / math.sqrt(RightEnergy)

	for Index = 1, Count do
		local LeftValue = Mid * Left[Index] - Right[Index]
		local RightValue = Mid * Left[Index] + Right[Index]

		Left[Index] = LeftValue * LeftScale
		Right[Index] = RightValue * RightScale
	end
end

---Apply one Hadamard pass.
---@param Vector table
---@param Count number
---@param Stride number
local function Haar1(Vector, Count, Stride)
	local HalfCount = math.floor(Count / 2)
	local Scale = math.sqrt(0.5)

	for Offset = 0, Stride - 1 do
		for Index = 0, HalfCount - 1 do
			local FirstIndex = Stride * 2 * Index + Offset + 1
			local SecondIndex = Stride * (2 * Index + 1) + Offset + 1
			local First = Scale * Vector[FirstIndex]
			local Second = Scale * Vector[SecondIndex]

			Vector[FirstIndex] = First + Second
			Vector[SecondIndex] = First - Second
		end
	end
end

---Get reusable float scratch space.
---@param State table
---@param Count number
---@return table
local function FloatScratch(State, Count)
	State.TmpScratch = State.TmpScratch or {}

	for Index = 1, Count do
		State.TmpScratch[Index] = 0
	end

	for Index = Count + 1, #State.TmpScratch do
		State.TmpScratch[Index] = nil
	end

	return State.TmpScratch
end

---Copy a vector range into a new one-based vector.
---@param Source table
---@param Start number
---@param Count number
---@return table
local function Slice(Source, Start, Count)
	if not Source then
		return nil
	end

	local Result = {}

	for Index = 1, Count do
		Result[Index] = Source[Start + Index - 1]
	end

	return Result
end

---Copy a one-based vector into another vector range.
---@param Target table
---@param Start number
---@param Source table
---@param Count number
local function CopyInto(Target, Start, Source, Count)
	if not Target or not Source then
		return
	end

	for Index = 1, Count do
		Target[Start + Index - 1] = Source[Index]
	end
end

---Cast to signed 32-bit.
---@param Value number
---@return number
local function Int32(Value)
	Value = Value % 4294967296
	if Value >= 2147483648 then
		return Value - 4294967296
	end

	return Value
end

---Deinterleave Hadamard-ordered coefficients.
---@param Vector table
---@param Count number
---@param Stride number
---@param Hadamard boolean
---@param State table
local function DeinterleaveHadamard(Vector, Count, Stride, Hadamard, State)
	local Temp = FloatScratch(State, Count * Stride)

	if Hadamard then
		local OrderOffset = Stride - 2
		for Offset = 0, Stride - 1 do
			for Index = 0, Count - 1 do
				Temp[OrderYTable[OrderOffset + Offset + 1] * Count + Index + 1] = Vector[Index * Stride + Offset + 1]
			end
		end
	else
		for Offset = 0, Stride - 1 do
			for Index = 0, Count - 1 do
				Temp[Offset * Count + Index + 1] = Vector[Index * Stride + Offset + 1]
			end
		end
	end

	for Index = 1, Count * Stride do
		Vector[Index] = Temp[Index]
	end
