---Interleave Hadamard-ordered coefficients.
---@param Vector table
---@param Count number
---@param Stride number
---@param Hadamard boolean
---@param State table
local function InterleaveHadamard(Vector, Count, Stride, Hadamard, State)
	local Temp = FloatScratch(State, Count * Stride)

	if Hadamard then
		local OrderOffset = Stride - 2
		for Offset = 0, Stride - 1 do
			for Index = 0, Count - 1 do
				Temp[Index * Stride + Offset + 1] = Vector[OrderYTable[OrderOffset + Offset + 1] * Count + Index + 1]
			end
		end
	else
		for Offset = 0, Stride - 1 do
			for Index = 0, Count - 1 do
				Temp[Index * Stride + Offset + 1] = Vector[Offset * Count + Index + 1]
			end
		end
	end

	for Index = 1, Count * Stride do
		Vector[Index] = Temp[Index]
	end
end

---Decode a CELT band shape.
---@param Band number
---@param X table
---@param Y table?
---@param Count number
---@param BandBits number
---@param Spread number
---@param Blocks number
---@param Intensity number
---@param TfChange number
---@param Lowband table?
---@param RemainingBits table
---@param Lm number
---@param LowbandOut table?
---@param Level number
---@param Gain number
---@param LowbandScratch table?
---@param Fill number
---@param State table
---@return number
local function QuantBand(
	Band,
	X,
	Y,
	Count,
	BandBits,
	Spread,
	Blocks,
	Intensity,
	TfChange,
	Lowband,
	RemainingBits,
	Lm,
	LowbandOut,
	Level,
	Gain,
	LowbandScratch,
	Fill,
	State
)
	local FullBand = X
	local Stereo = Y ~= nil
	local Split = Stereo
	local OriginalCount = Count
	local CountPerBlock = Count / Blocks
	local OriginalBlocks = Blocks
	local LongBlocks = Blocks == 1
	local TimeDivide = 0
	local Recombine = 0
	local Invert = false
	local Mid = 0
	local Side = 0
	local CollapseMask = 0
	local MonoSplit = false

	if Count == 1 then
		local Channels = 1
		if Stereo then
			Channels = 2
		end

		for Channel = 1, Channels do
			local Sign = 0
			if RemainingBits.Value >= 2 ^ BitResolution then
				Sign = State.RangeDecoder:DecodeRawBits(1)
				RemainingBits.Value = RemainingBits.Value - 2 ^ BitResolution
				BandBits = BandBits - 2 ^ BitResolution
			end

			local Value = 1
			if Sign ~= 0 then
				Value = -Value
			end

			if Channel == 1 then
				X[1] = Value
			else
				Y[1] = Value
			end
		end

		if LowbandOut then
			LowbandOut[1] = X[1]
		end

		return 1
	end

	if not Stereo and Level == 0 then
		if TfChange > 0 then
			Recombine = TfChange
		end

		if Lowband and (Recombine ~= 0 or (CountPerBlock % 2) == 0 and TfChange < 0 or OriginalBlocks > 1) then
			LowbandScratch = LowbandScratch or {}
			for Index = 1, Count do
				LowbandScratch[Index] = Lowband[Index]
			end
			Lowband = LowbandScratch
		end

		for Index = 0, Recombine - 1 do
			if Lowband then
				Haar1(Lowband, math.floor(Count / (2 ^ Index)), 2 ^ Index)
			end
			Fill = BitInterleave(Fill)
		end

		Blocks = math.floor(Blocks / (2 ^ Recombine))
		CountPerBlock = CountPerBlock * (2 ^ Recombine)

		while (CountPerBlock % 2) == 0 and TfChange < 0 do
			if Lowband then
				Haar1(Lowband, CountPerBlock, Blocks)
			end

			Fill = BitOr(Fill, Fill * (2 ^ Blocks))
			Blocks = Blocks * 2
			CountPerBlock = CountPerBlock / 2
			TimeDivide = TimeDivide + 1
			TfChange = TfChange + 1
		end

		OriginalBlocks = Blocks
		if OriginalBlocks > 1 and Lowband then
			DeinterleaveHadamard(Lowband, math.floor(CountPerBlock / (2 ^ Recombine)), OriginalBlocks * (2 ^ Recombine), LongBlocks, State)
		end
	end

	if not Stereo and Lm ~= -1 and ShouldSplitBand(Band, Lm, BandBits) and Count > 2 then
		local Half = math.floor(Count / 2)
		X = Slice(FullBand, 1, Half)
		Y = Slice(FullBand, Half + 1, Half)
		Count = Half
		Split = true
		MonoSplit = true
		Lm = Lm - 1

		if Blocks == 1 then
			Fill = BitOr(BitAnd(Fill, 1), Fill * 2)
		end

		Blocks = math.floor((Blocks + 1) / 2)
	end

	if Split then
		local PulseCap = Tables.LogN400[Band + 1] + Lm * (2 ^ BitResolution)
		local ThetaOffset = QThetaOffset
		if Stereo and Count == 2 then
			ThetaOffset = QThetaOffsetTwoPhase
		end

		local Qn = ComputeQN(Count, BandBits, math.floor(PulseCap / 2) - ThetaOffset, PulseCap, Stereo)
		if Stereo and Band >= Intensity then
			Qn = 1
		end

		local Tell = State.RangeDecoder:TellFrac()
		local ITheta = 0
		if Qn ~= 1 then
			ITheta = DecodeBandTheta(Qn, Count, Stereo, OriginalBlocks, State.RangeDecoder)
			ITheta = math.floor(ITheta * 16384 / Qn)
		elseif Stereo then
			if BandBits > 2 * (2 ^ BitResolution) and RemainingBits.Value > 2 * (2 ^ BitResolution) then
				Invert = State.RangeDecoder:DecodeSymbolLogP(2) ~= 0
			end
		end

		local QAlloc = State.RangeDecoder:TellFrac() - Tell
		BandBits = BandBits - QAlloc

		local OriginalFill = Fill
		local Delta = 0
		local IMid = 0
		local ISide = 0

		if ITheta == 0 then
			IMid = 32767
			Fill = BitAnd(Fill, (2 ^ Blocks) - 1)
			Delta = -16384
		elseif ITheta == 16384 then
			ISide = 32767
			Fill = BitAnd(Fill, ((2 ^ Blocks) - 1) * (2 ^ Blocks))
			Delta = 16384
		else
			IMid = BitExactCos(ITheta)
			ISide = BitExactCos(16384 - ITheta)
			Delta = FracMul16((Count - 1) * 128, BitExactLog2Tan(ISide, IMid))
		end

		Mid = IMid / 32768
		Side = ISide / 32768

		if Count == 2 and Stereo then
			local MidBits = BandBits
			local SideBits = 0
			if ITheta ~= 0 and ITheta ~= 16384 then
				SideBits = 2 ^ BitResolution
			end

			MidBits = MidBits - SideBits
			RemainingBits.Value = RemainingBits.Value - QAlloc - SideBits

			local X2 = X
			local Y2 = Y
			if ITheta > 8192 then
				X2 = Y
				Y2 = X
			end

			local Sign = 0
			if SideBits ~= 0 then
				Sign = State.RangeDecoder:DecodeRawBits(1)
			end

			local SignScale = 1
			if Sign ~= 0 then
				SignScale = -1
			end

			CollapseMask = QuantBand(Band, X2, nil, Count, MidBits, Spread, Blocks, Intensity, TfChange, Lowband, RemainingBits, Lm, LowbandOut, Level, Gain, LowbandScratch, OriginalFill, State)
			Y2[1] = -SignScale * X2[2]
			Y2[2] = SignScale * X2[1]

			local X0 = Mid * X[1]
			local X1 = Mid * X[2]
			local Y0 = Side * Y[1]
			local Y1 = Side * Y[2]

			X[1] = X0 - Y0
			Y[1] = X0 + Y0
			X[2] = X1 - Y1
			Y[2] = X1 + Y1
		else
			if OriginalBlocks > 1 and not Stereo and BitAnd(ITheta, 0x3FFF) ~= 0 then
				if ITheta > 8192 then
					Delta = Delta - math.floor(Delta / (2 ^ (4 - Lm)))
				else
					Delta = Min(0, Delta + math.floor(Count * (2 ^ BitResolution) / (2 ^ (5 - Lm))))
				end
			end

			local MidBits = Max(0, Min(BandBits, math.floor((BandBits - Delta) / 2)))
			local SideBits = BandBits - MidBits
			RemainingBits.Value = RemainingBits.Value - QAlloc

			local NextLowband2 = nil
			if Lowband and not Stereo then
				NextLowband2 = Slice(Lowband, Count + 1, Count)
			end

			local NextLowbandOut1 = nil
			local NextLevel = 0
			if Stereo then
				NextLowbandOut1 = LowbandOut
			else
				NextLevel = Level + 1
			end

			local CollapseShift = 0
			if not Stereo then
				CollapseShift = math.floor(OriginalBlocks / 2)
			end

			local Rebalance = RemainingBits.Value
			if MidBits >= SideBits then
				local MidGain = Gain * Mid
				if Stereo then
					MidGain = 1
				end

				CollapseMask = QuantBand(Band, X, nil, Count, MidBits, Spread, Blocks, Intensity, TfChange, Lowband, RemainingBits, Lm, NextLowbandOut1, NextLevel, MidGain, LowbandScratch, Fill, State)
				Rebalance = MidBits - (Rebalance - RemainingBits.Value)
				if Rebalance > 3 * (2 ^ BitResolution) and ITheta ~= 0 then
					SideBits = SideBits + Rebalance - 3 * (2 ^ BitResolution)
				end

				local SideMask = QuantBand(Band, Y, nil, Count, SideBits, Spread, Blocks, Intensity, TfChange, NextLowband2, RemainingBits, Lm, nil, NextLevel, Gain * Side, nil, math.floor(Fill / (2 ^ Blocks)), State)
				CollapseMask = BitOr(CollapseMask, SideMask * (2 ^ CollapseShift))
			else
				local SideMask = QuantBand(Band, Y, nil, Count, SideBits, Spread, Blocks, Intensity, TfChange, NextLowband2, RemainingBits, Lm, nil, NextLevel, Gain * Side, nil, math.floor(Fill / (2 ^ Blocks)), State)
				CollapseMask = SideMask * (2 ^ CollapseShift)
				Rebalance = SideBits - (Rebalance - RemainingBits.Value)
				if Rebalance > 3 * (2 ^ BitResolution) and ITheta ~= 16384 then
					MidBits = MidBits + Rebalance - 3 * (2 ^ BitResolution)
				end

				local MidGain = Gain * Mid
				if Stereo then
					MidGain = 1
				end

				CollapseMask = BitOr(CollapseMask, QuantBand(Band, X, nil, Count, MidBits, Spread, Blocks, Intensity, TfChange, Lowband, RemainingBits, Lm, NextLowbandOut1, NextLevel, MidGain, LowbandScratch, Fill, State))
			end
		end
	else
		local Q = Allocation.BitsToPulses(Band, Lm, BandBits)
		local CurrentBits = Allocation.PulsesToBits(Band, Lm, Q)

		RemainingBits.Value = RemainingBits.Value - CurrentBits
		while RemainingBits.Value < 0 and Q > 0 do
			RemainingBits.Value = RemainingBits.Value + CurrentBits
			Q = Q - 1
			CurrentBits = Allocation.PulsesToBits(Band, Lm, Q)
			RemainingBits.Value = RemainingBits.Value - CurrentBits
		end

		if Q ~= 0 then
			CollapseMask = Pvq.AlgUnquant(X, Count, Allocation.GetPulses(Q), Spread, Blocks, State.RangeDecoder, Gain, State)
		else
			local Mask = (2 ^ Blocks) - 1
			Fill = BitAnd(Fill, Mask)

			if Fill == 0 then
				for Index = 1, Count do
					X[Index] = 0
				end
			else
				if not Lowband then
					for Index = 1, Count do
						State.Seed = LcgRand(State.Seed or 0)
						X[Index] = math.floor(Int32(State.Seed) / (2 ^ 20))
					end

					CollapseMask = Mask
				else
					for Index = 1, Count do
						State.Seed = LcgRand(State.Seed or 0)
						local Noise = 1 / 256
						if BitAnd(State.Seed, 0x8000) == 0 then
							Noise = -Noise
						end

						X[Index] = Lowband[Index] + Noise
					end

					CollapseMask = Fill
				end

				Pvq.RenormaliseVector(X, Count, Gain)
			end
		end
	end

	if MonoSplit then
		CopyInto(FullBand, 1, X, Count)
		CopyInto(FullBand, Count + 1, Y, Count)
	end

	if Stereo then
		if Count ~= 2 then
			StereoMerge(X, Y, Mid, Count)
		end

		if Invert then
			for Index = 1, Count do
				Y[Index] = -Y[Index]
			end
		end
	elseif Level == 0 then
		X = FullBand

		if OriginalBlocks > 1 then
			InterleaveHadamard(X, math.floor(CountPerBlock / (2 ^ Recombine)), OriginalBlocks * (2 ^ Recombine), LongBlocks, State)
		end

		CountPerBlock = OriginalCount / OriginalBlocks
		Blocks = OriginalBlocks

		for Index = 1, TimeDivide do
			Blocks = math.floor(Blocks / 2)
			CountPerBlock = CountPerBlock * 2
			CollapseMask = BitOr(CollapseMask, math.floor(CollapseMask / (2 ^ Blocks)))
			Haar1(X, CountPerBlock, Blocks)
		end

		for Index = 0, Recombine - 1 do
			CollapseMask = BitDeinterleave(CollapseMask)
			Haar1(X, math.floor(OriginalCount / (2 ^ Index)), 2 ^ Index)
		end

		Blocks = Blocks * (2 ^ Recombine)

		if LowbandOut then
			local Scale = math.sqrt(OriginalCount)
			for Index = 1, OriginalCount do
				LowbandOut[Index] = Scale * X[Index]
			end
		end

		CollapseMask = BitAnd(CollapseMask, (2 ^ Blocks) - 1)
	end

	return CollapseMask
end

---Decode all coded CELT bands.
---@param Info table
---@param X table
---@param Y table?
---@param TotalBits number
---@param State table
---@return table
local function QuantAllBands(Info, X, Y, TotalBits, State)
	local ChannelCount = 1
	if Y then
		ChannelCount = 2
	end

	local Blocks = 1
	if Info.Transient then
		Blocks = 2 ^ Info.Lm
	end

	local Scale = 2 ^ Info.Lm
	local FrameBins = Scale * BandEdge(MaxBands)
	local Norm = {}
	local NormTwo = {}
	local LowbandScratch = {}
	local CollapseMasks = {}

	for Index = 1, FrameBins do
		Norm[Index] = 0
		NormTwo[Index] = 0
	end

	for Index = 1, Scale * (BandEdge(MaxBands) - BandEdge(MaxBands - 1)) do
		LowbandScratch[Index] = 0
	end

	local LowbandOffset = 0
	local UpdateLowband = true
	local Balance = Info.Allocation.Balance or 0
	local DualStereo = ChannelCount == 2 and (Info.Allocation.DualStereo or 0) ~= 0

	for Band = Info.StartBand, Info.EndBand - 1 do
		local Tell = State.RangeDecoder:TellFrac()
		if Band ~= Info.StartBand then
			Balance = Balance - Tell
		end

		local RemainingBits = TotalBits - Tell - 1
		local BandBits = 0
		if Band <= (Info.Allocation.CodedBands or 0) - 1 then
			local CurrentBalance = SignedDivide(Balance, Min(3, (Info.Allocation.CodedBands or 0) - Band))
			BandBits = Max(0, Min(16383, Min(RemainingBits + 1, (Info.Allocation.Pulses[Band] or 0) + CurrentBalance)))
		end

		local BandStart = Scale * BandEdge(Band)
		local BandEnd = Scale * BandEdge(Band + 1)
		local BandWidth = BandEnd - BandStart

		if BandStart - BandWidth >= Scale * BandEdge(Info.StartBand) or Band == Info.StartBand + 1 then
			if UpdateLowband or LowbandOffset == 0 then
				LowbandOffset = Band
			end
		end

		if Band == Info.StartBand + 1 and Info.StartBand + 2 <= MaxBands then
			local FirstWidth = Scale * (BandEdge(Info.StartBand + 1) - BandEdge(Info.StartBand))
			local SecondWidth = Scale * (BandEdge(Info.StartBand + 2) - BandEdge(Info.StartBand + 1))
			local Offset = Scale * BandEdge(Info.StartBand)

			if SecondWidth > FirstWidth then
				for Index = FirstWidth, SecondWidth - 1 do
					Norm[Offset + Index + 1] = Norm[Offset + 2 * FirstWidth - SecondWidth + Index + 1]
					if ChannelCount == 2 then
						NormTwo[Offset + Index + 1] = NormTwo[Offset + 2 * FirstWidth - SecondWidth + Index + 1]
					end
				end
			end
		end

		local EffectiveLowband = -1
		local XMask = 0
		local YMask = 0
		local TfChange = 0
		if Info.TfChange then
			TfChange = Info.TfChange[Band] or 0
		end

		if LowbandOffset ~= 0 and (Info.Spread ~= Pvq.SpreadAggressive or Blocks > 1 or TfChange < 0) then
			EffectiveLowband = Max(Scale * BandEdge(Info.StartBand), Scale * BandEdge(LowbandOffset) - BandWidth)
			local FoldStart = LowbandOffset

			while true do
				FoldStart = FoldStart - 1
				if Scale * BandEdge(FoldStart) <= EffectiveLowband then
					break
				end
			end

			local FoldEnd = LowbandOffset - 1
			while true do
				FoldEnd = FoldEnd + 1
				if FoldEnd >= Band or Scale * BandEdge(FoldEnd) >= EffectiveLowband + BandWidth then
					break
				end
			end

			for Fold = FoldStart, FoldEnd - 1 do
				XMask = BitOr(XMask, CollapseMasks[Fold * ChannelCount] or 0)
				YMask = BitOr(YMask, CollapseMasks[Fold * ChannelCount + ChannelCount - 1] or 0)
			end
		else
			XMask = (2 ^ Blocks) - 1
			YMask = XMask
		end

		if DualStereo and Band == (Info.Allocation.Intensity or 0) then
			DualStereo = false

			for Index = Scale * BandEdge(Info.StartBand), BandStart - 1 do
				Norm[Index + 1] = 0.5 * (Norm[Index + 1] + NormTwo[Index + 1])
			end
		end

		local Lowband = nil
		if EffectiveLowband >= 0 then
			Lowband = Slice(Norm, EffectiveLowband + 1, BandWidth)
		end

		if DualStereo then
			local Remaining = { Value = RemainingBits }
			local XBand = Slice(X, BandStart + 1, BandWidth)
			local NormOutX = Slice(Norm, BandStart + 1, BandWidth)
			XMask = QuantBand(
				Band,
				XBand,
				nil,
				BandWidth,
				math.floor(BandBits / 2),
				Info.Spread,
				Blocks,
				Info.Allocation.Intensity or MaxBands,
				TfChange,
				Lowband,
				Remaining,
				Info.Lm,
				NormOutX,
				0,
				1,
				LowbandScratch,
				XMask,
				State
			)
			CopyInto(X, BandStart + 1, XBand, BandWidth)
			CopyInto(Norm, BandStart + 1, NormOutX, BandWidth)

			local LowbandY = nil
			if EffectiveLowband >= 0 then
				LowbandY = Slice(NormTwo, EffectiveLowband + 1, BandWidth)
			end

			local YBand = Slice(Y, BandStart + 1, BandWidth)
			local NormOutY = Slice(NormTwo, BandStart + 1, BandWidth)
			YMask = QuantBand(
				Band,
				YBand,
				nil,
				BandWidth,
				math.floor(BandBits / 2),
				Info.Spread,
				Blocks,
				Info.Allocation.Intensity or MaxBands,
				TfChange,
				LowbandY,
				Remaining,
				Info.Lm,
				NormOutY,
				0,
				1,
				LowbandScratch,
				YMask,
				State
			)
			CopyInto(Y, BandStart + 1, YBand, BandWidth)
			CopyInto(NormTwo, BandStart + 1, NormOutY, BandWidth)
		else
			local Remaining = { Value = RemainingBits }
			local XBand = Slice(X, BandStart + 1, BandWidth)
			local YBand = Slice(Y, BandStart + 1, BandWidth)
			local NormOut = Slice(Norm, BandStart + 1, BandWidth)

			XMask = QuantBand(
				Band,
				XBand,
				YBand,
				BandWidth,
				BandBits,
				Info.Spread,
				Blocks,
				Info.Allocation.Intensity or MaxBands,
				TfChange,
				Lowband,
				Remaining,
				Info.Lm,
				NormOut,
				0,
				1,
				LowbandScratch,
				BitOr(XMask, YMask),
				State
			)
			YMask = XMask

			CopyInto(X, BandStart + 1, XBand, BandWidth)
			CopyInto(Y, BandStart + 1, YBand, BandWidth)
			CopyInto(Norm, BandStart + 1, NormOut, BandWidth)
		end

		CollapseMasks[Band * ChannelCount] = XMask
		CollapseMasks[Band * ChannelCount + ChannelCount - 1] = YMask
		Balance = Balance + (Info.Allocation.Pulses[Band] or 0) + Tell
		UpdateLowband = BandBits > BandWidth * (2 ^ BitResolution)
	end

	return CollapseMasks
end

OpusCeltBands.ShouldSplitBand = ShouldSplitBand
OpusCeltBands.QuantBand = QuantBand
OpusCeltBands.QuantAllBands = QuantAllBands
OpusCeltBands.DecodeBandTheta = DecodeBandTheta
OpusCeltBands.ComputeQN = ComputeQN
OpusCeltBands.BitExactCos = BitExactCos
OpusCeltBands.BitExactLog2Tan = BitExactLog2Tan
OpusCeltBands.FracMul16 = FracMul16
OpusCeltBands.Isqrt32 = Isqrt32
OpusCeltBands.LcgRand = LcgRand
OpusCeltBands.StereoMerge = StereoMerge
OpusCeltBands.Haar1 = Haar1
OpusCeltBands.DeinterleaveHadamard = DeinterleaveHadamard
OpusCeltBands.InterleaveHadamard = InterleaveHadamard
OpusCeltBands.BitInterleave = BitInterleave
OpusCeltBands.BitDeinterleave = BitDeinterleave
OpusCeltBands.QThetaOffset = QThetaOffset
OpusCeltBands.QThetaOffsetTwoPhase = QThetaOffsetTwoPhase
