---Minimum value.
---@param Left number
---@param Right number
---@return number
local function Min(Left, Right)
	if Left < Right then
		return Left
	end

	return Right
end

---Maximum value.
---@param Left number
---@param Right number
---@return number
local function Max(Left, Right)
	if Left > Right then
		return Left
	end

	return Right
end

---Boolean to numeric index.
---@param Value boolean
---@return number
local function BoolIndex(Value)
	return Value and 1 or 0
end

---Get band edge by zero-based band index.
---@param Band number
---@return number
local function BandEdge(Band)
	return Tables.BandEdges[Band + 1]
end

---Create a zero-based band vector.
---@param Value number
---@return table
local function CreateBandVector(Value)
	local Vector = {}

	for Band = 0, MaxBands - 1 do
		Vector[Band] = Value or 0
	end

	return Vector
end

---Create a one-based sample vector.
---@param Count number
---@param Value number?
---@return table
local function CreateSampleVector(Count, Value)
	local Vector = {}

	for Index = 1, Count do
		Vector[Index] = Value or 0
	end

	return Vector
end

---Small energy delta mapping.
---@param Symbol number
---@return number
local function SmallEnergyDelta(Symbol)
	if Symbol == 1 then
		return -1
	elseif Symbol == 2 then
		return 1
	end

	return 0
end

---Copy a band vector.
---@param Source table
---@return table
local function CopyBandVector(Source)
	local Result = {}

	for Band = 0, MaxBands - 1 do
		Result[Band] = Source[Band] or 0
	end

	return Result
end

---Reset CELT decoder state.
function Decoder:Reset()
	self.RangeDecoder = nil
	self.PreviousLogE = { [0] = CreateBandVector(0), [1] = CreateBandVector(0) }
	self.PreviousLogE1 = { [0] = CreateBandVector(-28), [1] = CreateBandVector(-28) }
	self.PreviousLogE2 = { [0] = CreateBandVector(-28), [1] = CreateBandVector(-28) }
	self.Overlap = {
		[0] = CreateSampleVector(ShortBlockSampleCount, 0),
		[1] = CreateSampleVector(ShortBlockSampleCount, 0),
	}
	self.PreemphasisMem = { [0] = 0, [1] = 0 }
	self.PostFilter = {
		Period = 0,
		PeriodOld = 0,
		Gain = 0,
		GainOld = 0,
		Tapset = 0,
		TapsetOld = 0,
	}
	self.PostFilterHistory = {
		[0] = CreateSampleVector(PostFilterHistorySize, 0),
		[1] = CreateSampleVector(PostFilterHistorySize, 0),
	}
	self.Rng = 0
end

---Decode the silence flag.
---@param Info table
function Decoder:DecodeSilenceFlag(Info)
	local Tell = self.RangeDecoder:Tell()

	if Tell >= Info.TotalBits then
		Info.Silence = true
	elseif Tell == 1 then
		Info.Silence = self.RangeDecoder:DecodeSymbolLogP(15) == 1
	end
end

---Decode the optional pitch post-filter header.
---@param Info table
function Decoder:DecodePostFilter(Info)
	if Info.StartBand ~= 0 or self.RangeDecoder:Tell() + 16 > Info.TotalBits then
		return
	end

	if self.RangeDecoder:DecodeSymbolLogP(1) == 0 then
		return
	end

	local Octave = self.RangeDecoder:DecodeUniform(6)
	local RawPeriod = self.RangeDecoder:DecodeRawBits(4 + Octave)
	local RawGain = self.RangeDecoder:DecodeRawBits(3)

	Info.PostFilter = {
		Enabled = true,
		Octave = Octave,
		Period = (PostFilterPitchBase * (2 ^ Octave)) + RawPeriod - 1,
		Gain = PostFilterGainStep * (RawGain + 1),
		Tapset = 0,
	}

	if self.RangeDecoder:Tell() + 2 <= Info.TotalBits then
		Info.PostFilter.Tapset = self.RangeDecoder:DecodeSymbolWithICDF(Tables.IcdfTapset)
	end
end

---Decode transient flag.
---@param Info table
function Decoder:DecodeTransientFlag(Info)
	if Info.Lm == 0 or self.RangeDecoder:Tell() + 3 > Info.TotalBits then
		return
	end

	Info.Transient = self.RangeDecoder:DecodeSymbolLogP(3) == 1
	if Info.Transient then
		Info.ShortBlockCount = 2 ^ Info.Lm
	end
end

---Decode intra-energy flag.
---@param Info table
function Decoder:DecodeIntraEnergyFlag(Info)
	if self.RangeDecoder:Tell() + 3 > Info.TotalBits then
		return
	end

	Info.IntraEnergy = self.RangeDecoder:DecodeSymbolLogP(3) == 1
end

---Prepare mono coarse-energy history.
---@param Info table
function Decoder:PrepareCoarseEnergyHistory(Info)
	if Info.ChannelCount ~= 1 then
		return
	end

	for Band = 0, MaxBands - 1 do
		self.PreviousLogE[0][Band] = Max(self.PreviousLogE[0][Band], self.PreviousLogE[1][Band])
	end
end

---Decode one coarse-energy delta.
---@param Info table
---@param ProbModel table
---@param Band number
---@return number
function Decoder:DecodeCoarseEnergyDelta(Info, ProbModel, Band)
	local Tell = self.RangeDecoder:Tell()
	if Tell >= Info.TotalBits then
		return -1
	end

	local BitsLeft = Info.TotalBits - Tell
	if BitsLeft >= 15 then
		local ProbIndex = 2 * Min(Band, MaxBands - 1)
		return self.RangeDecoder:DecodeLaplace(ProbModel[ProbIndex + 1] * 128, ProbModel[ProbIndex + 2] * 64)
	elseif BitsLeft >= 2 then
		return SmallEnergyDelta(self.RangeDecoder:DecodeSymbolWithICDF(Tables.IcdfSmallEnergy))
	end

	return -self.RangeDecoder:DecodeSymbolLogP(1)
end

---Decode coarse energy.
---@param Info table
function Decoder:DecodeCoarseEnergy(Info)
	local ProbModel = Tables.EProbModel[Info.Lm + 1][BoolIndex(Info.IntraEnergy) + 1]
	local PreviousBandPrediction = { [0] = 0, [1] = 0 }
	local Coef = Tables.EnergyPredictionCoefficients[Info.Lm + 1]
	local Beta = Tables.EnergyBetaCoefficients[Info.Lm + 1]

	if Info.IntraEnergy then
		Coef = 0
		Beta = Tables.EnergyIntraBeta
	end

	Info.CoarseEnergy = {
		[0] = CopyBandVector(self.PreviousLogE[0]),
		[1] = CopyBandVector(self.PreviousLogE[1]),
	}

	for Band = Info.StartBand, Info.EndBand - 1 do
		for Channel = 0, Info.ChannelCount - 1 do
			local Quant = self:DecodeCoarseEnergyDelta(Info, ProbModel, Band)
			local OldEnergy = Max(-9, self.PreviousLogE[Channel][Band])
			local Energy = Coef * OldEnergy + PreviousBandPrediction[Channel] + Quant

			self.PreviousLogE[Channel][Band] = Energy
			Info.CoarseEnergy[Channel][Band] = Energy
			PreviousBandPrediction[Channel] = PreviousBandPrediction[Channel] + Quant - Beta * Quant
		end
	end

	if Info.ChannelCount == 1 then
		for Band = 0, MaxBands - 1 do
			self.PreviousLogE[1][Band] = self.PreviousLogE[0][Band]
			Info.CoarseEnergy[1][Band] = Info.CoarseEnergy[0][Band]
		end
	end
end

---Decode time-frequency changes.
---@param Info table
function Decoder:DecodeTimeFrequencyChanges(Info)
	local LogP = FirstTimeFrequencyChangeLogP
	if Info.Transient then
		LogP = FirstTransientFrequencyChangeLogP
	end

	local Budget = Info.TotalBits
	local Tell = self.RangeDecoder:Tell()
	local TfSelectReserved = Info.Lm > 0 and Tell + LogP + 1 <= Budget
	if TfSelectReserved then
		Budget = Budget - 1
	end

	local Current = 0
	local Changed = 0

	for Band = Info.StartBand, Info.EndBand - 1 do
		if Tell + LogP <= Budget then
			Current = (Current + self.RangeDecoder:DecodeSymbolLogP(LogP)) % 2
			Tell = self.RangeDecoder:Tell()
			if Current ~= 0 then
				Changed = 1
			end
		end

		Info.TfChange[Band] = Current

		if Info.Transient then
			LogP = NextTransientFrequencyChangeLogP
		else
			LogP = NextTimeFrequencyChangeLogP
		end
	end

	Info.TfSelect = 0
	local Table = Tables.TfSelectTable[Info.Lm + 1]
	local Base = 4 * BoolIndex(Info.Transient)
	if TfSelectReserved and Table[Base + Changed + 1] ~= Table[Base + 2 + Changed + 1] then
		Info.TfSelect = self.RangeDecoder:DecodeSymbolLogP(1)
	end

	for Band = Info.StartBand, Info.EndBand - 1 do
		Info.TfChange[Band] = Table[Base + 2 * Info.TfSelect + Info.TfChange[Band] + 1]
	end
end

---Decode spread decision.
---@param Info table
function Decoder:DecodeSpread(Info)
	Info.Spread = Tables.DefaultSpreadDecision
	if self.RangeDecoder:Tell() + 4 <= Info.TotalBits then
		Info.Spread = self.RangeDecoder:DecodeSymbolWithICDF(Tables.IcdfSpread)
	end
end

---Decode dynamic allocation.
---@param Info table
---@param TotalBitsEighth number
---@return number
function Decoder:DecodeDynamicAllocation(Info, TotalBitsEighth)
	local Caps = Allocation.AllocationCaps(Info.Lm, Info.ChannelCount)
	local DynamicAllocationLogP = InitialDynamicAllocationLogP
	local TellFrac = self.RangeDecoder:TellFrac()

	for Band = Info.StartBand, Info.EndBand - 1 do
		local Width = Info.ChannelCount * ((BandEdge(Band + 1) - BandEdge(Band)) * (2 ^ Info.Lm))
		local Quanta = Min(Width * (2 ^ BitResolution), Max(AllocationTrimBitCost * (2 ^ BitResolution), Width))
		local LoopLogP = DynamicAllocationLogP
		local Boost = 0

		while TellFrac + LoopLogP * (2 ^ BitResolution) < TotalBitsEighth and Boost < Caps[Band] do
			local Flag = self.RangeDecoder:DecodeSymbolLogP(LoopLogP)
			TellFrac = self.RangeDecoder:TellFrac()
			if Flag == 0 then
				break
			end

			Boost = Boost + Quanta
			if Quanta >= TotalBitsEighth then
				TotalBitsEighth = 0
			else
				TotalBitsEighth = TotalBitsEighth - Quanta
			end

			LoopLogP = 1
		end

		Info.BandBoost[Band] = Boost
		if Boost > 0 then
			DynamicAllocationLogP = Max(MinDynamicAllocationLogP, DynamicAllocationLogP - 1)
		end
	end

	return TotalBitsEighth
end

---Decode allocation trim.
---@param Info table
---@param TotalBitsEighth number
function Decoder:DecodeAllocationTrim(Info, TotalBitsEighth)
	Info.AllocationTrim = Tables.DefaultAllocationTrim
	if self.RangeDecoder:TellFrac() + AllocationTrimBitCost * (2 ^ BitResolution) <= TotalBitsEighth then
		Info.AllocationTrim = self.RangeDecoder:DecodeSymbolWithICDF(Tables.IcdfAllocationTrim)
	end
end

---Decode allocation header.
---@param Info table
function Decoder:DecodeAllocationHeader(Info)
	self:DecodeTimeFrequencyChanges(Info)
	self:DecodeSpread(Info)
	local TotalBitsEighth = self:DecodeDynamicAllocation(Info, Info.TotalBits * (2 ^ BitResolution))
	self:DecodeAllocationTrim(Info, TotalBitsEighth)
end

---Decode allocation and first fine energy pass.
---@param Info table
function Decoder:DecodeAllocationAndFineEnergy(Info)
	local Bits = Info.TotalBits * (2 ^ BitResolution) - self.RangeDecoder:TellFrac() - 1
	Info.AntiCollapseRsv = 0

	if Info.Transient and Info.Lm >= 2 and Bits >= (Info.Lm + 2) * (2 ^ BitResolution) then
		Info.AntiCollapseRsv = 2 ^ BitResolution
	end

	Bits = Bits - Info.AntiCollapseRsv
	Info.Allocation = Allocation.Compute(Info, Bits, self.RangeDecoder)
	Allocation.DecodeFineEnergy(self, Info, Info.Allocation.FineQuant)
end

---Decode CELT frame side information.
---@param Data string
---@param IsStereo boolean
---@return boolean
---@return table|string
function Decoder:DecodeFrameSideInfo(Data, IsStereo)
	local ChannelCount = IsStereo and 2 or 1
	local Info = {
		Lm = 3,
		TotalBits = #Data * 8,
		StartBand = 0,
		EndBand = MaxBands,
		ChannelCount = ChannelCount,
		OutputChannelCount = ChannelCount,
		OutputSampleRate = SampleRate,
		Silence = false,
		PostFilter = {},
		Transient = false,
		ShortBlockCount = 0,
		IntraEnergy = false,
		TfChange = CreateBandVector(0),
		TfSelect = 0,
		Spread = Tables.DefaultSpreadDecision,
		BandBoost = CreateBandVector(0),
		AllocationTrim = Tables.DefaultAllocationTrim,
		AntiCollapseRsv = 0,
	}

	self.RangeDecoder = OpusRangeDecoder.New(Data)
	self:DecodeSilenceFlag(Info)
	if Info.Silence then
		return true, Info
	end

	self:DecodePostFilter(Info)
	self:DecodeTransientFlag(Info)
	self:DecodeIntraEnergyFlag(Info)
	self:PrepareCoarseEnergyHistory(Info)
	self:DecodeCoarseEnergy(Info)
	self:DecodeAllocationHeader(Info)
	self:DecodeAllocationAndFineEnergy(Info)

	return true, Info
end

---Convert log energy to amplitude.
---@param Info table
---@return table
function Decoder:Log2Amp(Info)
	local Energy = { [0] = CreateBandVector(0), [1] = CreateBandVector(0) }

	for Channel = 0, Info.ChannelCount - 1 do
		for Band = Info.StartBand, Info.EndBand - 1 do
			local LogEnergy = Min(32, self.PreviousLogE[Channel][Band] + EnergyMeans[Band + 1])
			Energy[Channel][Band] = 2 ^ LogEnergy
		end
	end

	return Energy
end

---Denormalize bands.
---@param Info table
---@param Input table
---@param Output table
---@param BandEnergy table
local function DenormaliseBands(Info, Input, Output, BandEnergy)
	local Scale = 2 ^ Info.Lm

	for Band = Info.StartBand, Info.EndBand - 1 do
		local Start = Scale * BandEdge(Band)
		local Stop = Scale * BandEdge(Band + 1)

		for Index = Start, Stop - 1 do
			Output[Index + 1] = (Input[Index + 1] or 0) * (BandEnergy[Band] or 0)
		end
	end
end

---Inverse complex DFT.
---@param Input table
---@return table
local function InverseComplexDFT(Input)
	local Count = #Input
	if Count == 1 then
		return {
			{
				R = Input[1].R,
				I = Input[1].I,
			},
		}
	end

	local Factor = nil
	for Candidate = 2, math.floor(math.sqrt(Count)) do
		if Count % Candidate == 0 then
			Factor = Candidate
			break
		end
	end

	if Factor then
		local InnerCount = Count / Factor
		local SubTransforms = {}

		for FactorIndex = 0, Factor - 1 do
			local SubInput = {}

			for InnerIndex = 0, InnerCount - 1 do
				SubInput[InnerIndex + 1] = Input[FactorIndex + Factor * InnerIndex + 1]
			end

			SubTransforms[FactorIndex + 1] = InverseComplexDFT(SubInput)
		end

		local Output = {}
		for OuterIndex = 0, Factor - 1 do
			for InnerIndex = 0, InnerCount - 1 do
				local K = InnerIndex + InnerCount * OuterIndex
				local SumR = 0
				local SumI = 0

				for FactorIndex = 0, Factor - 1 do
					local Value = SubTransforms[FactorIndex + 1][InnerIndex + 1]
					local Angle = 2 * math.pi * K * FactorIndex / Count
					local Cosine = math.cos(Angle)
					local Sine = math.sin(Angle)

					SumR = SumR + Value.R * Cosine - Value.I * Sine
					SumI = SumI + Value.R * Sine + Value.I * Cosine
				end

				Output[K + 1] = { R = SumR, I = SumI }
			end
		end

		return Output
	end

	local Output = {}

	for K = 0, Count - 1 do
		local SumR = 0
		local SumI = 0

		for M = 0, Count - 1 do
			local Value = Input[M + 1]
			local Angle = 2 * math.pi * K * M / Count
			local Cosine = math.cos(Angle)
			local Sine = math.sin(Angle)

			SumR = SumR + Value.R * Cosine - Value.I * Sine
			SumI = SumI + Value.R * Sine + Value.I * Cosine
		end

		Output[K + 1] = { R = SumR, I = SumI }
	end

	return Output
end

---Inverse MDCT.
---@param Frequency table
---@return table
local function InverseMdct(Frequency)
	local Count2 = #Frequency
	local Count = 2 * Count2
	local Count4 = Count / 4
	local Sine = 2 * math.pi * 0.125 / Count
	local PreRotated = {}

	for Index = 0, Count4 - 1 do
		local Xp1 = Frequency[2 * Index + 1] or 0
		local Xp2 = Frequency[Count2 - 2 * Index] or 0
		local Cosine = math.cos(2 * math.pi * Index / Count)
		local SineQuarter = math.cos(2 * math.pi * (Count4 - Index) / Count)
		local Yr = -Xp2 * Cosine + Xp1 * SineQuarter
		local Yi = -Xp2 * SineQuarter - Xp1 * Cosine

		PreRotated[Index + 1] = {
			R = Yr - Yi * Sine,
			I = Yi + Yr * Sine,
		}
	end

	local FftOut = InverseComplexDFT(PreRotated)
	local PostRotated = {}

	for Index = 0, Count4 - 1 do
		local Value = FftOut[Index + 1]
		local Cosine = math.cos(2 * math.pi * Index / Count)
		local SineQuarter = math.cos(2 * math.pi * (Count4 - Index) / Count)
		local Yr = Value.R * Cosine - Value.I * SineQuarter
		local Yi = Value.I * Cosine + Value.R * SineQuarter

		PostRotated[2 * Index + 1] = Yr - Yi * Sine
		PostRotated[2 * Index + 2] = Yi + Yr * Sine
	end

	local Deshuffled = {}
	for Index = 0, Count4 - 1 do
		Deshuffled[2 * Index + 1] = -(PostRotated[2 * Index + 1] or 0)
		Deshuffled[2 * Index + 2] = PostRotated[Count2 - 2 * Index] or 0
	end

	local Overlap = ShortBlockSampleCount
	local Output = CreateSampleVector(Count2 + Overlap, 0)
	local LeftPlain = Count4 - Overlap / 2

	for Index = 0, LeftPlain - 1 do
		Output[Count4 + Overlap / 2 - Index] = Deshuffled[Count4 - Index] or 0
	end

	for Index = LeftPlain, Count4 - 1 do
		local X1 = Deshuffled[Count4 - Index] or 0
		local WindowIndex = Index - LeftPlain

		Output[WindowIndex + 1] = Output[WindowIndex + 1] - CeltWindow[WindowIndex + 1] * X1
		Output[Count4 + Overlap / 2 - Index] = Output[Count4 + Overlap / 2 - Index]
			+ CeltWindow[Overlap - WindowIndex] * X1
	end

	for Index = 0, LeftPlain - 1 do
		Output[Count4 + Overlap / 2 + Index + 1] = Deshuffled[Count4 + Index + 1] or 0
	end

	for Index = LeftPlain, Count4 - 1 do
		local X2 = Deshuffled[Count4 + Index + 1] or 0
		local WindowIndex = Index - LeftPlain

		Output[Count2 + Overlap - WindowIndex] = CeltWindow[WindowIndex + 1] * X2
		Output[Count4 + Overlap / 2 + Index + 1] = CeltWindow[Overlap - WindowIndex] * X2
	end

	return Output
end

---Inverse transform one channel.
---@param Frequency table
---@param Channel number
---@param Info table
---@return table
function Decoder:InverseTransformChannel(Frequency, Channel, Info)
	local FrameSampleCount = #Frequency
	local Accumulated = CreateSampleVector(FrameSampleCount + ShortBlockSampleCount, 0)
	local BlockCount = 1
	local BlockSampleCount = FrameSampleCount
	local Stride = 1

	if Info.Transient then
		BlockCount = 2 ^ Info.Lm
		BlockSampleCount = ShortBlockSampleCount
		Stride = BlockCount
	end

	for Block = 0, BlockCount - 1 do
		local BlockFrequency = {}

		if Info.Transient then
			for Index = 0, BlockSampleCount - 1 do
				BlockFrequency[Index + 1] = Frequency[Block + Index * Stride + 1] or 0
			end
		else
			for Index = 1, BlockSampleCount do
				BlockFrequency[Index] = Frequency[Index] or 0
			end
		end

		local BlockTime = InverseMdct(BlockFrequency)
		for Index = 0, BlockSampleCount + ShortBlockSampleCount - 1 do
			Accumulated[Block * BlockSampleCount + Index + 1] = Accumulated[Block * BlockSampleCount + Index + 1]
				+ (BlockTime[Index + 1] or 0)
		end
	end

	local Time = CreateSampleVector(FrameSampleCount, 0)

	for Index = 1, ShortBlockSampleCount do
		Time[Index] = Accumulated[Index] + (self.Overlap[Channel][Index] or 0)
	end

	for Index = ShortBlockSampleCount + 1, FrameSampleCount do
		Time[Index] = Accumulated[Index]
	end

	for Index = 1, ShortBlockSampleCount do
		self.Overlap[Channel][Index] = Accumulated[FrameSampleCount + Index] or 0
	end

	return Time
end

---Apply deemphasis and interleave samples.
---@param TimeX table
---@param TimeY table?
---@param FrameSampleCount number
---@param ChannelCount number
---@return table
function Decoder:DeemphasisAndInterleave(TimeX, TimeY, FrameSampleCount, ChannelCount)
	local Output = CreateSampleVector(FrameSampleCount * ChannelCount, 0)
	local OutputSample = 0

	for Sample = 1, FrameSampleCount do
		local Left = TimeX[Sample] + self.PreemphasisMem[0]
		self.PreemphasisMem[0] = 0.85000610 * Left

		Output[OutputSample * ChannelCount + 1] = Left / 32768

		if ChannelCount == 2 then
			local Right = TimeY[Sample] + self.PreemphasisMem[1]
			self.PreemphasisMem[1] = 0.85000610 * Right
			Output[OutputSample * ChannelCount + 2] = Right / 32768
		end

		OutputSample = OutputSample + 1
	end

	return Output
end

---Get a post-filter sample from history or current frame.
---@param History table
---@param Time table
---@param Index number
---@return number
local function PostFilterSample(History, Time, Index)
	if Index >= 0 then
		return Time[Index + 1] or 0
	end

	return History[#History + Index + 1] or 0
end

---Calculate one pitch post-filter contribution.
---@param History table
---@param Time table
---@param Index number
---@param Period number
---@param GainOne number
---@param GainTwo number
---@param GainThree number
---@return number
local function PostFilterContribution(History, Time, Index, Period, GainOne, GainTwo, GainThree)
	return GainOne * PostFilterSample(History, Time, Index - Period)
		+ GainTwo
			* (
				PostFilterSample(History, Time, Index - Period + 1)
				+ PostFilterSample(History, Time, Index - Period - 1)
			)
		+ GainThree
			* (
				PostFilterSample(History, Time, Index - Period + 2)
				+ PostFilterSample(History, Time, Index - Period - 2)
			)
end

---Get scaled post-filter taps.
---@param Gain number
---@param Tapset number
---@return number
---@return number
---@return number
local function PostFilterTaps(Gain, Tapset)
	local Taps = PostFilterGains[Tapset + 1] or PostFilterGains[1]

	return Gain * Taps[1], Gain * Taps[2], Gain * Taps[3]
end

---Apply a CELT pitch post-filter segment.
---@param Time table
---@param History table
---@param StartIndex number
---@param Count number
---@param PeriodOld number
---@param PeriodNew number
---@param GainOld number
---@param GainNew number
---@param TapsetOld number
---@param TapsetNew number
local function ApplyPostFilterSegment(
	Time,
	History,
	StartIndex,
	Count,
	PeriodOld,
	PeriodNew,
	GainOld,
	GainNew,
	TapsetOld,
	TapsetNew
)
	if Count <= 0 or (GainOld == 0 and GainNew == 0) then
		return
	end

	PeriodOld = Max(PeriodOld, PostFilterMinPeriod)
	PeriodNew = Max(PeriodNew, PostFilterMinPeriod)

	local OldOne, OldTwo, OldThree = PostFilterTaps(GainOld, TapsetOld)
	local NewOne, NewTwo, NewThree = PostFilterTaps(GainNew, TapsetNew)
	local Overlap = ShortBlockSampleCount

	if GainOld == GainNew and PeriodOld == PeriodNew and TapsetOld == TapsetNew then
		Overlap = 0
	end

	local TransitionCount = Min(Overlap, Count)
	for Offset = 0, TransitionCount - 1 do
		local Index = StartIndex + Offset
		local Window = CeltWindow[Offset + 1] or 1
		local Fade = Window * Window
		local OldContribution = PostFilterContribution(History, Time, Index, PeriodOld, OldOne, OldTwo, OldThree)
		local NewContribution = PostFilterContribution(History, Time, Index, PeriodNew, NewOne, NewTwo, NewThree)

		Time[Index + 1] = (Time[Index + 1] or 0) + (1 - Fade) * OldContribution + Fade * NewContribution
	end

	if GainNew == 0 then
		return
	end

	for Offset = TransitionCount, Count - 1 do
		local Index = StartIndex + Offset
		Time[Index + 1] = (Time[Index + 1] or 0)
			+ PostFilterContribution(History, Time, Index, PeriodNew, NewOne, NewTwo, NewThree)
	end
end

---Append post-filtered samples to channel history.
---@param Channel number
---@param Time table
function Decoder:AppendPostFilterHistory(Channel, Time)
	local History = self.PostFilterHistory[Channel]
	local Total = #History + #Time
	local Start = Max(1, Total - PostFilterHistorySize + 1)
	local Updated = {}

	for Index = Start, Total do
		if Index <= #History then
			Updated[#Updated + 1] = History[Index]
		else
			Updated[#Updated + 1] = Time[Index - #History]
		end
	end

	self.PostFilterHistory[Channel] = Updated
end

---Apply decoded CELT pitch post-filter state.
---@param Info table
---@param TimeX table
---@param TimeY table?
function Decoder:ApplyPostFilter(Info, TimeX, TimeY)
	local State = self.PostFilter
	local NextPeriod = 0
	local NextGain = 0
	local NextTapset = 0

	if Info.PostFilter and Info.PostFilter.Enabled then
		NextPeriod = Info.PostFilter.Period or 0
		NextGain = Info.PostFilter.Gain or 0
		NextTapset = Info.PostFilter.Tapset or 0
	end

	State.Period = Max(State.Period or 0, PostFilterMinPeriod)
	State.PeriodOld = Max(State.PeriodOld or 0, PostFilterMinPeriod)

	local Times = { [0] = TimeX, [1] = TimeY }
	for Channel = 0, Info.OutputChannelCount - 1 do
		local Time = Times[Channel]
		if Time then
			local History = self.PostFilterHistory[Channel]

			ApplyPostFilterSegment(
				Time,
				History,
				0,
				ShortBlockSampleCount,
				State.PeriodOld,
				State.Period,
				State.GainOld or 0,
				State.Gain or 0,
				State.TapsetOld or 0,
				State.Tapset or 0
			)

			if Info.Lm ~= 0 then
				ApplyPostFilterSegment(
					Time,
					History,
					ShortBlockSampleCount,
					#Time - ShortBlockSampleCount,
					State.Period,
					NextPeriod,
					State.Gain or 0,
					NextGain,
					State.Tapset or 0,
					NextTapset
				)
			end

			self:AppendPostFilterHistory(Channel, Time)
		end
	end

	State.PeriodOld = State.Period
	State.GainOld = State.Gain
	State.TapsetOld = State.Tapset
	State.Period = NextPeriod
	State.Gain = NextGain
	State.Tapset = NextTapset

	if Info.Lm ~= 0 then
		State.PeriodOld = State.Period
		State.GainOld = State.Gain
		State.TapsetOld = State.Tapset
	end
end

---Denormalize and synthesize PCM.
---@param Info table
---@param X table
---@param Y table?
---@param BandEnergy table
---@return table
function Decoder:DenormaliseAndSynthesize(Info, X, Y, BandEnergy)
	local FrameSampleCount = #X
	local FrequencyX = CreateSampleVector(FrameSampleCount, 0)
	DenormaliseBands(Info, X, FrequencyX, BandEnergy[0])

	local FrequencyY = nil
	if Info.ChannelCount == 2 then
		FrequencyY = CreateSampleVector(FrameSampleCount, 0)
		DenormaliseBands(Info, Y, FrequencyY, BandEnergy[1])
	end

	local TimeX = self:InverseTransformChannel(FrequencyX, 0, Info)
	if Info.OutputChannelCount == 1 then
		self:ApplyPostFilter(Info, TimeX, nil)
		return self:DeemphasisAndInterleave(TimeX, nil, FrameSampleCount, 1)
	end

	local TimeY = self:InverseTransformChannel(FrequencyY, 1, Info)
	self:ApplyPostFilter(Info, TimeX, TimeY)
	return self:DeemphasisAndInterleave(TimeX, TimeY, FrameSampleCount, 2)
end

---Update log-energy history.
---@param Info table
function Decoder:UpdateLogEHistory(Info)
	if Info.ChannelCount == 1 then
		for Band = 0, MaxBands - 1 do
			self.PreviousLogE[1][Band] = self.PreviousLogE[0][Band]
		end
	end

	if not Info.Transient then
		for Channel = 0, 1 do
			for Band = 0, MaxBands - 1 do
				self.PreviousLogE2[Channel][Band] = self.PreviousLogE1[Channel][Band]
				self.PreviousLogE1[Channel][Band] = self.PreviousLogE[Channel][Band]
			end
		end

		return
	end

	for Channel = 0, 1 do
		for Band = 0, MaxBands - 1 do
			self.PreviousLogE1[Channel][Band] = Min(self.PreviousLogE1[Channel][Band], self.PreviousLogE[Channel][Band])
		end
	end
end

---Reset inactive band history.
---@param Info table
function Decoder:ResetInactiveBandState(Info)
	for Channel = 0, 1 do
		for Band = 0, Info.StartBand - 1 do
			self.PreviousLogE[Channel][Band] = 0
			self.PreviousLogE1[Channel][Band] = -28
			self.PreviousLogE2[Channel][Band] = -28
		end

		for Band = Info.EndBand, MaxBands - 1 do
			self.PreviousLogE[Channel][Band] = 0
			self.PreviousLogE1[Channel][Band] = -28
			self.PreviousLogE2[Channel][Band] = -28
		end
	end
end

---Decode a CELT-only Opus frame payload.
---@param Data string
---@param IsStereo boolean
---@return boolean
---@return table|string
function Decoder:DecodeFrame(Data, IsStereo)
	local Ok, Info = self:DecodeFrameSideInfo(Data, IsStereo)
	if not Ok then
		return false, Info
	end

	local FrameSampleCount = ShortBlockSampleCount * (2 ^ Info.Lm)
	local X = CreateSampleVector(FrameSampleCount, 0)
	local Y = IsStereo and CreateSampleVector(FrameSampleCount, 0) or nil

	if Info.Silence then
		for Channel = 0, Info.ChannelCount - 1 do
			for Band = Info.StartBand, Info.EndBand - 1 do
				self.PreviousLogE[Channel][Band] = -28
			end
		end
	else
		local State = {
			RangeDecoder = self.RangeDecoder,
			Seed = self.Rng,
		}
		local TotalBits = Info.TotalBits * (2 ^ BitResolution) - Info.AntiCollapseRsv
		Bands.QuantAllBands(Info, X, Y, TotalBits, State)

		if Info.AntiCollapseRsv > 0 then
			self.RangeDecoder:DecodeRawBits(1)
		end

		local BitsLeft = Info.TotalBits - self.RangeDecoder:Tell()
		Allocation.FinalizeFineEnergy(self, Info, Info.Allocation.FineQuant, Info.Allocation.FinePriority, BitsLeft)
		self.Rng = State.Seed or self.Rng
	end

	local BandEnergy = self:Log2Amp(Info)
	local Output = self:DenormaliseAndSynthesize(Info, X, Y, BandEnergy)
	self:UpdateLogEHistory(Info)
	self:ResetInactiveBandState(Info)
	self.Rng = self.RangeDecoder:FinalRange()

	return true, {
		Samples = Output,
		SampleRate = SampleRate,
		Channels = Info.OutputChannelCount,
		FrameSamples = FrameSampleCount,
		FinalRange = self.Rng,
	}
end

---Decode a CELT-only Opus packet.
---@param Packet string
---@return boolean
---@return table|string
function Decoder:DecodePacket(Packet)
	if type(Packet) ~= "string" or #Packet < 2 then
		return false, "Opus packet is empty."
	end

	local Toc = string.byte(Packet, 1)
	local Config = math.floor(Toc / 8)
	local IsStereo = (math.floor(Toc / 4) % 2) ~= 0
	local FrameCode = Toc % 4

	if Config ~= 31 then
		return false, "Only fullband 20 ms CELT-only Opus packets are supported."
	end

	if FrameCode ~= 0 then
		return false, "Only single-frame Opus packets are supported."
	end

	return self:DecodeFrame(Packet:sub(2), IsStereo)
end

---Create a CELT decoder.
---@return table
function OpusCeltDecoder.New()
	local self = setmetatable({}, Decoder)
	self:Reset()
	return self
end

-- Return Opus CELT decoder module.
return OpusCeltDecoder
end)
__bundle_register("Audio/OpusCeltPulses", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus CELT pulse decoder module.
local OpusCeltPulses = {}

---Clear pulse vector.
---@param Output table
---@param Count number
local function ClearOutput(Output, Count)
	for Index = 1, Count do
		Output[Index] = 0
	end
end

---Advance the CWRS row by one dimension.
---@param Row table
---@param Start number
---@param Length number
---@param Value0 number
local function CwrsNextRow(Row, Start, Length, Value0)
	local Value = Value0
	local Last = Start + Length - 1

	for Index = Start + 1, Last do
		local Next = Row[Index] + Row[Index - 1] + Value
		Row[Index - 1] = Value
		Value = Next
	end

	Row[Last] = Value
end

---Rewind the CWRS row after one coefficient is decoded.
---@param Row table
---@param Length number
---@param Value0 number
local function CwrsPreviousRow(Row, Length, Value0)
	local Value = Value0

	for Index = 2, Length do
		local Next = Row[Index] - Row[Index - 1] - Value
		Row[Index - 1] = Value
		Value = Next
	end

	Row[Length] = Value
end

---Build the CWRS recurrence row for a vector size and pulse count.
---@param Count number
---@param PulseCount number
---@return table
local function CwrsUrow(Count, PulseCount)
	local Row = {}

	for Index = 1, PulseCount + 2 do
		Row[Index] = 0
	end

	if Count == 0 then
		Row[1] = 1
		return Row
	end

	Row[1] = 0
	if #Row > 1 then
		Row[2] = 1
	end

	if Count == 1 then
		for Index = 3, #Row do
			Row[Index] = 1
		end

		return Row
	end

	for Pulses = 2, PulseCount + 1 do
		Row[Pulses + 1] = (Pulses * 2) - 1
	end

	for Index = 2, Count - 1 do
		CwrsNextRow(Row, 2, PulseCount + 1, 1)
	end

	return Row
end

---Decode a CWRS index into pulse signs and magnitudes.
---@param Output table
---@param Count number
---@param PulseCount number
---@param Index number
---@param Row table
local function CwrsDecode(Output, Count, PulseCount, Index, Row)
	for OutputIndex = 1, Count do
		local Probability = Row[PulseCount + 2]
		local Negative = Index >= Probability

		if Negative then
			Index = Index - Probability
		end

		local Magnitude = PulseCount
		Probability = Row[PulseCount + 1]

		while Probability > Index do
			PulseCount = PulseCount - 1
			Probability = Row[PulseCount + 1]
		end

		Index = Index - Probability
		Magnitude = Magnitude - PulseCount

		if Negative then
			Output[OutputIndex] = -Magnitude
		else
			Output[OutputIndex] = Magnitude
		end

		CwrsPreviousRow(Row, PulseCount + 2, 0)
	end
end

---Decode CELT PVQ pulses.
---@param Output table
---@param Count number
---@param PulseCount number
---@param RangeDecoder table
function OpusCeltPulses.DecodePulses(Output, Count, PulseCount, RangeDecoder)
	ClearOutput(Output, Count)

	if PulseCount <= 0 then
		return
	end

	local Row = CwrsUrow(Count, PulseCount)
	local Total = Row[PulseCount + 1] + Row[PulseCount + 2]
	local Index = RangeDecoder:DecodeUniform(Total)

	CwrsDecode(Output, Count, PulseCount, Index, Row)
end

OpusCeltPulses.CwrsUrow = CwrsUrow
OpusCeltPulses.CwrsNextRow = CwrsNextRow
OpusCeltPulses.CwrsPreviousRow = CwrsPreviousRow
OpusCeltPulses.CwrsDecode = CwrsDecode

-- Return Opus CELT pulse decoder module.
return OpusCeltPulses
end)
__bundle_register("Audio/OpusCeltPvq", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus CELT PVQ module.
local OpusCeltPvq = {}

---@module Audio.OpusCeltPulses
local Pulses = require("Audio/OpusCeltPulses")

-- Constants.
local SpreadNone = 0
local SpreadLight = 1
local SpreadNormal = 2
local SpreadAggressive = 3
local NormScaling = 1

---Get reusable integer scratch space.
---@param State table
---@param Count number
---@return table
local function IntScratch(State, Count)
	State.PulseScratch = State.PulseScratch or {}

	for Index = 1, Count do
		State.PulseScratch[Index] = 0
	end

	for Index = Count + 1, #State.PulseScratch do
		State.PulseScratch[Index] = nil
	end

	return State.PulseScratch
end

---Calculate vector energy.
---@param Vector table
---@param Count number
---@param Offset number?
---@return number
local function VectorEnergy(Vector, Count, Offset)
	local Energy = 0
	local Start = Offset or 1

	for Index = 0, Count - 1 do
		local Value = Vector[Start + Index]
		Energy = Energy + Value * Value
	end

	return Energy
end

---Normalize PVQ pulse residual into a floating vector.
---@param PulseVector table
---@param Output table
---@param Count number
---@param Energy number
---@param Gain number
---@param Offset number?
local function NormaliseResidual(PulseVector, Output, Count, Energy, Gain, Offset)
	local Start = Offset or 1

	if Energy <= 0 then
		for Index = 0, Count - 1 do
			Output[Start + Index] = 0
		end

		return
	end

	local Scale = Gain / math.sqrt(Energy)

	for Index = 0, Count - 1 do
		Output[Start + Index] = PulseVector[Index + 1] * Scale
	end
end

---Extract the transient-block collapse mask.
---@param PulseVector table
---@param Count number
---@param Blocks number
---@return number
local function ExtractCollapseMask(PulseVector, Count, Blocks)
	if Blocks <= 1 then
		return 1
	end

	local BlockSize = Count / Blocks
	local Mask = 0

	for Block = 0, Blocks - 1 do
		for Index = 1, BlockSize do
			if PulseVector[Block * BlockSize + Index] ~= 0 then
				Mask = Mask + 2 ^ Block
				break
			end
		end
	end

	return Mask
end

---Renormalize a vector to a requested gain.
---@param Vector table
---@param Count number
---@param Gain number
---@param Offset number?
local function RenormaliseVector(Vector, Count, Gain, Offset)
	local Start = Offset or 1
	local Energy = 1e-27

	for Index = 0, Count - 1 do
		local Value = Vector[Start + Index]
		Energy = Energy + Value * Value
	end

	local Scale = Gain / math.sqrt(Energy)

	for Index = 0, Count - 1 do
		Vector[Start + Index] = Vector[Start + Index] * Scale
	end
end

---Apply one spreading rotation pass.
---@param Vector table
---@param Offset number
---@param Length number
---@param Stride number
---@param Cosine number
---@param Sine number
local function ExpRotationOne(Vector, Offset, Length, Stride, Cosine, Sine)
	for Index = 0, Length - Stride - 1 do
		local FirstIndex = Offset + Index
		local SecondIndex = FirstIndex + Stride
		local First = Vector[FirstIndex]
		local Second = Vector[SecondIndex]

		Vector[SecondIndex] = Cosine * Second + Sine * First
		Vector[FirstIndex] = Cosine * First - Sine * Second
	end

	for Index = Length - (2 * Stride) - 1, 0, -1 do
		local FirstIndex = Offset + Index
		local SecondIndex = FirstIndex + Stride
		local First = Vector[FirstIndex]
		local Second = Vector[SecondIndex]

		Vector[SecondIndex] = Cosine * Second + Sine * First
		Vector[FirstIndex] = Cosine * First - Sine * Second
	end
end

---Apply CELT spreading rotation.
---@param Vector table
---@param Offset number
---@param Length number
---@param Direction number
---@param Stride number
---@param PulseCount number
---@param Spread number
local function ExpRotation(Vector, Offset, Length, Direction, Stride, PulseCount, Spread)
	if 2 * PulseCount >= Length or Spread == SpreadNone then
		return
	end

	local Factors = { 15, 10, 5 }
	local Factor = Factors[Spread]
	local Gain = Length / (Length + Factor * PulseCount)
	local Theta = 0.5 * Gain * Gain
	local Cosine = math.cos(0.5 * math.pi * Theta)
	local Sine = math.sin(0.5 * math.pi * Theta)
	local SecondStride = 0

	if Length >= 8 * Stride then
		SecondStride = 1

		while ((SecondStride * SecondStride + SecondStride) * Stride + math.floor(Stride / 4)) < Length do
			SecondStride = SecondStride + 1
		end
	end

	local BlockLength = Length / Stride

	for Block = 0, Stride - 1 do
		local Start = Offset + Block * BlockLength

		if Direction < 0 then
			if SecondStride ~= 0 then
				ExpRotationOne(Vector, Start, BlockLength, SecondStride, Sine, Cosine)
			end

			ExpRotationOne(Vector, Start, BlockLength, 1, Cosine, Sine)
		else
			ExpRotationOne(Vector, Start, BlockLength, 1, Cosine, -Sine)

			if SecondStride ~= 0 then
				ExpRotationOne(Vector, Start, BlockLength, SecondStride, Sine, -Cosine)
			end
		end
	end
end

---Decode and unquantize a CELT PVQ vector.
---@param Output table
---@param Count number
---@param PulseCount number
---@param Spread number
---@param Blocks number
---@param RangeDecoder table
---@param Gain number
---@param State table
---@param Offset number?
---@return number
local function AlgUnquant(Output, Count, PulseCount, Spread, Blocks, RangeDecoder, Gain, State, Offset)
	local Start = Offset or 1
	local PulseVector = IntScratch(State, Count)

	Pulses.DecodePulses(PulseVector, Count, PulseCount, RangeDecoder)

	local Energy = 0
	for Index = 1, Count do
		Energy = Energy + PulseVector[Index] * PulseVector[Index]
	end

	NormaliseResidual(PulseVector, Output, Count, Energy, Gain, Start)
	ExpRotation(Output, Start, Count, -1, Blocks, PulseCount, Spread)

	return ExtractCollapseMask(PulseVector, Count, Blocks)
end

OpusCeltPvq.SpreadNone = SpreadNone
OpusCeltPvq.SpreadLight = SpreadLight
OpusCeltPvq.SpreadNormal = SpreadNormal
OpusCeltPvq.SpreadAggressive = SpreadAggressive
OpusCeltPvq.NormScaling = NormScaling
OpusCeltPvq.AlgUnquant = AlgUnquant
OpusCeltPvq.NormaliseResidual = NormaliseResidual
OpusCeltPvq.ExtractCollapseMask = ExtractCollapseMask
OpusCeltPvq.RenormaliseVector = RenormaliseVector
OpusCeltPvq.ExpRotation = ExpRotation
OpusCeltPvq.VectorEnergy = VectorEnergy

-- Return Opus CELT PVQ module.
return OpusCeltPvq
end)
