__bundle_register("Audio/OpusPcmDecoder", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus PCM decoder module.
local OpusPcmDecoder = {}
local OpusStream = {}
OpusStream.__index = OpusStream

---@module Audio.OpusCeltDecoder
local OpusCeltDecoder = require("Audio/OpusCeltDecoder")

-- Constants.
local SampleRate = 48000
local Channels = 2
local BitsPerSample = 16
local BytesPerSample = 2
local DefaultFrameLimit = 240
local DefaultYieldAfterSeconds = 0.03
local DefaultYieldEveryFrames = 6

---Write little-endian unsigned 16-bit integer.
---@param Value number
---@return string
local function U16(Value)
	Value = math.floor(Value) % 65536
	return string.char(Value % 256, math.floor(Value / 256) % 256)
end

---Write little-endian unsigned 32-bit integer.
---@param Value number
---@return string
local function U32(Value)
	Value = math.floor(Value) % 4294967296
	local B1 = Value % 256
	local B2 = math.floor(Value / 256) % 256
	local B3 = math.floor(Value / 65536) % 256
	local B4 = math.floor(Value / 16777216) % 256

	return string.char(B1, B2, B3, B4)
end

---Read little-endian unsigned 16-bit integer from a string.
---@param Body string
---@param Position number
---@return number
local function ReadU16(Body, Position)
	local First = string.byte(Body, Position) or 0
	local Second = string.byte(Body, Position + 1) or 0

	return First + Second * 256
end

---Build WAV body.
---@param Chunks table
---@param SampleCount number
---@return string
local function BuildWav(Chunks, SampleCount)
	local Data = table.concat(Chunks)
	local DataSize = #Data
	local ByteRate = SampleRate * Channels * BytesPerSample
	local BlockAlign = Channels * BytesPerSample

	return table.concat({
		"RIFF",
		U32(36 + DataSize),
		"WAVE",
		"fmt ",
		U32(16),
		U16(1),
		U16(Channels),
		U32(SampleRate),
		U32(ByteRate),
		U16(BlockAlign),
		U16(BitsPerSample),
		"data",
		U32(DataSize),
		Data,
	})
end

---Convert float sample to little-endian PCM16.
---@param Sample number
---@return string
local function FloatToPcm16(Sample)
	if Sample > 1 then
		Sample = 1
	elseif Sample < -1 then
		Sample = -1
	end

	local Value
	if Sample >= 1 then
		Value = 32767
	elseif Sample <= -1 then
		Value = -32768
	elseif Sample < 0 then
		Value = math.floor(Sample * 32768 + 0.5)
	else
		Value = math.floor(Sample * 32767 + 0.5)
	end

	if Value < 0 then
		Value = Value + 65536
	end

	return U16(Value)
end

---Build PCM body from interleaved float samples.
---@param Samples table
---@param StartSample number
---@param SourceChannels number
---@return string
---@return number
---@return number
local function BuildPcm(Samples, StartSample, SourceChannels)
	local Chunks = {}
	local RmsSum = 0
	local RmsCount = 0
	SourceChannels = tonumber(SourceChannels) or Channels
	if SourceChannels < 1 then
		SourceChannels = 1
	end

	local StartFrame = math.floor((StartSample - 1) / SourceChannels)
	local FrameCount = math.floor(#Samples / SourceChannels)

	for Frame = StartFrame, FrameCount - 1 do
		local Left = Samples[Frame * SourceChannels + 1] or 0
		local Right = Left
		if SourceChannels >= 2 then
			Right = Samples[Frame * SourceChannels + 2] or Left
		end

		Chunks[#Chunks + 1] = FloatToPcm16(Left)
		Chunks[#Chunks + 1] = FloatToPcm16(Right)
		RmsSum = RmsSum + Left * Left + Right * Right
		RmsCount = RmsCount + 2
	end

	return table.concat(Chunks), RmsSum, RmsCount
end

---Parse OpusHead pre-skip.
---@param CodecPrivate string?
---@return number
local function ParsePreSkip(CodecPrivate)
	if type(CodecPrivate) ~= "string" or #CodecPrivate < 12 then
		return 0
	end

	if CodecPrivate:sub(1, 8) ~= "OpusHead" then
		return 0
	end

	return ReadU16(CodecPrivate, 11)
end

---Build segment decode options.
---@param Self table
---@param Options table?
---@return number
---@return number
local function BuildSegmentDecodeOptions(Self, Options)
	Options = Options or {}

	local YieldAfterSeconds = Options.YieldAfterSeconds
	if YieldAfterSeconds == nil then
		YieldAfterSeconds = Self.YieldAfterSeconds
	end

	local YieldEveryFrames = Options.YieldEveryFrames
	if YieldEveryFrames == nil then
		YieldEveryFrames = Self.YieldEveryFrames
	end

	YieldAfterSeconds = tonumber(YieldAfterSeconds) or DefaultYieldAfterSeconds
	YieldEveryFrames = tonumber(YieldEveryFrames) or DefaultYieldEveryFrames

	if YieldAfterSeconds < 0 then
		YieldAfterSeconds = 0
	end

	if YieldEveryFrames < 1 then
		YieldEveryFrames = 1
	else
		YieldEveryFrames = math.floor(YieldEveryFrames)
	end

	return YieldAfterSeconds, YieldEveryFrames
end

---Yield during segment decode if needed.
---@param YieldAfterSeconds number
---@param LastYieldAt number
---@return number
local function YieldSegmentDecode(YieldAfterSeconds, LastYieldAt)
	if YieldAfterSeconds <= 0 then
		return LastYieldAt
	end

	if os.clock() - LastYieldAt < YieldAfterSeconds then
		return LastYieldAt
	end

	task.wait()
	return os.clock()
end

---Read a WAV segment from an Opus stream.
---@param FrameLimit number?
---@param Options table?
---@return boolean
---@return table|string
function OpusStream:ReadSegment(FrameLimit, Options)
	FrameLimit = tonumber(FrameLimit) or DefaultFrameLimit
	if FrameLimit <= 0 then
		FrameLimit = DefaultFrameLimit
	else
		FrameLimit = math.floor(FrameLimit)
	end

	local YieldAfterSeconds, YieldEveryFrames = BuildSegmentDecodeOptions(self, Options)
	local PacketCount = 0
	local AudioSampleCount = 0
	local Chunks = {}
	local RmsSum = 0
	local RmsCount = 0
	local StartFrame = self.FrameCount + 1
	local DecodeStartedAt = os.clock()
	local LastYieldAt = DecodeStartedAt
	local FramesSinceYield = 0

	while self.Position <= #self.Packets and PacketCount < FrameLimit do
		local PacketInfo = self.Packets[self.Position]
		local DecodeOk, Decoded = self.Decoder:DecodePacket(PacketInfo.Packet)
		if not DecodeOk then
			return false, Decoded
		end

		local Samples = Decoded.Samples
		local StartSample = 1
		if self.SkipSamples > 0 then
			local FrameSamples = math.floor(#Samples / Decoded.Channels)
			local SkipFrames = math.min(self.SkipSamples, FrameSamples)
			StartSample = SkipFrames * Decoded.Channels + 1
			self.SkipSamples = self.SkipSamples - SkipFrames
		end

		if StartSample <= #Samples then
			local Body, FrameRmsSum, FrameRmsCount = BuildPcm(Samples, StartSample, Decoded.Channels)
			Chunks[#Chunks + 1] = Body
			RmsSum = RmsSum + FrameRmsSum
			RmsCount = RmsCount + FrameRmsCount
			AudioSampleCount = AudioSampleCount + math.floor((#Samples - StartSample + 1) / Decoded.Channels)
		end

		PacketCount = PacketCount + 1
		self.FrameCount = self.FrameCount + 1
		self.Position = self.Position + 1
		FramesSinceYield = FramesSinceYield + 1

		if FramesSinceYield >= YieldEveryFrames then
			LastYieldAt = YieldSegmentDecode(YieldAfterSeconds, LastYieldAt)
			FramesSinceYield = 0
		end
	end

	if self.Position > #self.Packets then
		self.Done = true
	end

	local DecodeSeconds = os.clock() - DecodeStartedAt
	local WavStartedAt = os.clock()
	local WavBody = BuildWav(Chunks, AudioSampleCount)
	local WavSeconds = os.clock() - WavStartedAt
	local Rms = RmsCount > 0 and math.sqrt(RmsSum / RmsCount) or 0

	return true, {
		Frames = PacketCount,
		Bytes = self.Bytes,
		WavBody = WavBody,
		WavBytes = #WavBody,
		SampleRate = SampleRate,
		Channels = Channels,
		SamplesPerChannel = AudioSampleCount,
		Duration = AudioSampleCount / SampleRate,
		Rms = Rms,
		DecodeSeconds = DecodeSeconds,
		WavSeconds = WavSeconds,
		StartFrame = StartFrame,
		EndFrame = self.FrameCount,
		Done = self.Done,
	}
end

---Create an Opus stream decoder.
---@param Parsed table
---@return boolean
---@return table|string
function OpusPcmDecoder.CreateStream(Parsed)
	if type(Parsed) ~= "table" or type(Parsed.Packets) ~= "table" or #Parsed.Packets <= 0 then
		return false, "Missing Opus packet data."
	end

	return true, setmetatable({
		Packets = Parsed.Packets,
		Bytes = tonumber(Parsed.Bytes) or 0,
		Position = 1,
		FrameCount = 0,
		Done = false,
		Decoder = OpusCeltDecoder.New(),
		SkipSamples = ParsePreSkip(Parsed.CodecPrivate),
	}, OpusStream)
end

OpusPcmDecoder.ParsePreSkip = ParsePreSkip

-- Return Opus PCM decoder module.
return OpusPcmDecoder
end)
__bundle_register("Audio/OpusRangeDecoder", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Opus range decoder module.
local OpusRangeDecoder = {}
local RangeDecoder = {}
RangeDecoder.__index = RangeDecoder

-- Constants.
local MaxUniformRangeCoderBits = 8
local LaplaceTotal = 32768
local LaplaceMinProbability = 1
local LaplaceGuaranteedDeltas = 16
local MinRangeSize = 8388608
local Uint31Mask = 0x7FFFFFFF
local TellFracCorrections = { 35733, 38967, 42495, 46340, 50535, 55109, 60097, 65535 }

---Read unsigned 8-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU8(Data, Position)
	return Data:byte(Position, Position) or 0
end

---Count bits needed for an unsigned 32-bit integer.
---@param Value number
---@return number
local function BitLength(Value)
	Value = math.floor(tonumber(Value) or 0)
	if Value <= 0 then
		return 0
	end

	local Length = 0
	while Value > 0 do
		Value = math.floor(Value / 2)
		Length = Length + 1
	end

	return Length
end

---Left shift within 32-bit integer range.
---@param Value number
---@param Shift number
---@return number
local function LeftShift(Value, Shift)
	return (Value * (2 ^ Shift)) % 4294967296
end

---Right shift.
---@param Value number
---@param Shift number
---@return number
local function RightShift(Value, Shift)
	return math.floor((Value % 4294967296) / (2 ^ Shift))
end

---Bitwise and.
---@param Left number
---@param Right number
---@return number
local function BitAnd(Left, Right)
	if bit32 then
		return bit32.band(Left, Right)
	end

	local Result = 0
	local BitValue = 1
	Left = math.floor(Left)
	Right = math.floor(Right)

	while Left > 0 or Right > 0 do
		local LeftBit = Left % 2
		local RightBit = Right % 2
		if LeftBit == 1 and RightBit == 1 then
			Result = Result + BitValue
		end

		Left = math.floor(Left / 2)
		Right = math.floor(Right / 2)
		BitValue = BitValue * 2
	end

	return Result
end

---Bitwise or.
---@param Left number
---@param Right number
---@return number
local function BitOr(Left, Right)
	if bit32 then
		return bit32.bor(Left, Right)
	end

	local Result = 0
	local BitValue = 1
	Left = math.floor(Left)
	Right = math.floor(Right)

	while Left > 0 or Right > 0 do
		local LeftBit = Left % 2
		local RightBit = Right % 2
		if LeftBit == 1 or RightBit == 1 then
			Result = Result + BitValue
		end

		Left = math.floor(Left / 2)
		Right = math.floor(Right / 2)
		BitValue = BitValue * 2
	end

	return Result
end

---Minimum value.
---@param Left number
---@param Right number
---@return number
local function Min(Left, Right)
	if Left < Right then
		return Left
	end

	return Right
end

---Laplace first decay frequency.
---@param ZeroFrequency number
---@param Decay number
---@return number
local function LaplaceFirstDecayFrequency(ZeroFrequency, Decay)
	local FrequencyTotal = LaplaceTotal - LaplaceMinProbability * (2 * LaplaceGuaranteedDeltas) - ZeroFrequency
	return RightShift(FrequencyTotal * (16384 - Decay), 15)
end

---Normalize the range decoder state.
function RangeDecoder:Normalize()
	while self.RangeSize <= MinRangeSize do
		self.RangeSize = LeftShift(self.RangeSize, 8)
		self.NBitsTotal = self.NBitsTotal + 8
		self.HighAndCodedDifference = BitAnd(
			LeftShift(self.HighAndCodedDifference, 8) + (255 - self:GetBits(8)),
			Uint31Mask
		)
	end
end

---Read one range-coded bit.
---@return number
function RangeDecoder:GetBit()
	local Index = math.floor(self.BitsRead / 8)
	local Offset = self.BitsRead % 8

	if Index >= #self.Data then
		return 0
	end

	self.BitsRead = self.BitsRead + 1
	return math.floor(ReadU8(self.Data, Index + 1) / (2 ^ (7 - Offset))) % 2
end

---Read range-coded bits.
---@param Count number
---@return number
function RangeDecoder:GetBits(Count)
	local Value = 0

	for Index = 1, Count do
		if Index ~= 1 then
			Value = LeftShift(Value, 1)
		end

		Value = BitOr(Value, self:GetBit())
	end

	return Value
end

---Read one raw bit from the frame tail.
---@return number
function RangeDecoder:GetRawBit()
	local Index = math.floor(self.RawBitsRead / 8)
	local Offset = self.RawBitsRead % 8
	self.RawBitsRead = self.RawBitsRead + 1
	self.NBitsTotal = self.NBitsTotal + 1

	if Index >= #self.Data then
		return 0
	end

	local ByteIndex = #self.Data - Index
	return math.floor(ReadU8(self.Data, ByteIndex) / (2 ^ Offset)) % 2
end

---Read raw bits from the frame tail.
---@param Count number
---@return number
function RangeDecoder:GetRawBits(Count)
	local Value = 0

	for Index = 0, math.min(Count, 32) - 1 do
		Value = BitOr(Value, LeftShift(self:GetRawBit(), Index))
	end

	for Index = 33, Count do
		self:GetRawBit()
	end

	return Value
end

---Update range-coded cumulative interval.
---@param Scale number
---@param Low number
---@param High number
---@param Total number
function RangeDecoder:Update(Scale, Low, High, Total)
	self.HighAndCodedDifference = self.HighAndCodedDifference - Scale * (Total - High)
	if Low ~= 0 then
		self.RangeSize = Scale * (High - Low)
	else
		self.RangeSize = self.RangeSize - Scale * (Total - High)
	end

	self:Normalize()
end

---Decode uniform symbol without committing state.
---@param Total number
---@return number
function RangeDecoder:DecodeUniformSymbol(Total)
	local Scale = math.floor(self.RangeSize / Total)
	local Symbol = math.floor(self.HighAndCodedDifference / Scale) + 1
	return Total - Min(Symbol, Total)
end

---Decode and commit uniform symbol.
---@param Total number
---@return number
function RangeDecoder:DecodeAndUpdateUniformSymbol(Total)
	local Symbol = self:DecodeUniformSymbol(Total)
	self:Update(math.floor(self.RangeSize / Total), Symbol, Symbol + 1, Total)
	return Symbol
end

---Decode a symbol with an inverse CDF table.
---@param CumulativeDistributionTable table
---@return number
function RangeDecoder:DecodeSymbolWithICDF(CumulativeDistributionTable)
	local Total = CumulativeDistributionTable[1]
	local Scale = math.floor(self.RangeSize / Total)
	local Symbol = math.floor(self.HighAndCodedDifference / Scale) + 1
	Symbol = Total - Min(Symbol, Total)

	local SymbolIndex = 0
	while CumulativeDistributionTable[SymbolIndex + 2] <= Symbol do
		SymbolIndex = SymbolIndex + 1
	end

	local High = CumulativeDistributionTable[SymbolIndex + 2]
	local Low = SymbolIndex ~= 0 and CumulativeDistributionTable[SymbolIndex + 1] or 0
	self:Update(Scale, Low, High, Total)
	return SymbolIndex
end

---Decode a cumulative value.
---@param Total number
---@return number
function RangeDecoder:DecodeCumulative(Total)
	return self:DecodeUniformSymbol(Total)
end

---Commit a cumulative interval.
---@param Low number
---@param High number
---@param Total number
function RangeDecoder:UpdateCumulative(Low, High, Total)
	self:Update(math.floor(self.RangeSize / Total), Low, High, Total)
end

---Decode uniform value.
---@param Total number
---@return number
---@return boolean
function RangeDecoder:DecodeUniform(Total)
	if Total == 0 then
		return 0, false
	end

	if Total == 1 then
		return 0, true
	end

	local Limit = Total - 1
	local BitCount = BitLength(Limit)
	if BitCount <= MaxUniformRangeCoderBits then
		return self:DecodeAndUpdateUniformSymbol(Total), true
	end

	local RawBitCount = BitCount - MaxUniformRangeCoderBits
	local RangeTotal = RightShift(Limit, RawBitCount) + 1
	local Symbol = self:DecodeAndUpdateUniformSymbol(RangeTotal)
	local Value = BitOr(LeftShift(Symbol, RawBitCount), self:DecodeRawBits(RawBitCount))
	if Value <= Limit then
		return Value, true
	end

	return Limit, false
end

---Decode Laplace-distributed symbol.
---@param ZeroFrequency number
---@param Decay number
---@return number
function RangeDecoder:DecodeLaplace(ZeroFrequency, Decay)
	local Value = 0
	local Symbol = self:DecodeUniformSymbol(LaplaceTotal)
	local Low = 0
	local Frequency = ZeroFrequency

	if Symbol >= Frequency then
		Value = Value + 1
		Low = Frequency
		Frequency = LaplaceFirstDecayFrequency(ZeroFrequency, Decay) + LaplaceMinProbability

		while Frequency > LaplaceMinProbability and Symbol >= Low + 2 * Frequency do
			Frequency = Frequency * 2
			Low = Low + Frequency
			Frequency = RightShift((Frequency - 2 * LaplaceMinProbability) * Decay, 15)
			Frequency = Frequency + LaplaceMinProbability
			Value = Value + 1
		end

		if Frequency <= LaplaceMinProbability then
			local Extra = RightShift(Symbol - Low, 1)
			Value = Value + Extra
			Low = Low + 2 * Extra * LaplaceMinProbability
		end

		if Symbol < Low + Frequency then
			Value = -Value
		else
			Low = Low + Frequency
		end
	end

	local High = math.min(Low + Frequency, LaplaceTotal)
	self:Update(math.floor(self.RangeSize / LaplaceTotal), Low, High, LaplaceTotal)
	return Value
end

---Decode binary symbol.
---@param LogP number
---@return number
function RangeDecoder:DecodeSymbolLogP(LogP)
	local Scale = RightShift(self.RangeSize, LogP)
	local Symbol = 0

	if self.HighAndCodedDifference >= Scale then
		self.HighAndCodedDifference = self.HighAndCodedDifference - Scale
		self.RangeSize = self.RangeSize - Scale
	else
		self.RangeSize = Scale
		Symbol = 1
	end

	self:Normalize()
	return Symbol
end

---Set logical frame storage size.
---@param Size number
function RangeDecoder:SetStorageSize(Size)
	Size = math.floor(tonumber(Size) or 0)
	if Size < 0 then
		Size = 0
	end

	if Size < #self.Data then
		self.Data = self.Data:sub(1, Size)
	end
end

---Set internal values for tests.
---@param Data string
---@param BitsRead number
---@param RangeSize number
---@param HighAndCodedDifference number
function RangeDecoder:SetInternalValues(Data, BitsRead, RangeSize, HighAndCodedDifference)
	self.Data = Data or ""
	self.BitsRead = BitsRead
	self.RawBitsRead = 0
	self.NBitsTotal = BitsRead
	self.RangeSize = RangeSize
	self.HighAndCodedDifference = HighAndCodedDifference
end

---Decode raw bits.
---@param Count number
---@return number
function RangeDecoder:DecodeRawBits(Count)
	return self:GetRawBits(Count)
end

---Get conservative whole-bit cursor.
---@return number
function RangeDecoder:Tell()
	local Length = BitLength(self.RangeSize)
	if Length == 0 then
		return self.NBitsTotal
	end

	if self.NBitsTotal <= Length then
		return 0
	end

	return self.NBitsTotal - Length
end

---Get conservative fractional-bit cursor.
---@return number
function RangeDecoder:TellFrac()
	local Length = BitLength(self.RangeSize)
	local Range = RightShift(self.RangeSize, Length - 16)
	local CorrectionIndex = RightShift(Range, 12) - 8

	if Range > TellFracCorrections[CorrectionIndex + 1] then
		CorrectionIndex = CorrectionIndex + 1
	end

	return self.NBitsTotal * 8 - (Length * 8 + CorrectionIndex)
end

---Get remaining bits.
---@return number
function RangeDecoder:RemainingBits()
	return #self.Data * 8 - self.BitsRead - self.RawBitsRead
end

---Get final range.
---@return number
function RangeDecoder:FinalRange()
	return self.RangeSize
end

---Create range decoder.
---@param Data string?
---@return table
function OpusRangeDecoder.New(Data)
	local Decoder = setmetatable({
		Data = "",
		BitsRead = 0,
		RawBitsRead = 0,
		NBitsTotal = 0,
		RangeSize = 0,
		HighAndCodedDifference = 0,
	}, RangeDecoder)

	if Data ~= nil then
		Decoder:Init(Data)
	end

	return Decoder
end

---Initialize decoder.
---@param Data string?
function RangeDecoder:Init(Data)
	self.Data = Data or ""
	self.BitsRead = 0
	self.RawBitsRead = 0
	self.NBitsTotal = 9
	self.RangeSize = 128
	self.HighAndCodedDifference = 127 - self:GetBits(7)
	self:Normalize()
end

OpusRangeDecoder.RangeDecoder = RangeDecoder

-- Return Opus range decoder module.
return OpusRangeDecoder
end)
__bundle_register("Audio/WebmOpus", function(require, _LOADED, __bundle_register, __bundle_modules)
-- WebM Opus parser module.
local WebmOpus = {}

-- Constants.
local EbmlId = 0x1A45DFA3
local SegmentId = 0x18538067
local InfoId = 0x1549A966
local TimecodeScaleId = 0x2AD7B1
local TracksId = 0x1654AE6B
local TrackEntryId = 0xAE
local TrackNumberId = 0xD7
local TrackTypeId = 0x83
local CodecIdId = 0x86
local CodecPrivateId = 0x63A2
local AudioId = 0xE1
local SamplingFrequencyId = 0xB5
local ChannelsId = 0x9F
local ClusterId = 0x1F43B675
local ClusterTimecodeId = 0xE7
local SimpleBlockId = 0xA3
local BlockGroupId = 0xA0
local BlockId = 0xA1
local BlockDurationId = 0x9B

local MasterIds = {
	[EbmlId] = true,
	[SegmentId] = true,
	[InfoId] = true,
	[TracksId] = true,
	[TrackEntryId] = true,
	[AudioId] = true,
	[ClusterId] = true,
	[BlockGroupId] = true,
}

---Read unsigned 8-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadU8(Data, Position)
	return Data:byte(Position, Position) or 0
end

---Read unsigned EBML ID.
---@param Data string
---@param Position number
---@return number
---@return number
local function ReadElementId(Data, Position)
	local First = ReadU8(Data, Position)
	local Mask = 0x80
	local Length = 1

	while Length <= 4 and math.floor(First / Mask) % 2 == 0 do
		Mask = math.floor(Mask / 2)
		Length = Length + 1
	end

	if Length > 4 or Position + Length - 1 > #Data then
		error("webm: invalid element id")
	end

	local Value = 0
	for Index = 0, Length - 1 do
		Value = Value * 256 + ReadU8(Data, Position + Index)
	end

	return Value, Position + Length
end

---Read EBML variable length size.
---@param Data string
---@param Position number
---@return number?
---@return number
local function ReadElementSize(Data, Position)
	local First = ReadU8(Data, Position)
	local Mask = 0x80
	local Length = 1

	while Length <= 8 and math.floor(First / Mask) % 2 == 0 do
		Mask = math.floor(Mask / 2)
		Length = Length + 1
	end

	if Length > 8 or Position + Length - 1 > #Data then
		error("webm: invalid element size")
	end

	local Value = First % Mask
	for Index = 1, Length - 1 do
		Value = Value * 256 + ReadU8(Data, Position + Index)
	end

	if Value == (2 ^ (7 * Length)) - 1 then
		return nil, Position + Length
	end

	return Value, Position + Length
end

---Read EBML variable length integer.
---@param Data string
---@param Position number
---@return number
---@return number
local function ReadVint(Data, Position)
	local First = ReadU8(Data, Position)
	local Mask = 0x80
	local Length = 1

	while Length <= 8 and math.floor(First / Mask) % 2 == 0 do
		Mask = math.floor(Mask / 2)
		Length = Length + 1
	end

	if Length > 8 or Position + Length - 1 > #Data then
		error("webm: invalid vint")
	end

	local Value = First % Mask
	for Index = 1, Length - 1 do
		Value = Value * 256 + ReadU8(Data, Position + Index)
	end

	return Value, Position + Length
end

---Read unsigned big-endian integer.
---@param Data string
---@return number
local function ReadUint(Data)
	local Value = 0

	for Index = 1, #Data do
		Value = Value * 256 + ReadU8(Data, Index)
	end

	return Value
end

---Read signed big-endian 16-bit integer.
---@param Data string
---@param Position number
---@return number
local function ReadS16(Data, Position)
	local Value = ReadU8(Data, Position) * 256 + ReadU8(Data, Position + 1)
	if Value >= 0x8000 then
		return Value - 0x10000
	end

	return Value
end

---Read big-endian IEEE float.
---@param Data string
---@return number
local function ReadFloat(Data)
	if #Data == 4 and string.unpack then
		local Success, Value = pcall(string.unpack, ">f", Data)
		return Success and Value or 0
	elseif #Data == 8 and string.unpack then
		local Success, Value = pcall(string.unpack, ">d", Data)
		return Success and Value or 0
	end

	return 0
end

---Read text.
---@param Data string
---@return string
local function ReadText(Data)
	return tostring(Data or "")
end

---Get Opus packet sample count for the YouTube fullband profile.
---@param Packet string
---@return number
local function GetPacketSamples(Packet)
	if type(Packet) ~= "string" or Packet == "" then
		return 0
	end

	local Toc = ReadU8(Packet, 1)
	local Config = math.floor(Toc / 8)
	local Code = Toc % 4
	local DurationMs = 20

	if Config < 12 then
		local Durations = { 10, 20, 40, 60 }
		DurationMs = Durations[(Config % 4) + 1]
	elseif Config < 16 then
		local Durations = { 10, 20 }
		DurationMs = Durations[(Config % 2) + 1]
	else
		local Durations = { 2.5, 5, 10, 20 }
		DurationMs = Durations[(Config % 4) + 1]
	end

	local FrameCount = 1
	if Code == 1 or Code == 2 then
		FrameCount = 2
	elseif Code == 3 then
		FrameCount = ReadU8(Packet, 2) % 64
	end

	return math.floor(DurationMs * FrameCount * 48 + 0.5)
end

---Read packets from a block payload.
---@param State table
---@param Payload string
---@param ClusterTimecode number
local function ReadBlock(State, Payload, ClusterTimecode)
	local TrackNumber, Position = ReadVint(Payload, 1)
	if TrackNumber ~= State.OpusTrackNumber then
		return
	end

	local RelativeTimecode = ReadS16(Payload, Position)
	Position = Position + 2

	local Flags = ReadU8(Payload, Position)
	Position = Position + 1

	local Lacing = math.floor((Flags % 8) / 2)
	if Lacing ~= 0 then
		error("webm: opus lacing is not supported")
	end

	local Packet = Payload:sub(Position)
	State.Packets[#State.Packets + 1] = {
		Timecode = ClusterTimecode + RelativeTimecode,
		Packet = Packet,
		Samples = GetPacketSamples(Packet),
	}
end

---Walk WebM elements.
---@param State table
---@param Data string
---@param StartPosition number
---@param EndPosition number
---@param Context table
local function WalkElements(State, Data, StartPosition, EndPosition, Context)
	local Position = StartPosition
	local ClusterTimecode = Context.ClusterTimecode or 0

	while Position <= EndPosition do
		local ElementId, SizePosition = ReadElementId(Data, Position)
		local Size, PayloadPosition = ReadElementSize(Data, SizePosition)
		local PayloadEnd = Size and math.min(PayloadPosition + Size - 1, EndPosition) or EndPosition
		local Payload = Data:sub(PayloadPosition, PayloadEnd)

		if ElementId == TimecodeScaleId then
			State.TimecodeScale = ReadUint(Payload)
		elseif ElementId == TrackEntryId then
			local TrackInfo = {}
			WalkElements(State, Data, PayloadPosition, PayloadEnd, { TrackInfo = TrackInfo })

			if TrackInfo.CodecId == "A_OPUS" then
				State.OpusTrackNumber = TrackInfo.Number
				State.CodecPrivate = TrackInfo.CodecPrivate
				State.Channels = TrackInfo.Channels or State.Channels
				State.SampleRate = TrackInfo.SampleRate or State.SampleRate
			end
		elseif ElementId == TrackNumberId and Context.TrackInfo then
			Context.TrackInfo.Number = ReadUint(Payload)
		elseif ElementId == TrackTypeId and Context.TrackInfo then
			Context.TrackInfo.Type = ReadUint(Payload)
		elseif ElementId == CodecIdId and Context.TrackInfo then
			Context.TrackInfo.CodecId = ReadText(Payload)
		elseif ElementId == CodecPrivateId and Context.TrackInfo then
			Context.TrackInfo.CodecPrivate = Payload
		elseif ElementId == SamplingFrequencyId and Context.TrackInfo then
			Context.TrackInfo.SampleRate = ReadFloat(Payload)
		elseif ElementId == ChannelsId and Context.TrackInfo then
			Context.TrackInfo.Channels = ReadUint(Payload)
		elseif ElementId == ClusterId then
			WalkElements(State, Data, PayloadPosition, PayloadEnd, { InCluster = true, ClusterTimecode = 0 })
		elseif ElementId == ClusterTimecodeId and Context.InCluster then
			ClusterTimecode = ReadUint(Payload)
			Context.ClusterTimecode = ClusterTimecode
		elseif ElementId == SimpleBlockId and State.OpusTrackNumber then
			ReadBlock(State, Payload, ClusterTimecode)
		elseif ElementId == BlockId and State.OpusTrackNumber then
			ReadBlock(State, Payload, ClusterTimecode)
		elseif ElementId == BlockDurationId then
			-- Block duration is not required for fixed 20 ms YouTube Opus packets.
		elseif MasterIds[ElementId] then
			WalkElements(State, Data, PayloadPosition, PayloadEnd, Context)
		end

		Position = PayloadEnd + 1
	end
end

---Parse WebM Opus data.
---@param Data string
---@return boolean
---@return table|string
function WebmOpus.Parse(Data)
	if type(Data) ~= "string" or Data == "" then
		return false, "WebM body is empty."
	end

	local State = {
		TimecodeScale = 1000000,
		SampleRate = 48000,
		Channels = 2,
		Packets = {},
	}

	local Success, Err = pcall(WalkElements, State, Data, 1, #Data, {})
	if not Success then
		return false, tostring(Err)
	end

	if not State.OpusTrackNumber then
		return false, "WebM did not contain an Opus audio track."
	end

	if #State.Packets <= 0 then
		return false, "WebM Opus track did not contain packets."
	end

	table.sort(State.Packets, function(Left, Right)
		return Left.Timecode < Right.Timecode
	end)

	local TotalSamples = 0
	for Index = 1, #State.Packets do
		TotalSamples = TotalSamples + (State.Packets[Index].Samples or 0)
	end

	return true, {
		CodecPrivate = State.CodecPrivate,
		TrackNumber = State.OpusTrackNumber,
		SampleRate = State.SampleRate,
		Channels = State.Channels,
		TimecodeScale = State.TimecodeScale,
		Packets = State.Packets,
		PacketCount = #State.Packets,
		SamplesPerChannel = TotalSamples,
		Duration = TotalSamples / 48000,
	}
end

-- Return WebM Opus parser module.
return WebmOpus
end)
__bundle_register("Audio/YoutubeExtractor", function(require, _LOADED, __bundle_register, __bundle_modules)
-- YouTube extractor module.
local YoutubeExtractor = {}

-- Services.
local HttpService = game:GetService("HttpService")

-- Constants.
local WatchUserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
local AndroidVrUserAgent = "com.google.android.apps.youtube.vr.oculus/1.65.10 (Linux; U; Android 12L; eureka-user Build/SQ3A.220605.009.A1) gzip"
local AndroidVrVersion = "1.65.10"
local AndroidVrClientName = "28"
local M4aChunkBytes = 1048576
local WebmChunkBytes = 1048576
local MaxPlaylistVideoIds = 50

---Trim text.
---@param Text string
---@return string
local function Trim(Text)
	return tostring(Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

---Check if text starts with prefix.
---@param Text string
---@param Prefix string
---@return boolean
local function StartsWith(Text, Prefix)
	return Text:sub(1, #Prefix) == Prefix
end

---Resolve relative URL.
---@param Url string
---@param BaseUrl string
---@return string
local function ResolveRelativeUrl(Url, BaseUrl)
	if StartsWith(Url, "//") then
		return "https:" .. Url
	end

	if StartsWith(Url, "/") then
		local Root = BaseUrl:match("^(https?://[^/]+)")
		if Root then
			return Root .. Url
		end
	end

	return Url
end

---Get request function.
---@return function?
local function GetRequestFunction()
	return request
		or http_request
		or (syn and syn.request)
		or (http and http.request)
		or (fluxus and fluxus.request)
end

---Get response body.
---@param Response table
---@return string?
local function GetResponseBody(Response)
	return rawget(Response, "Body") or rawget(Response, "body")
end

---Get status code.
---@param Response table
---@return number
local function GetStatusCode(Response)
	return tonumber(rawget(Response, "StatusCode") or rawget(Response, "status_code") or rawget(Response, "Status") or rawget(Response, "status")) or 0
end

---Check if status code is successful.
---@param StatusCode number
---@return boolean
local function IsSuccessStatus(StatusCode)
	return StatusCode == 0 or (StatusCode >= 200 and StatusCode < 300)
end

---Run an HTTP request.
---@param Options table
---@return boolean
---@return table|string
local function Request(Options)
	local RequestFunction = GetRequestFunction()
	if not RequestFunction then
		return false, "Executor does not support request()."
	end

	local Success, Response = pcall(RequestFunction, Options)
	if not Success then
		return false, tostring(Response)
	end

	if type(Response) ~= "table" then
		return false, "Request returned an invalid response."
	end

	return true, Response
end

---Download a URL as text/body.
---@param Url string
---@param Headers table
---@return boolean
---@return string|table
local function DownloadBody(Url, Headers)
	local RequestOk, Response = Request({
		Url = Url,
		Method = "GET",
		Headers = Headers,
	})

	if not RequestOk then
		return false, Response
	end

	local StatusCode = GetStatusCode(Response)
	if not IsSuccessStatus(StatusCode) then
		return false, string.format("YouTube request failed with HTTP %d.", StatusCode)
	end

	local Body = GetResponseBody(Response)
	if type(Body) ~= "string" or Body == "" then
		return false, "YouTube request returned an empty body."
	end

	return true, Body
end

---Download a byte range.
---@param Url string
---@param StartByte number
---@param EndByte number
---@param AcceptHeader string
---@return boolean
---@return string
local function DownloadRange(Url, StartByte, EndByte, AcceptHeader)
	local RequestOk, Response = Request({
		Url = Url,
		Method = "GET",
		Headers = {
			["Accept"] = AcceptHeader,
			["Range"] = string.format("bytes=%d-%d", StartByte, EndByte),
			["User-Agent"] = AndroidVrUserAgent,
		},
	})

	if not RequestOk then
		return false, Response
	end

	local StatusCode = GetStatusCode(Response)
	if StatusCode ~= 206 and not IsSuccessStatus(StatusCode) then
		return false, string.format("YouTube range request failed with HTTP %d.", StatusCode)
	end

	local Body = GetResponseBody(Response)
	if type(Body) ~= "string" or Body == "" then
		return false, "YouTube range request returned an empty body."
	end

	return true, Body
end

---Download a URL as ranged chunks.
---@param Stream table
---@param AcceptHeader string
---@param ChunkBytes number
---@return boolean
---@return string
local function DownloadChunks(Stream, AcceptHeader, ChunkBytes)
	local ContentLength = tonumber(Stream.ContentLength)
	if not ContentLength or ContentLength <= 0 then
		return DownloadBody(Stream.Url, {
			["Accept"] = AcceptHeader,
			["User-Agent"] = AndroidVrUserAgent,
		})
	end

	local Chunks = {}
	local Position = 0

	while Position < ContentLength do
		local EndByte = math.min(Position + ChunkBytes - 1, ContentLength - 1)
		local RangeOk, Body = DownloadRange(Stream.Url, Position, EndByte, AcceptHeader)
		if not RangeOk then
			return false, Body
		end

		Chunks[#Chunks + 1] = Body
		Position = Position + #Body
		task.wait()

		if #Body == 0 then
			return false, "YouTube range request stopped before the stream was complete."
		end
	end

	return true, table.concat(Chunks)
end

---Download an M4A URL as ranged chunks.
---@param Stream table
---@return boolean
---@return string
local function DownloadM4aChunks(Stream)
	return DownloadChunks(Stream, "audio/mp4,*/*", M4aChunkBytes)
end

---Download a WebM URL as ranged chunks.
---@param Stream table
---@return boolean
---@return string
local function DownloadWebmChunks(Stream)
	return DownloadChunks(Stream, "audio/webm,*/*", WebmChunkBytes)
end

---Decode a URL query component.
---@param Text string
---@return string
local function DecodeUrlComponent(Text)
	Text = tostring(Text or ""):gsub("+", " ")

	return (Text:gsub("%%(%x%x)", function(Hex)
		return string.char(tonumber(Hex, 16) or 0)
	end))
end

---Extract a query value from a URL.
---@param Text string
---@param Name string
---@return string?
local function ExtractQueryValue(Text, Name)
	local Value = tostring(Text or ""):match("[?&]" .. Name .. "=([^&#]+)")
	if type(Value) ~= "string" or Value == "" then
		return nil
	end

	return DecodeUrlComponent(Value)
end

---Extract YouTube ID from URL.
---@param Text string
---@return string?
local function ExtractYoutubeId(Text)
	local Id = ExtractQueryValue(Text, "v")
		or Text:match("youtu%.be/([%w_%-]+)")
		or Text:match("/shorts/([%w_%-]+)")
		or Text:match("/embed/([%w_%-]+)")

	if Id and #Id > 0 and Id:match("^[%w_%-]+$") then
		return Id:sub(1, 32)
	end

	return nil
end

---Extract YouTube playlist ID from URL.
---@param Text string
---@return string?
local function ExtractYoutubeListId(Text)
	local ListId = ExtractQueryValue(Text, "list")
	if ListId and #ListId > 0 and ListId:match("^[%w_%-]+$") then
		return ListId:sub(1, 128)
	end

	return nil
end

---Extract a video ID from a radio playlist ID.
---@param ListId string
---@return string?
local function ExtractRadioPlaylistVideoId(ListId)
	local Candidate = ListId:match("^RDMM([%w_%-]+)$") or ListId:match("^RD([%w_%-]+)$")
	if Candidate and #Candidate >= 11 then
		return Candidate:sub(1, 11)
	end

	return nil
end

---Build playlist URL.
---@param ListId string
---@return string
local function BuildPlaylistUrl(ListId)
	return "https://www.youtube.com/playlist?list=" .. ListId .. "&bpctr=9999999999&has_verified=1"
end

---Build watch playlist URL.
---@param VideoId string
---@param ListId string
---@return string
local function BuildWatchPlaylistUrl(VideoId, ListId)
	return "https://www.youtube.com/watch?v=" .. VideoId .. "&list=" .. ListId .. "&bpctr=9999999999&has_verified=1"
end

---Add a playlist video ID.
---@param VideoIds table
---@param Seen table
---@param VideoId string?
local function AddPlaylistVideoId(VideoIds, Seen, VideoId)
	if type(VideoId) ~= "string" then return end
	if #VideoId ~= 11 then return end
	if not VideoId:match("^[%w_%-]+$") then return end
	if Seen[VideoId] then return end

	Seen[VideoId] = true
	VideoIds[#VideoIds + 1] = VideoId
end

---Extract video IDs from playlist HTML.
---@param Body string
---@param PreferredVideoId string?
---@return table
local function ExtractPlaylistVideoIds(Body, PreferredVideoId)
	local VideoIds = {}
	local Seen = {}

	AddPlaylistVideoId(VideoIds, Seen, PreferredVideoId)

	for VideoId in tostring(Body or ""):gmatch("\"videoId\":\"([%w_%-]+)\"") do
		AddPlaylistVideoId(VideoIds, Seen, VideoId)
		if #VideoIds >= MaxPlaylistVideoIds then
			return VideoIds
		end
	end

	for VideoId in tostring(Body or ""):gmatch("watch%?v=([%w_%-]+)") do
		AddPlaylistVideoId(VideoIds, Seen, VideoId)
		if #VideoIds >= MaxPlaylistVideoIds then
			return VideoIds
		end
	end

	return VideoIds
end

---Resolve playable video IDs from a YouTube source.
---@param Source string
---@return boolean
---@return table|string
local function ResolveYoutubeVideoIds(Source)
	local SourceVideoId = ExtractYoutubeId(Source)
	local ListId = ExtractYoutubeListId(Source)
	if not ListId then
		if SourceVideoId then
			return true, {
				VideoId = SourceVideoId,
				VideoIds = { SourceVideoId },
				SelectedIndex = 1,
			}
		end

		return false, "Could not extract a YouTube video ID."
	end

	local PreferredVideoId = SourceVideoId or ExtractRadioPlaylistVideoId(ListId)
	local PlaylistUrl = PreferredVideoId and BuildWatchPlaylistUrl(PreferredVideoId, ListId) or BuildPlaylistUrl(ListId)

	local BodyOk, Body = DownloadBody(PlaylistUrl, {
		["Accept"] = "text/html,*/*",
		["Accept-Language"] = "en-US,en;q=0.9",
		["User-Agent"] = WatchUserAgent,
	})

	if not BodyOk then
		if PreferredVideoId then
			return true, {
				VideoId = PreferredVideoId,
				VideoIds = { PreferredVideoId },
				ListId = ListId,
				SelectedIndex = 1,
				PlaylistError = Body,
			}
		end

		return false, Body
	end

	local VideoIds = ExtractPlaylistVideoIds(Body, PreferredVideoId)
	if #VideoIds <= 0 then
		return false, "Could not extract a playable video from the YouTube playlist."
	end

	return true, {
		VideoId = VideoIds[1],
		VideoIds = VideoIds,
		ListId = ListId,
		SelectedIndex = 1,
	}
end

---Resolve a playable video ID from a YouTube source.
---@param Source string
---@return boolean
---@return string
local function ResolveYoutubeVideoId(Source)
	local ResolveOk, Resolved = ResolveYoutubeVideoIds(Source)
	if not ResolveOk then
		return false, Resolved
	end

	return true, Resolved.VideoId
end

---Extract a balanced JSON object after a marker.
---@param Text string
---@param Marker string
---@return string?
local function ExtractBalancedJson(Text, Marker)
	local MarkerStart = Text:find(Marker, 1, true)
	if not MarkerStart then return nil end

	local Position = Text:find("{", MarkerStart, true)
	if not Position then return nil end

	local Depth = 0
	local InString = false
	local Escape = false

	for Index = Position, #Text do
		local Char = Text:sub(Index, Index)

		if InString then
			if Escape then
				Escape = false
			elseif Char == "\\" then
				Escape = true
			elseif Char == '"' then
				InString = false
			end
		elseif Char == '"' then
			InString = true
		elseif Char == "{" then
			Depth = Depth + 1
		elseif Char == "}" then
			Depth = Depth - 1
			if Depth == 0 then
				return Text:sub(Position, Index)
			end
		end
	end

	return nil
end

---Decode JSON.
---@param Body string
---@param Label string
---@return boolean
---@return table|string
local function DecodeJson(Body, Label)
	local Success, Data = pcall(HttpService.JSONDecode, HttpService, Body)
	if not Success then
		return false, string.format("Failed to parse %s JSON: %s", Label, tostring(Data))
	end

	if type(Data) ~= "table" then
		return false, string.format("%s JSON was not an object.", Label)
	end

	return true, Data
end

---Find player JS URL in ytcfg.
---@param Config table
---@param BaseUrl string
---@return string?
local function FindPlayerJsUrl(Config, BaseUrl)
	local DirectUrl = rawget(Config, "PLAYER_JS_URL")
	if type(DirectUrl) == "string" and DirectUrl ~= "" then
		return ResolveRelativeUrl(DirectUrl, BaseUrl)
	end

	local Contexts = rawget(Config, "WEB_PLAYER_CONTEXT_CONFIGS")
	if type(Contexts) ~= "table" then return nil end

	for Name, Context in next, Contexts do
		if type(Context) ~= "table" then continue end

		local JsUrl = rawget(Context, "jsUrl")
		if type(JsUrl) == "string" and JsUrl ~= "" then
			return ResolveRelativeUrl(JsUrl, BaseUrl)
		end
	end

	return nil
end

---Extract signature timestamp from player JS.
---@param PlayerUrl string
---@return boolean
---@return number|string
local function ExtractSignatureTimestamp(PlayerUrl)
	local BodyOk, Body = DownloadBody(PlayerUrl, {
		["Accept"] = "*/*",
		["User-Agent"] = WatchUserAgent,
	})

	if not BodyOk then
		return false, Body
	end

	local Timestamp = Body:match("signatureTimestamp%s*:%s*(%d+)")
		or Body:match("sts%s*:%s*(%d+)")
	if not Timestamp then
		return false, "Could not extract YouTube player signature timestamp."
	end

	return true, tonumber(Timestamp)
end

---Build watch URL.
---@param VideoId string
---@return string
local function BuildWatchUrl(VideoId)
	return "https://www.youtube.com/watch?v=" .. VideoId .. "&bpctr=9999999999&has_verified=1"
end

---Fetch watch config.
---@param Source string
---@return boolean
---@return table|string
local function FetchWatchConfig(Source)
	local VideoOk, VideoId = ResolveYoutubeVideoId(Source)
	if not VideoOk then
		return false, VideoId
	end

	local WatchUrl = BuildWatchUrl(VideoId)
	local BodyOk, Body = DownloadBody(WatchUrl, {
		["Accept"] = "text/html,*/*",
		["Accept-Language"] = "en-US,en;q=0.9",
		["User-Agent"] = WatchUserAgent,
	})

	if not BodyOk then
		return false, Body
	end

	local ConfigJson = ExtractBalancedJson(Body, "ytcfg.set({")
	if not ConfigJson then
		return false, "Could not find YouTube page config."
	end

	local ConfigOk, Config = DecodeJson(ConfigJson, "YouTube config")
	if not ConfigOk then
		return false, Config
	end

	local ApiKey = rawget(Config, "INNERTUBE_API_KEY")
	local Context = rawget(Config, "INNERTUBE_CONTEXT")
	local Client = type(Context) == "table" and rawget(Context, "client") or nil
	local VisitorData = type(Client) == "table" and rawget(Client, "visitorData") or nil
	local PlayerUrl = FindPlayerJsUrl(Config, WatchUrl)

	if type(ApiKey) ~= "string" or ApiKey == "" then
		return false, "YouTube page config did not include an API key."
	end

	if type(VisitorData) ~= "string" or VisitorData == "" then
		return false, "YouTube page config did not include visitor data."
	end

	if type(PlayerUrl) ~= "string" or PlayerUrl == "" then
		return false, "YouTube page config did not include a player script."
	end

	return true, {
		VideoId = VideoId,
		WatchUrl = WatchUrl,
		ApiKey = ApiKey,
		VisitorData = VisitorData,
		PlayerUrl = PlayerUrl,
	}
end

---Build Android VR player query.
---@param VideoId string
---@param VisitorData string
---@param SignatureTimestamp number
---@return string
local function BuildAndroidVrPlayerBody(VideoId, VisitorData, SignatureTimestamp)
	return HttpService:JSONEncode({
		["context"] = {
			["client"] = {
				["clientName"] = "ANDROID_VR",
				["clientVersion"] = AndroidVrVersion,
				["deviceMake"] = "Oculus",
				["deviceModel"] = "Quest 3",
				["androidSdkVersion"] = 32,
				["userAgent"] = AndroidVrUserAgent,
				["osName"] = "Android",
				["osVersion"] = "12L",
				["hl"] = "en",
				["gl"] = "US",
				["visitorData"] = VisitorData,
			},
		},
		["videoId"] = VideoId,
		["contentCheckOk"] = true,
		["racyCheckOk"] = true,
		["playbackContext"] = {
			["contentPlaybackContext"] = {
				["html5Preference"] = "HTML5_PREF_WANTS",
				["signatureTimestamp"] = SignatureTimestamp,
			},
		},
	})
end

---Call Android VR player API.
---@param Config table
---@param SignatureTimestamp number
---@return boolean
---@return table|string
local function FetchAndroidVrPlayer(Config, SignatureTimestamp)
	local RequestOk, Response = Request({
		Url = "https://www.youtube.com/youtubei/v1/player?key=" .. Config.ApiKey,
		Method = "POST",
		Headers = {
			["Accept"] = "application/json",
			["Content-Type"] = "application/json",
			["Origin"] = "https://www.youtube.com",
			["User-Agent"] = AndroidVrUserAgent,
			["X-Goog-Visitor-Id"] = Config.VisitorData,
			["X-YouTube-Client-Name"] = AndroidVrClientName,
			["X-YouTube-Client-Version"] = AndroidVrVersion,
		},
		Body = BuildAndroidVrPlayerBody(Config.VideoId, Config.VisitorData, SignatureTimestamp),
	})

	if not RequestOk then
		return false, Response
	end

	local StatusCode = GetStatusCode(Response)
	if not IsSuccessStatus(StatusCode) then
		return false, string.format("YouTube player API failed with HTTP %d.", StatusCode)
	end

	local Body = GetResponseBody(Response)
	if type(Body) ~= "string" or Body == "" then
		return false, "YouTube player API returned an empty body."
	end

	return DecodeJson(Body, "YouTube player")
end

---Get playability error.
---@param Player table
---@return string
local function GetPlayabilityError(Player)
	local Status = rawget(Player, "playabilityStatus")
	if type(Status) ~= "table" then
		return "YouTube player response did not include playability status."
	end

	local StatusText = tostring(rawget(Status, "status") or "unknown")
	local Reason = rawget(Status, "reason")
	if Reason then
		return string.format("YouTube returned %s: %s", StatusText, tostring(Reason))
	end

	return "YouTube returned " .. StatusText .. "."
end

---Check if URL contains a throttling challenge.
---@param Url string
---@return boolean
local function HasNChallenge(Url)
	return Url:find("?n=", 1, true) ~= nil or Url:find("&n=", 1, true) ~= nil
end

---Select M4A audio format.
---@param Player table
---@return boolean
---@return table|string
local function SelectM4aFormat(Player)
	local Status = rawget(Player, "playabilityStatus")
	if type(Status) ~= "table" or rawget(Status, "status") ~= "OK" then
		return false, GetPlayabilityError(Player)
	end

	local StreamingData = rawget(Player, "streamingData")
	if type(StreamingData) ~= "table" then
		return false, "YouTube player response did not include streaming data."
	end

	local Formats = rawget(StreamingData, "adaptiveFormats")
	if type(Formats) ~= "table" then
		return false, "YouTube player response did not include adaptive formats."
	end

	local Fallback = nil
	for Index = 1, #Formats do
		local Format = Formats[Index]
		if type(Format) ~= "table" then continue end

		local MimeType = tostring(rawget(Format, "mimeType") or "")
		local Url = rawget(Format, "url")
		local SignatureCipher = rawget(Format, "signatureCipher") or rawget(Format, "cipher")
		local IsAacLc = MimeType:find("audio/mp4", 1, true) and MimeType:find("mp4a.40.2", 1, true)

		if IsAacLc and type(Url) == "string" and Url ~= "" and not SignatureCipher then
			local Candidate = {
				Itag = rawget(Format, "itag"),
				Url = Url,
				MimeType = MimeType,
				Bitrate = rawget(Format, "bitrate"),
				AverageBitrate = rawget(Format, "averageBitrate"),
				ContentLength = tonumber(rawget(Format, "contentLength")),
				ApproxDurationMs = tonumber(rawget(Format, "approxDurationMs")),
				AudioSampleRate = tonumber(rawget(Format, "audioSampleRate")),
				AudioQuality = rawget(Format, "audioQuality"),
			}

			if tostring(Candidate.Itag) == "140" then
				if HasNChallenge(Url) then
					return false, "YouTube returned itag 140 with an unresolved n-challenge."
				end

				return true, Candidate
			end

			Fallback = Fallback or Candidate
		end
	end

	if Fallback then
		if HasNChallenge(Fallback.Url) then
			return false, "YouTube returned M4A audio with an unresolved n-challenge."
		end

		return true, Fallback
	end

	return false, "YouTube did not return a direct AAC-LC M4A stream."
end

---Select Opus WebM audio format.
---@param Player table
---@return boolean
---@return table|string
local function SelectOpusWebmFormat(Player)
	local Status = rawget(Player, "playabilityStatus")
	if type(Status) ~= "table" or rawget(Status, "status") ~= "OK" then
		return false, GetPlayabilityError(Player)
	end

	local StreamingData = rawget(Player, "streamingData")
	if type(StreamingData) ~= "table" then
		return false, "YouTube player response did not include streaming data."
	end

	local Formats = rawget(StreamingData, "adaptiveFormats")
	if type(Formats) ~= "table" then
		return false, "YouTube player response did not include adaptive formats."
	end

	local Best = nil
	local BestRate = -1

	for Index = 1, #Formats do
		local Format = Formats[Index]
		if type(Format) ~= "table" then continue end

		local MimeType = tostring(rawget(Format, "mimeType") or "")
		local Url = rawget(Format, "url")
		local SignatureCipher = rawget(Format, "signatureCipher") or rawget(Format, "cipher")
		local IsOpusWebm = MimeType:find("audio/webm", 1, true) and MimeType:find("opus", 1, true)

		if IsOpusWebm and type(Url) == "string" and Url ~= "" and not SignatureCipher then
			if HasNChallenge(Url) then
				return false, "YouTube returned Opus WebM audio with an unresolved n-challenge."
			end

			local Candidate = {
				Itag = rawget(Format, "itag"),
				Url = Url,
				MimeType = MimeType,
				Bitrate = rawget(Format, "bitrate"),
				AverageBitrate = rawget(Format, "averageBitrate"),
				ContentLength = tonumber(rawget(Format, "contentLength")),
				ApproxDurationMs = tonumber(rawget(Format, "approxDurationMs")),
				AudioSampleRate = tonumber(rawget(Format, "audioSampleRate")),
				AudioQuality = rawget(Format, "audioQuality"),
			}
			local CandidateRate = tonumber(Candidate.AverageBitrate or Candidate.Bitrate) or 0

			if CandidateRate > BestRate then
				Best = Candidate
				BestRate = CandidateRate
			end
		end
	end

	if Best then
		return true, Best
	end

	return false, "YouTube did not return a direct Opus WebM stream."
end

---Resolve YouTube M4A stream.
---@param Source string
---@return boolean
---@return table|string
function YoutubeExtractor.ResolveM4a(Source)
	Source = Trim(Source)

	local ConfigOk, Config = FetchWatchConfig(Source)
	if not ConfigOk then
		return false, Config
	end

	local TimestampOk, SignatureTimestamp = ExtractSignatureTimestamp(Config.PlayerUrl)
	if not TimestampOk then
		return false, SignatureTimestamp
	end

	local PlayerOk, Player = FetchAndroidVrPlayer(Config, SignatureTimestamp)
	if not PlayerOk then
		return false, Player
	end

	local FormatOk, Format = SelectM4aFormat(Player)
	if not FormatOk then
		return false, Format
	end

	local VideoDetails = rawget(Player, "videoDetails")
	local Title = type(VideoDetails) == "table" and rawget(VideoDetails, "title") or nil

	Format.VideoId = Config.VideoId
	Format.Title = Title or Config.VideoId
	Format.PlayerUrl = Config.PlayerUrl
	Format.SignatureTimestamp = SignatureTimestamp
	Format.SourceType = "YouTube"
	return true, Format
end

---Resolve YouTube Opus WebM stream.
---@param Source string
---@return boolean
---@return table|string
function YoutubeExtractor.ResolveOpusWebm(Source)
	Source = Trim(Source)

	local ConfigOk, Config = FetchWatchConfig(Source)
	if not ConfigOk then
		return false, Config
	end

	local TimestampOk, SignatureTimestamp = ExtractSignatureTimestamp(Config.PlayerUrl)
	if not TimestampOk then
		return false, SignatureTimestamp
	end

	local PlayerOk, Player = FetchAndroidVrPlayer(Config, SignatureTimestamp)
	if not PlayerOk then
		return false, Player
	end

	local FormatOk, Format = SelectOpusWebmFormat(Player)
	if not FormatOk then
		return false, Format
	end

	local VideoDetails = rawget(Player, "videoDetails")
	local Title = type(VideoDetails) == "table" and rawget(VideoDetails, "title") or nil

	Format.VideoId = Config.VideoId
	Format.Title = Title or Config.VideoId
	Format.PlayerUrl = Config.PlayerUrl
	Format.SignatureTimestamp = SignatureTimestamp
	Format.SourceType = "YouTubeOpus"
	return true, Format
end

---Resolve playable YouTube video IDs.
---@param Source string
---@return boolean
---@return table|string
function YoutubeExtractor.ResolveVideoIds(Source)
	return ResolveYoutubeVideoIds(Trim(Source))
end

---Resolve a playable YouTube video ID.
---@param Source string
---@return boolean
---@return string
function YoutubeExtractor.ResolveVideoId(Source)
	return ResolveYoutubeVideoId(Trim(Source))
end

---Download resolved M4A stream.
---@param Stream table
---@return boolean
---@return string
function YoutubeExtractor.DownloadM4a(Stream)
	if type(Stream) ~= "table" or type(Stream.Url) ~= "string" or Stream.Url == "" then
		return false, "Missing YouTube stream URL."
	end

	return DownloadM4aChunks(Stream)
end

---Download resolved WebM Opus stream.
---@param Stream table
---@return boolean
---@return string
function YoutubeExtractor.DownloadOpusWebm(Stream)
	if type(Stream) ~= "table" or type(Stream.Url) ~= "string" or Stream.Url == "" then
		return false, "Missing YouTube stream URL."
	end

	return DownloadWebmChunks(Stream)
end

-- Return YouTube extractor module.
return YoutubeExtractor
end)
__bundle_register("Builder/AnimationBuilderSection", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Builder.BuilderSection
local BuilderSection = require("Builder/BuilderSection")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Timings.AnimationTiming
local AnimationTiming = require("Timings/AnimationTiming")

---@class AnimationBuilderSection: BuilderSection
---@field AnimationId table
---@field Hyperarmor table
---@field IgnoreAnimationEnd table
---@field IgnoreEarlyAnimationEnd table
---@field MaxAnimationTimeout table
---@field PredictFacingHitbox table
---@field PredictionTime table
---@field PastHitboxDetection table
---@field HistorySeconds table
---@field DisablePrediction table
local AnimationBuilderSection = setmetatable({}, { __index = BuilderSection })
AnimationBuilderSection.__index = AnimationBuilderSection

---Create timing ID element. Override me.
---@param Tab table
function AnimationBuilderSection:Tide(Tab)
	self.AnimationId = Tab:Textbox({
		Placeholder = "Animation ID",
	})
end

---Load the extra elements. Override me.
---@param TimingObj AnimationTiming
function AnimationBuilderSection:Exload(TimingObj)
	self.AnimationId:Set(TimingObj._id)
	self.Hyperarmor:Set(TimingObj.ha)
	self.IgnoreAnimationEnd:Set(TimingObj.iae)
	self.IgnoreEarlyAnimationEnd:Set(TimingObj.ieae)
	self.MaxAnimationTimeout:Set(TimingObj.mat)
	self.PredictFacingHitbox:Set(TimingObj.pfh)
	self.PredictionTime:Set(TimingObj.pfht)
	self.PastHitboxDetection:Set(TimingObj.phd)
	self.HistorySeconds:Set(TimingObj.phds)
	self.DisablePrediction:Set(TimingObj.dp)
end

---Reset the elements. Extend me.
function AnimationBuilderSection:Reset()
	local WasResetting = self.Resetting
	BuilderSection.Reset(self)
	self.Resetting = true
	self.AnimationId:Set("")
	self.Hyperarmor:Set(false)
	self.HitboxFacingOffset:Set(true)
	self.IgnoreAnimationEnd:Set(false)
	self.IgnoreEarlyAnimationEnd:Set(false)
	self.MaxAnimationTimeout:Set(2000)
	self.PredictFacingHitbox:Set(false)
	self.PredictionTime:Set(0.15)
	self.PastHitboxDetection:Set(false)
	self.HistorySeconds:Set(0.5)
	self.DisablePrediction:Set(false)
	self.Resetting = WasResetting
end

---Check before creating new timing. Override me.
---@return boolean
function AnimationBuilderSection:Check()
	if not BuilderSection.Check(self) then
		return false
	end

	if not self.AnimationId.Value or #self.AnimationId.Value <= 0 then
		return Logger.LongNotify("Please enter a valid animation ID.")
	end

	local TimingObj = self.Pair:Index(self.AnimationId.Value)
	if TimingObj then
		return Logger.LongNotify("The timing ID '%s' (%s) is already in the list.", self.AnimationId.Value, TimingObj.name)
	end

	return true
end

---Set creation timing properties. Override me.
---@param TimingObj AnimationTiming
function AnimationBuilderSection:Cset(TimingObj)
	BuilderSection.Cset(self, TimingObj)
	TimingObj._id = self.AnimationId.Value or ""
	TimingObj.ha = self.Hyperarmor.Value == true
	TimingObj.iae = self.IgnoreAnimationEnd.Value == true
	TimingObj.ieae = self.IgnoreEarlyAnimationEnd.Value == true
	TimingObj.mat = tonumber(self.MaxAnimationTimeout.Value) or 2000
	TimingObj.pfh = self.PredictFacingHitbox.Value == true
	TimingObj.pfht = tonumber(self.PredictionTime.Value) or 0.15
	TimingObj.phd = self.PastHitboxDetection.Value == true
	TimingObj.phds = tonumber(self.HistorySeconds.Value) or 0
	TimingObj.dp = self.DisablePrediction.Value == true
end

---Flush extra timing elements. Override me.
---@param TimingObj AnimationTiming
function AnimationBuilderSection:FlushExtraTiming(TimingObj)
	TimingObj.ha = self.Hyperarmor.Value == true
	TimingObj.iae = self.IgnoreAnimationEnd.Value == true
	TimingObj.ieae = self.IgnoreEarlyAnimationEnd.Value == true
	TimingObj.mat = tonumber(self.MaxAnimationTimeout.Value) or 2000
	TimingObj.pfh = self.PredictFacingHitbox.Value == true
	TimingObj.pfht = tonumber(self.PredictionTime.Value) or 0.15
	TimingObj.phd = self.PastHitboxDetection.Value == true
	TimingObj.phds = tonumber(self.HistorySeconds.Value) or 0
	TimingObj.dp = self.DisablePrediction.Value == true
end

---Create new timing. Override me.
---@return AnimationTiming
function AnimationBuilderSection:Create()
	local TimingObj = AnimationTiming.new()
	self:Cset(TimingObj)
	return TimingObj
end

---Initialize extra tab.
---@param Tab table
function AnimationBuilderSection:Extra(Tab)
	self.Hyperarmor = Tab:Toggle({
		Name = "Hyperarmor Flag",
		Tooltip = "Is this timing not able to be interrupted by attacks during the animation?",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.ha = Value
		end),
	})

	self.IgnoreAnimationEnd = Tab:Toggle({
		Name = "Ignore Animation End",
		Tooltip = "Should the timing ignore the end of the animation?",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.iae = Value
		end),
	})

	local DepBoxEnd = Tab:DependencyBox()

	self.MaxAnimationTimeout = DepBoxEnd:Textbox({
		Placeholder = "Max Animation Timeout",
		Tooltip = "The maximum time (in milliseconds) that the animation is allowed to run with no end check.",
		Default = 2000,
		Numeric = true,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.mat = tonumber(Value)
		end),
	})

	DepBoxEnd:SetupDependencies({
		{ self.IgnoreAnimationEnd, true },
	})

	self.IgnoreEarlyAnimationEnd = Tab:Toggle({
		Name = "Ignore Early Animation End",
		Tooltip = "Should the timing ignore the early end of the animation?",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.ieae = Value
		end),
	})

	Tab:Divider()

	self.DisablePrediction = Tab:Toggle({
		Name = "Disable Prediction",
		Tooltip = "Force disable all hitbox prediction for this timing.",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.dp = Value
		end),
	})

	self.PastHitboxDetection = Tab:Toggle({
		Name = "Past Hitbox Detection",
		Tooltip = "Should the hitbox detection track the past hitboxes too?",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.phd = Value
		end),
	})

	local PhdDepBox = Tab:DependencyBox()

	self.HistorySeconds = PhdDepBox:Slider({
		Name = "History Seconds",
		Tooltip = "How far back in seconds should we fetch history?",
		Min = 0,
		Max = 3,
		Default = 0.5,
		Decimals = 0.01,
		Suffix = "s",
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.phds = Value
		end),
	})

	PhdDepBox:SetupDependencies({
		{ self.PastHitboxDetection, true },
	})

	self.PredictFacingHitbox = Tab:Toggle({
		Name = "Predict Facing Hitbox",
		Tooltip = "Should we make a prediction on the facing direction and make a hitbox on that?",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.pfh = Value
		end),
	})

	self.PredictionTime = Tab:Slider({
		Name = "Extrapolation Time",
		Tooltip = "The time (in seconds) to extrapolate by.",
		Min = 0,
		Max = 2,
		Default = 0.15,
		Decimals = 0.001,
		Suffix = "s",
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.pfht = Value
		end),
	})
end

---Create new AnimationBuilderSection object.
---@param Name string
---@param Tabbox table
---@param Pair TimingContainerPair
---@return AnimationBuilderSection
function AnimationBuilderSection.new(Name, Tabbox, Pair)
	return setmetatable(BuilderSection.new(Name, Tabbox, Pair), AnimationBuilderSection)
end

-- Return AnimationBuilderSection module.
return AnimationBuilderSection
end)
__bundle_register("Builder/BuilderSection", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Timings.Action
local Action = require("Timings/Action")
local SaveManager = require("Timings/SaveManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Timings.Timing
local Timing = require("Timings/Timing")

---@class BuilderSection
---@note: We assume that all elements will exist in callbacks. This is why they are not explicitly set in the constructor.
---@field Tabbox table
---@field Pair TimingContainerPair
---@field Name string
---@field TimingList table
---@field TimingName table
---@field TimingTag table
---@field HitboxLength table
---@field HitboxWidth table
---@field HitboxHeight table
---@field PunishableWindow table
---@field AfterWindow table
---@field DelayUntilInHitbox table
---@field InitialMinimumDistance table
---@field InitialMaximumDistance table
---@field ActionList table
---@field ActionName table
---@field ActionDelay table
---@field ActionType table
---@field IgnoreHitboxCheck table
local BuilderSection = {}
BuilderSection.__index = BuilderSection

-- Services.
local Stats = game:GetService("Stats")

local function NumberValue(Element, Default)
	local Items = Element and Element.Items
	local Input = Items and Items["Input"]
	local Instance = Input and Input.Instance
	local Value = Instance and Instance.Text or (Element and Element.Value)
	return tonumber(Value) or Default
end

local function StringValue(Element, Default)
	local Items = Element and Element.Items
	local Input = Items and Items["Input"]
	local Instance = Input and Input.Instance
	local Value = Instance and Instance.Text or (Element and Element.Value)
	if type(Value) == "string" and #Value > 0 then return Value end
	return Default
end

local function BooleanValue(Element, Default)
	if not Element then return Default == true end
	return Element.Value == true
end

local function QueueAutoSave()
	if SaveManager.QueueAutoSave then
		SaveManager.QueueAutoSave()
	end
end

---Get configured action types for timing actions.
---@return table
local function GetConfiguredActionTypes()
	local Environment = getgenv and getgenv() or _G
	local Values = Environment.__EP_TimingActionTypes
	if type(Values) ~= "table" or #Values == 0 then
		return { "Parry" }
	end

	local Out = {}
	for Index = 1, #Values do
		Out[#Out + 1] = Values[Index]
	end

	return Out
end

---Create timing ID element. Override me.
---@param Tab table
function BuilderSection:Tide(Tab) end

---Create extra elements. Override me.
---@param Tab table
function BuilderSection:Extra(Tab) end

---Load the extra elements. Override me.
---@param TimingObj Timing
function BuilderSection:Exload(TimingObj) end

---Load the extra action elements. Override me.
---@param ActionRef Action
function BuilderSection:Exaload(ActionRef) end

---Flush extra timing elements. Override me.
---@param TimingObj Timing
function BuilderSection:FlushExtraTiming(TimingObj) end

---Flush extra action elements. Override me.
---@param ActionRef Action
function BuilderSection:FlushExtraAction(ActionRef) end

---Action delay. Override me.
---@param Base table
function BuilderSection:Daction(Base)
	-- The user can accidently click this input through the dropdown and override the delay.
	-- It has been moved and set to "Finished" to prevent this.
	self.ActionDelay = Base:Textbox({
		Placeholder = "Action Delay",
		Numeric = true,
		Finished = true,
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef._when = tonumber(Value)
		end),
	})
end

---Reset elements. Extend me.
function BuilderSection:Reset()
	self.Resetting = true
	-- Reset timing elements.
	self.TimingName:Set("")
	self.TimingTag:Set("Undefined")
	self.InitialMaximumDistance:Set(0)
	self.PunishableWindow:Set(0)
	self.AfterWindow:Set(0)
	self.InitialMinimumDistance:Set(0)
	self.DelayUntilInHitbox:Set(false)
	self.TimingHitboxHeight:Set(0)
	self.TimingHitboxLength:Set(0)
	self.TimingHitboxWidth:Set(0)
	self.RepeatParryDelay:Set(0)
	self.RepeatStartDelay:Set(0)
	self.RepeatUntilParryEnd:Set(false)
	self.UseModuleOverActions:Set(false)
	self.SkipModuleNotification:Set(false)
	self.SelectedModule:Set("")
	self.SkipRepeatNotification:Set(false)
	self.NoDashFallback:Set(false)
	self.NoVentFallback:Set(false)
	self.HitboxFacingOffset:Set(true)
	self.HitboxShiftOffset:Set(0)
	self.BlockFallbackHoldTime:Set(0.3)
	self.NoBlockFallback:Set(false)
	self.PreferBlockFallback:Set(false)
	self.AllowAttacking:Set(false)

	-- Reset action list.
	self:Arefresh(nil)

	-- Reset action elements.
	self:Raction()
	self.Resetting = false
end

---Check before creating new timing. Override me.
---@return boolean
function BuilderSection:Check()
	if not self.TimingName.Value or #self.TimingName.Value <= 0 then
		return Logger.LongNotify("Please enter a valid timing name.")
	end

	if self.Pair:Find(self.TimingName.Value) then
		return Logger.LongNotify("The timing '%s' already exists in the list.", self.TimingName.Value)
	end

	return true
end

---Check before creating new action. Override me.
---@param TimingObj Timing
---@return boolean
function BuilderSection:Acheck(TimingObj)
	local ActionName = StringValue(self.ActionName, "")
	if #ActionName <= 0 then
		return Logger.LongNotify("Please enter a valid action name.")
	end

	if TimingObj.actions:Find(ActionName) then
		return Logger.LongNotify("The action '%s' already exists in the list.", ActionName)
	end

	return true
end

---Set creation timing properties. Override me.
---@param TimingObj Timing
function BuilderSection:Cset(TimingObj)
	TimingObj.name = StringValue(self.TimingName, "N/A")
	TimingObj.tag = StringValue(self.TimingTag, "Undefined")
	TimingObj.imdd = NumberValue(self.InitialMinimumDistance, 0)
	TimingObj.imxd = NumberValue(self.InitialMaximumDistance, 0)
	TimingObj.duih = BooleanValue(self.DelayUntilInHitbox, false)
	TimingObj.hitbox = Vector3.new(
		NumberValue(self.TimingHitboxWidth, 0),
		NumberValue(self.TimingHitboxHeight, 0),
		NumberValue(self.TimingHitboxLength, 0)
	)
	TimingObj.punishable = NumberValue(self.PunishableWindow, 0)
	TimingObj.after = NumberValue(self.AfterWindow, 0)
	TimingObj.umoa = BooleanValue(self.UseModuleOverActions, false)
	TimingObj.smn = BooleanValue(self.SkipModuleNotification, false)
	TimingObj.smod = StringValue(self.SelectedModule, "N/A")
	TimingObj.srpn = BooleanValue(self.SkipRepeatNotification, false)
	TimingObj.fhb = BooleanValue(self.HitboxFacingOffset, true)
	TimingObj.hso = NumberValue(self.HitboxShiftOffset, 0)
	TimingObj.ndfb = BooleanValue(self.NoDashFallback, false)
	TimingObj.nvfb = BooleanValue(self.NoVentFallback, false)
	TimingObj.bfht = NumberValue(self.BlockFallbackHoldTime, 0.3)
	TimingObj.nbfb = BooleanValue(self.NoBlockFallback, false)
	TimingObj.pbfb = BooleanValue(self.PreferBlockFallback, false)
	TimingObj.aatk = BooleanValue(self.AllowAttacking, false)
	TimingObj._rpd = NumberValue(self.RepeatParryDelay, 0)
	TimingObj._rsd = NumberValue(self.RepeatStartDelay, 0)
	TimingObj.rpue = BooleanValue(self.RepeatUntilParryEnd, false)
end

---Create new timing. Override me.
---@return Timing
function BuilderSection:Create()
	local TimingObj = Timing.new()
	self:Cset(TimingObj)
	return TimingObj
end

---Find selected timing.
---@return Timing?
function BuilderSection:FindSelectedTiming()
	local TimingValue = self.TimingList and self.TimingList.Value
	if type(TimingValue) ~= "string" then return nil end
	return self.Pair:Find(TimingValue)
end

---Find selected action.
---@param TimingObj Timing
---@return Action?
function BuilderSection:FindSelectedAction(TimingObj)
	local ActionValue = self.ActionList and self.ActionList.Value
	if type(ActionValue) ~= "string" then return nil end
	return TimingObj.actions:Find(ActionValue)
end

---Flush visible timing edits into the selected timing.
---@param TimingObj Timing
function BuilderSection:FlushSelectedTiming(TimingObj)
	TimingObj.tag = StringValue(self.TimingTag, TimingObj.tag or "Undefined")
	TimingObj.imdd = NumberValue(self.InitialMinimumDistance, TimingObj.imdd or 0)
	TimingObj.imxd = NumberValue(self.InitialMaximumDistance, TimingObj.imxd or 0)
	TimingObj.duih = BooleanValue(self.DelayUntilInHitbox, false)
	TimingObj.hitbox = Vector3.new(
		NumberValue(self.TimingHitboxWidth, TimingObj.hitbox and TimingObj.hitbox.X or 0),
		NumberValue(self.TimingHitboxHeight, TimingObj.hitbox and TimingObj.hitbox.Y or 0),
		NumberValue(self.TimingHitboxLength, TimingObj.hitbox and TimingObj.hitbox.Z or 0)
	)
	TimingObj.punishable = NumberValue(self.PunishableWindow, TimingObj.punishable or 0)
	TimingObj.after = NumberValue(self.AfterWindow, TimingObj.after or 0)
	TimingObj.umoa = BooleanValue(self.UseModuleOverActions, false)
	TimingObj.smn = BooleanValue(self.SkipModuleNotification, false)
	TimingObj.smod = StringValue(self.SelectedModule, TimingObj.smod or "N/A")
	TimingObj.srpn = BooleanValue(self.SkipRepeatNotification, false)
	TimingObj.fhb = BooleanValue(self.HitboxFacingOffset, true)
	TimingObj.hso = NumberValue(self.HitboxShiftOffset, TimingObj.hso or 0)
	TimingObj.ndfb = BooleanValue(self.NoDashFallback, false)
	TimingObj.nvfb = BooleanValue(self.NoVentFallback, false)
	TimingObj.bfht = NumberValue(self.BlockFallbackHoldTime, TimingObj.bfht or 0.3)
	TimingObj.nbfb = BooleanValue(self.NoBlockFallback, false)
	TimingObj.pbfb = BooleanValue(self.PreferBlockFallback, false)
	TimingObj.aatk = BooleanValue(self.AllowAttacking, false)
	TimingObj._rpd = NumberValue(self.RepeatParryDelay, TimingObj._rpd or 0)
	TimingObj._rsd = NumberValue(self.RepeatStartDelay, TimingObj._rsd or 0)
	TimingObj.rpue = BooleanValue(self.RepeatUntilParryEnd, false)

	self:FlushExtraTiming(TimingObj)
end

---Flush visible action edits into the selected action.
---@param ActionRef Action
function BuilderSection:FlushSelectedAction(ActionRef)
	if StringValue(self.ActionName, "") ~= ActionRef.name then
		return
	end

	ActionRef._type = self.ActionType.Value or ActionRef._type
	ActionRef._when = NumberValue(self.ActionDelay, ActionRef._when or 0)
	ActionRef.ihbc = BooleanValue(self.IgnoreHitboxCheck, false)
	ActionRef.hitbox = Vector3.new(
		NumberValue(self.HitboxWidth, ActionRef.hitbox and ActionRef.hitbox.X or 0),
		NumberValue(self.HitboxHeight, ActionRef.hitbox and ActionRef.hitbox.Y or 0),
		NumberValue(self.HitboxLength, ActionRef.hitbox and ActionRef.hitbox.Z or 0)
	)

	self:FlushExtraAction(ActionRef)
	self.SelectedActionSnapshot = ActionRef:Clone()
end

---Flush visible edits before saving.
function BuilderSection:FlushPendingEdits()
	if self.Initializing or self.Resetting then return end

	local TimingObj = self:FindSelectedTiming()
	if not TimingObj then return end

	self:FlushSelectedTiming(TimingObj)

	local ActionRef = self:FindSelectedAction(TimingObj)
	if ActionRef then
		self:FlushSelectedAction(ActionRef)
	end
end

---Initialize action tab.
function BuilderSection:Action()
	local Tab = self.Tabbox:AddTab("Action")

	self.RepeatUntilParryEnd = Tab:Toggle({
		Name = "Repeat Parry Until End",
		Default = false,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.rpue = Value
		end),
	})

	local DepBoxOn = Tab:DependencyBox()

	self.RepeatStartDelay = DepBoxOn:Textbox({
		Placeholder = "Repeat Start Delay",
		Numeric = true,
		Finished = true,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj._rsd = tonumber(Value) or 0
		end),
	})

	self.RepeatParryDelay = DepBoxOn:Textbox({
		Placeholder = "Repeat Parry Delay",
		Numeric = true,
		Finished = true,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj._rpd = tonumber(Value) or 0
		end),
	})

	DepBoxOn:SetupDependencies({
		{ self.RepeatUntilParryEnd, true },
	})

	Tab:Divider()

	self:Baction(Tab)
end

---Reset action elements.
function BuilderSection:Raction()
	local WasResetting = self.Resetting
	self.Resetting = true
	self.SelectedActionName = nil
	self.SelectedActionSnapshot = nil
	self.ActionName:Set("")
	self.ActionDelay:Set(0)
	local ActionTypes = GetConfiguredActionTypes()
	self.ActionType:Set(ActionTypes[1] or "Parry")
	self.IgnoreHitboxCheck:Set(false)
	self.HitboxHeight:Set(0)
	self.HitboxLength:Set(0)
	self.HitboxWidth:Set(0)
	self.Resetting = WasResetting
end

---Refresh timing list.
function BuilderSection:Refresh()
	local WasResetting = self.Resetting
	self.Resetting = true
	local Values = self.Pair.Config:Names()
	self.TimingList:Refresh(Values)
	self.TimingList.Value = nil
	self.Resetting = WasResetting
end

---Refresh action list.
---@param TimingObj Timing?
function BuilderSection:Arefresh(TimingObj)
	local WasResetting = self.Resetting
	self.Resetting = true
	self.ActionList:Refresh(TimingObj and TimingObj.actions:Names() or {})
	self.ActionList.Value = nil
	self.Resetting = WasResetting
end

---Refresh action type dropdown from configured dispatch actions.
function BuilderSection:RefreshActionTypes()
	if not self.ActionType then return end

	local WasResetting = self.Resetting
	self.Resetting = true
	local Values = GetConfiguredActionTypes()
	local Current = self.ActionType.Value
	local Found = false

	for Index = 1, #Values do
		if Values[Index] == Current then
			Found = true
			break
		end
	end

	self.ActionType:Refresh(Values)
	self.ActionType:Set(Found and Current or Values[1])
	self.Resetting = WasResetting
end

---Set an element value without assuming it exists.
---@param Element table?
---@param Value any
function BuilderSection:SetElementValue(Element, Value)
	if Element and Element.Set then
		Element:Set(Value)
	end
end

---Load timing elements.
---@param TimingObj Timing
function BuilderSection:LoadTimingElements(TimingObj)
	local WasResetting = self.Resetting
	self.Resetting = true

	self:SetElementValue(self.TimingName, TimingObj.name or "")
	self:SetElementValue(self.TimingTag, TimingObj.tag or "Undefined")
	self:SetElementValue(self.InitialMaximumDistance, TimingObj.imxd or 0)
	self:SetElementValue(self.InitialMinimumDistance, TimingObj.imdd or 0)
	self:SetElementValue(self.DelayUntilInHitbox, TimingObj.duih == true)
	self:SetElementValue(self.TimingHitboxLength, TimingObj.hitbox and TimingObj.hitbox.Z or 0)
	self:SetElementValue(self.TimingHitboxWidth, TimingObj.hitbox and TimingObj.hitbox.X or 0)
	self:SetElementValue(self.TimingHitboxHeight, TimingObj.hitbox and TimingObj.hitbox.Y or 0)
	self:SetElementValue(self.PunishableWindow, TimingObj.punishable or 0)
	self:SetElementValue(self.AfterWindow, TimingObj.after or 0)
	self:SetElementValue(self.UseModuleOverActions, TimingObj.umoa == true)
	self:SetElementValue(self.SkipModuleNotification, TimingObj.smn == true)
	self:SetElementValue(self.SelectedModule, TimingObj.smod or "")
	self:SetElementValue(self.SkipRepeatNotification, TimingObj.srpn == true)
	self:SetElementValue(self.HitboxFacingOffset, TimingObj.fhb ~= false)
	self:SetElementValue(self.HitboxShiftOffset, TimingObj.hso or 0)
	self:SetElementValue(self.NoDashFallback, TimingObj.ndfb == true)
	self:SetElementValue(self.NoVentFallback, TimingObj.nvfb == true)
	self:SetElementValue(self.BlockFallbackHoldTime, TimingObj.bfht or 0.3)
	self:SetElementValue(self.NoBlockFallback, TimingObj.nbfb == true)
	self:SetElementValue(self.PreferBlockFallback, TimingObj.pbfb == true)
	self:SetElementValue(self.AllowAttacking, TimingObj.aatk == true)
	self:SetElementValue(self.RepeatParryDelay, TimingObj._rpd or 0)
	self:SetElementValue(self.RepeatStartDelay, TimingObj._rsd or 0)
	self:SetElementValue(self.RepeatUntilParryEnd, TimingObj.rpue == true)

	self:Exload(TimingObj)
	self:Arefresh(TimingObj)

	self.Resetting = WasResetting
end

---Load action elements.
---@param ActionRef Action
function BuilderSection:LoadActionElements(ActionRef)
	local WasResetting = self.Resetting
	self.Resetting = true
	self.SelectedActionName = ActionRef.name
	self.SelectedActionSnapshot = ActionRef:Clone()

	self:SetElementValue(self.ActionName, ActionRef.name or "")
	self:SetElementValue(self.ActionDelay, ActionRef._when or 0)
	self:SetElementValue(self.ActionType, ActionRef._type or "Parry")
	self:SetElementValue(self.IgnoreHitboxCheck, ActionRef.ihbc == true)
	self:SetElementValue(self.HitboxWidth, ActionRef.hitbox and ActionRef.hitbox.X or 0)
	self:SetElementValue(self.HitboxHeight, ActionRef.hitbox and ActionRef.hitbox.Y or 0)
	self:SetElementValue(self.HitboxLength, ActionRef.hitbox and ActionRef.hitbox.Z or 0)

	self:Exaload(ActionRef)

	self.Resetting = WasResetting
end

---Restore selected action fields when the controls are being used as a new-action draft.
---@param TimingObj Timing
function BuilderSection:RestoreDraftAction(TimingObj)
	local SelectedName = self.SelectedActionName
	local Snapshot = self.SelectedActionSnapshot
	if type(SelectedName) ~= "string" or not Snapshot then
		return
	end

	local ActionName = StringValue(self.ActionName, "")
	if ActionName == SelectedName then
		return
	end

	local ActionRef = TimingObj.actions:Find(SelectedName)
	if not ActionRef then
		return
	end

	ActionRef._type = Snapshot._type
	ActionRef._when = Snapshot._when
	ActionRef.hitbox = Snapshot.hitbox
	ActionRef.ihbc = Snapshot.ihbc
end

---Wrap a callback that needs a timing.
---@param Callback function(Timing, ...)
---@return function(...)
function BuilderSection:Tnc(Callback)
	return function(...)
		if self.Initializing or self.Resetting then return end
		-- If no value, return silently.
		local TimingValue = self.TimingList.Value
		if type(TimingValue) ~= "string" then return end
		local TimingObj = self.Pair:Find(TimingValue)
		if not TimingObj then
			return Logger.LongNotify("You must select a valid timing to perform this action.")
		end

		-- Fire callback.
		Callback(TimingObj, ...)
		QueueAutoSave()
	end
end

---Wrap a callback that needs both an action and a timing.
---@param Callback function(Timing, Action, ...)
---@return function
function BuilderSection:Tanc(Callback)
	return function(...)
		if self.Initializing or self.Resetting then return end
		-- If no value, return.
		local TimingValue = self.TimingList.Value
		if type(TimingValue) ~= "string" then return end

		-- Find timing.
		local TimingObj = self.Pair:Find(TimingValue)
		if not TimingObj then
			return Logger.LongNotify("You must select a valid timing to perform this action.")
		end

		-- If no value, return.
		local ActionValue = self.ActionList.Value
		if type(ActionValue) ~= "string" then return end

		-- Find action.
		local ActionRef = TimingObj.actions:Find(ActionValue)
		if not ActionRef then return end

		-- Fire callback.
		Callback(TimingObj, ActionRef, ...)
		QueueAutoSave()
	end
end

---Wrap a callback that needs an action.
---@param Callback function(Action, ...)
---@return function
function BuilderSection:Anc(Callback)
	return function(...)
		if self.Initializing or self.Resetting then return end
		-- If no value, return.
		local TimingValue = self.TimingList.Value
		if type(TimingValue) ~= "string" then return end

		-- Find timing.
		local TimingObj = self.Pair:Find(TimingValue)
		if not TimingObj then return end

		-- If no value, return.
		local ActionValue = self.ActionList.Value
		if type(ActionValue) ~= "string" then return end

		-- Find action.
		local ActionRef = TimingObj.actions:Find(ActionValue)
		if not ActionRef then return end

		-- Skip if ActionName changed (user is setting up a new action, not editing).
		if self.ActionName and StringValue(self.ActionName, "") ~= ActionRef.name then return end

		-- Fire callback.
		Callback(ActionRef, ...)
		QueueAutoSave()
	end
end

---Initialize action base.
---@param Base table
function BuilderSection:Baction(Base)
	self.ActionList = Base:Dropdown({
		Name = "Action List",
		Items = {},
		AllowNull = true,
		Callback = self:Tnc(function(TimingObj, Value)
			-- Reset action elements.
			self:Raction()

			-- Check if value exists.
			if not Value then
				return Logger.Warn("No action value.")
			end

			-- Find action.
			local ActionRef = TimingObj.actions:Find(Value)
			if not ActionRef then
				return Logger.LongNotify("The selected action '%s' does not exist in the list.", Value)
			end

			-- Load action elements.
			self:LoadActionElements(ActionRef)
		end),
	})

	local ActionTypes = GetConfiguredActionTypes()
	self.ActionType = Base:Dropdown({
		Name = "Action Type",
		Items = ActionTypes,
		Default = ActionTypes[1],
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef._type = Value
		end),
	})

	self:Daction(Base)

	self.IgnoreHitboxCheck = Base:Toggle({
		Name = "Ignore Hitbox Check",
		Tooltip = "If enabled, the action executes without checking whether the target is inside the hitbox.",
		Default = false,
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef.ihbc = Value
		end),
	})

	self.HitboxWidth = Base:Slider({
		Name = "Hitbox Width (X)",
		Min = 0,
		Max = 300,
		Suffix = "s",
		Default = 0,
		Decimals = 1,
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef.hitbox = Vector3.new(Value, ActionRef.hitbox.Y, ActionRef.hitbox.Z)
		end),
	})

	self.HitboxHeight = Base:Slider({
		Name = "Hitbox Height (Y)",
		Min = 0,
		Max = 300,
		Suffix = "s",
		Default = 0,
		Decimals = 1,
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef.hitbox = Vector3.new(ActionRef.hitbox.X, Value, ActionRef.hitbox.Z)
		end),
	})

	self.HitboxLength = Base:Slider({
		Name = "Hitbox Length (Z)",
		Min = 0,
		Max = 300,
		Suffix = "s",
		Default = 0,
		Decimals = 1,
		Callback = self:Anc(function(ActionRef, Value)
			ActionRef.hitbox = Vector3.new(ActionRef.hitbox.X, ActionRef.hitbox.Y, Value)
		end),
	})

	Base:Divider()

	self.ActionName = Base:Textbox({
		Placeholder = "Action Name",
	})

	Base:Button({
		Name = "Create New Action",
		Callback = function()
			-- Explicit timing check with notification.
			local TimingValue = self.TimingList.Value
			if type(TimingValue) ~= "string" then
				return Logger.LongNotify("Please select a timing first.")
			end
			local TimingObj = self.Pair:Find(TimingValue)
			if not TimingObj then
				return Logger.LongNotify("Selected timing not found.")
			end

			-- Fetch actions.
			local Actions = TimingObj.actions

			-- Check.
			if not self:Acheck(TimingObj) then
				return
			end

			-- Restore selected action if the current controls are being used to draft a new action.
			self:RestoreDraftAction(TimingObj)

			-- Create new action from current slider/dropdown values.
			local ActionRef = Action.new()
			ActionRef.name = StringValue(self.ActionName, "")
			ActionRef._type = self.ActionType.Value or "Parry"
			ActionRef._when = NumberValue(self.ActionDelay, 0)
			ActionRef.ihbc = self.IgnoreHitboxCheck.Value == true

			ActionRef.hitbox = Vector3.new(
				self.HitboxWidth.Value or 0,
				self.HitboxHeight.Value or 0,
				self.HitboxLength.Value or 0
			)

			-- Record ping for telemetry.
			local Network = Stats:FindFirstChild("Network")
			local ServerStatsItem = Network and Network:FindFirstChild("ServerStatsItem")
			local DataPingItem = ServerStatsItem and ServerStatsItem:FindFirstChild("Data Ping")

			if DataPingItem then
				ActionRef.ping = DataPingItem:GetValue()
			end

			-- Push action.
			Actions:Push(ActionRef)

			-- Refresh action list.
			self:Arefresh(TimingObj)

			-- Clear action fields so the next draft does not edit the newly created action.
			self:Raction()

			QueueAutoSave()
		end,
	})

	Base:Button({
		Name = "Duplicate Selected Action",
		Callback = self:Tanc(function(TimingObj, ActionRef)
			-- Fetch actions.
			local Actions = TimingObj.actions

			-- Check.
			if not self:Acheck(TimingObj) then
				return
			end

			-- Create new action.
			local NewAction = ActionRef:Clone()
			NewAction.name = StringValue(self.ActionName, "")

			-- Record ping for telemetry.
			local Network = Stats:FindFirstChild("Network")
			local ServerStatsItem = Network and Network:FindFirstChild("ServerStatsItem")
			local DataPingItem = ServerStatsItem and ServerStatsItem:FindFirstChild("Data Ping")

			if DataPingItem then
				NewAction.ping = DataPingItem:GetValue()
			end

			-- Push action.
			Actions:Push(NewAction)

			-- Refresh action list.
			self:Arefresh(TimingObj)

			-- Clear action fields so the next draft does not edit the newly duplicated action.
			self:Raction()

			QueueAutoSave()
		end),
	})

	Base:Button({
		Name = "Remove Selected Action",
		Callback = self:Tnc(function(TimingObj)
			-- Get selected value.
			local Selected = self.ActionList.Value
			if not Selected then
				return Logger.LongNotify("Please select an action to remove.")
			end

			-- Fetch actions.
			local Actions = TimingObj.actions

			-- Find action.
			local ActionRef = Actions:Find(Selected)
			if not ActionRef then
				return Logger.LongNotify("The selected action '%s' does not exist in the list.", Selected)
			end

			-- Remove action.
			Actions:Remove(ActionRef)

			-- Save updated timing to disk.
			SaveManager.SaveAll()

			-- Refresh action list.
			self:Arefresh(TimingObj)

			QueueAutoSave()
		end),
	})
end

---Initialize timing tab.
function BuilderSection:TimingTab()
	local Tab = self.Tabbox:AddTab("Timings")

	self.TimingList = Tab:Dropdown({
		Name = "Timing List",
		Items = self.Pair.Config:Names(),
		AllowNull = true,
		Callback = function(Value)
			-- Reset elements.
			self:Reset()

			-- Check if value exists.
			if not Value then
				return Logger.Warn("No timing value.")
			end

			-- Fetch timing.
			local Found = self.Pair:Find(Value)
			if not Found then
				return Logger.LongNotify("The selected timing '%s' does not exist in the list.", Value)
			end

			-- Load timing elements.
			self:LoadTimingElements(Found)
		end,
	})

	Tab:Divider()

	self.TimingName = Tab:Textbox({
		Placeholder = "Timing Name",
		Finished = true,
	})

	self:Tide(Tab)

	Tab:Button({
		Name = "Create New Timing",
		Callback = function()
			-- Fetch config.
			local ConfigContainer = self.Pair.Config

			-- Check if we can successfully create a timing from the given data.
			if not self:Check() then
				return
			end

			-- Create new timing.
			local TimingObj = self:Create()

			-- Push new timing.
			ConfigContainer:Push(TimingObj)

			-- Refresh timing list.
			self:Refresh()

			-- Set timing list value.
			self.TimingList:Set(TimingObj.name)

			QueueAutoSave()
		end,
	})

	Tab:Button({
		Name = "Duplicate Selected Timing",
		Callback = self:Tnc(function(Found)
			-- Fetch config.
			local ConfigContainer = self.Pair.Config

			-- Clone new timing.
			local TimingObj = Found:Clone()

			-- Auto-generate unique name if needed.
			local BaseName = self.TimingName.Value
			if not BaseName or #BaseName <= 0 then
				BaseName = Found.name
			end
			local FinalName = BaseName
			local Suffix = 2
			while self.Pair:Find(FinalName) do
				FinalName = BaseName .. " (" .. Suffix .. ")"
				Suffix = Suffix + 1
			end
			-- Set creation properties.
			self:Cset(TimingObj)
			TimingObj.name = FinalName

			-- Push new timing.
			ConfigContainer:Push(TimingObj)

			-- Refresh timing list.
			self:Refresh()

			-- Set timing list value.
			self.TimingList:Set(TimingObj.name)

			QueueAutoSave()
		end),
	})

	Tab:Button({
		Name = "Remove Selected Timing",
		Callback = function()
			-- Fetch name.
			local Name = self.TimingList.Value
			if not Name then
				return Logger.LongNotify("Please select a timing to remove.")
			end

			-- Fetch data.
			local ConfigContainer = self.Pair.Config
			local Found = ConfigContainer:Find(Name)

			-- Check if found.
			if not Found then
				return Logger.LongNotify("The selected timing '%s' does not exist in the list.", Name)
			end

			-- Remove timing.
			ConfigContainer:Remove(Found)

			-- Delete from disk.
			SaveManager.Delete(self.Name:lower(), Name)

			-- Refresh timing list.
			self:Refresh()

			QueueAutoSave()
		end,
	})
end

---Initialize builder tab.
function BuilderSection:Builder()
	local Tab = self.Tabbox:AddTab(string.format("%s", self.Name))

	self.TimingTag = Tab:Dropdown({
		Name = "Timing Tag",
		Items = { "Undefined", "Critical", "Mantra", "M1" },
		Default = "Undefined",
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.tag = Value
		end),
	})

	self.InitialMinimumDistance = Tab:Slider({
		Name = "Initial Minimum Distance",
		Min = 0,
		Max = 300,
		Suffix = "s",
		Default = 0,
		Decimals = 1,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.imdd = Value
		end),
	})

	self.InitialMaximumDistance = Tab:Slider({
		Name = "Initial Maximum Distance",
		Min = 0,
		Max = 2500,
		Suffix = "s",
		Default = 1000,
		Decimals = 1,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.imxd = Value
		end),
	})

	self.PunishableWindow = Tab:Slider({
