---Initialize BuilderSection object.
function BuilderSection:Init()
	self.Initializing = true
	self:TimingTab()
	self:Builder()
	self:Action()
	self.Initializing = false
end

---Create new BuilderSection object.
---@param Name string
---@param Tabbox table
---@param Pair TimingContainerPair
---@return BuilderSection
function BuilderSection.new(Name, Tabbox, Pair)
	local Self = setmetatable({}, BuilderSection)
	Self.Name = Name
	Self.Tabbox = Tabbox
	Self.Pair = Pair
	return Self
end

-- Return BuilderSection module.
return BuilderSection
end)
__bundle_register("Builder/BuilderTab", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Timings.SaveManager
local SaveManager = require("Timings/SaveManager")

---@module Builder.AnimationBuilderSection
local AnimationBuilderSection = require("Builder/AnimationBuilderSection")

---@module Builder.SoundBuilderSection
local SoundBuilderSection = require("Builder/SoundBuilderSection")

---@module Builder.PartBuilderSection
local PartBuilderSection = require("Builder/PartBuilderSection")

---@module Timings.AnimationTiming
local AnimationTiming = require("Timings/AnimationTiming")

---@module Timings.PartTiming
local PartTiming = require("Timings/PartTiming")

---@module Timings.SoundTiming
local SoundTiming = require("Timings/SoundTiming")

---@module Modules.ModuleManager
local ModuleManager = require("Modules/ModuleManager")

---@module Core.AnimationVisualizer
local AnimationVisualizer = require("Core/AnimationVisualizer")

---@module Core.InfoLogger
local InfoLogger = require("Core/InfoLogger")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

-- Simulation state.
local BuilderMaid = Maid.new()
local SimulationMaid = Maid.new()
local HitboxSimulationSection = nil

-- Capture session ID at load time. Old loops will have a stale ID.
local MySessionId = getgenv().__EP_SimulationSession

local function RunSimulationStep()
	if getgenv().__EP_SimulationSession ~= MySessionId then
		SimulationMaid:Clean()
		return
	end

	if not HitboxSimulationSection or not HitboxSimulationSection.IsActive then
		return SimulationMaid:Clean()
	end

	local Character = Players.LocalPlayer.Character
	if not Character then
		return
	end

	local Root = Character:FindFirstChild("HumanoidRootPart")
	if not Root then
		return
	end

	local HitboxType = Configuration.ExpectOptionValue("EP_HS_HitboxType") or "Block"
	local Size = Vector3.new(
		Configuration.ExpectOptionValue("EP_HS_HitboxSizeX") or 4,
		Configuration.ExpectOptionValue("EP_HS_HitboxSizeY") or 4,
		Configuration.ExpectOptionValue("EP_HS_HitboxSizeZ") or 4
	)

	local Fd = Configuration.ExpectToggleValue("EP_HS_FacingOffset")
	local Soffset = Configuration.ExpectOptionValue("EP_HS_ShiftOffset") or 0

	-- Calculate CFrame.
	local UsedCFrame = Root.CFrame

	if Fd then
		UsedCFrame = UsedCFrame * CFrame.new(0, 0, -(Size.Z / 2))
	end

	if Soffset and Soffset ~= 0 then
		UsedCFrame = UsedCFrame * CFrame.new(0, 0, Soffset)
	end

	-- Clean previous frame.
	SimulationMaid:Clean()

	-- Visualize.
	local SimulationPart = Instance.new("Part")
	SimulationPart.Name = "__EP_HitboxSim"
	SimulationPart.Anchored = true
	SimulationPart.CanCollide = false
	SimulationPart.CanQuery = false
	SimulationPart.Size = Size
	SimulationPart.CanTouch = false
	SimulationPart.Material = Enum.Material.ForceField
	SimulationPart.CastShadow = false
	SimulationPart.Transparency = 0.5

	if HitboxType == "Block" then
		SimulationPart.Shape = Enum.PartType.Block
		SimulationPart.CFrame = UsedCFrame
	elseif HitboxType == "Ball" then
		SimulationPart.Shape = Enum.PartType.Ball
		SimulationPart.CFrame = UsedCFrame
	elseif HitboxType == "Cylinder" then
		SimulationPart.Shape = Enum.PartType.Cylinder
		SimulationPart.CFrame = UsedCFrame * CFrame.Angles(0, 0, math.rad(90))
	end

	SimulationPart.Parent = workspace

	-- Hit detection coloring.
	if Configuration.ExpectToggleValue("EP_HS_HitDetection") then
		local OverlapParamsObj = OverlapParams.new()
		OverlapParamsObj.FilterDescendantsInstances = { Character }
		OverlapParamsObj.FilterType = Enum.RaycastFilterType.Exclude

		local Parts = workspace:GetPartsInPart(SimulationPart, OverlapParamsObj)
		local Hitting = false
		for Index, Part in next, Parts do
			local Model = Part:FindFirstAncestorOfClass("Model")
			if Model and Model:FindFirstChildOfClass("Humanoid") and Model ~= Character then
				Hitting = true
				break
			end
		end

		SimulationPart.Color = Hitting and Color3.fromRGB(0, 255, 0) or Color3.fromRGB(255, 0, 0)
	else
		SimulationPart.Color = Color3.fromRGB(0, 120, 255)
	end

	SimulationMaid:Add(function()
		SimulationPart:Destroy()
	end)
end

-- BuilderTab module.
local BuilderTab = {
	Abs = nil,
	Pbs = nil,
	Sbs = nil,
}

---Refresh builder lists.
function BuilderTab.Refresh()
	if BuilderTab.Abs then
		BuilderTab.Abs:Reset()
		BuilderTab.Abs:Refresh()
	end

	if BuilderTab.Pbs then
		BuilderTab.Pbs:Reset()
		BuilderTab.Pbs:Refresh()
	end

	if BuilderTab.Sbs then
		BuilderTab.Sbs:Reset()
		BuilderTab.Sbs:Refresh()
	end
end

---Refresh builder action type lists.
function BuilderTab.RefreshActionTypes()
	local Sections = { BuilderTab.Abs, BuilderTab.Pbs, BuilderTab.Sbs }
	for Index, Section in next, Sections do
		if Section and Section.RefreshActionTypes then
			Section:RefreshActionTypes()
		end
	end
end

---Flush visible builder edits before saving.
function BuilderTab.FlushPendingEdits()
	local Sections = { BuilderTab.Abs, BuilderTab.Pbs, BuilderTab.Sbs }
	for Index, Section in next, Sections do
		if Section and Section.FlushPendingEdits then
			Section:FlushPendingEdits()
		end
	end
end

