---Initialize place ID alias section.
---@param Section table
---@param Config table
function BuilderTab.InitAliasSection(Section, Config)
	local MarketplaceService = game:GetService("MarketplaceService")
	local GamePath = Config.GamePath
	local GameName = Config.GameName or "Unknown"
	local PlaceId = Config.PlaceId or 0
	local AliasFile = GamePath .. "/aliases.json"
	local BasePath = GamePath:match("^(.*)[/\\][^/\\]+$") or "Epiphyllum"
	local OnAliasConfigImported = Config.OnAliasConfigImported or function() end
	local TimingTypes = {
		{ Name = "Animation", IdField = "_id" },
		{ Name = "Sound", IdField = "_id" },
		{ Name = "Part", IdField = "pname" },
	}

	---Fetch game name for a Place ID.
	local function FetchGameName(Id)
		local Success, Info = pcall(function()
			return MarketplaceService:GetProductInfo(tonumber(Id))
		end)
		return (Success and Info and Info.Name) or "Unknown"
	end

	---Load aliases from this game folder.
	local function LoadAliases()
		if not isfile(AliasFile) then return {} end
		local Success, Data = pcall(function()
			return HttpService:JSONDecode(readfile(AliasFile))
		end)
		return (Success and type(Data) == "table" and Data) or {}
	end

	---Save aliases to this game folder.
	local function SaveAliases(Data)
		pcall(function()
			writefile(AliasFile, HttpService:JSONEncode(Data))
		end)
	end

	---Find a saved game folder by Place ID.
	---@param Id string
	---@return string?
	local function FindGamePathByPlaceId(Id)
		if not isfolder(BasePath) then return nil end

		local Success, Folders = pcall(listfiles, BasePath)
		if not Success or not Folders then return nil end

		for Index, FolderPath in next, Folders do
			if not isfolder(FolderPath) then continue end
			local FolderPlaceId = tostring(FolderPath):match("%- (%d+)$")
			if FolderPlaceId == tostring(Id) then
				return FolderPath
			end
		end
	end

	---Create timing folders for a game path.
	---@param Path string
	local function EnsureTimingFolders(Path)
		if not isfolder(Path) then makefolder(Path) end
		if not isfolder(Path .. "/Timings") then makefolder(Path .. "/Timings") end

		for Index, TimingType in next, TimingTypes do
			local TypePath = Path .. "/Timings/" .. TimingType.Name
			if not isfolder(TypePath) then makefolder(TypePath) end
		end
	end

	---Check if two JSON values are equal.
	---@param Left any
	---@param Right any
	---@return boolean
	local function DeepEquals(Left, Right)
		if Left == Right then
			return true
		end

		if typeof(Left) ~= typeof(Right) then
			return false
		end

		if typeof(Left) ~= "table" then
			return false
		end

		for Key, Value in next, Left do
			if not DeepEquals(Value, Right[Key]) then
				return false
			end
		end

		for Key in next, Right do
			if Left[Key] == nil then
				return false
			end
		end

		return true
	end

	---Read timing entries from a type folder.
	---@param TypePath string
	---@param IdField string
	---@return table
	local function ReadTimingEntries(TypePath, IdField)
		local Entries = {
			List = {},
			ByFilename = {},
			ById = {},
			ByName = {},
			DuplicateIds = {},
			DuplicateNames = {},
			Invalid = 0,
		}

		if not isfolder(TypePath) then
			return Entries
		end

		local Success, Files = pcall(listfiles, TypePath)
		if not Success or not Files then
			return Entries
		end

		for Index, FilePath in next, Files do
			if FilePath:sub(-5) ~= ".json" then continue end

			local ReadOk, Content = pcall(readfile, FilePath)
			if not ReadOk or not Content then
				Entries.Invalid = Entries.Invalid + 1
				continue
			end

			local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
			if not DecodeOk or typeof(Data) ~= "table" then
				Entries.Invalid = Entries.Invalid + 1
				continue
			end

			local Filename = tostring(FilePath):match("[^/\\]+$") or "timing.json"
			local Entry = {
				FilePath = FilePath,
				Filename = Filename,
				Content = Content,
				Data = Data,
				TimingId = Data[IdField] and tostring(Data[IdField]) or nil,
				TimingName = Data.name and tostring(Data.name) or nil,
			}

			Entries.List[#Entries.List + 1] = Entry
			Entries.ByFilename[Filename] = Entry

			if Entry.TimingId then
				if Entries.ById[Entry.TimingId] then
					Entries.DuplicateIds[Entry.TimingId] = true
				end
				Entries.ById[Entry.TimingId] = Entry
			end

			if Entry.TimingName then
				if Entries.ByName[Entry.TimingName] then
					Entries.DuplicateNames[Entry.TimingName] = true
				end
				Entries.ByName[Entry.TimingName] = Entry
			end
		end

		return Entries
	end

	---Index a timing entry.
	---@param Entries table
	---@param Entry table
	local function IndexTimingEntry(Entries, Entry)
		Entries.ByFilename[Entry.Filename] = Entry

		if Entry.TimingId then
			Entries.ById[Entry.TimingId] = Entry
		end

		if Entry.TimingName then
			Entries.ByName[Entry.TimingName] = Entry
		end
	end

	---Unindex a timing entry.
	---@param Entries table
	---@param Entry table
	local function UnindexTimingEntry(Entries, Entry)
		if Entries.ByFilename[Entry.Filename] == Entry then
			Entries.ByFilename[Entry.Filename] = nil
		end

		if Entry.TimingId and Entries.ById[Entry.TimingId] == Entry then
			Entries.ById[Entry.TimingId] = nil
		end

		if Entry.TimingName and Entries.ByName[Entry.TimingName] == Entry then
			Entries.ByName[Entry.TimingName] = nil
		end
	end

	---Create a unique destination file path.
	---@param TypePath string
	---@param Filename string
	---@return string
	local function UniqueFilePath(TypePath, Filename)
		local BaseName = Filename:sub(1, -6)
		local Extension = ".json"
		local Candidate = TypePath .. "/" .. Filename

		if not isfile(Candidate) then
			return Candidate
		end

		for Index = 2, 100 do
			Candidate = TypePath .. "/" .. BaseName .. "_" .. tostring(Index) .. Extension
			if not isfile(Candidate) then
				return Candidate
			end
		end

		return TypePath .. "/" .. tostring(os.clock()) .. "_" .. Filename
	end

	---Import and update timing files from a linked place folder.
	---@param Id string
	---@return number
	---@return number
	---@return number
	---@return number
	---@return number
	---@return boolean
	local function ImportAliasTimings(Id)
		local SourcePath = FindGamePathByPlaceId(Id)
		if not SourcePath or SourcePath == GamePath then
			return 0, 0, 0, 0, 0, false
		end

		EnsureTimingFolders(GamePath)

		local Added = 0
		local Updated = 0
		local Unchanged = 0
		local Conflicted = 0
		local Failed = 0

		for Index, TimingType in next, TimingTypes do
			local SourceTypePath = SourcePath .. "/Timings/" .. TimingType.Name
			local TargetTypePath = GamePath .. "/Timings/" .. TimingType.Name
			if not isfolder(SourceTypePath) then continue end

			local SourceEntries = ReadTimingEntries(SourceTypePath, TimingType.IdField)
			local TargetEntries = ReadTimingEntries(TargetTypePath, TimingType.IdField)
			Failed = Failed + SourceEntries.Invalid + TargetEntries.Invalid

			for FileIndex, SourceEntry in next, SourceEntries.List do
				if not SourceEntry.TimingId or not SourceEntry.TimingName then
					Failed = Failed + 1
					continue
				end

				if
					SourceEntries.DuplicateIds[SourceEntry.TimingId]
					or SourceEntries.DuplicateNames[SourceEntry.TimingName]
					or TargetEntries.DuplicateIds[SourceEntry.TimingId]
					or TargetEntries.DuplicateNames[SourceEntry.TimingName]
				then
					Conflicted = Conflicted + 1
					continue
				end

				local IdMatch = TargetEntries.ById[SourceEntry.TimingId]
				local NameMatch = TargetEntries.ByName[SourceEntry.TimingName]
				local TargetEntry = IdMatch or NameMatch

				if IdMatch and NameMatch and IdMatch ~= NameMatch then
					Conflicted = Conflicted + 1
					continue
				end

				if TargetEntry then
					if DeepEquals(SourceEntry.Data, TargetEntry.Data) then
						Unchanged = Unchanged + 1
						continue
					end

					local WriteOk = pcall(writefile, TargetEntry.FilePath, SourceEntry.Content)
					if WriteOk then
						UnindexTimingEntry(TargetEntries, TargetEntry)
						TargetEntry.Content = SourceEntry.Content
						TargetEntry.Data = SourceEntry.Data
						TargetEntry.TimingId = SourceEntry.TimingId
						TargetEntry.TimingName = SourceEntry.TimingName
						IndexTimingEntry(TargetEntries, TargetEntry)
						Updated = Updated + 1
					else
						Failed = Failed + 1
					end

					continue
				end

				local TargetFilePath = UniqueFilePath(TargetTypePath, SourceEntry.Filename)
				local WriteOk = pcall(writefile, TargetFilePath, SourceEntry.Content)
				if WriteOk then
					local TargetFilename = tostring(TargetFilePath):match("[^/\\]+$") or SourceEntry.Filename
					IndexTimingEntry(TargetEntries, {
						FilePath = TargetFilePath,
						Filename = TargetFilename,
						Content = SourceEntry.Content,
						Data = SourceEntry.Data,
						TimingId = SourceEntry.TimingId,
						TimingName = SourceEntry.TimingName,
					})
					Added = Added + 1
				else
					Failed = Failed + 1
				end
			end
		end

		if Added > 0 or Updated > 0 then
			SaveManager.Refresh()
			BuilderTab.Refresh()
		end

		return Added, Updated, Unchanged, Conflicted, Failed, true
	end

	---Normalize remote/input config.
	---@param Data table?
	---@return table
	local function NormalizeDispatchConfig(Data)
		Data = typeof(Data) == "table" and Data or {}

		local Out = {
			remotes = {},
			inputs = {},
		}

		local Remotes = typeof(Data.remotes) == "table" and Data.remotes or {}
		for Index, Entry in next, Remotes do
			if typeof(Entry) ~= "table" then continue end
			local Action = tostring(Entry.action or "")
			local Path = tostring(Entry.path or "")
			local Args = typeof(Entry.args) == "table" and Entry.args or {}
			local CleanArgs = {}

			for ArgIndex, Arg in next, Args do
				if typeof(Arg) == "string" and Arg ~= "" then
					CleanArgs[#CleanArgs + 1] = Arg
				end
			end

			Out.remotes[#Out.remotes + 1] = {
				action = Action,
				path = Path,
				args = CleanArgs,
			}
		end

		local Inputs = typeof(Data.inputs) == "table" and Data.inputs or {}
		for Index, Entry in next, Inputs do
			if typeof(Entry) ~= "table" then continue end
			Out.inputs[#Out.inputs + 1] = {
				action = tostring(Entry.action or ""),
				key = tostring(Entry.key or ""),
			}
		end

		return Out
	end

	---Read dispatch config from a game folder.
	---@param Path string
	---@return table
	---@return boolean
	---@return boolean
	local function ReadDispatchConfig(Path)
		local ConfigPath = Path .. "/remotes.json"
		if not isfile(ConfigPath) then
			return NormalizeDispatchConfig(nil), false, true
		end

		local ReadOk, Content = pcall(readfile, ConfigPath)
		if not ReadOk or not Content then
			return NormalizeDispatchConfig(nil), true, false
		end

		local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
		if not DecodeOk or typeof(Data) ~= "table" then
			return NormalizeDispatchConfig(nil), true, false
		end

		return NormalizeDispatchConfig(Data), true, true
	end

	---Create a config signature.
	---@param Parts table
	---@return string
	local function ConfigSignature(Parts)
		local EncodeOk, Json = pcall(HttpService.JSONEncode, HttpService, Parts)
		if EncodeOk then
			return Json
		end

		local Out = {}
		for Index, Part in next, Parts do
			Out[#Out + 1] = tostring(Part)
		end

		return table.concat(Out, "\31")
	end

	---Build dispatch config indexes.
	---@param TargetConfig table
	---@return table
	local function BuildDispatchIndexes(TargetConfig)
		local Indexes = {
			RemoteExact = {},
			RemoteBlankByAction = {},
			InputExact = {},
			InputBlankByAction = {},
		}

		for Index, Entry in next, TargetConfig.remotes do
			local Action = tostring(Entry.action or "")
			local Path = tostring(Entry.path or "")
			local Signature = ConfigSignature({ Action, Path, Entry.args or {} })
			Indexes.RemoteExact[Signature] = true

			if Action ~= "" and Path == "" then
				Indexes.RemoteBlankByAction[Action] = Entry
			end
		end

		for Index, Entry in next, TargetConfig.inputs do
			local Action = tostring(Entry.action or "")
			local Key = tostring(Entry.key or "")
			local Signature = ConfigSignature({ Action, Key })
			Indexes.InputExact[Signature] = true

			if Action ~= "" and Key == "" then
				Indexes.InputBlankByAction[Action] = Entry
			end
		end

		return Indexes
	end

	---Merge remote and input config from a linked place folder.
	---@param Id string
	---@return number
	---@return number
	---@return number
	---@return number
	---@return boolean
	local function ImportAliasDispatchConfig(Id)
		local SourcePath = FindGamePathByPlaceId(Id)
		if not SourcePath or SourcePath == GamePath then
			return 0, 0, 0, 0, false
		end

		local SourceConfig, SourceFound, SourceOk = ReadDispatchConfig(SourcePath)
		if not SourceFound then
			return 0, 0, 0, 0, true
		end

		if not SourceOk then
			return 0, 0, 0, 1, true
		end

		local TargetConfig, TargetFound, TargetOk = ReadDispatchConfig(GamePath)
		if TargetFound and not TargetOk then
			return 0, 0, 0, 1, true
		end

		local Indexes = BuildDispatchIndexes(TargetConfig)
		local Added = 0
		local Updated = 0
		local Unchanged = 0
		local Failed = 0

		for Index, Entry in next, SourceConfig.remotes do
			local Action = tostring(Entry.action or "")
			local Path = tostring(Entry.path or "")
			if Action == "" or Path == "" then continue end

			local Signature = ConfigSignature({ Action, Path, Entry.args or {} })
			if Indexes.RemoteExact[Signature] then
				Unchanged = Unchanged + 1
				continue
			end

			local BlankEntry = Indexes.RemoteBlankByAction[Action]
			if BlankEntry then
				BlankEntry.path = Path
				BlankEntry.args = Entry.args or {}
				Indexes.RemoteBlankByAction[Action] = nil
				Indexes.RemoteExact[Signature] = true
				Updated = Updated + 1
				continue
			end

			TargetConfig.remotes[#TargetConfig.remotes + 1] = {
				action = Action,
				path = Path,
				args = Entry.args or {},
			}
			Indexes.RemoteExact[Signature] = true
			Added = Added + 1
		end

		for Index, Entry in next, SourceConfig.inputs do
			local Action = tostring(Entry.action or "")
			local Key = tostring(Entry.key or "")
			if Action == "" or Key == "" then continue end

			local Signature = ConfigSignature({ Action, Key })
			if Indexes.InputExact[Signature] then
				Unchanged = Unchanged + 1
				continue
			end

			local BlankEntry = Indexes.InputBlankByAction[Action]
			if BlankEntry then
				BlankEntry.key = Key
				Indexes.InputBlankByAction[Action] = nil
				Indexes.InputExact[Signature] = true
				Updated = Updated + 1
				continue
			end

			TargetConfig.inputs[#TargetConfig.inputs + 1] = {
				action = Action,
				key = Key,
			}
			Indexes.InputExact[Signature] = true
			Added = Added + 1
		end

		if Added > 0 or Updated > 0 then
			local EncodeOk, Json = pcall(HttpService.JSONEncode, HttpService, TargetConfig)
			if EncodeOk then
				local WriteOk = pcall(writefile, GamePath .. "/remotes.json", Json)
				if WriteOk then
					OnAliasConfigImported()
				else
					Failed = Failed + 1
				end
			else
				Failed = Failed + 1
			end
		end

		return Added, Updated, Unchanged, Failed, true
	end

	---Get alias list for display.
	local function GetAliasList()
		local Aliases = LoadAliases()
		local Out = {}
		for I = 1, #Aliases do
			local Id = tostring(Aliases[I])
			local Name = FetchGameName(Id)
			Out[#Out + 1] = string.format("%s - %s", Name, Id)
		end
		table.sort(Out)
		return Out
	end

	-- Current game info.
	Section:Label(string.format("Current: %s - %s", GameName, tostring(PlaceId)))

	local AliasDropdown = Section:Listbox({
		Flag = "EP_AliasList",
		Items = GetAliasList(),
		Multi = false,
		Marquee = true,
	})

	local AliasPlaceIdInput = nil

	Section:Textbox({
		Flag = "EP_AliasPlaceId",
		Placeholder = "Place ID to link",
		Numeric = true,
		Finished = false,
		Callback = function(Value)
			AliasPlaceIdInput = Value
		end,
	})

	Section:Button({
		Name = "Link Place ID",
		Callback = function()
			local Input = AliasPlaceIdInput or Configuration.ExpectOptionValue("EP_AliasPlaceId") or ""
			if Input == "" then return Logger.Notify("Enter a Place ID first.") end
			Input = tostring(Input)

			local Aliases = LoadAliases()
			local AlreadyLinked = false

			-- Check for duplicate.
			for I = 1, #Aliases do
				if tostring(Aliases[I]) == tostring(Input) then
					AlreadyLinked = true
					break
				end
			end

			if not AlreadyLinked then
				Aliases[#Aliases + 1] = Input
				SaveAliases(Aliases)
			end

			AliasDropdown:Refresh(GetAliasList())
			local LinkedName = FetchGameName(Input)
			local Added, Updated, Unchanged, Conflicted, Failed, SourceFound = ImportAliasTimings(Input)
			local ConfigAdded, ConfigUpdated, ConfigUnchanged, ConfigFailed = ImportAliasDispatchConfig(Input)

			if not SourceFound then
				if AlreadyLinked then
					return Logger.Notify("Place ID %s is already linked. No saved timing folder found.", Input)
				end

				return Logger.Notify("%s (%s) linked. No saved timing folder found.", LinkedName, Input)
			end

			if AlreadyLinked then
				Logger.Notify(
					"Place ID %s already linked. Added %d, updated %d, unchanged %d, conflicts %d, failed %d.",
					Input,
					Added + ConfigAdded,
					Updated + ConfigUpdated,
					Unchanged + ConfigUnchanged,
					Conflicted,
					Failed + ConfigFailed
				)
			else
				Logger.Notify(
					"%s (%s) linked. Added %d, updated %d, unchanged %d, conflicts %d, failed %d.",
					LinkedName,
					Input,
					Added + ConfigAdded,
					Updated + ConfigUpdated,
					Unchanged + ConfigUnchanged,
					Conflicted,
					Failed + ConfigFailed
				)
			end
		end,
	})

	Section:Button({
		Name = "Remove Selected",
		Callback = function()
			local Selected = Configuration.ExpectOptionValue("EP_AliasList")
			if not Selected or Selected == "" then return end
			local Id = Selected:match("- (%d+)$")
			if not Id then return end
			local Aliases = LoadAliases()
			local New = {}
			for I = 1, #Aliases do
				if tostring(Aliases[I]) ~= Id then
					New[#New + 1] = Aliases[I]
				end
			end
			SaveAliases(New)
			AliasDropdown:Refresh(GetAliasList())
			Logger.Notify("Place ID %s removed.", Id)
		end,
	})
end

---Initialize tabs on a window.
---@param Window table
---@param Icons table?
function BuilderTab.Init(Window, Icons, AliasConfig)
	Icons = Icons or {}
	AliasConfig = AliasConfig or {}

	Window:Category("Builder")

	-- Config page.
	local ConfigPage = Window:Page({ Name = "Config", Icon = Icons["sliders-horizontal"] or "" })
	BuilderTab.InitSaveManagerSection(ConfigPage:Section({ Name = "Save Manager", Side = 1, Icon = Icons["save"] or "", Collapsible = false }))
	BuilderTab.InitModuleManagerSection(ConfigPage:Section({ Name = "Module Manager", Side = 2, Icon = Icons["puzzle"] or "", Collapsible = false }))
	local HitboxSimSection = ConfigPage:Section({ Name = "Hitbox Simulation", Side = 2, Icon = Icons["crosshair"] or "" })
	HitboxSimSection:ToggleBackground()
	BuilderTab.InitHitboxSimulationSection(HitboxSimSection)
	BuilderTab.InitInfoLoggerSection(ConfigPage:Section({ Name = "Debugging", Side = 1, Icon = Icons["scroll-text"] or "" }))

	-- Place ID aliases.
	if AliasConfig.GamePath then
		BuilderTab.InitAliasSection(
			ConfigPage:Section({ Name = "Place ID Aliases", Side = 2, Icon = Icons["users-round"] or "", Collapsible = false }),
			AliasConfig
		)
	end

	-- Animation builder.
	local AnimPage = Window:Page({ Name = "Animation", Icon = Icons["film"] or "" })
	local AnimSection = AnimPage:Section({ Name = "Animation Builder", Side = 1, Icon = Icons["film"] or "" })
	local AnimTabBox = AnimSection:TabBox()
	BuilderTab.Abs = AnimationBuilderSection.new("Animation", AnimTabBox, SaveManager.As)
	BuilderTab.Abs:Init()

	-- Sound builder.
	local SoundPage = Window:Page({ Name = "Sound", Icon = Icons["volume-2"] or "" })
	local SoundSection = SoundPage:Section({ Name = "Sound Builder", Side = 1, Icon = Icons["volume-2"] or "" })
	local SoundTabBox = SoundSection:TabBox()
	BuilderTab.Sbs = SoundBuilderSection.new("Sound", SoundTabBox, SaveManager.Ss)
	BuilderTab.Sbs:Init()

	-- Part builder.
	local PartPage = Window:Page({ Name = "Part", Icon = Icons["box"] or "" })
	local PartSection = PartPage:Section({ Name = "Part Builder", Side = 1, Icon = Icons["box"] or "" })
	local PartTabBox = PartSection:TabBox()
	BuilderTab.Pbs = PartBuilderSection.new("Part", PartTabBox, SaveManager.Ps)
	BuilderTab.Pbs:Init()

	-- Refresh action types when dispatch configuration changes.
	getgenv().__EP_RefreshBuilderActionTypes = function()
		BuilderTab.RefreshActionTypes()
	end
	BuilderTab.RefreshActionTypes()

	-- Initialize animation visualizer.
	AnimationVisualizer.Init()

	-- Hitbox simulation render loop.
	local RenderStepped = Signal.new(RunService.RenderStepped)
	BuilderMaid:Mark(RenderStepped:Connect("BuilderTab_RunSimulationStep", RunSimulationStep))
end

---Detach tab.
function BuilderTab.Detach()
	if getgenv().__EP_RefreshBuilderActionTypes then
		getgenv().__EP_RefreshBuilderActionTypes = nil
	end

	AnimationVisualizer.Detach()
	BuilderMaid:Clean()
	SimulationMaid:Clean()
end

-- Return BuilderTab module.
return BuilderTab
end)
__bundle_register("Builder/PartBuilderSection", function(require, _LOADED, __bundle_register, __bundle_modules)
---@module Builder.BuilderSection
local BuilderSection = require("Builder/BuilderSection")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Timings.PartTiming
local PartTiming = require("Timings/PartTiming")

---@class PartBuilderSection: BuilderSection
---@field PartName table
---@field UseHitboxCFrame table
local PartBuilderSection = setmetatable({}, { __index = BuilderSection })
PartBuilderSection.__index = PartBuilderSection

---Create timing ID element. Override me.
---@param Tab table
function PartBuilderSection:Tide(Tab)
	self.PartName = Tab:Textbox({
		Placeholder = "Part Name",
	})
end

---Load the extra elements. Override me.
---@param TimingObj PartTiming
function PartBuilderSection:Exload(TimingObj)
	self.UseHitboxCFrame:Set(TimingObj.uhc)
	self.PartName:Set(TimingObj.pname)
end

---Reset the elements. Extend me.
function PartBuilderSection:Reset()
	local WasResetting = self.Resetting
	BuilderSection.Reset(self)
	self.Resetting = true
	self.PartName:Set("")
	self.UseHitboxCFrame:Set(true)
	self.Resetting = WasResetting
end

---Check before creating new timing. Override me.
---@return boolean
function PartBuilderSection:Check()
	if not BuilderSection.Check(self) then
		return false
	end

	if not self.PartName.Value or #self.PartName.Value <= 0 then
		return Logger.LongNotify("Please enter a valid part name.")
	end

	if self.Pair:Index(self.PartName.Value) then
		return Logger.LongNotify("The timing ID '%s' is already in the list.", self.PartName.Value)
	end

	return true
end

---Set creation timing properties. Override me.
---@param TimingObj PartTiming
function PartBuilderSection:Cset(TimingObj)
	BuilderSection.Cset(self, TimingObj)
	TimingObj.pname = self.PartName.Value or ""
	TimingObj.uhc = self.UseHitboxCFrame.Value == true
end

---Flush extra timing elements. Override me.
---@param TimingObj PartTiming
function PartBuilderSection:FlushExtraTiming(TimingObj)
	TimingObj.uhc = self.UseHitboxCFrame.Value == true
end

---Create new timing. Override me.
---@return PartTiming
function PartBuilderSection:Create()
	local TimingObj = PartTiming.new()
	self:Cset(TimingObj)
	return TimingObj
end

---Initialize extra tab.
---@param Tab table
function PartBuilderSection:Extra(Tab)
	self.UseHitboxCFrame = Tab:Toggle({
		Name = "Use Hitbox CFrame",
		Tooltip = "Should the hitbox face where it was originally supposed to?",
		Default = true,
		Callback = self:Tnc(function(TimingObj, Value)
			TimingObj.uhc = Value
		end),
	})
end

---Create new PartBuilderSection object.
---@param Name string
---@param Tabbox table
---@param Pair TimingContainerPair
---@return PartBuilderSection
function PartBuilderSection.new(Name, Tabbox, Pair)
	return setmetatable(BuilderSection.new(Name, Tabbox, Pair), PartBuilderSection)
end

-- Return PartBuilderSection module.
return PartBuilderSection
end)
