__bundle_register("Core/AnimationVisualizer", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Animation visualizer module.
---@note: Rewritten with Mentality UI aesthetic. All GUI created in Init, destroyed in Detach.
local AnimationVisualizer = {}

---@module Core.Defense
local Defense = require("Core/Defense")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module GUI.Library
local Library = require("GUI/Library")

-- Services.
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Players = game:GetService("Players")

-- Maid.
local VisualizerMaid = Maid.new()

-- GUI references (set in Init).
local ScreenGui = nil
local Outer = nil
local ViewportFrame = nil
local NoViewportFrame = nil
local ErrorLabel = nil
local WorldModel = nil
local Camera = nil
local CurrentEntity = nil
local SliderOuter = nil
local SliderFill = nil
local SliderText = nil
local SliderTextGradient = nil
local SpeedText = nil
local IconTwo = nil
local AnimationTextbox = nil

-- Playback state.
local CurrentPlaybackData = nil
local CurrentTrack = nil
local CurrentLength = 0
local IsPaused = false
local TimeElapsed = 0.0

---Map slider value.
local function MapSliderValue(Value, Min, Max, MinSize, MaxSize)
	return (1 - ((Value - Min) / (Max - Min))) * MinSize + ((Value - Min) / (Max - Min)) * MaxSize
end

---On Animation ID focus lost.
local function OnIdFocusLost(Enter, _)
	if not Enter then return end

	CurrentTrack = nil
	CurrentPlaybackData = nil
	CurrentLength = 0

	local PbData = Defense.Agpd(AnimationTextbox.Text)

	if CurrentEntity then
		CurrentEntity:Destroy()
		CurrentEntity = nil
	end

	local Entity = nil

	if PbData and PbData.Entity then
		local CloneSuccess, ClonedEntity = pcall(function()
			PbData.Entity.Archivable = true
			return PbData.Entity:Clone()
		end)
		if CloneSuccess and ClonedEntity then Entity = ClonedEntity end
	end

	if not Entity then
		local Character = Players.LocalPlayer and Players.LocalPlayer.Character
		if Character then
			local FallbackSuccess, FallbackEntity = pcall(function()
				Character.Archivable = true
				return Character:Clone()
			end)
			if FallbackSuccess and FallbackEntity then
				Entity = FallbackEntity
				PbData = {
					Base = os.clock(),
					Entity = Character,
					Ash = { [0] = 1.0 },
					Last = function(Self, From) return 1.0 end,
					Astrack = function() end,
				}
			end
		end
	end

	if not Entity then
		return AnimationVisualizer.Message("No Entity Found")
	end
	Entity.Parent = WorldModel
	CurrentEntity = Entity

	local PrimaryPart = Entity.PrimaryPart or Entity:FindFirstChild("HumanoidRootPart")
	if not PrimaryPart then
		return AnimationVisualizer.Message("No Primary Part Found")
	end

	-- Center HumanoidRootPart at origin.
	Entity:PivotTo(CFrame.new(0, 0, 0))
	local HrpPos = PrimaryPart.Position
	Entity:PivotTo(CFrame.new(-HrpPos))

	-- Zoom to fit: center on bounding box so full character is visible.
	local BbCf, Bbs = Entity:GetBoundingBox()
	local TargetY = BbCf.Position.Y
	local VFov = math.rad(Camera.FieldOfView / 2)
	local AspectRatio = ViewportFrame.AbsoluteSize.X / math.max(ViewportFrame.AbsoluteSize.Y, 1)
	local HFov = math.atan(math.tan(VFov) * AspectRatio)
	local DistH = (Bbs.Y / 2) / math.tan(VFov)
	local DistW = (Bbs.X / 2) / math.tan(HFov)
	local Distance = math.max(DistH, DistW, 3) * 1.5

	Camera.CFrame = CFrame.lookAt(Vector3.new(0, TargetY, -Distance), Vector3.new(0, TargetY, 0))

	local Animator = Entity:FindFirstChildWhichIsA("Animator", true)
	if not Animator then
		local Humanoid = Entity:FindFirstChildWhichIsA("Humanoid")
		if Humanoid then
			Animator = Instance.new("Animator")
			Animator.Parent = Humanoid
		end
	end

	if not Animator then
		return AnimationVisualizer.Message("No Animator Found")
	end

	for Index, Track in next, Animator:GetPlayingAnimationTracks() do
		Track:Stop()
	end

	local Animation = Instance.new("Animation")
	Animation.AnimationId = AnimationTextbox.Text

	-- Load on real character first to get Length (viewport animators can't load metadata).
	local RealLength = 0
	local Character = Players.LocalPlayer and Players.LocalPlayer.Character
	if Character then
		local RealAnimator = Character:FindFirstChildWhichIsA("Animator", true)
		if RealAnimator then
			local RealSuccess, RealTrack = pcall(function()
				return RealAnimator:LoadAnimation(Animation)
			end)
			if RealSuccess and RealTrack then
				RealTrack:Play(0.0, 1, 0.0)
				local WaitStart = os.clock()
				while RealTrack.Length == 0 and (os.clock() - WaitStart) < 3 do
					task.wait()
				end
				RealLength = RealTrack.Length
				RealTrack:Stop(0)
				RealTrack:Destroy()
			end
		end
	end

	local LoadSuccess, LoadedTrack = pcall(function()
		return Animator:LoadAnimation(Animation)
	end)

	if not LoadSuccess or not LoadedTrack then
		return AnimationVisualizer.Message("Failed to Load Animation")
	end

	CurrentPlaybackData = PbData
	CurrentTrack = LoadedTrack
	CurrentLength = RealLength

	local PlaySuccess = pcall(function()
		CurrentTrack:Play(0.0, 1, 1.0)
		CurrentTrack.Priority = Enum.AnimationPriority.Action4
		CurrentTrack.Looped = true
	end)

	if not PlaySuccess then
		return AnimationVisualizer.Message("Failed to Play Animation")
	end

	-- Use real length if viewport track didn't load metadata.
	if CurrentTrack.Length > 0 then
		CurrentLength = CurrentTrack.Length
	end

	VisualizerMaid:Mark(CurrentTrack.DidLoop:Connect(function()
		TimeElapsed = 0.0
	end))

	TimeElapsed = 0.0
	IsPaused = true

	ViewportFrame.Visible = true
	NoViewportFrame.Visible = false
end

---Get time elapsed from time position.
local function GetTimeElapsedFromTp(TimePosition, AnimationLength)
	if not CurrentPlaybackData then return nil end
	if TimePosition <= 0 then return 0.0 end

	local CurrentPos = 0
	local Elapsed = 0
	local Dt = 0.01
	local Iterations = 0

	while CurrentPos < TimePosition do
		local Speed = CurrentPlaybackData:Last(Elapsed) or 1
		local StepSize = Speed * Dt
		Iterations = Iterations + 1
		if Iterations >= math.max(((AnimationLength * 100) * 10), 1000) then break end
		if CurrentPos + StepSize > TimePosition then
			Elapsed = Elapsed + (TimePosition - CurrentPos) / Speed
			break
		end
		CurrentPos = CurrentPos + StepSize
		Elapsed = Elapsed + Dt
	end

	return Elapsed
end

---On playback loop.
local function OnPlaybackLoop(Delta)
	if not ScreenGui or not ScreenGui.Enabled then return end

	IconTwo.Image = IsPaused and Library.Icons["play"] or Library.Icons["pause"]

	local Mhs = SliderOuter.AbsoluteSize.X
	local TrackLength = CurrentLength > 0 and CurrentLength or (CurrentTrack and CurrentTrack.Length or 0)
	local Hs = (CurrentTrack and TrackLength > 0)
		and MapSliderValue(CurrentTrack.TimePosition, 0.0, TrackLength, 0, Mhs) or 0.0

	SliderText.Text = (CurrentTrack and CurrentPlaybackData)
		and string.format("%.3f/%.3f (%ims)", CurrentTrack.TimePosition, TrackLength,
			math.round((GetTimeElapsedFromTp(CurrentTrack.TimePosition, TrackLength) or 0.0) * 1000))
		or "0.000 / ??? (???ms)"

	SliderFill.Visible = not (Hs == 0)
	SliderFill.Size = UDim2.new(0, math.max(math.ceil(Hs), 1), 1, 0)
	-- Update text gradient for contrast against fill.
	local FillFraction = Mhs > 0 and math.clamp(Hs / Mhs, 0, 1) or 0
	if FillFraction <= 0.001 then
		SliderTextGradient.Color = ColorSequence.new(Color3.new(1, 1, 1))
	elseif FillFraction >= 0.999 then
		SliderTextGradient.Color = ColorSequence.new(Color3.new(0, 0, 0))
	else
		SliderTextGradient.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.new(0, 0, 0)),
			ColorSequenceKeypoint.new(FillFraction, Color3.new(0, 0, 0)),
			ColorSequenceKeypoint.new(math.min(FillFraction + 0.005, 1), Color3.new(1, 1, 1)),
			ColorSequenceKeypoint.new(1, Color3.new(1, 1, 1)),
		})
	end

	SpeedText.Text = CurrentTrack and string.format("Speed (%.2f)", CurrentTrack.Speed) or "Speed (???)"

	if CurrentTrack and IsPaused then
		SpeedText.Text = string.format("Speed (%.2f)",
			CurrentPlaybackData:Last(GetTimeElapsedFromTp(CurrentTrack.TimePosition, TrackLength) or 0.0) or 0.0)
	end

	-- Track bounding box center Y and shift camera to keep model framed.
	if CurrentEntity and Camera then
		local BbCf = CurrentEntity:GetBoundingBox()
		local CamPos = Camera.CFrame.Position
		local TargetY = CamPos.Y + (BbCf.Position.Y - CamPos.Y) * 0.15
		Camera.CFrame = CFrame.lookAt(Vector3.new(CamPos.X, TargetY, CamPos.Z), Vector3.new(0, TargetY, 0))
	end

	if not CurrentTrack or not CurrentPlaybackData then return end
	if IsPaused then return CurrentTrack:AdjustSpeed(0.0) end

	TimeElapsed = TimeElapsed + Delta
	CurrentTrack:AdjustSpeed(CurrentPlaybackData:Last(TimeElapsed) or 0.0)
end

local function TogglePlayStop()
	if not CurrentTrack or not CurrentTrack.IsPlaying then return end
	IsPaused = not IsPaused
end

local function OnFrameBackwards()
	if not CurrentTrack then return end
	CurrentTrack.TimePosition = math.max(CurrentTrack.TimePosition - 0.01, 0)
end

local function OnFrameForwards()
	if not CurrentTrack then return end
	local TrackLength = CurrentLength > 0 and CurrentLength or CurrentTrack.Length
	CurrentTrack.TimePosition = math.min(CurrentTrack.TimePosition + 0.01, TrackLength)
end

local function OnSliderInputBegan(Input, GameProcessed)
	if GameProcessed or Input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
	if not CurrentTrack then return end
	if Library.DragLock then return end
	Library.DragLock = true

	IsPaused = true

	while ScreenGui and ScreenGui.Enabled and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
		local TrackLength = CurrentLength > 0 and CurrentLength or (CurrentTrack and CurrentTrack.Length or 0)
		if not CurrentTrack or TrackLength <= 0 then break end
		local Mouse = Players.LocalPlayer:GetMouse()
		local SliderOuterSize = SliderOuter.AbsoluteSize.X
		local MouseX = math.clamp(Mouse.X - SliderOuter.AbsolutePosition.X, 0, SliderOuterSize)
		CurrentTrack.TimePosition = math.clamp(MapSliderValue(MouseX, 0, SliderOuterSize, 0, TrackLength), 0, TrackLength - 1e-7)
		RunService.PreRender:Wait()
	end

	if CurrentTrack then
		local TrackLength = CurrentLength > 0 and CurrentLength or CurrentTrack.Length
		TimeElapsed = GetTimeElapsedFromTp(CurrentTrack.TimePosition, TrackLength) or 0.0
	end

	Library.DragLock = false
end

local function HoldRepeat(KeyCode, Callback)
	Callback()
	task.spawn(function()
		task.wait(0.4)
		while UserInputService:IsKeyDown(KeyCode) do
			Callback()
			task.wait(0.03)
		end
	end)
end

local function OuterFrameInputBegan(Input, GameProcessed)
	if GameProcessed then return end
	if Input.KeyCode == Enum.KeyCode.Space then return TogglePlayStop() end
	if Input.KeyCode == Enum.KeyCode.E then return HoldRepeat(Enum.KeyCode.E, OnFrameForwards) end
	if Input.KeyCode == Enum.KeyCode.Q then return HoldRepeat(Enum.KeyCode.Q, OnFrameBackwards) end
end

---Set visibility.
function AnimationVisualizer.Visible(State)
	if ScreenGui then ScreenGui.Enabled = State == true and not getgenv().EpiphyllumSilentMode end
end

---Show a message.
function AnimationVisualizer.Message(Msg)
	if ViewportFrame then ViewportFrame.Visible = false end
	if NoViewportFrame then NoViewportFrame.Visible = true end
	if ErrorLabel then ErrorLabel.Text = Msg end
end

