	TitleLabel.Parent = TitleBar

	-- Draggable (tweened, matching Library.MakeDraggable).
	local Dragging = false
	local DragStart = nil
	local StartAbsPos = nil
	local DragTweenInfo = TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	local DragInputChanged = nil

	VisualizerMaid:Add(TitleBar.InputBegan:Connect(function(Input)
		if Input.UserInputType == Enum.UserInputType.MouseButton1 then
			if Library.DragLock then return end
			Library.DragLock = true
			Dragging = true
			DragStart = Input.Position
			StartAbsPos = Outer.AbsolutePosition

			if DragInputChanged then return end
			DragInputChanged = Input.Changed:Connect(function()
				if Input.UserInputState == Enum.UserInputState.End then
					Dragging = false
					Library.DragLock = false
					DragInputChanged:Disconnect()
					DragInputChanged = nil
				end
			end)
		end
	end))

	VisualizerMaid:Add(UserInputService.InputChanged:Connect(function(Input)
		if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
			local Delta = Input.Position - DragStart
			local NewX = StartAbsPos.X + Delta.X
			local NewY = StartAbsPos.Y + Delta.Y
			local ScreenSize = Outer.Parent.AbsoluteSize
			local GuiSize = Outer.AbsoluteSize
			NewX = math.clamp(NewX, 0, ScreenSize.X - GuiSize.X)
			NewY = math.clamp(NewY, 0, ScreenSize.Y - GuiSize.Y)
			TweenService:Create(Outer, DragTweenInfo, { Position = UDim2.fromOffset(NewX, NewY) }):Play()
