	AnimationVisualizer.Message("Waiting For Animation ID")
end

---Detach AnimationVisualizer module.
function AnimationVisualizer.Detach()
	VisualizerMaid:Clean()

	if ScreenGui then
		ScreenGui:Destroy()
		ScreenGui = nil
	end

	-- Reset state.
	CurrentPlaybackData = nil
	CurrentTrack = nil
	CurrentLength = 0
	IsPaused = false
	TimeElapsed = 0.0
	Outer = nil
	ViewportFrame = nil
	NoViewportFrame = nil
	ErrorLabel = nil
	WorldModel = nil
	Camera = nil
	CurrentEntity = nil
	SliderOuter = nil
	SliderFill = nil
	SliderText = nil
	SliderTextGradient = nil
	SpeedText = nil
	IconTwo = nil
	AnimationTextbox = nil
end

-- Return AnimationVisualizer module.
return AnimationVisualizer
end)
__bundle_register("Core/DefaultRemotes", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Default dispatch config (remotes + inputs) baked into the script so anyone
-- who executes it gets the auto-defense remotes/inputs without a local
-- remotes.json. Used by LoadConfig() when no dispatch config exists on disk.
-- Returns a FRESH copy each call so callers can mutate it safely.

return function()
