			{ action = "Counter", path = "game.ReplicatedStorage.Requests.RedCounter", args = {} },
			{ action = "Dodge", path = "game.ReplicatedStorage.Requests.Dash", args = { "\"LookVector\"", "-73" } },
			{ action = "Forced Full Dodge", path = "game.ReplicatedStorage.Requests.FlashStep", args = {} },
			{ action = "Counter", path = "game.ReplicatedStorage.Requests.FlashStep", args = {} },
			{ action = "FlashStep", path = "game.ReplicatedStorage.Requests.FlashStep", args = {} },
		},
	}
end
end)
__bundle_register("Core/Defense", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Defense orchestrator module.

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Defenders.AnimatorDefender
local AnimatorDefender = require("Defenders/AnimatorDefender")

---@module Defenders.PartDefender
local PartDefender = require("Defenders/PartDefender")

---@module Defenders.SoundDefender
local SoundDefender = require("Defenders/SoundDefender")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Core.EntityHistory
local EntityHistory = require("Core/EntityHistory")

---@module Core.InfoLogger
local InfoLogger = require("Core/InfoLogger")

-- Handle all defense related functions.
local Defense = {}

-- Services.
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

-- Maids.
local DefenseMaid = Maid.new()
local DamageLoggerMaid = Maid.new()

-- Defender objects.
local DefenderPartObjects = {}
local DefenderAnimationObjects = {}
local DefenderObjects = {}

-- Stored deleted playback data.
local DeletedPlaybackData = {}

---Add animator defender.
---@param Animator Animator
local function AddAnimatorDefender(Animator)
	local AnimationDefender = AnimatorDefender.new(Animator)
	DefenderObjects[Animator] = AnimationDefender
	DefenderAnimationObjects[Animator] = AnimationDefender
end

---Add sound defender.
---@param Sound Sound
local function AddSoundDefender(Sound)
	---@note: If there's nothing to base the sound position off of, then I'm just gonna skip it bruh.
	local Part = Sound:FindFirstAncestorWhichIsA("BasePart")
	if not Part then
		return
	end

	-- Add sound defender.
	DefenderObjects[Sound] = SoundDefender.new(Sound, Part)
end

---Add parry effect log.
---@param Descendant Instance
local function AddParryLog(Descendant)
	if not Configuration.ExpectToggleValue("EP_ShowInfoLogger") then
		return
	end

	local LocalPlayer = Players.LocalPlayer
	local Character = LocalPlayer and LocalPlayer.Character
	if not Character then
		return
	end

	local EffectFolder = Descendant:FindFirstAncestorWhichIsA("Folder")
	if not EffectFolder or EffectFolder.Name ~= Character.Name then
		return
	end

	InfoLogger.AddTelemetryEntry("(%s) Instance '%s' created in effect folder.", EffectFolder.Name, Descendant.Name)
	InfoLogger.AddTimelineEntry("Parry effect '%s' created for '%s'.", Descendant.Name, EffectFolder.Name)
end

---Add local damage logger.
---@param Character Model
local function AddDamageLogger(Character)
	DamageLoggerMaid:Clean()

	local Humanoid = Character:FindFirstChildOfClass("Humanoid") or Character:WaitForChild("Humanoid", 10)
	if not Humanoid then
		return
	end

	local CurrentHealth = Humanoid.Health
	local HealthChanged = Signal.new(Humanoid.HealthChanged)

	DamageLoggerMaid:Mark(HealthChanged:Connect("Defense_HumanoidHealthChange", function(Health)
		if CurrentHealth <= Health then
			CurrentHealth = Health
			return
		end

		local Change = CurrentHealth - Health
		CurrentHealth = Health

		if not Configuration.ExpectToggleValue("EP_ShowInfoLogger") then
			return
		end

		InfoLogger.AddDamageEntry(Health, Humanoid.MaxHealth, Change)
	end))
end

---On game descendant added.
---@param Descendant Instance
local function OnGameDescendantAdded(Descendant)
	if Descendant:IsA("Animator") then
		return AddAnimatorDefender(Descendant)
	end

	if Descendant:IsA("Sound") then
		return AddSoundDefender(Descendant)
	end

	if Descendant:IsA("BasePart") and Descendant.Name ~= "__EP_HitboxSim" then
		if Descendant.Name == "ParryEffect" then
			AddParryLog(Descendant)
		end

		return Defense.Cdpo(Descendant)
	end
end

---On game descendant removed.
---@param Descendant Instance
local function OnGameDescendantRemoved(Descendant)
	local Object = DefenderObjects[Descendant]
	if not Object then
		return
	end

	-- Flush active playback data to recorded before saving.
	if Object.Pbdata then
		for Track, Data in next, Object.Pbdata do
			Object.Rpbdata[tostring(Track.Animation.AnimationId)] = Data
		end
	end

	if Object.Rpbdata then
		DeletedPlaybackData[Descendant] = Object.Rpbdata
	end

	if DefenderPartObjects[Descendant] then
		DefenderPartObjects[Descendant] = nil
	end

	if DefenderAnimationObjects[Descendant] then
		DefenderAnimationObjects[Descendant] = nil
	end

	Object:Detach()
	DefenderObjects[Descendant] = nil
end

---Update animation defenders (playback data tracking).
local function UpdateAnimationDefenders()
	for Index, Object in next, DefenderAnimationObjects do
		Object:Update()
	end
end

---Update history for an entity model once per frame.
---@param Entity Model?
---@param Seen table
local function UpdateEntityModelHistory(Entity, Seen)
	if not Entity or Seen[Entity] then return end

	local Root = Entity:FindFirstChild("HumanoidRootPart")
	if not Root then return end

	Seen[Entity] = true
	EntityHistory.Add(Entity, Root.CFrame, Root.AssemblyLinearVelocity, tick())
end

---Update entity history (CFrame + velocity tracking for prediction).
local function UpdateEntityHistory()
	local Character = Players.LocalPlayer.Character
	local Seen = {}

	if Character then
		local LocalRoot = Character:FindFirstChild("HumanoidRootPart")
		if LocalRoot then
			EntityHistory.Add(Players.LocalPlayer, LocalRoot.CFrame, LocalRoot.AssemblyLinearVelocity, tick())
		end

		UpdateEntityModelHistory(Character, Seen)
	end

	for Index, Player in next, Players:GetPlayers() do
		if Player == Players.LocalPlayer then
			continue
		end

		UpdateEntityModelHistory(Player.Character, Seen)
	end

	for Index, Object in next, DefenderAnimationObjects do
		UpdateEntityModelHistory(Object.Entity, Seen)
	end
end

---Update defenders.
local function UpdateDefenders()
	for Index, Object in next, DefenderPartObjects do
		Object:Update()
	end

	UpdateAnimationDefenders()
	UpdateEntityHistory()
end

---Create a defender part object.
---@param Part BasePart
---@param TimingObj PartTiming?
---@return PartDefender?
function Defense.Cdpo(Part, TimingObj)
	local Defender = PartDefender.new(Part, TimingObj)
	if not Defender then
		return nil
	end

	DefenderObjects[Part] = Defender
	DefenderPartObjects[Part] = Defender

	return Defender
end

---Extract numeric asset ID from any format.
---@param Aid string
---@return string
local function ExtractNumericId(Aid)
	return Aid:match("%d+") or Aid
end

---Get playback data of first defender with Animation ID.
---@param Aid string
---@return PlaybackData?
function Defense.Agpd(Aid)
	local NumericId = ExtractNumericId(Aid)

	-- Search recorded (finished) playback data.
	for Index, Object in next, DefenderAnimationObjects do
		for StoredAid, Pbdata in next, Object.Rpbdata do
			if ExtractNumericId(StoredAid) == NumericId then
				return Pbdata
			end
		end
	end

	-- Search active (still playing) playback data.
	for Index, Object in next, DefenderAnimationObjects do
		for Track, Pbdata in next, Object.Pbdata do
			local TrackAid = ""
			pcall(function()
				TrackAid = tostring(Track.Animation.AnimationId)
			end)
			if ExtractNumericId(TrackAid) == NumericId then
				return Pbdata
			end
		end
	end

	-- Fallback to deleted playback data.
	for Index, Rpbdata in next, DeletedPlaybackData do
		for StoredAid, Pbdata in next, Rpbdata do
			if ExtractNumericId(StoredAid) == NumericId then
				return Pbdata
			end
		end
	end
end

---Initialize defense.
function Defense.Init()
	local LocalPlayer = Players.LocalPlayer

	-- Signals.
	local GameDescendantAdded = Signal.new(game.DescendantAdded)
	local GameDescendantRemoved = Signal.new(game.DescendantRemoving)
	local PostSimulation = Signal.new(RunService.PostSimulation)
	local CharacterAdded = LocalPlayer and Signal.new(LocalPlayer.CharacterAdded)

	DefenseMaid:Mark(GameDescendantAdded:Connect("Defense_OnDescendantAdded", OnGameDescendantAdded))
	DefenseMaid:Mark(GameDescendantRemoved:Connect("Defense_OnDescendantRemoved", OnGameDescendantRemoved))
	DefenseMaid:Mark(PostSimulation:Connect("Defense_UpdateDefenders", UpdateDefenders))

	if CharacterAdded then
		DefenseMaid:Mark(CharacterAdded:Connect("Defense_OnCharacterAdded", AddDamageLogger))
	end

	if LocalPlayer and LocalPlayer.Character then
		AddDamageLogger(LocalPlayer.Character)
	end

	-- Process existing descendants.
	for Index, Descendant in next, game:GetDescendants() do
		OnGameDescendantAdded(Descendant)
	end

	-- Expose debug state.
	_G.EP_DAO = DefenderAnimationObjects
	_G.EP_DPD = DeletedPlaybackData
	_G.EP_AGPD = Defense.Agpd

	Logger.Warn("Defense initialized.")
end

---Detach defense.
function Defense.Detach()
	for Index, Object in next, DefenderObjects do
		Object:Detach()
	end

	DefenseMaid:Clean()
	DamageLoggerMaid:Clean()

	-- Clear state.
	DefenderPartObjects = {}
	DefenderAnimationObjects = {}
	DefenderObjects = {}
	DeletedPlaybackData = {}
	EntityHistory.Clear()

	-- Recreate maid for hot reload.
	DefenseMaid = Maid.new()
	DamageLoggerMaid = Maid.new()

	Logger.Warn("Defense detached.")
end

-- Return Defense module.
return Defense
end)
__bundle_register("Core/EntityHistory", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Entity history module. Tracks per-entity CFrame and velocity over time.
local EntityHistory = {}

-- Histories table.
local Histories = {}

-- Max history seconds.
local MaxHistorySecs = 3.0

---Add an entry to the history list.
---@param Idx any
---@param Position CFrame
---@param Velocity Vector3
---@param Timestamp number
function EntityHistory.Add(Idx, Position, Velocity, Timestamp)
	local History = Histories[Idx] or {}

	if not Histories[Idx] then
		Histories[Idx] = History
	end

	History[#History + 1] = {
		Position = Position,
		Timestamp = Timestamp,
		Velocity = Velocity,
	}

	while true do
		local Tail = History[1]
		if not Tail then
			break
		end

		if tick() - Tail.Timestamp <= MaxHistorySecs then
			break
		end

		table.remove(History, 1)
	end
end

---Get the horizontal angular velocity (yaw rate) for a current index.
---@param Index any
---@return number?
function EntityHistory.Yrate(Index)
	local History = Histories[Index]
	if not History or #History < 2 then
		return nil
	end

	local Latest = History[#History]
	local Previous = History[#History - 1]
	local Dt = Latest.Timestamp - Previous.Timestamp
	if Dt <= 1e-4 then
		return nil
	end

	local PrevLook = Vector3.new(Previous.Position.LookVector.X, 0, Previous.Position.LookVector.Z).Unit
	local LatestLook = Vector3.new(Latest.Position.LookVector.X, 0, Latest.Position.LookVector.Z).Unit
	local Dot = PrevLook:Dot(LatestLook)
	local CrossY = PrevLook:Cross(LatestLook).Y
	local Angle = math.atan2(CrossY, Dot)
	return Angle / Dt
end

---Divides the history into a number of equal steps and returns the position at each step.
---@param Idx any
---@param Steps number
---@param Phds number History second limit for past hitbox detection.
---@return CFrame[]?
function EntityHistory.Pstepped(Idx, Steps, Phds)
	local History = Histories[Idx]
	if not History or #History == 0 then
		return nil
	end

	if not Steps or Steps <= 0 then
		return nil
	end

	local Vhistory = {}
	local Vhtime = History[#History].Timestamp

	for I = 1, #History do
		local Data = History[I]
		if Vhtime - Data.Timestamp > Phds then
			continue
		end

		Vhistory[#Vhistory + 1] = Data.Position
	end

	if #Vhistory == 0 then
		return {}
	end

	local Count = math.min(Steps, #Vhistory)
	local Out = table.create(Count)

	for Cidx = 1, Count do
		Out[Cidx] = Vhistory[math.max(math.floor((Cidx * #Vhistory) / Count), 1)]
	end

	return Out
end

---Clear all history data (for hot reload).
function EntityHistory.Clear()
	Histories = {}
end

-- Return EntityHistory module.
return EntityHistory
end)
__bundle_register("Core/InfoLogger", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Info Logger module.
---@note: Tracks missing and existing timing entries from defenders. Mentality-styled floating panel.
local InfoLogger = {}

---@module GUI.Library
local Library = require("GUI/Library")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Signal
local Signal = require("Utility/Signal")

-- Services.
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local MarketplaceService = game:GetService("MarketplaceService")
local Players = game:GetService("Players")

-- Constants.
local ScreenGuiName = "__EP_InfoLogger"
local MaxEntriesPerType = 30
local TypeCycles = { "Animation", "Sound", "Part", "Timeline", "Keyframe", "Telemetry" }
local PanelDefaultWidth = 210
local PanelCurrentWidth = PanelDefaultWidth
local PanelScreenPadding = 12
local PanelMinHeight = 24
local PanelMaxHeight = 176

-- Helpers.
local FromRGB = Color3.fromRGB
local UDim2New = UDim2.new
local Vector2New = Vector2.new

-- Services.
local HttpService = game:GetService("HttpService")

-- State.
local LoggerMaid = Maid.new()
local CurrentCycle = 1
local Entries = {}
local BlacklistList = {}
local BlacklistHistory = {}
local EntryQueue = {}
local AssetNameCache = {}
local BlacklistFilePath = nil
local BlacklistSyncPaths = {}
local LastAnimationStart = nil

-- GUI references.
local ScreenGuiRef = nil
local OuterFrame = nil
local TitleLabel = nil
local ScrollingFrame = nil

-- ─── Helpers ────────────────────────────────────────────────────────────────────

---Get icon from Library.Icons (already loaded as getcustomasset paths).
---@param Name string
---@return string
local function GetIcon(Name)
	return Library.Icons and Library.Icons[Name] or ""
end

---Get maximum panel width inside the current viewport.
---@return number
local function GetPanelMaxWidth()
	local ScreenWidth = 0
	if ScreenGuiRef then
		ScreenWidth = ScreenGuiRef.AbsoluteSize.X
	end

	if ScreenWidth <= 0 and OuterFrame and OuterFrame.Parent then
		ScreenWidth = OuterFrame.Parent.AbsoluteSize.X
	end

	if ScreenWidth <= 0 then
		return PanelDefaultWidth
	end

	return math.max(PanelDefaultWidth, ScreenWidth - PanelScreenPadding * 2)
end

---Keep the panel inside the current viewport after resizing.
---@param TargetWidth number
---@param TargetHeight number
local function ClampPanelPosition(TargetWidth, TargetHeight)
	if not OuterFrame or not OuterFrame.Parent then return end

	local ScreenSize = OuterFrame.Parent.AbsoluteSize
	if ScreenSize.X <= 0 or ScreenSize.Y <= 0 then return end

	local Position = OuterFrame.AbsolutePosition
	local NewX = math.clamp(Position.X, 0, math.max(0, ScreenSize.X - TargetWidth - PanelScreenPadding))
	local NewY = math.clamp(Position.Y, 0, math.max(0, ScreenSize.Y - TargetHeight - PanelScreenPadding))

	if NewX ~= Position.X or NewY ~= Position.Y then
		OuterFrame.Position = UDim2.fromOffset(NewX, NewY)
	end
end

---Normalize a filesystem path for comparisons.
---@param Path string
---@return string
local function NormalizePath(Path)
	return tostring(Path or ""):gsub("\\", "/")
end

---Get the base folder from a game path.
---@param Path string
---@return string
local function BasePathFromGamePath(Path)
	return tostring(Path or "Epiphyllum"):match("^(.*)[/\\][^/\\]+$") or "Epiphyllum"
end

---Get a folder's trailing Place ID.
---@param Path string
---@return string?
local function FolderPlaceId(Path)
	return tostring(Path or ""):match("%- (%d+)$")
end

---Normalize a key to rbxassetid:// format for display.
---@param Key string
---@return string
local function NormalizeKey(Key)
	if not Key then return "" end
	if Key:sub(1, 13) == "rbxassetid://" then return Key end
	local Id = Key:match("id=(%d+)")
	if Id then return "rbxassetid://" .. Id end
	Id = Key:match("%d+")
	if Id then return "rbxassetid://" .. Id end
	return Key
end

---Read aliases from a game folder.
---@param Path string
---@return table
local function ReadAliasList(Path)
	local AliasFile = tostring(Path or "") .. "/aliases.json"
	if not isfile(AliasFile) then return {} end

	local ReadOk, Content = pcall(readfile, AliasFile)
	if not ReadOk or not Content then return {} end

	local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
	if not DecodeOk or typeof(Data) ~= "table" then return {} end

	local Aliases = {}
	for Index, Id in next, Data do
		Aliases[#Aliases + 1] = tostring(Id)
	end

	return Aliases
end

---Collect blacklist sync paths for the current place alias group.
---@param GamePath string
---@return table
local function CollectBlacklistSyncPaths(GamePath)
	local Targets = {}
	local Seen = {}

	local function AddTarget(Path)
		local PathKey = NormalizePath(Path)
		if PathKey == "" or Seen[PathKey] then return end
		Targets[#Targets + 1] = Path
		Seen[PathKey] = true
	end

	if not GamePath then return Targets end
	AddTarget(GamePath)

	local BasePath = BasePathFromGamePath(GamePath)
	if not isfolder(BasePath) then return Targets end

	local ListOk, FolderList = pcall(listfiles, BasePath)
	if not ListOk or not FolderList then return Targets end
	table.sort(FolderList)

	local PlaceIds = {}
	local FolderAliases = {}
	local FolderPlaceIds = {}
	local FolderPaths = {}

	local CurrentPlaceId = FolderPlaceId(GamePath)
	if CurrentPlaceId then
		PlaceIds[CurrentPlaceId] = true
	end

	for Index, AliasId in next, ReadAliasList(GamePath) do
		PlaceIds[AliasId] = true
	end

	for Index, FolderPath in next, FolderList do
		if not isfolder(FolderPath) then continue end

		local FolderPathKey = NormalizePath(FolderPath)
		FolderPaths[#FolderPaths + 1] = FolderPath
		FolderPlaceIds[FolderPathKey] = FolderPlaceId(FolderPath)
		FolderAliases[FolderPathKey] = ReadAliasList(FolderPath)
	end

	local Changed = true
	while Changed do
		Changed = false

		for Index, FolderPath in next, FolderPaths do
			local FolderPathKey = NormalizePath(FolderPath)
			local PlaceId = FolderPlaceIds[FolderPathKey]
			local Aliases = FolderAliases[FolderPathKey] or {}
			local Connected = PlaceId and PlaceIds[PlaceId] == true

			if not Connected then
				for AliasIndex, AliasId in next, Aliases do
					if PlaceIds[AliasId] then
						Connected = true
						break
					end
				end
			end

			if Connected then
				if PlaceId and not PlaceIds[PlaceId] then
					PlaceIds[PlaceId] = true
					Changed = true
				end

				for AliasIndex, AliasId in next, Aliases do
					if not PlaceIds[AliasId] then
						PlaceIds[AliasId] = true
						Changed = true
					end
				end
			end
		end
	end

	for Index, FolderPath in next, FolderPaths do
		local FolderPathKey = NormalizePath(FolderPath)
		local PlaceId = FolderPlaceIds[FolderPathKey]

		if PlaceId and PlaceIds[PlaceId] then
			AddTarget(FolderPath)
		end
	end

	return Targets
end

---Read blacklist keys from a game folder.
---@param Path string
---@return table
local function ReadBlacklistKeys(Path)
	local FilePath = tostring(Path or "") .. "/blacklist.json"
	if not isfile(FilePath) then return {} end

	local ReadOk, Content = pcall(readfile, FilePath)
	if not ReadOk or not Content then return {} end

	local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
	if not DecodeOk or typeof(Data) ~= "table" then return {} end

	local Keys = {}
	for I = 1, #Data do
		local Key = NormalizeKey(tostring(Data[I]))
		if Key ~= "" then
			Keys[#Keys + 1] = Key
		end
	end

	return Keys
end

---Save blacklist to disk for every linked place alias.
local function SaveBlacklist()
	if #BlacklistSyncPaths == 0 and BlacklistFilePath then
		BlacklistSyncPaths = { BlacklistFilePath:gsub("/blacklist%.json$", "") }
	end

	if #BlacklistSyncPaths == 0 then return end

	local Keys = {}
	for Key, Val in next, BlacklistList do
		if Val then Keys[#Keys + 1] = Key end
	end
	table.sort(Keys)

	local EncodeOk, Json = pcall(HttpService.JSONEncode, HttpService, Keys)
	if not EncodeOk then return end

	for Index, Path in next, BlacklistSyncPaths do
		pcall(writefile, tostring(Path) .. "/blacklist.json", Json)
	end
end

---Load and merge blacklist keys from every linked place alias.
local function LoadBlacklist()
	BlacklistList = {}
	BlacklistHistory = {}

	local LoadedKeys = {}
	for Index, Path in next, BlacklistSyncPaths do
		local Keys = ReadBlacklistKeys(Path)
		LoadedKeys[#LoadedKeys + 1] = Keys

		for KeyIndex, Key in next, Keys do
			if not BlacklistList[Key] then
				BlacklistList[Key] = true
				BlacklistHistory[#BlacklistHistory + 1] = Key
			end
		end
	end

	local BlacklistCount = 0
	for Key, Val in next, BlacklistList do
		if Val then
			BlacklistCount = BlacklistCount + 1
		end
	end

	local NeedsSync = false
	for Index, Keys in next, LoadedKeys do
		local Seen = {}
		local SeenCount = 0

		for KeyIndex, Key in next, Keys do
			if not Seen[Key] then
				Seen[Key] = true
				SeenCount = SeenCount + 1
			end
		end

		if SeenCount ~= BlacklistCount then
			NeedsSync = true
			break
		end

		for Key, Val in next, BlacklistList do
			if Val and not Seen[Key] then
				NeedsSync = true
				break
			end
		end

		if NeedsSync then
			break
		end
	end

	if NeedsSync then
		SaveBlacklist()
	end
end

---Format a blacklist key for display: "AssetName - rbxassetid://ID" or just the normalized ID.
---@param Key string
---@return string
local function FormatBlacklistDisplay(Key)
	local Normalized = NormalizeKey(Key)
	local AssetId = tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))
	local AssetName = AssetId and AssetNameCache[AssetId]
	if AssetName then
		return string.format("%s - %s", AssetName, Normalized)
	end
	return Normalized
end

---Build padded display items from current blacklist.
---@return table[]
local function BuildBlacklistDisplayItems()
	local DisplayItems = {}
	local MaxName = 0

	-- First pass: collect items and find max name width.
	for Key, Val in next, BlacklistList do
		if not Val then continue end
		local Normalized = NormalizeKey(Key)
		local AssetId = tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))
		local AssetName = AssetId and AssetNameCache[AssetId] or nil
		local NameLen = AssetName and #AssetName or 0
		if NameLen > MaxName then MaxName = NameLen end
		DisplayItems[#DisplayItems + 1] = {
			Key = Key,
			AssetName = AssetName,
			Normalized = Normalized,
		}
	end

	-- Second pass: format with padding.
	for I = 1, #DisplayItems do
		local Item = DisplayItems[I]
		if Item.AssetName then
			local Padded = Item.AssetName .. string.rep(" ", MaxName - #Item.AssetName)
			Item.Display = string.format("%s - %s", Padded, Item.Normalized)
		else
			Item.Display = Item.Normalized
		end
	end

	return DisplayItems
end

---Sync blacklist list with current state, resolving names if requested.
---@param ResolveNames boolean?
local function SyncBlacklistDropdown(ResolveNames)
	local List = InfoLogger.BlacklistDropdown
	if not List then return end

	-- Immediate refresh with whatever names we have.
	pcall(List.Refresh, List, BuildBlacklistDisplayItems())

	if not ResolveNames then
		return
	end

	-- Resolve uncached names in background, then refresh again.
	local NeedResolve = false
	for Key, Val in next, BlacklistList do
		if not Val then continue end
		local AssetId = tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))
		if AssetId and not AssetNameCache[AssetId] then
			NeedResolve = true
			break
		end
	end

	if NeedResolve then
		task.spawn(function()
			for Key, Val in next, BlacklistList do
				if not Val then continue end
				local AssetId = tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))
				if AssetId and not AssetNameCache[AssetId] then
					pcall(function()
						local Info = MarketplaceService:GetProductInfo(AssetId)
						if Info and Info.Name then
							AssetNameCache[AssetId] = Info.Name
						end
					end)
				end
			end
			-- Refresh with resolved names.
			if List then
				pcall(List.Refresh, List, BuildBlacklistDisplayItems())
			end
		end)
	end
end

-- ─── Entry Label Creation ───────────────────────────────────────────────────────

-- Monospace font for aligned columns.
local MonoFont = Font.new("rbxasset://fonts/families/RobotoMono.json")

---Pad a string to a fixed display width (right-padded with spaces).
---@param Str string
---@param Width number
---@return string
local function PadRight(Str, Width)
	local Len = #Str
	if Len >= Width then return Str end
	return Str .. string.rep(" ", Width - Len)
end

---Build formatted RichText for an entry with dynamic column widths.
---@param Entry table
---@param MaxAsset number Max width of asset name column.
---@param MaxEntity number Max width of entity name column.
---@param MaxParent number Max width of parent column.
---@param MaxDist number Max width of distance column.
---@param MaxKey number Max width of key column.
---@return string
local function FormatEntryText(Entry, MaxAsset, MaxEntity, MaxParent, MaxDist, MaxKey)
	local AssetCol = PadRight(Entry.AssetCol, MaxAsset + 1)
	local EntityCol = PadRight(Entry.EntityCol, MaxEntity + 1)
	local ParentCol = PadRight(Entry.ParentCol, MaxParent + 1)
	local DistCol = PadRight(Entry.DistCol, MaxDist + 1)
	local Status = Entry.IsMissing and 'is <font color="#FF5050">missing</font>' or "exists"

	-- Pad the plain-text key column, then insert color tags around the key only.
	local KeyPlain = string.format("Key '%s'", Entry.DisplayKey)
	local KeyPadded = PadRight(KeyPlain, MaxKey + 6)
	local KeyColored = KeyPadded:gsub("'([^']+)'", "'<font color=\"#FFD700\">%1</font>'")

	return string.format("%s%s%s%s%s %s.", AssetCol, EntityCol, ParentCol, DistCol, KeyColored, Status)
end

---Create an entry label.
---@param Text string
---@return TextButton
local function CreateEntryLabel(Text)
	local Label = Instance.new("TextButton")
	Label.Name = "Entry"
	Label.FontFace = MonoFont
	Label.TextColor3 = Library.Theme.Text
	Label.RichText = true
	Label.Text = Text
	Label.TextXAlignment = Enum.TextXAlignment.Left
	Label.Size = UDim2New(1, 0, 0, 14)
	Label.BackgroundTransparency = 1
	Label.BorderSizePixel = 0
	Label.TextSize = 12
	Label.AutoButtonColor = false
	return Label
end

-- ─── Core Logic ─────────────────────────────────────────────────────────────────

---Refresh the info logger display.
function InfoLogger.Refresh()
	if not ScrollingFrame or not ScreenGuiRef or not ScreenGuiRef.Parent then return end

	local CurrentType = TypeCycles[CurrentCycle]

	-- Remove blacklisted entries.
	for I = #Entries, 1, -1 do
		local Entry = Entries[I]
		if BlacklistList[NormalizeKey(Entry.Key)] then
			if Entry.Label and Entry.Label.Parent then
				Entry.Label:Destroy()
			end
			table.remove(Entries, I)
		end
	end

	-- Calculate dynamic column widths for visible entries.
	local MaxAsset = 0
	local MaxEntity = 0
	local MaxParent = 0
	local MaxDist = 0
	local MaxKey = 0

	for Index, Entry in next, Entries do
		if Entry.Type == CurrentType then
			if Entry.RawText then
				continue
			end

			if #Entry.AssetCol > MaxAsset then MaxAsset = #Entry.AssetCol end
			if #Entry.EntityCol > MaxEntity then MaxEntity = #Entry.EntityCol end
			if #Entry.ParentCol > MaxParent then MaxParent = #Entry.ParentCol end
			if #Entry.DistCol > MaxDist then MaxDist = #Entry.DistCol end
			if #Entry.DisplayKey > MaxKey then MaxKey = #Entry.DisplayKey end
		end
	end

	-- Show/hide entries and reformat with aligned columns.
	for I, Entry in next, Entries do
		pcall(function()
			if Entry.Type == CurrentType then
				Entry.Label.Text = Entry.RawText or FormatEntryText(Entry, MaxAsset, MaxEntity, MaxParent, MaxDist, MaxKey)
				Entry.Label.Parent = ScrollingFrame
				Entry.Label.LayoutOrder = I
			else
				Entry.Label.Parent = nil
			end
		end)
	end

	-- Update title.
	if TitleLabel then
		TitleLabel.Text = string.format("Info Logger (%s)", CurrentType)
	end

	-- Hide scrollbar when no entries are visible for the current type.
	local HasVisibleEntries = false
	for Index, Entry in next, Entries do
		if Entry.Type == CurrentType then
			HasVisibleEntries = true
			break
		end
	end
	ScrollingFrame.ScrollBarThickness = HasVisibleEntries and 4 or 0

	-- Dynamic resize (matches old builder: expand width, never shrink).
	local YSize = 0
	local XSize = 0

	for Index, Entry in next, Entries do
		if Entry.Label.Parent then
			YSize = YSize + Entry.Label.TextBounds.Y + 2
			if Entry.Label.TextBounds.X > XSize then
				XSize = Entry.Label.TextBounds.X
			end
		end
	end

	XSize = XSize + 20
	YSize = YSize + 38

	-- Width only expands, never shrinks (resets on cycle change).
	if XSize > PanelCurrentWidth then
		PanelCurrentWidth = XSize
	end

	if OuterFrame then
		local TargetWidth = math.clamp(PanelCurrentWidth, PanelDefaultWidth, GetPanelMaxWidth())
		local TargetHeight = math.clamp(YSize, PanelMinHeight, PanelMaxHeight)
		ClampPanelPosition(TargetWidth, TargetHeight)
		OuterFrame.Size = UDim2New(
			0, TargetWidth,
			0, TargetHeight
		)
	end
end

---Add a raw text entry.
---@param Type string
---@param Key string?
---@param Text string
---@param Timestamp number?
---@param CopyValue any?
local function AddTextEntry(Type, Key, Text, Timestamp, CopyValue)
	local NormalizedKey = Key and NormalizeKey(Key) or nil
	if NormalizedKey and BlacklistList[NormalizedKey] then return end
	if not ScrollingFrame then return end

	Timestamp = Timestamp or os.clock()

	local TypeEntries = {}
	for I, Entry in next, Entries do
		if Entry.Type == Type then
			TypeEntries[#TypeEntries + 1] = { Entry = Entry, Index = I }
		end
	end

	if #TypeEntries > MaxEntriesPerType then
		local Last = TypeEntries[#TypeEntries]
		if Last.Entry.Label then Last.Entry.Label:Destroy() end
		table.remove(Entries, Last.Index)
	end

	local DisplayText = string.format("[%.3fms] %s", Timestamp * 1000, Text)
	local Label = CreateEntryLabel(DisplayText)

	Label.MouseButton1Click:Connect(function()
		pcall(setclipboard, tostring(CopyValue or NormalizedKey or DisplayText))
		pcall(function() Library:Notification({ Title = "Info Logger", Description = "Copied info logger entry to clipboard.", Duration = 3 }) end)
	end)

	Label.MouseButton2Click:Connect(function()
		if not NormalizedKey then return end

		BlacklistList[NormalizedKey] = true
		BlacklistHistory[#BlacklistHistory + 1] = NormalizedKey
		SaveBlacklist()
		SyncBlacklistDropdown()
		InfoLogger.Refresh()
		pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Blacklisted key '%s'.", NormalizedKey), Duration = 3 }) end)
	end)

	table.insert(Entries, 1, {
		Label = Label,
		Key = NormalizedKey or "",
		Type = Type,
		RawText = DisplayText,
	})

	InfoLogger.Refresh()
end

---Add a missing entry.
---@param Type string
---@param Key string
---@param Name string?
---@param Distance number
---@param Parent string?
function InfoLogger.AddMissEntry(Type, Key, Name, Distance, Parent)
	if BlacklistList[NormalizeKey(Key)] then return end
	if not ScrollingFrame then return end

	-- Cap entries per type.
	local TypeEntries = {}
	for I, E in next, Entries do
		if E.Type == Type then
			TypeEntries[#TypeEntries + 1] = { Entry = E, Index = I }
		end
	end
	if #TypeEntries > MaxEntriesPerType then
		local Last = TypeEntries[#TypeEntries]
		if Last.Entry.Label then Last.Entry.Label:Destroy() end
		table.remove(Entries, Last.Index)
	end

	-- Build column data (separate asset name and entity name columns).
	local EntityCol = Name and string.format("(%s)", Name) or ""
	local ParentCol = Parent and string.format("(%s)", Parent) or ""
	local DistCol = string.format("(%.2fm away)", Distance)
	local DisplayKey = NormalizeKey(Key)

	-- Create label (text set by Refresh).
	local Label = CreateEntryLabel("")

	-- Click handlers.
	Label.MouseButton1Click:Connect(function()
		pcall(setclipboard, Key)
		pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Copied key '%s' to clipboard.", Key), Duration = 3 }) end)
	end)

	Label.MouseButton2Click:Connect(function()
		local NKey = NormalizeKey(Key)
		BlacklistList[NKey] = true
		BlacklistHistory[#BlacklistHistory + 1] = NKey
		SaveBlacklist()
		SyncBlacklistDropdown()
		InfoLogger.Refresh()
		pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Blacklisted key '%s'.", NKey), Duration = 3 }) end)
	end)

	-- Insert entry with raw column data.
	local EntryData = {
		Label = Label, Key = Key, DisplayKey = DisplayKey, Type = Type, IsMissing = true,
		AssetCol = "", EntityCol = EntityCol, ParentCol = ParentCol, DistCol = DistCol,
	}
	table.insert(Entries, 1, EntryData)

	-- MarketplaceService lookup — cached, update entry AssetCol async then reformat.
	local Asset = typeof(Key) == "string" and (tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))) or nil
	if Asset then
		if AssetNameCache[Asset] then
			EntryData.AssetCol = string.format("(%s)", AssetNameCache[Asset])
		else
			task.spawn(function()
				pcall(function()
					local Info = MarketplaceService:GetProductInfo(Asset)
					if Info and Info.Name then
						AssetNameCache[Asset] = Info.Name
						EntryData.AssetCol = string.format("(%s)", Info.Name)
						InfoLogger.Refresh()
					end
				end)
			end)
		end
	end

	InfoLogger.Refresh()
end

---Add an existing entry.
---@param Type string
---@param Key string
---@param Name string?
---@param Distance number
---@param Parent string?
function InfoLogger.AddExistingEntry(Type, Key, Name, Distance, Parent)
	if BlacklistList[NormalizeKey(Key)] then return end
	if not ScrollingFrame then return end

	-- Cap entries per type.
	local TypeEntries = {}
	for I, E in next, Entries do
		if E.Type == Type then
			TypeEntries[#TypeEntries + 1] = { Entry = E, Index = I }
		end
	end
	if #TypeEntries > MaxEntriesPerType then
		local Last = TypeEntries[#TypeEntries]
		if Last.Entry.Label then Last.Entry.Label:Destroy() end
		table.remove(Entries, Last.Index)
	end

	-- Build column data (separate asset name and entity name columns).
	local EntityCol = Name and string.format("(%s)", Name) or ""
	local ParentCol = Parent and string.format("(%s)", Parent) or ""
	local DistCol = string.format("(%.2fm away)", Distance)
	local DisplayKey = NormalizeKey(Key)

	-- Create label (text set by Refresh).
	local Label = CreateEntryLabel("")

	-- Click handlers.
	Label.MouseButton1Click:Connect(function()
		pcall(setclipboard, Key)
		pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Copied key '%s' to clipboard.", Key), Duration = 3 }) end)
	end)

	Label.MouseButton2Click:Connect(function()
		local NKey = NormalizeKey(Key)
		BlacklistList[NKey] = true
		BlacklistHistory[#BlacklistHistory + 1] = NKey
		SaveBlacklist()
		SyncBlacklistDropdown()
		InfoLogger.Refresh()
		pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Blacklisted key '%s'.", NKey), Duration = 3 }) end)
	end)

	-- Insert entry with raw column data.
	local EntryData = {
		Label = Label, Key = Key, DisplayKey = DisplayKey, Type = Type, IsMissing = false,
		AssetCol = "", EntityCol = EntityCol, ParentCol = ParentCol, DistCol = DistCol,
	}
	table.insert(Entries, 1, EntryData)

	-- MarketplaceService lookup — cached, update entry AssetCol async then reformat.
	local Asset = typeof(Key) == "string" and (tonumber(Key:match("id=(%d+)")) or tonumber(Key:match("://(%d+)")) or tonumber(Key:match("%d+"))) or nil
	if Asset then
		if AssetNameCache[Asset] then
			EntryData.AssetCol = string.format("(%s)", AssetNameCache[Asset])
		else
			task.spawn(function()
				pcall(function()
					local Info = MarketplaceService:GetProductInfo(Asset)
					if Info and Info.Name then
						AssetNameCache[Asset] = Info.Name
						EntryData.AssetCol = string.format("(%s)", Info.Name)
						InfoLogger.Refresh()
					end
				end)
			end)
		end
	end

	InfoLogger.Refresh()
end

---Add a telemetry entry.
---@param Format string
function InfoLogger.AddTelemetryEntry(Format, ...)
	return AddTextEntry("Telemetry", nil, string.format(Format, ...), os.clock())
end

---Add a timeline entry.
---@param Format string
function InfoLogger.AddTimelineEntry(Format, ...)
	return AddTextEntry("Timeline", nil, string.format(Format, ...), os.clock())
end

---Add an animation start entry.
---@param Distance number
---@param Key string
---@param Name string?
---@param Track AnimationTrack
function InfoLogger.AddAnimationStartEntry(Distance, Key, Name, Track)
	local Timestamp = os.clock()
	LastAnimationStart = {
		Key = Key,
		Name = Name,
		Timestamp = Timestamp,
	}

	local Text = string.format(
		"(%.2fm away) Animation '%s' from '%s' started at '%.3f' time position. Speed=%.2f Priority=%s.",
		Distance,
		Key,
		Name or "N/A",
		Track.TimePosition,
		Track.Speed,
		tostring(Track.Priority)
	)

	return AddTextEntry("Timeline", Key, Text, Timestamp, Key)
end

---Add a keyframe entry.
---@param Distance number
---@param Key string
---@param Name string
---@param Position number
---@param Flag boolean?
function InfoLogger.AddKeyframeEntry(Distance, Key, Name, Position, Flag)
	local Timestamp = os.clock()
	local Text = string.format(
		"(%.2fm away) Animation '%s' %s keyframe '%s' at '%.3f' time position.",
		Distance,
		Key,
		Flag and "will reach" or "reached",
		Name,
		Position
	)

	AddTextEntry("Keyframe", Key, Text, Timestamp, Key)
	return AddTextEntry("Timeline", Key, Text, Timestamp, Key)
end

---Add a damage entry.
---@param Health number
---@param MaxHealth number
---@param Change number
function InfoLogger.AddDamageEntry(Health, MaxHealth, Change)
	local Timestamp = os.clock()
	local Text = string.format("Started taking damage. Health %.2f/%.2f (-%.2f).", Health, MaxHealth, Change)

	if LastAnimationStart then
		local Elapsed = math.max(Timestamp - LastAnimationStart.Timestamp, 0) * 1000
		Text = string.format(
			"(%.3fms from animation start) Started taking damage. Last animation '%s' from '%s'. Health %.2f/%.2f (-%.2f).",
			Elapsed,
			LastAnimationStart.Key or "N/A",
			LastAnimationStart.Name or "N/A",
			Health,
			MaxHealth,
			Change
		)
	end

	AddTextEntry("Telemetry", "Damage", Text, Timestamp, Text)
	return AddTextEntry("Timeline", "Damage", Text, Timestamp, Text)
end

---Get blacklisted keys.
---@return string[]
function InfoLogger.GetBlacklists()
	local Tbl = {}
	for Key, Val in next, BlacklistList do
		if Val then Tbl[#Tbl + 1] = Key end
	end
	return Tbl
end

---Remove a single key from the blacklist.
---@param Key string
function InfoLogger.RemoveBlacklist(Key)
	local NormalizedKey = NormalizeKey(Key)
	if not BlacklistList[NormalizedKey] then return end
	BlacklistList[NormalizedKey] = nil

	-- Remove from history.
	for I = #BlacklistHistory, 1, -1 do
		if BlacklistHistory[I] == NormalizedKey then
			table.remove(BlacklistHistory, I)
			break
		end
	end

	SaveBlacklist()
	SyncBlacklistDropdown()
	InfoLogger.Refresh()
	pcall(function() Library:Notification({ Title = "Info Logger", Description = string.format("Unblacklisted key '%s'.", NormalizedKey), Duration = 3 }) end)
end

---Public sync for deferred init.
---@param ResolveNames boolean?
function InfoLogger.SyncDropdown(ResolveNames)
	SyncBlacklistDropdown(ResolveNames)
end

---Set visibility.
---@param State boolean
function InfoLogger.Visible(State)
	if ScreenGuiRef then ScreenGuiRef.Enabled = State == true and not getgenv().EpiphyllumSilentMode end
end

-- ─── GUI Construction ───────────────────────────────────────────────────────────

---Initialize InfoLogger module.
function InfoLogger.Init(GamePath)
	-- Set up alias-shared blacklist file paths.
	if GamePath then
		BlacklistFilePath = GamePath .. "/blacklist.json"
		BlacklistSyncPaths = CollectBlacklistSyncPaths(GamePath)
		LoadBlacklist()
	end

	-- Clean up previous.
	pcall(function()
		local CoreGuiRef = game:GetService("CoreGui")
		local Prev = CoreGuiRef:FindFirstChild(ScreenGuiName)
		if Prev then Prev:Destroy() end
	end)
	pcall(function()
		local Prev = Players.LocalPlayer.PlayerGui:FindFirstChild(ScreenGuiName)
		if Prev then Prev:Destroy() end
	end)

	-- ScreenGui.
	ScreenGuiRef = Instance.new("ScreenGui")
	ScreenGuiRef.Name = ScreenGuiName
	ScreenGuiRef.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	ScreenGuiRef.ResetOnSpawn = false
	ScreenGuiRef.Enabled = false
	ScreenGuiRef.DisplayOrder = 5

	pcall(function() ScreenGuiRef.Parent = game:GetService("CoreGui") end)
	if not ScreenGuiRef.Parent then
		ScreenGuiRef.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
	end
	pcall(function() ScreenGuiRef.Parent = gethui() end)

	-- Outer frame.
	OuterFrame = Instance.new("Frame")
	OuterFrame.Name = "Outer"
	OuterFrame.Active = true
	OuterFrame.BackgroundColor3 = Library.Theme.Background
	OuterFrame.BackgroundTransparency = 0.3
	OuterFrame.Position = UDim2New(0.02, 0, 0.4, 0)
	OuterFrame.Size = UDim2New(0, PanelDefaultWidth, 0, PanelMinHeight)
	OuterFrame.BorderSizePixel = 0
	OuterFrame.ZIndex = 100
	OuterFrame.Parent = ScreenGuiRef

	local OuterCorner = Instance.new("UICorner")
	OuterCorner.CornerRadius = UDim.new(0, 6)
	OuterCorner.Parent = OuterFrame

	-- Title area (opaque header, like main GUI section tops).
	local TitleArea = Instance.new("Frame")
	TitleArea.Name = "TitleArea"
	TitleArea.Size = UDim2New(1, 0, 0, 30)
	TitleArea.BackgroundColor3 = FromRGB(26, 26, 30)
	TitleArea.BackgroundTransparency = 0.2
	TitleArea.BorderSizePixel = 0
	TitleArea.ZIndex = 101
	TitleArea.Parent = OuterFrame

	local TitleCorner = Instance.new("UICorner")
	TitleCorner.CornerRadius = UDim.new(0, 6)
	TitleCorner.Parent = TitleArea

	-- Cycle left button.
	local CycleLeft = Instance.new("ImageButton")
	CycleLeft.Name = "CycleLeft"
	CycleLeft.Image = GetIcon("chevron-left")
	CycleLeft.ImageColor3 = Library.Theme.Text
	CycleLeft.BackgroundTransparency = 1
	CycleLeft.Size = UDim2New(0, 16, 0, 16)
	CycleLeft.Position = UDim2New(0, 8, 0.5, 0)
	CycleLeft.AnchorPoint = Vector2New(0, 0.5)
	CycleLeft.ZIndex = 102
	CycleLeft.ScaleType = Enum.ScaleType.Fit
	CycleLeft.Parent = TitleArea

	-- Title label.
	TitleLabel = Instance.new("TextLabel")
	TitleLabel.Name = "Title"
	TitleLabel.FontFace = Library.Font
	TitleLabel.TextColor3 = Library.Theme.Text
	TitleLabel.Text = string.format("Info Logger (%s)", TypeCycles[CurrentCycle])
	TitleLabel.TextSize = 14
	TitleLabel.Size = UDim2New(1, -60, 1, 0)
	TitleLabel.Position = UDim2New(0.5, 0, 0, 0)
	TitleLabel.AnchorPoint = Vector2New(0.5, 0)
	TitleLabel.BackgroundTransparency = 1
	TitleLabel.BorderSizePixel = 0
	TitleLabel.ZIndex = 102
	TitleLabel.Parent = TitleArea

	-- Cycle right button.
	local CycleRight = Instance.new("ImageButton")
	CycleRight.Name = "CycleRight"
	CycleRight.Image = GetIcon("chevron-right")
	CycleRight.ImageColor3 = Library.Theme.Text
	CycleRight.BackgroundTransparency = 1
	CycleRight.Size = UDim2New(0, 16, 0, 16)
	CycleRight.Position = UDim2New(1, -8, 0.5, 0)
	CycleRight.AnchorPoint = Vector2New(1, 0.5)
	CycleRight.ZIndex = 102
	CycleRight.ScaleType = Enum.ScaleType.Fit
	CycleRight.Parent = TitleArea

	-- Scrolling frame (content area, slightly more transparent than title).
	ScrollingFrame = Instance.new("ScrollingFrame")
	ScrollingFrame.Name = "Entries"
	ScrollingFrame.Size = UDim2New(1, 0, 1, -32)
	ScrollingFrame.Position = UDim2New(0, 0, 0, 32)
	ScrollingFrame.BackgroundTransparency = 1
	ScrollingFrame.BorderSizePixel = 0
	ScrollingFrame.ScrollBarThickness = 4
	ScrollingFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
	ScrollingFrame.ScrollBarImageColor3 = Library.Theme.Accent
	ScrollingFrame.CanvasSize = UDim2.fromOffset(0, 0)
	ScrollingFrame.ZIndex = 101
	ScrollingFrame.Parent = OuterFrame

	local ListLayout = Instance.new("UIListLayout")
	ListLayout.SortOrder = Enum.SortOrder.LayoutOrder
	ListLayout.FillDirection = Enum.FillDirection.Vertical
	ListLayout.Padding = UDim.new(0, 2)
	ListLayout.Parent = ScrollingFrame

	-- Live canvas size update (add padding so last entry isn't clipped).
	ListLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		ScrollingFrame.CanvasSize = UDim2.fromOffset(0, ListLayout.AbsoluteContentSize.Y + 8)
	end)

	local Padding = Instance.new("UIPadding")
	Padding.PaddingLeft = UDim.new(0, 5)
	Padding.PaddingBottom = UDim.new(0, 4)
	Padding.Parent = ScrollingFrame

	-- ─── Interactions ───────────────────────────────────────────────────────────

	-- Cycle buttons.
	CycleLeft.MouseButton1Click:Connect(function()
		CurrentCycle = CurrentCycle <= 1 and #TypeCycles or CurrentCycle - 1
		PanelCurrentWidth = PanelDefaultWidth
		InfoLogger.Refresh()
	end)

	CycleRight.MouseButton1Click:Connect(function()
		CurrentCycle = CurrentCycle >= #TypeCycles and 1 or CurrentCycle + 1
		PanelCurrentWidth = PanelDefaultWidth
		InfoLogger.Refresh()
	end)

	-- Keyboard shortcuts.
	OuterFrame.InputBegan:Connect(function(Input)
		if Input.KeyCode == Enum.KeyCode.Q then
			CurrentCycle = CurrentCycle <= 1 and #TypeCycles or CurrentCycle - 1
			PanelCurrentWidth = PanelDefaultWidth
			InfoLogger.Refresh()
		elseif Input.KeyCode == Enum.KeyCode.E then
			CurrentCycle = CurrentCycle >= #TypeCycles and 1 or CurrentCycle + 1
			PanelCurrentWidth = PanelDefaultWidth
			InfoLogger.Refresh()
		elseif Input.KeyCode == Enum.KeyCode.Backspace then
			-- Undo last blacklist.
			local LastKey = BlacklistHistory[#BlacklistHistory]
			if LastKey then
				BlacklistList[LastKey] = nil
				BlacklistHistory[#BlacklistHistory] = nil
				SaveBlacklist()
				SyncBlacklistDropdown()
				InfoLogger.Refresh()
				if Library.Notify then
					Library:Notify(string.format("Unblacklisted key '%s'.", LastKey))
				end
			end
		end
	end)

	-- Draggable (tweened).
	local Dragging = false
	local DragStart = nil
	local StartAbsPos = nil
	local DragTweenInfo = TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	local DragInputChanged = nil

	TitleArea.InputBegan:Connect(function(Input)
		if Input.UserInputType == Enum.UserInputType.MouseButton1 then
			if Library.DragLock then return end
			Library.DragLock = true
			Dragging = true
			DragStart = Input.Position
			StartAbsPos = OuterFrame.AbsolutePosition

			if DragInputChanged then return end
			DragInputChanged = Input.Changed:Connect(function()
				if Input.UserInputState == Enum.UserInputState.End then
					Dragging = false
					Library.DragLock = false
					DragInputChanged:Disconnect()
					DragInputChanged = nil
				end
			end)
		end
	end)

	UserInputService.InputChanged:Connect(function(Input)
		if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
			local Delta = Input.Position - DragStart
			local NewX = StartAbsPos.X + Delta.X
			local NewY = StartAbsPos.Y + Delta.Y
			local ScreenSize = OuterFrame.Parent.AbsoluteSize
			local GuiSize = OuterFrame.AbsoluteSize
			NewX = math.clamp(NewX, 0, ScreenSize.X - GuiSize.X)
			NewY = math.clamp(NewY, 0, ScreenSize.Y - GuiSize.Y)
			TweenService:Create(OuterFrame, DragTweenInfo, { Position = UDim2.fromOffset(NewX, NewY) }):Play()
		end
	end)

end

---Detach InfoLogger module.
function InfoLogger.Detach()
	LoggerMaid:Clean()
	if ScreenGuiRef then
		ScreenGuiRef:Destroy()
		ScreenGuiRef = nil
	end
	Entries = {}
	EntryQueue = {}
	BlacklistList = {}
	BlacklistHistory = {}
	BlacklistFilePath = nil
	BlacklistSyncPaths = {}
	LastAnimationStart = nil
end

-- Return InfoLogger module.
return InfoLogger
end)
__bundle_register("Core/Latency", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Latency module.
local Latency = {}

-- Services.
local Stats = game:GetService("Stats")

---Get receiving delay.
---@return number
function Latency.Rdelay()
	return math.max(Latency.Rtt() / 2, 0.0)
end

---Get sending delay.
---@return number
function Latency.Sdelay()
	return math.max(Latency.Rtt() / 2, 0.0)
end

---Get round-trip time from Stats.Network.ServerStatsItem.Data Ping.
---@return number
function Latency.Rtt()
	local Network = Stats:FindFirstChild("Network")
	if not Network then
		return 0
	end

	local ServerStatsItem = Network:FindFirstChild("ServerStatsItem")
	if not ServerStatsItem then
		return 0
	end

	local DataPingItem = ServerStatsItem:FindFirstChild("Data Ping")
	if not DataPingItem then
		return 0
	end

	return (DataPingItem:GetValue() / 1000)
end

-- Return Latency module.
return Latency
end)
__bundle_register("Core/PlaybackData", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class PlaybackData
---@field Base number Timestamp of when the object was created.
---@field Ash table<number, number> Animation speed history. The key is the timestamp delta and the value is the speed at that point.
---@field Entity Model Entity to playback.
local PlaybackData = {}
PlaybackData.__index = PlaybackData

---Get last exceeded speed difference from a timestamp delta.
---@param From number
---@return number?, number?
function PlaybackData:Last(From)
	local LatestExceededSpeed = nil
	local LatestExceededDelta = nil

	for Delta, Speed in next, self.Ash do
		if From <= Delta then
			continue
		end

		if LatestExceededDelta and Delta <= LatestExceededDelta then
			continue
		end

		LatestExceededSpeed = Speed
		LatestExceededDelta = Delta
	end

	return LatestExceededSpeed, LatestExceededDelta
end

---Track animation speed.
---@param Speed number
function PlaybackData:Astrack(Speed)
	local Delta = os.clock() - self.Base

	if self:Last(Delta) == Speed then
		return
	end

	self.Ash[Delta] = Speed
end

---Create new PlaybackData object.
---@param Entity Model
---@return PlaybackData
function PlaybackData.new(Entity)
	local Self = setmetatable({}, PlaybackData)
	Self.Base = os.clock()
	Self.Entity = Entity
	Self.Ash = {}

	return Self
end

-- Return PlaybackData module.
return PlaybackData
end)
__bundle_register("Core/Remotes", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Remote configuration and action dispatch.
local Remotes = {}

local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

-- Action category mapping.
local RemoteToCategory = {
	parry = "Parry",
	block = "Block",
	unblock = "Block",
	dodge = "Dodge",
	dodgecancel = "Dodge",
	forcedfulldodge = "Dodge",
	counter = "Counter",
	jump = "Jump",
	teleportup = "Teleport Up",
	slide = "Slide",
	startslide = "Slide",
	endslide = "Slide",
	crouch = "Crouch",
	startcrouch = "Crouch",
	endcrouch = "Crouch",
	flashstep = "FlashStep",
}

-- Stored remotes (arrays per action).
local StoredRemotes = {}

-- Stored callbacks.
local Callbacks = {}

-- Stored remote arguments (arrays of arrays per action).
local RemoteArgs = {}

---Configure remotes.
---@param RemotesConfig table
---@param CallbacksConfig table?
---@param ArgsConfig table?
function Remotes.Configure(RemotesConfig, CallbacksConfig, ArgsConfig)
	StoredRemotes = RemotesConfig or {}
	Callbacks = CallbacksConfig or {}
	RemoteArgs = ArgsConfig or {}
end

---Build combined arguments from stored args and runtime args.
---@param Name string
---@param Index number
---@param ... any
---@return table?
local function BuildArgs(Name, Index, ...)
	local ArgsList = RemoteArgs[Name]
	local Args = ArgsList and ArgsList[Index]
	local Extra = { ... }
	local HasArgs = Args and #Args > 0
	local HasExtra = #Extra > 0

	if not HasArgs and not HasExtra then
		return nil
	end

	if HasArgs and not HasExtra then
		return Args
	end

	if not HasArgs and HasExtra then
		return Extra
	end

	-- Combine stored args with runtime args.
	local Combined = table.clone(Args)
	for I = 1, #Extra do
		Combined[#Combined + 1] = Extra[I]
	end
	return Combined
end

---Call a RemoteEvent or RemoteFunction.
---@param Remote Instance
---@param Args table?
---@return boolean
---@return any
local function CallRemote(Remote, Args)
	if Remote:IsA("RemoteEvent") then
		if Args then
			return pcall(Remote.FireServer, Remote, unpack(Args))
		end

		return pcall(Remote.FireServer, Remote)
	end

	if Remote:IsA("RemoteFunction") then
		if Args then
			return pcall(Remote.InvokeServer, Remote, unpack(Args))
		end

		return pcall(Remote.InvokeServer, Remote)
	end

	return false, "unsupported remote class " .. Remote.ClassName
end

---Fire a remote with optional callback override.
---@param Name string
---@param ... any
local function FireRemote(Name, ...)
	-- Check if action category is enabled.
	local EnabledActions = Configuration.ExpectOptionValue("EP_EnabledActions")
	if EnabledActions then
		-- Known actions map to categories, custom actions use name as-is (first letter uppercase).
		local Category = RemoteToCategory[Name] or (Name:sub(1, 1):upper() .. Name:sub(2))
		-- Multi-select dropdown returns an array, not a dictionary.
		local Found = false
		for Index, V in next, EnabledActions do
			if V == Category then Found = true break end
		end
		if not Found then
			return false
		end
	end

	local RemoteList = StoredRemotes[Name]
	local Callback = Callbacks[Name]

	if (not RemoteList or #RemoteList == 0) and not Callback then
		return false
	end

	-- Fire callback if set (VIM input).
	if Callback then
		local FirstRemote = RemoteList and RemoteList[1] or nil
		local Args = BuildArgs(Name, 1, ...)
		local Success, Err
		if Args then
			Success, Err = pcall(Callback, FirstRemote, unpack(Args))
		else
			Success, Err = pcall(Callback, FirstRemote)
		end
		if not Success then
			Logger.Warn("Remote callback '%s' failed: %s", Name, tostring(Err))
		end
		return Success
	end

	-- Fire all remotes for this action.
	local AnySuccess = false
	for I, Remote in next, RemoteList do
		local Args = BuildArgs(Name, I, ...)
		local Success, Err = CallRemote(Remote, Args)
		if not Success then
			Logger.Warn("Remote '%s' [%d] call failed: %s", Name, I, tostring(Err))
		end
		if Success then AnySuccess = true end
	end
	return AnySuccess
end

---Check if a remote exists.
---@param Name string
---@return boolean
function Remotes.Has(Name)
	local RemoteList = StoredRemotes[Name]
	return (RemoteList ~= nil and #RemoteList > 0) or Callbacks[Name] ~= nil
end

---Fire a configured action.
---@param Name string
---@param ... any
function Remotes.Fire(Name, ...)
	return FireRemote(Name, ...)
end

---Fire parry remote.
function Remotes.Parry()
	return FireRemote("parry")
end

---Fire block remote.
function Remotes.Block()
	return FireRemote("block")
end

---Fire unblock remote.
function Remotes.Unblock()
	return FireRemote("unblock")
end

---Fire dodge remote.
function Remotes.Dodge()
	return FireRemote("dodge")
end

-- Return Remotes module.
return Remotes
end)
__bundle_register("Core/StateChecker", function(require, _LOADED, __bundle_register, __bundle_modules)
-- State checker with user-overridable state checks.
local StateChecker = {}

-- Default state checks (always return true).
local StateChecks = {
	CanParry = function() return true end,
	CanDodge = function() return true end,
	CanBlock = function() return true end,
}

---Configure state checks.
---@param Checks table
function StateChecker.Configure(Checks)
	if not Checks then return end

	for Key, Fn in next, Checks do
		if typeof(Fn) == "function" then
			StateChecks[Key] = Fn
		end
	end
end

---Check if can parry.
---@return boolean
function StateChecker.CanParry()
	return StateChecks.CanParry()
end

---Check if can dodge.
---@return boolean
function StateChecker.CanDodge()
	return StateChecks.CanDodge()
end

---Check if can block.
---@return boolean
function StateChecker.CanBlock()
	return StateChecks.CanBlock()
end

-- Return StateChecker module.
return StateChecker
end)
__bundle_register("Defenders/AnimatorDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Animator defender module.

---@module Defenders.Defender
local Defender = require("Defenders/Defender")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Timings.SaveManager
local SaveManager = require("Timings/SaveManager")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Defenders.RepeatInfo
local RepeatInfo = require("Defenders/RepeatInfo")

---@module Defenders.HitboxOptions
local HitboxOptions = require("Defenders/HitboxOptions")

---@module Core.Latency
local Latency = require("Core/Latency")

---@module Core.PlaybackData
local PlaybackData = require("Core/PlaybackData")

---@module Core.EntityHistory
local EntityHistory = require("Core/EntityHistory")

---@module Core.InfoLogger
local InfoLogger = require("Core/InfoLogger")

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@class AnimatorDefender: Defender
---@field Animator Animator
---@field Offset number?
---@field Entity Model
---@field KfMaid Maid
---@field Keyframes Action[]
---@field TimingRef AnimationTiming?
---@field Track AnimationTrack?
---@field Pbdata table<AnimationTrack, PlaybackData> Playback data to be recorded.
---@field Rpbdata table<string, PlaybackData> Recorded playback data.
local AnimatorDefender = setmetatable({}, { __index = Defender })
AnimatorDefender.__index = AnimatorDefender
AnimatorDefender.__type = "Animation"

-- Services.
local Players = game:GetService("Players")

-- Constants.
local MaxRepeatTime = 5.0
local HistorySteps = 5.0
local PredictFacingDelta = 3

---Start info logger timeline tracking.
---@param Self AnimatorDefender
---@param Track AnimationTrack
---@param Aid string
local function StartTimelineTracking(Self, Track, Aid)
	Self.KfMaid:Clean()

	if not Configuration.ExpectToggleValue("EP_ShowInfoLogger") then
		return
	end

	local Distance = Self:Distance(Self.Entity)
	if not Distance then
		return
	end

	if
		Distance < (Configuration.ExpectOptionValue("EP_MinimumLoggerDistance") or 0)
		or Distance > (Configuration.ExpectOptionValue("EP_MaximumLoggerDistance") or 0)
	then
		return
	end

	InfoLogger.AddAnimationStartEntry(Distance, Aid, Self.Entity.Name, Track)

	local KeyframeReached = Signal.new(Track.KeyframeReached)
	local Stopped = Signal.new(Track.Stopped)

	Self.KfMaid:Mark(KeyframeReached:Connect("AnimatorDefender_OnKeyframeReached", function(KeyframeName)
		InfoLogger.AddKeyframeEntry(Distance, Aid, KeyframeName, Track.TimePosition, false)
	end))

	Self.KfMaid:Mark(Stopped:Connect("AnimatorDefender_OnTimelineTrackStopped", function()
		Self.KfMaid:Clean()
	end))
end

---Is animation stopped?
---@param Track AnimationTrack
---@param TimingObj AnimationTiming
---@return boolean
function AnimatorDefender:Stopped(Track, TimingObj)
	if not TimingObj.iae and not Track.IsPlaying then
		return true
	end

	if TimingObj.iae and not TimingObj.ieae and not Track.IsPlaying and Track.TimePosition < Track.Length then
		return true
	end
end

---Repeat conditional.
---@param Info RepeatInfo
---@return boolean
function AnimatorDefender:Rc(Info)
	---@note: There are cases where we might not have a track.
	if not Info.Track then
		return Logger.Warn(
			"(%s) Did you forget to pass the track? Or perhaps you forgot to place a hook before using this function.",
			Info.TimingRef.name
		)
	end

	if self:Stopped(Info.Track, Info.TimingRef) then
		return false
	end

	if Info.TimingRef.iae and os.clock() - Info.Start >= ((Info.TimingRef.mat / 1000) or MaxRepeatTime) then
		return self:Notify(Info.TimingRef, "Max animation timeout exceeded.")
	end

	return true
end

---Run predict facing hitbox check.
---@param Options HitboxOptions
---@return boolean
function AnimatorDefender:Pfh(Options)
	local Root = self.Entity:FindFirstChild("HumanoidRootPart")
	if not Root then
		return false
	end

	local YrateVal = EntityHistory.Yrate(self.Entity)
	if not YrateVal then
		return false
	end

	if not Options.TimingRef.ffh then
		if math.abs(YrateVal) < PredictFacingDelta then
			return false
		end
	end

	local Clone = Options:Clone()
	Clone:Ucache()

	-- Extrapolate opponent's facing direction based on their yaw rate.
	local Ptime = Options.Ptime or 0.15
	local PredictedAngle = YrateVal * Ptime
	local ExtrapolatedCFrame = Root.CFrame * CFrame.Angles(0, PredictedAngle, 0)

	local Result = false
	local Store = OriginalStore.new()

	Store:Run(Root, "CFrame", ExtrapolatedCFrame, function()
		Result = self:Hc(Clone, nil)
	end)

	return Result
end

---Run past hitbox detection.
---@param TimingObj AnimationTiming
---@param Options HitboxOptions
---@return boolean
function AnimatorDefender:Phd(TimingObj, Options)
	local Frames = EntityHistory.Pstepped(self.Entity, HistorySteps, TimingObj.phds)
	if not Frames then
		return false
	end

	for I = 1, #Frames do
		local Clone = Options:Clone()
		Clone.Cframe = Frames[I]
		Clone:Ucache()

		if self:Hc(Clone, nil) then
			return true
		end
	end

	return false
end

---Run facing prediction chain (extrapolation then interpolation fallback).
---@param TimingObj AnimationTiming
---@param Options HitboxOptions
---@return boolean
function AnimatorDefender:Fpc(TimingObj, Options)
	if (TimingObj.ffh or TimingObj.pfh) and self:Pfh(Options) then
		return true
	end

	if TimingObj.phd and self:Phd(TimingObj, Options) then
		return true
	end

	return false
end

---Check if we're in a valid state to proceed with the action.
---@param ActionRef Action?
---@param TimingObj AnimationTiming
---@return boolean
function AnimatorDefender:Valid(ActionRef, TimingObj)
	if not Defender.Valid(self, ActionRef, TimingObj) then
		return false
	end

	if not self.Track then
		return self:Notify(TimingObj, "No current track.")
	end

	if not self.Entity then
		return self:Notify(TimingObj, "No entity found.")
	end

	local TargetData = self:Target(self.Entity)
	if not TargetData then
		return self:Notify(TimingObj, "Not a viable target.")
	end

	local Root = self.Entity:FindFirstChild("HumanoidRootPart")
	if not Root then
		return self:Notify(TimingObj, "No humanoid root part found.")
	end

	local Character = Players.LocalPlayer.Character
	if not Character then
		return self:Notify(TimingObj, "No character found.")
	end

	if self:Stopped(self.Track, TimingObj) then
		return false
	end

	local Hoptions = HitboxOptions.new(Root, TimingObj)
	Hoptions.Spredict = not TimingObj.dp
	Hoptions.Ptime = self:Fsecs(TimingObj)
	Hoptions.ActionRef = ActionRef
	Hoptions.Entity = self.Entity
	Hoptions.Visualize = Configuration.ExpectToggleValue("EP_EnableVisualizations")
	Hoptions:Ucache()

	local Info = RepeatInfo.new(TimingObj, Latency.Rdelay(), self:Uid(10))
	Info.Track = self.Track

	-- Standard hitbox check.
	if self:Hc(Hoptions, nil) then
		return true
	end

	-- Prediction fallback (extrapolation + past hitbox detection).
	if self:Fpc(TimingObj, Hoptions) then
		return true
	end

	-- Delay until in hitbox.
	if TimingObj.duih and self:Hc(Hoptions, Info) then
		return true
	end

	return self:Notify(TimingObj, "Action '%s' is not in hitbox.", ActionRef and ActionRef.name or "N/A")
end

---Process animation track.
---@param Track AnimationTrack
function AnimatorDefender:Process(Track)
	local Aid = tostring(Track.Animation.AnimationId)

	-- Record playback data for visualizer.
	self.Pbdata[Track] = PlaybackData.new(self.Entity)
	StartTimelineTracking(self, Track, Aid)

	-- Log and process.
	self:ProcessValidated(Track, Aid)
end

---Update playback data tracking.
function AnimatorDefender:Update()
	for Track, Data in next, self.Pbdata do
		if not Track.IsPlaying then
			self.Pbdata[Track] = nil
			self.Rpbdata[tostring(Track.Animation.AnimationId)] = Data
			continue
		end

		Data:Astrack(Track.Speed)
	end
end

---Process validated animation track.
---@param Track AnimationTrack
---@param Aid string
function AnimatorDefender:ProcessValidated(Track, Aid)
	---@type AnimationTiming?
	local TimingObj = self:Initial(self.Entity, SaveManager.As, self.Entity.Name, Aid)

	if not TimingObj then
		return
	end

	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return
	end

	local HumanoidRootPart = self.Entity:FindFirstChild("HumanoidRootPart")
	if not HumanoidRootPart then
		return
	end

	if TimingObj.tag == "Critical" then
		TimingObj.nbfb = true
		TimingObj.ha = true
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:Clean()

	-- Set current data.
	self.TimingRef = TimingObj
	self.Track = Track
	self.Offset = Latency.Rdelay()

	-- Use module over actions.
	if TimingObj.umoa then
		return self:Module(TimingObj)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not TimingObj.rpue then
		return self:Actions(TimingObj)
	end

	-- Start RPUE.
	local Info = RepeatInfo.new(TimingObj, Latency.Rdelay(), self:Uid(10))
	Info.Track = Track
	self:Srpue(self.Entity, TimingObj, Info)
end

---Clean up the defender.
function AnimatorDefender:Clean()
	-- Empty data.
	self.Keyframes = {}

	-- Clean through base method.
	Defender.Clean(self)
end

---Create new AnimatorDefender object.
---@param AnimatorInstance Animator
---@return AnimatorDefender
function AnimatorDefender.new(AnimatorInstance)
	local Entity = AnimatorInstance:FindFirstAncestorWhichIsA("Model")
	if not Entity then
		return error(string.format("AnimatorDefender.new(%s) - no entity.", AnimatorInstance:GetFullName()))
	end

	local Self = setmetatable(Defender.new(), AnimatorDefender)
	local AnimationPlayed = Signal.new(AnimatorInstance.AnimationPlayed)

	Self.Animator = AnimatorInstance
	Self.Entity = Entity
	Self.KfMaid = Maid.new()

	Self.Track = nil
	Self.TimingRef = nil
	Self.Offset = nil
	Self.Keyframes = {}
	Self.Pbdata = {}
	Self.Rpbdata = {}

	Self.Maid:Mark(AnimationPlayed:Connect(
		"AnimatorDefender_OnAnimationPlayed",
		function(Track)
			Self:Process(Track)
		end
	))
	Self.Maid:Mark(function()
		Self.KfMaid:Clean()
	end)

	return Self
end

-- Return AnimatorDefender module.
return AnimatorDefender
end)
__bundle_register("Defenders/Defender", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Defender module.

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Defenders.Task
local Task = require("Defenders/Task")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Defenders.HitboxOptions
local HitboxOptions = require("Defenders/HitboxOptions")

---@module GUI.Library
local Library = require("GUI/Library")

---@module Core.Latency
local Latency = require("Core/Latency")

---@module Core.Remotes
local Remotes = require("Core/Remotes")

---@module Core.StateChecker
local StateChecker = require("Core/StateChecker")

-- Lazy-loaded modules.
local ModuleManager

---@class Defender
---@field Tasks Task[]
---@field Tmaid Maid Cleaned up every clean cycle.
---@field Rhook table<string, function> Hooked functions that we can restore on clean-up.
---@field Markers table<string, boolean> Blocking markers.
---@field Maid Maid
---@field Hmaid Maid Maid for hitbox visualizations.
---@field Uids number Unique ID counter for hitbox visualizations.
local Defender = {}
Defender.__index = Defender
Defender.__type = "Defender"

-- Services.
local UserInputService = game:GetService("UserInputService")
local Players = game:GetService("Players")
local TextChatService = game:GetService("TextChatService")
local DebrisService = game:GetService("Debris")

-- Constants.
local MaxVisualizationTime = 5.0
local MaxRepeatWait = 10.0

-- Action to dispatch mapping.
local ActionToInternal = {
	Parry = "parry",
	Dodge = "dodge",
	["Dodge Cancel"] = "dodgecancel",
	["Forced Full Dodge"] = "forcedfulldodge",
	Jump = "jump",
	["Teleport Up"] = "teleportup",
	["Start Block"] = "block",
	["End Block"] = "unblock",
	["Start Slide"] = "startslide",
	["End Slide"] = "endslide",
	["Start Crouch"] = "startcrouch",
	["End Crouch"] = "endcrouch",
}

---Get internal action name.
---@param ActionType string
---@return string
local function GetActionInternalName(ActionType)
	ActionType = tostring(ActionType or "")
	return ActionToInternal[ActionType] or ActionType:gsub("%s+", ""):lower()
end

---Fetch distance.
---@param From Model|BasePart?
---@return number?
function Defender:Distance(From)
	if not From then
		return
	end

	local EntRootPart = From

	if From:IsA("Model") then
		EntRootPart = From:FindFirstChild("HumanoidRootPart")
	end

	if not EntRootPart then
		return
	end

	local LocalCharacter = Players.LocalPlayer.Character
	if not LocalCharacter then
		return
	end

	local LocalRootPart = LocalCharacter:FindFirstChild("HumanoidRootPart")
	if not LocalRootPart then
		return
	end

	return (EntRootPart.Position - LocalRootPart.Position).Magnitude
end

---Check if a source belongs to the local player.
---@param From Instance?
---@return boolean
function Defender:IsLocalPlayerSource(From)
	if not Configuration.ExpectToggleValue("EP_IgnoreLocalPlayer") then
		return false
	end

	local Character = Players.LocalPlayer.Character
	if not Character or not From or typeof(From) ~= "Instance" then
		return false
	end

	return From == Character or From:IsDescendantOf(Character)
end

---Find target - hookable function.
---@param Entity Model
---@return table?
function Defender:Target(Entity)
	if not Entity then
		return nil
	end

	if not Entity:IsA("Model") then
		return nil
	end

	local Root = Entity:FindFirstChild("HumanoidRootPart")
	if not Root then
		return nil
	end

	-- Skip local player if enabled.
	if self:IsLocalPlayerSource(Entity) then
		return nil
	end

	-- Skip mobs if Ignore Mobs is enabled.
	local IsPlayer = Players:GetPlayerFromCharacter(Entity) ~= nil
	if Configuration.ExpectToggleValue("EP_IgnoreMobs") and not IsPlayer then
		return nil
	end

	-- Skip players if Ignore Players is enabled.
	if Configuration.ExpectToggleValue("EP_IgnorePlayers") and IsPlayer then
		return nil
	end

	return { Root = Root }
end

---Get extrapolated seconds.
---@param TimingObj Timing
---@return number
function Defender:Fsecs(TimingObj)
	local Player = self.Entity and Players:GetPlayerFromCharacter(self.Entity)
	local Sd = (Player and Player:GetAttribute("AveragePing") or 50.0) / 2000
	return (TimingObj.pfht or 0.15) + (Sd + Latency.Rdelay())
end

---Get a unique ID for hitboxes.
---@param Spaces number
---@return number
function Defender:Uid(Spaces)
	self.Uids = self.Uids + Spaces
	return self.Uids
end

---Visualize a position and size.
---@param Identifier number?
---@param Cf CFrame
---@param Size Vector3
---@param Color Color3
---@param Shape Enum.PartType
function Defender:Visualize(Identifier, Cf, Size, Color, Shape)
	if not Configuration.ExpectToggleValue("EP_EnableVisualizations") then
		return
	end

	local Id = Identifier or self:Uid(10)
	local Vpart = self.Hmaid[Id] or Instance.new("Part")

	pcall(function()
		Vpart.Parent = workspace
	end)

	if Vpart.Parent then
		Vpart.Anchored = true
		Vpart.CanCollide = false
		Vpart.CanQuery = false
		Vpart.CanTouch = false
		Vpart.Material = Enum.Material.ForceField
		Vpart.CastShadow = false
		Vpart.Size = Size
		Vpart.CFrame = Cf
		Vpart.Color = Color
		Vpart.Shape = Shape
		Vpart.Transparency = 0.2
	end

	if self.Hmaid[Id] then
		return
	end

	self.Hmaid[Id] = Vpart
	DebrisService:AddItem(Vpart, MaxVisualizationTime)
end

---Run hitbox check. Returns whether the hitbox is being touched.
---@param Cf CFrame
---@param Fd boolean
---@param Soffset number
---@param Size Vector3
---@param FilterList Instance[]
---@param Shape Enum.PartType
---@return boolean?, CFrame?
function Defender:HitboxCheck(Cf, Fd, Soffset, Size, FilterList, Shape)
	local OverlapParamsObj = OverlapParams.new()
	OverlapParamsObj.FilterDescendantsInstances = FilterList
	OverlapParamsObj.FilterType = Enum.RaycastFilterType.Include

	local Character = Players.LocalPlayer.Character
	if not Character then
		return nil, nil
	end

	local Root = Character:FindFirstChild("HumanoidRootPart")
	if not Root then
		return nil, nil
	end

	-- Used CFrame.
	local UsedCFrame = Cf

	if Fd then
		UsedCFrame = UsedCFrame * CFrame.new(0, 0, -(Size.Z / 2))
	end

	if Soffset and Soffset ~= 0 then
		UsedCFrame = UsedCFrame * CFrame.new(0, 0, Soffset)
	end

	-- Create simulation part.
	local SimulationPart = Instance.new("Part")
	SimulationPart.Size = Size
	SimulationPart.Material = Enum.Material.ForceField
	SimulationPart.Shape = Shape
	SimulationPart.CFrame = UsedCFrame

	if Shape == Enum.PartType.Cylinder then
		SimulationPart.CFrame = UsedCFrame * CFrame.Angles(0, 0, math.rad(90))
	end

	-- Parts in bounds.
	local Parts = workspace:GetPartsInPart(SimulationPart, OverlapParamsObj)

	-- Return result.
	return #Parts > 0, UsedCFrame
end

---Handle delay until in hitbox.
---@param Options HitboxOptions
---@param Info RepeatInfo
---@return boolean
function Defender:Duih(Options, Info)
	local ClonedOptions = Options:Clone()
	ClonedOptions.Hmid = Info.Hmid
	ClonedOptions:Ucache()

	while task.wait() do
		if not self:Rc(Info) then
			return false
		end

		if not self:Hc(ClonedOptions, nil) then
			continue
		end

		return true
	end
end

---Repeat conditional.
---@param Info RepeatInfo
---@return boolean
function Defender:Rc(Info)
	if os.clock() - Info.Start >= MaxRepeatWait then
		return false
	end

	return true
end

---Handle hitbox check options.
---@param Options HitboxOptions
---@param Info RepeatInfo?
---@return boolean
function Defender:Hc(Options, Info)
	local ActionRef = Options.ActionRef
	local TimingRef = Options.TimingRef

	-- Run basic validation.
	local Character = Players.LocalPlayer.Character
	if not Character then
		return false
	end

	local Root = Character:FindFirstChild("HumanoidRootPart")
	if not Root then
		return false
	end

	if ActionRef and ActionRef.ihbc then
		return true
	end

	-- If we have info, then we want to delay until in hitbox.
	if Info then
		return self:Duih(Options, Info)
	end

	-- Fetch the data that we need.
	local HitboxSize = Options:Hitbox()
	local Position = Options:Pos()
	local Pt = TimingRef.htype or Enum.PartType.Block

	-- Run hitbox check.
	local Result, UsedCFrame = self:HitboxCheck(Position, TimingRef.fhb, TimingRef.hso, HitboxSize, Options.Filter, Pt)

	-- Visualize.
	if UsedCFrame and Options.Visualize then
		local HitColor = Result and Color3.new(0, 1, 0) or Color3.new(1, 0, 0)
		self:Visualize(Options.Hmid, UsedCFrame, HitboxSize, HitColor, Pt)
	end

	return Result
end

---Log a missing timing to the Info Logger.
---@param Type string
---@param Key string
---@param Name string?
---@param Dist number
---@param ParentName string?
---@return boolean
function Defender:Miss(Type, Key, Name, Dist, ParentName)
	if not Configuration.ExpectToggleValue("EP_ShowInfoLogger") then
		return false
	end

	local MinDist = Configuration.ExpectOptionValue("EP_MinimumLoggerDistance") or 0
	local MaxDist = Configuration.ExpectOptionValue("EP_MaximumLoggerDistance") or 0

	if Dist < MinDist then
		return false
	end

	if MaxDist > 0 and Dist > MaxDist then
		return false
	end

	Library:AddMissEntry(Type, Key, Name, Dist, ParentName)

	return true
end

---Log an existing timing to the Info Logger.
---@param Type string
---@param Key string
---@param Name string?
---@param Dist number
---@param ParentName string?
---@return boolean
function Defender:Existing(Type, Key, Name, Dist, ParentName)
	if not Configuration.ExpectToggleValue("EP_ShowInfoLogger") then
		return false
	end

	local MinDist = Configuration.ExpectOptionValue("EP_MinimumLoggerDistance") or 0
	local MaxDist = Configuration.ExpectOptionValue("EP_MaximumLoggerDistance") or 0

	if Dist < MinDist then
		return false
	end

	if MaxDist > 0 and Dist > MaxDist then
		return false
	end

	Library:AddExistingEntry(Type, Key, Name, Dist, ParentName)

	return true
end

---Check initial state.
---@param From Model|BasePart?
---@param Pair TimingContainerPair
---@param Name string?
---@param Key string
---@return Timing?
function Defender:Initial(From, Pair, Name, Key)
	if self:IsLocalPlayerSource(From) then
		return nil
	end

	-- Find timing.
	local TimingObj = Pair:Index(Key)

	-- Fetch distance.
	local Dist = self:Distance(From)
	if not Dist then
		return nil
	end

	-- Check for distance; if we have a timing.
	if TimingObj then
		local Md = TimingObj.imdd
		if Md <= 0.01 then
			Md = 0.0
		end

		-- Skip distance checks if ranges are default (0).
		if Md > 0 and Dist < Md then
			return nil
		end

		if TimingObj.imxd > 0 and Dist > TimingObj.imxd then
			return nil
		end
	end

	-- No timing found. Log a miss.
	if not TimingObj then
		self:Miss(self.__type, Key, Name, Dist, From and tostring(From.Parent) or nil)
		return false
	end

	-- Log existing timing.
	self:Existing(self.__type, Key, Name, Dist, From and tostring(From.Parent) or nil)

	-- Return timing.
	return TimingObj
end

---Logger notify (non-blocking).
---@param TimingObj Timing
---@param Str string
function Defender:Notify(TimingObj, Str, ...)
	if not Configuration.ExpectToggleValue("EP_EnableNotifications") then
		return
	end

	local Formatted = string.format("[%s] (%s) %s", TimingObj.name, self.__type, string.format(Str, ...))
	task.defer(Logger.QNotify, Formatted)
end

---Check if we're in a valid state to proceed with action handling.
---@param ActionRef Action?
---@param TimingObj Timing
---@return boolean
function Defender:Valid(ActionRef, TimingObj)
	-- Gate on main toggle.
	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return false
	end

	local Integer = Random.new():NextNumber(1.0, 100.0)
	local Rate = Configuration.ExpectOptionValue("EP_FailureRate") or 0.0

	if Configuration.ExpectToggleValue("EP_AllowFailure") and Integer <= Rate then
		return self:Notify(TimingObj, "(%i <= %i) Intentionally did not run.", Integer, Rate)
	end

	local SelectedFilters = Configuration.ExpectOptionValue("EP_AutoDefenseFilters") or {}

	-- Disable when textbox focused.
	if SelectedFilters["Disable When Textbox Focused"] then
		local ChatInputBarConfiguration = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration")
		local TextBoxFocused = UserInputService:GetFocusedTextBox()
		local ChatFocused = ChatInputBarConfiguration and ChatInputBarConfiguration.IsFocused

		if TextBoxFocused or ChatFocused then
			return self:Notify(TimingObj, "User is typing in a text box.")
		end
	end

	-- Disable when window not active.
	if SelectedFilters["Disable When Window Not Active"] and typeof(iswindowactive) == "function" and not iswindowactive() then
		return self:Notify(TimingObj, "Window is not active.")
	end

	-- Tag filters.
	if TimingObj.tag == "M1" and SelectedFilters["Filter Out M1s"] then
		return self:Notify(TimingObj, "Attacker is using a 'M1' attack.")
	end

	if TimingObj.tag == "Mantra" and SelectedFilters["Filter Out Mantras"] then
		return self:Notify(TimingObj, "Attacker is using a 'Mantra' attack.")
	end

	if TimingObj.tag == "Critical" and SelectedFilters["Filter Out Criticals"] then
		return self:Notify(TimingObj, "Attacker is using a 'Critical' attack.")
	end

	if TimingObj.tag == "Undefined" and SelectedFilters["Filter Out Undefined"] then
		return self:Notify(TimingObj, "Attacker is using an 'Undefined' attack.")
	end

	return true
end

---Run a dodge action.
---@param TimingObj Timing
---@param ForceFull boolean?
function Defender:RunDodge(TimingObj, ForceFull)
	if ForceFull and Remotes.Has("forcedfulldodge") then
		return Remotes.Fire("forcedfulldodge")
	end

	if Configuration.ExpectToggleValue("EP_DodgeCancel") and Remotes.Has("dodgecancel") then
		return Remotes.Fire("dodgecancel")
	end

	return Remotes.Dodge()
end

---Handle action.
---@param TimingObj Timing
---@param ActionRef Action
---@param Started number
function Defender:Handle(TimingObj, ActionRef, Started)
	local ActionType = ActionRef._type
	local InternalName = GetActionInternalName(ActionType)

	-- Release actions must always execute (pair with hold actions).
	if InternalName == "unblock" or InternalName == "endslide" or InternalName == "endcrouch" then
		return Remotes.Fire(InternalName)
	end

	-- Validate.
	if not self:Valid(ActionRef, TimingObj) then
		return
	end

	self:Notify(TimingObj, "Action type '%s' is being executed.", ActionType)

	-- Hold actions.
	if InternalName == "block" or InternalName == "startslide" or InternalName == "startcrouch" then
		return Remotes.Fire(InternalName)
	end

	-- Parry only override.
	if (InternalName == "dodge" or InternalName == "dodgecancel" or InternalName == "forcedfulldodge") and Configuration.ExpectToggleValue("EP_ParryOnly") then
		ActionType = "Parry"
		InternalName = "parry"
		self:Notify(TimingObj, "Action 'Dodge' changed to 'Parry'")
	end

	-- Dodge.
	if InternalName == "dodge" or InternalName == "dodgecancel" then
		return self:RunDodge(TimingObj, false)
	end

	-- Forced full dodge uses the configured full-dodge input when present, otherwise the normal dodge input.
	if InternalName == "forcedfulldodge" then
		return self:RunDodge(TimingObj, true)
	end

	-- Generic configured action.
	if InternalName ~= "parry" and Remotes.Has(InternalName) then
		return Remotes.Fire(InternalName)
	end

	-- Default: Parry (with fallback chain).
	self:DoParry(TimingObj, ActionRef)
end

---Handle parry with fallback chain.
---@param TimingObj Timing
---@param ActionRef Action?
function Defender:DoParry(TimingObj, ActionRef)
	local function InternalNotify(...)
		if TimingObj.rpue and TimingObj.srpn then
			return
		end

		return self:Notify(...)
	end

	-- Allow attacking override bypasses all state checks.
	local Aatk = TimingObj.aatk

	-- Parry if possible.
	if Aatk or StateChecker.CanParry() then
		return Remotes.Parry()
	end

	-- Prefer block fallback.
	if TimingObj.pbfb and not TimingObj.nbfb and (Aatk or StateChecker.CanBlock()) and Configuration.ExpectToggleValue("EP_BlockFallback") then
		Remotes.Block()
		local Bfht = TimingObj.bfht or 0.3
		task.delay(Bfht, function()
			Remotes.Unblock()
		end)
		return InternalNotify(TimingObj, "Action type 'Parry' fallback to 'Block' type.")
	end

	-- Dodge fallback.
	local CanDodge = (Aatk or StateChecker.CanDodge())
		and Configuration.ExpectToggleValue("EP_DodgeFallback")
		and not TimingObj.ndfb

	if CanDodge then
		self:RunDodge(TimingObj, false)
		return InternalNotify(TimingObj, "Action type 'Parry' fallback to 'Dodge' type.")
	end

	-- Block fallback (if not already tried via pbfb).
	if not TimingObj.pbfb and not TimingObj.nbfb and (Aatk or StateChecker.CanBlock()) and Configuration.ExpectToggleValue("EP_BlockFallback") then
		Remotes.Block()
		local Bfht = TimingObj.bfht or 0.3
		task.delay(Bfht, function()
			Remotes.Unblock()
		end)
		return InternalNotify(TimingObj, "Action type 'Parry' fallback to 'Block' type.")
	end

	-- Cannot fallback.
	return InternalNotify(TimingObj, "Action 'Parry' blocked because no fallbacks are available.")
end

---Start repeat until parry end.
---@param Ref Model|BasePart
---@param TimingObj Timing
---@param Info RepeatInfo
function Defender:Srpue(Ref, TimingObj, Info)
	if self:IsLocalPlayerSource(Ref) then
		return
	end

	local Cache = {
		Name = TimingObj.name,
		Imdd = TimingObj.imdd,
		Imxd = TimingObj.imxd,
		Rsd = TimingObj:Rsd(),
		Rpd = TimingObj:Rpd(),
	}

	local TargetData = self:Target(Ref)
	local Part = TargetData and TargetData.Root or CFrame.new()

	if Ref:IsA("BasePart") then
		Part = Ref
	end

	local Options = HitboxOptions.new(Part, TimingObj)
	Options.Spredict = not TimingObj.duih
	Options.Ptime = self:Fsecs(TimingObj)
	Options.Entity = Ref:IsA("Model") and TargetData or nil
	Options.ActionRef = TimingObj.actions and TimingObj.actions:Stack()[1] or nil
	Options.Hmid = Info.Hmid
	Options.Visualize = Configuration.ExpectToggleValue("EP_EnableVisualizations")
	Options.PreferActionHitbox = true
	Options:Ucache()

	-- Start RPUE.
	self:Mark(Task.new(string.format("RPUE_%s_%i", TimingObj.name, 0), function()
		return Cache.Rsd - Info.Irdelay - Latency.Sdelay()
	end, TimingObj.punishable, TimingObj.after, self.Rpue, self, Ref, TimingObj, Info, Cache, Options))

	-- Notify.
	self:Notify(
		TimingObj,
		"Added RPUE '%s' (%.2fs, then every %.2fs) with ping '%.2f' (changing) subtracted.",
		Cache.Name,
		Cache.Rsd,
		Cache.Rpd,
		Latency.Rtt()
	)
end

---Repeat until parry end.
---@param Ref Model|BasePart
---@param TimingObj Timing
---@param Info RepeatInfo
---@param Cache table
---@param Options HitboxOptions
function Defender:Rpue(Ref, TimingObj, Info, Cache, Options)
	-- Gate on main toggle.
	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return
	end

	if self:IsLocalPlayerSource(Ref) then
		return
	end

	local Dist = self:Distance(Ref)
	if not Dist then
		return Logger.Warn("Stopping RPUE '%s' because the distance is not valid.", Cache.Name)
	end

	if not self:Rc(Info) then
		return Logger.Warn("Stopping RPUE '%s' because the repeat condition is not valid.", Cache.Name)
	end

	local TargetData = Ref:IsA("Model") and self:Target(Ref) or true
	local Success = true
	local Reasons = {}

	Options.Part = Ref:IsA("BasePart") and Ref or (TargetData ~= true and TargetData and TargetData.Root)
	Options.Cframe = not Options.Part and CFrame.new()

	if TimingObj.duih and TargetData then
		Success = self:Hc(Options, Info)
		Reasons[#Reasons + 1] = string.format("hitbox (%s)", tostring(Options:Hitbox()))
	end

	-- Distance range check.
	if Cache.Imdd > 0 or Cache.Imxd > 0 then
		local Within = true
		if Cache.Imdd > 0 and Dist < Cache.Imdd then
			Within = false
		end
		if Cache.Imxd > 0 and Dist > Cache.Imxd then
			Within = false
		end

		Success = Within

		if not Within then
			Reasons[#Reasons + 1] = string.format("distance range (%.2f < %.2f > %.2f)", Cache.Imdd, Dist, Cache.Imxd)
		end
	end

	Info.Index = Info.Index + 1

	self:Mark(Task.new(string.format("RPUE_%s_%i", TimingObj.name, Info.Index), function()
		return Cache.Rpd - Info.Irdelay - Latency.Sdelay()
	end, TimingObj.punishable, TimingObj.after, self.Rpue, self, Ref, TimingObj, Info, Cache, Options))

	if not TargetData then
		return Logger.Warn("Skipping RPUE '%s' because the target is not valid.", Cache.Name)
	end

	if not Success then
		return Logger.Warn("Skipping RPUE '%s' (%s)", Cache.Name, #Reasons > 0 and table.concat(Reasons, ", ") or "N/A")
	end

	-- Check action type from timing actions.
	local ActionRef = Options.ActionRef
	local ActionType = ActionRef and ActionRef._type or "Parry"

	self:Notify(TimingObj, "Action type 'RPUE %s' is being executed.", ActionType)

	local InternalName = GetActionInternalName(ActionType)
	if InternalName == "dodge" or InternalName == "dodgecancel" or InternalName == "forcedfulldodge" then
		if not TimingObj.aatk and not StateChecker.CanDodge() then
			return Logger.Warn("Skipping RPUE '%s' because dodge is on cooldown.", Cache.Name)
		end
		return self:RunDodge(TimingObj, InternalName == "forcedfulldodge")
	end

	self:DoParry(TimingObj, ActionRef)
end

---Add a action to the defender object.
---@param TimingObj Timing
---@param ActionRef Action
function Defender:Action(TimingObj, ActionRef)
	if TimingObj.umoa and self.__type == "Animation" then
		TimingObj.et = ActionRef._when
	end

	-- Get initial receive delay.
	local Rdelay = Latency.Rdelay()
	local DelayFn = function()
		return ActionRef:When() - Rdelay - Latency.Sdelay()
	end

	-- Fast path: execute directly only when latency compensation makes the action due now.
	if DelayFn() <= 0 then
		self:Handle(TimingObj, ActionRef, os.clock())
		self:Notify(
			TimingObj,
			"Immediate action '%s' (%.2fs) with ping '%.2f' subtracted.",
			ActionRef.name,
			ActionRef:When(),
			Latency.Rtt()
		)
		return
	end

	-- Add action.
	local Atask = Task.new(ActionRef._type, DelayFn, TimingObj.punishable, TimingObj.after, self.Handle, self, TimingObj, ActionRef, os.clock())

	if TimingObj.forced then
		Atask.Forced = true
	end

	self:Mark(Atask)

	-- Log.
	self:Notify(
		TimingObj,
		"Added action '%s' (%.2fs) with ping '%.2f' (changing) subtracted.",
		ActionRef.name,
		ActionRef:When(),
		Latency.Rtt()
	)
end

---Add actions from timing to defender object.
---@param TimingObj Timing
function Defender:Actions(TimingObj)
	for Index, ActionRef in next, TimingObj.actions:Stack() do
		self:Action(TimingObj, ActionRef)
	end
end

---Process module.
---@param TimingObj Timing
function Defender:Module(TimingObj, ...)
	if not ModuleManager then
		ModuleManager = require("Modules/ModuleManager")
	end

	-- Get loaded function.
	local Lf = ModuleManager.Modules[TimingObj.smod]
	if not Lf then
		return self:Notify(TimingObj, "No module '%s' found.", TimingObj.smod)
	end

	-- Create identifier.
	local Identifier = string.format("Defender_RunModule_%s", TimingObj.smod)

	-- Notify.
	if not TimingObj.smn then
		self:Notify(TimingObj, "Running module '%s' on timing.", TimingObj.smod)
	end

	-- Run module.
	self.Tmaid:Mark(TaskSpawner.Spawn(Identifier, Lf, self, TimingObj, ...))
end

---Check if we have input blocking tasks.
---@return boolean
function Defender:Blocking()
	for Index, MarkerVal in next, self.Markers do
		if not MarkerVal then
			continue
		end

		return true
	end

	for Index, T in next, self.Tasks do
		if not T:Blocking() then
			continue
		end

		return true
	end
end

---Mark task.
---@param Atask Task
function Defender:Mark(Atask)
	self.Tasks[#self.Tasks + 1] = Atask
end

---Clean up hooks.
function Defender:Clhook()
	for Key, Old in next, self.Rhook do
		if not self[Key] then
			continue
		end

		self[Key] = Old
	end

	self.Rhook = {}
end

---Clean up all tasks.
function Defender:Clean()
	-- Clean-up tasks.
	for Idx, T in next, self.Tasks do
		if T.Forced then
			continue
		end

		-- Cancel task.
		T:Cancel()

		-- Clear in table.
		self.Tasks[Idx] = nil

		-- If we are cancelling a block task, end the block.
		if T.Identifier ~= "End Block" and T.Identifier ~= "Start Block" then
			continue
		end

		Remotes.Unblock()
	end

	-- Clean-up hooks.
	self:Clhook()

	-- Clear temporary maid.
	self.Tmaid:Clean()

	-- Clear markers.
	self.Markers = {}

	-- Clean up hitboxes.
	self.Hmaid:Clean()
end

---Safely replace a function in the defender object.
---@param Key string
---@param New function
---@return boolean, function?
function Defender:Hook(Key, New)
	-- Check if we're already hooked.
	if self.Rhook[Key] then
		Logger.Warn("Cannot hook '%s' because it is already hooked.", Key)
		return false, nil
	end

	-- Get our assumed old / target function.
	local Old = self[Key]

	-- Check if function.
	if typeof(Old) ~= "function" then
		Logger.Warn("Cannot hook '%s' because it is not a function.", Key)
		return false, nil
	end

	-- Create hook.
	self[Key] = New

	-- Add to hook table with the old function so we can restore it on clean-up.
	self.Rhook[Key] = Old

	-- Log.
	Logger.Warn("Hooked '%s' with new function.", Key)

	return true, Old
end

---Detach defender object.
function Defender:Detach()
	self:Clean()
	self.Maid:Clean()
	self.Hmaid:Clean()
end

---Create new Defender object.
---@return Defender
function Defender.new()
	local Self = setmetatable({}, Defender)
	Self.Tasks = {}
	Self.Rhook = {}
	Self.Tmaid = Maid.new()
	Self.Maid = Maid.new()
	Self.Hmaid = Maid.new()
	Self.Uids = 0
	Self.Markers = {}
	return Self
end

-- Return Defender module.
return Defender
end)
__bundle_register("Defenders/HitboxOptions", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class HitboxOptions
---@field Part BasePart?
---@field Cframe CFrame?
---@field TimingRef Timing|AnimationTiming|SoundTiming
---@field ActionRef Action?
---@field Cache Vector3
---@field Filter Instance[]
---@field Spredict boolean
---@field Ptime number?
---@field Entity Model?
---@field Hmid number?
---@field Visualize boolean
---@field PreferActionHitbox boolean
local HitboxOptions = {}
HitboxOptions.__index = HitboxOptions

-- Services.
local Players = game:GetService("Players")

---Cloned hitbox options.
---@return HitboxOptions
function HitboxOptions:Clone()
	local Options = setmetatable({}, HitboxOptions)
	Options.ActionRef = self.ActionRef
	Options.Spredict = self.Spredict
	Options.Entity = self.Entity
	Options.Ptime = self.Ptime
	Options.Filter = self.Filter
	Options.Part = self.Part
	Options.Cframe = self.Cframe
	Options.TimingRef = self.TimingRef
	Options.Hmid = self.Hmid
	Options.Visualize = self.Visualize
	Options.PreferActionHitbox = self.PreferActionHitbox
	return Options
end

---Update cache.
function HitboxOptions:Ucache()
	if not self.TimingRef then
		return error("HitboxOptions:Ucache - no timing specified")
	end

	local Hitbox = self.ActionRef and self.ActionRef.hitbox or self.TimingRef.hitbox

	if self.TimingRef.duih and not self.PreferActionHitbox then
		Hitbox = self.TimingRef.hitbox
	end

	if self.PreferActionHitbox and (not Hitbox or Hitbox == Vector3.zero) then
		Hitbox = self.TimingRef.hitbox
	end

	if not Hitbox then
		self.Cache = Vector3.new(0, 0, 0)
	else
		self.Cache = Vector3.new(Hitbox.X, Hitbox.Y, Hitbox.Z)
	end
end

---Get the hitbox size.
---@return Vector3
function HitboxOptions:Hitbox()
	if not self.Cache then
		self:Ucache()
	end

	return self.Cache
end

---Get extrapolated position.
---@return CFrame
function HitboxOptions:Extrapolate()
	if not self.Part then
		return error("HitboxOptions.Extrapolate - unimplemented for CFrame")
	end

	if not self.Ptime then
		return error("HitboxOptions.Extrapolate - no predicted time specified")
	end

	return self.Part.CFrame + (self.Part.AssemblyLinearVelocity * self.Ptime)
end

---Get position.
---@return CFrame
function HitboxOptions:Pos()
	if self.Cframe then
		return self.Cframe
	end

	if self.Part then
		if self.Spredict and self.Ptime and self.Ptime ~= 0 then
			return self:Extrapolate()
		end

		return self.Part.CFrame
	end

	return error("HitboxOptions.Pos - impossible condition")
end

---Create new HitboxOptions object.
---@param Target Instance|CFrame
---@param TimingObj Timing|AnimationTiming|SoundTiming
---@param FilterList Instance[]?
---@return HitboxOptions
function HitboxOptions.new(Target, TimingObj, FilterList)
	local Self = setmetatable({}, HitboxOptions)
	Self.Part = typeof(Target) == "Instance" and Target:IsA("BasePart") and Target
	Self.Cframe = typeof(Target) == "CFrame" and Target
	Self.TimingRef = TimingObj
	Self.ActionRef = nil
	Self.Filter = FilterList or {}
	Self.Cache = Vector3.zero
	Self.Spredict = false
	Self.Hmid = nil
	Self.Entity = nil
	Self.Ptime = nil
	Self.Visualize = false
	Self.PreferActionHitbox = false

	if not Self.Part and not Self.Cframe or not Self.TimingRef then
		return error("HitboxOptions: No part or CFrame or timing specified.")
	end

	Self:Ucache()

	if FilterList then
		return Self
	end

	local Character = Players.LocalPlayer.Character
	if not Character then
		return Self
	end

	Self.Filter = { Character }

	return Self
end

-- Return HitboxOptions module.
return HitboxOptions
end)
__bundle_register("Defenders/PartDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Part defender module.

---@module Defenders.Defender
local Defender = require("Defenders/Defender")

---@module Timings.SaveManager
local SaveManager = require("Timings/SaveManager")

---@module Defenders.RepeatInfo
local RepeatInfo = require("Defenders/RepeatInfo")

---@module Defenders.HitboxOptions
local HitboxOptions = require("Defenders/HitboxOptions")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Core.Latency
local Latency = require("Core/Latency")

---@class PartDefender: Defender
---@field Part BasePart
---@field TimingRef PartTiming
---@field Touched boolean Determines whether if we touched the timing in the past.
---@field Vuid number Visualizer UID.
local PartDefender = setmetatable({}, { __index = Defender })
PartDefender.__index = PartDefender
PartDefender.__type = "Part"

-- Services.
local Players = game:GetService("Players")

---Get CFrame.
---@return CFrame
function PartDefender:GetCframe()
	return self.TimingRef.uhc and self.Part.CFrame or CFrame.new(self.Part.Position)
end

---Check if we're in a valid state to proceed with the action.
---@param ActionRef Action?
---@param TimingObj PartTiming
---@return boolean
function PartDefender:Valid(ActionRef, TimingObj)
	if not Defender.Valid(self, ActionRef, TimingObj) then
		return false
	end

	if self:IsLocalPlayerSource(self.Part) then
		return false
	end

	local Character = Players.LocalPlayer.Character
	if not Character then
		return self:Notify(TimingObj, "No character found.")
	end

	local Hoptions = HitboxOptions.new(self.Part, TimingObj)
	Hoptions.Spredict = false
	Hoptions.ActionRef = ActionRef
	Hoptions:Ucache()

	if not TimingObj.duih or TimingObj.umoa then
		if not self:Hc(Hoptions, TimingObj.duih and RepeatInfo.new(TimingObj, Latency.Rdelay(), self.Vuid) or nil) then
			return self:Notify(TimingObj, "Action '%s' is not in hitbox.", ActionRef and ActionRef.name or "N/A")
		end
	end

	return true
end

---Update PartDefender object.
function PartDefender:Update()
	-- Gate on main toggle.
	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return
	end

	-- Skip if we're not handling delay until in hitbox or we want to use modules.
	if not self.TimingRef.duih or self.TimingRef.umoa then
		return
	end

	-- Deny updates if we already have actions in the queue.
	if #self.Tasks > 0 then
		return
	end

	local LocalPlayer = Players.LocalPlayer
	if not LocalPlayer then
		return
	end

	local Character = LocalPlayer.Character
	if not Character then
		return
	end

	if self:IsLocalPlayerSource(self.Part) then
		return
	end

	local Hb = self.TimingRef.hitbox
	Hb = Vector3.new(Hb.X, Hb.Y, Hb.Z)

	-- Get current hitbox state.
	local Touching, Cf = self:HitboxCheck(
		self:GetCframe(),
		self.TimingRef.fhb,
		self.TimingRef.hso,
		Hb,
		{ Character },
		self.TimingRef.htype or Enum.PartType.Block
	)

	if Cf then
		self:Visualize(
			self.Vuid,
			Cf,
			Hb,
			Touching and Color3.fromHex("#DDF527") or Color3.fromHex("#2765F5"),
			self.TimingRef.htype or Enum.PartType.Block
		)
	end

	-- Deny updates if we're not touching the part.
	if not Touching then
		return
	end

	-- Deny updates if we were touching the part last and we are touching it now.
	if self.Touched and Touching then
		return
	end

	-- Ok, set the new state.
	self.Touched = Touching

	-- Clean all previous tasks.
	self:Clean()

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not self.TimingRef.rpue then
		return self:Actions(self.TimingRef)
	end

	-- Start RPUE.
	self.Entity = self.Part
	local Info = RepeatInfo.new(self.TimingRef, Latency.Rdelay(), self:Uid(10))
	self:Srpue(self.Entity, self.TimingRef, Info)
end

---Create new PartDefender object.
---@param PartInstance BasePart
---@param TimingObj PartTiming?
---@return PartDefender?
function PartDefender.new(PartInstance, TimingObj)
	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return nil
	end

	local Self = setmetatable(Defender.new(), PartDefender)

	if Self:IsLocalPlayerSource(PartInstance) then
		return nil
	end

	Self.Part = PartInstance
	Self.TimingRef = TimingObj or Self:Initial(PartInstance, SaveManager.Ps, nil, PartInstance.Name)
	Self.Touched = false
	Self.Vuid = Self:Uid(10)

	-- Handle no timing.
	if not Self.TimingRef then
		return nil
	end

	-- Handle module.
	if Self.TimingRef.umoa then
		Self:Module(Self.TimingRef)
	end

	-- Handle no hitbox delay.
	if Self.TimingRef.umoa or Self.TimingRef.duih then
		return Self
	end

	local Info = RepeatInfo.new(Self.TimingRef, Latency.Rdelay(), Self:Uid(10))

	if Self.TimingRef.rpue then
		Self.Entity = Self.Part
		Self:Srpue(Self.Entity, Self.TimingRef, Info)
	else
		Self:Actions(Self.TimingRef)
	end

	-- Return self.
	return Self
end

-- Return PartDefender module.
return PartDefender
end)
__bundle_register("Defenders/RepeatInfo", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class RepeatInfo
---@field Track AnimationTrack?
---@field TimingRef Timing
---@field Start number
---@field Index number
---@field Irdelay number Initial receive delay.
---@field Hmid number Hitbox visualization ID for repeat hitbox check.
local RepeatInfo = {}
RepeatInfo.__index = RepeatInfo

---Create new RepeatInfo object.
---@param TimingObj Timing
---@param Irdelay number
---@param Hmid number
---@return RepeatInfo
function RepeatInfo.new(TimingObj, Irdelay, Hmid)
	local Self = setmetatable({}, RepeatInfo)
	Self.Track = nil
	Self.TimingRef = TimingObj
	Self.Start = os.clock()
	Self.Index = 0
	Self.Irdelay = Irdelay
	Self.Hmid = Hmid
	return Self
end

-- Return RepeatInfo module.
return RepeatInfo
end)
__bundle_register("Defenders/SoundDefender", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Sound defender module.

---@module Defenders.Defender
local Defender = require("Defenders/Defender")

---@module Timings.SaveManager
local SaveManager = require("Timings/SaveManager")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Defenders.RepeatInfo
local RepeatInfo = require("Defenders/RepeatInfo")

---@module Defenders.HitboxOptions
local HitboxOptions = require("Defenders/HitboxOptions")

---@module Core.Latency
local Latency = require("Core/Latency")

---@class SoundDefender: Defender
---@field Owner Model? The owner of the sound.
---@field Sound Sound The sound that we're defending.
---@field Part BasePart A part that we can base the position off of.
local SoundDefender = setmetatable({}, { __index = Defender })
SoundDefender.__index = SoundDefender
SoundDefender.__type = "Sound"

-- Services.
local Players = game:GetService("Players")

---Find owning model for a sound.
---@param SoundInstance Sound
---@return Model?
local function FindOwnerModel(SoundInstance)
	local Current = SoundInstance.Parent

	while Current do
		if Current:IsA("Model") and Current:FindFirstChild("HumanoidRootPart") then
			return Current
		end

		Current = Current.Parent
	end
end

---Check if we're in a valid state to proceed with the action.
---@param ActionRef Action?
---@param TimingObj SoundTiming
---@return boolean
function SoundDefender:Valid(ActionRef, TimingObj)
	if not Defender.Valid(self, ActionRef, TimingObj) then
		return false
	end

	if self.Owner and not self:Target(self.Owner) then
		if not TimingObj.alp or not Players.LocalPlayer.Character or self.Owner ~= Players.LocalPlayer.Character then
			return self:Notify(TimingObj, "Not a viable target.")
		end
	end

	local Character = Players.LocalPlayer.Character
	if not Character then
		return self:Notify(TimingObj, "No character found.")
	end

	local Hoptions = HitboxOptions.new(self.Part, TimingObj)
	Hoptions.Spredict = false
	Hoptions.ActionRef = ActionRef
	Hoptions:Ucache()

	if not self:Hc(Hoptions, TimingObj.duih and RepeatInfo.new(TimingObj, Latency.Rdelay(), self:Uid(10)) or nil) then
		return self:Notify(TimingObj, "Action '%s' is not in hitbox.", ActionRef and ActionRef.name or "N/A")
	end

	return true
end

---Repeat conditional.
---@param Info RepeatInfo
---@return boolean
function SoundDefender:Rc(Info)
	if not self.Sound.IsPlaying then
		return false
	end

	return true
end

---Process sound playing.
function SoundDefender:Process()
	---@type SoundTiming?
	local TimingObj = self:Initial(
		self.Owner or self.Part,
		SaveManager.Ss,
		self.Owner and self.Owner.Name or self.Part.Name,
		tostring(self.Sound.SoundId)
	)

	if not TimingObj then
		return
	end

	if not Configuration.ExpectToggleValue("EP_EnableAutoDefense") then
		return
	end

	if not TimingObj.alp and (Players.LocalPlayer.Character and self.Owner == Players.LocalPlayer.Character) then
		return
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:Clean()

	-- Use module if we need to.
	if TimingObj.umoa then
		return self:Module(TimingObj)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not TimingObj.rpue then
		return self:Actions(TimingObj)
	end

	-- Start RPUE.
	self.Entity = self.Owner or self.Part
	local Info = RepeatInfo.new(TimingObj, Latency.Rdelay(), self:Uid(10))
	self:Srpue(self.Entity, TimingObj, Info)
end

---Create new SoundDefender object.
---@param SoundInstance Sound
---@param PartInstance BasePart
---@return SoundDefender
function SoundDefender.new(SoundInstance, PartInstance)
	local Self = setmetatable(Defender.new(), SoundDefender)
	local SoundPlayed = Signal.new(SoundInstance.Played)

	Self.Sound = SoundInstance
	Self.Part = PartInstance
	Self.Owner = FindOwnerModel(SoundInstance)

	Self.Maid:Mark(SoundPlayed:Connect(
		"SoundDefender_OnSoundPlayed",
		function()
			Self:Process()
		end
	))

	if SoundInstance.Playing then
		Self:Process()
	end

	return Self
end

-- Return SoundDefender module.
return SoundDefender
end)
__bundle_register("Defenders/Task", function(require, _LOADED, __bundle_register, __bundle_modules)
local TaskSpawner = require("Utility/TaskSpawner")
local Configuration = require("Utility/Configuration")

---@class Task
---@field Thread thread
---@field Identifier string
---@field _when number A timestamp when the task will be executed.
---@field Punishable number A window in seconds where the task can be punished.
---@field After number A window in seconds where the task can be executed.
---@field DelayFn function
local Task = {}
Task.__index = Task

---Check if task should block the input.
---@return boolean
function Task:Blocking()
	if not (coroutine.status(self.Thread) ~= "dead") then
		return false
	end

	-- We've exceeded the execution time. Block if we're within the after window.
	if os.clock() >= self:When() then
		return os.clock() <= self:When() + self.After
	end

	---@note: Allow us to do inputs up until a certain amount of time before the task happens.
	return os.clock() >= self:When() - self.Punishable
end

---Cancel task.
function Task:Cancel()
	if coroutine.status(self.Thread) ~= "suspended" then
		return
	end

	task.cancel(self.Thread)
end

---Get when approximately the task will be executed.
---@return number
function Task:When()
	return self._Created + self.DelayFn()
end

---Create new Task object.
---@param Identifier string
---@param DelayFn function
---@param Punishable number
---@param After number
---@param Callback function
---@vararg any
---@return Task
function Task.new(Identifier, DelayFn, Punishable, After, Callback, ...)
	local Self = setmetatable({}, Task)
	Self.Identifier = Identifier
	Self.DelayFn = DelayFn
	Self.Punishable = Punishable
	Self.After = After
	Self._Created = os.clock()
	Self.Thread = TaskSpawner.Delay("Action_" .. Identifier, DelayFn, Callback, ...)
	Self.Forced = false

	if not Self.Punishable or Self.Punishable <= 0 then
		Self.Punishable = Configuration.ExpectOptionValue("EP_DefaultPunishableWindow") or 0.7
	end

	if not Self.After or Self.After <= 0 then
		Self.After = Configuration.ExpectOptionValue("EP_DefaultAfterWindow") or 0.1
	end

	return Self
end

-- Return Task module.
return Task
end)
