    Library.Unload = function(self)
        -- Kill simulation guard so hitbox loop dies.
        getgenv().__EP_SimulationSession = nil

        -- Unload embedded scripts via their module Unload() functions.
        local function UnloadScriptModules(ScriptModules)
            if type(ScriptModules) ~= "table" then return end

            for Index, Module in next, ScriptModules do
                pcall(function()
                    if Module and Module.Unload then Module.Unload() end
                end)
                ScriptModules[Index] = nil
            end
        end

        local function CleanupMCPBridgeTables()
            if not getgc then return end

            for Index, Candidate in next, getgc(true) do
                if type(Candidate) ~= "table" then continue end

                local Callbacks = rawget(Candidate, "Callbacks")
                if type(Callbacks) ~= "table" then continue end
                if not rawget(Callbacks, "execute") or not rawget(Callbacks, "get-data-by-code") then continue end
                if rawget(Candidate, "EpiphyllumOwned") ~= true then continue end

                local Destroy = rawget(Candidate, "Destroy")
                if Destroy then
                    pcall(Destroy, Candidate)
                else
                    rawset(Candidate, "Connected", false)

                    local AliveThread = rawget(Candidate, "AliveThread")
                    if AliveThread then
                        pcall(task.cancel, AliveThread)
                    end

                    local PollThread = rawget(Candidate, "PollThread")
                    if PollThread then
                        pcall(task.cancel, PollThread)
                    end

                    local Connections = rawget(Candidate, "Connections")
                    if type(Connections) == "table" then
                        for ConnectionIndex, Connection in next, Connections do
                            pcall(function()
                                Connection:Disconnect()
                            end)
                            Connections[ConnectionIndex] = nil
                        end
                    end

                    local WebSocket = rawget(Candidate, "WebSocket")
                    if WebSocket then
                        pcall(function()
                            WebSocket:Close()
                        end)
                    end
                end
            end
        end

        UnloadScriptModules(self._ScriptModules)
        UnloadScriptModules(getgenv().__EpiphyllumScriptModules)
        self._ScriptModules = nil
        getgenv().__EpiphyllumScriptModules = nil

        pcall(function()
            local Shutdown = getgenv().__EpiphyllumMCPConnectorShutdown
            if Shutdown then Shutdown() end
        end)
        getgenv().__EpiphyllumMCPConnectorShutdown = nil
        pcall(CleanupMCPBridgeTables)

        pcall(function()
            local Cobalt = getgenv().Cobalt
            if Cobalt and Cobalt.shared and Cobalt.shared.Unload then
                Cobalt.shared.Unload()
            end
        end)
        getgenv().Cobalt = nil
        getgenv().CobaltInitialized = nil
        getgenv().CobaltAutoExecuted = nil
        getgenv().IY_LOADED = nil
        getgenv().VexExecutedCheck = false

        -- Disconnect all connections.
        for Index, Value in next, self.Connections do
            pcall(function() Value.Connection:Disconnect() end)
        end

        for Index, Value in next, self.Threads do
            pcall(coroutine.close, Value)
        end

        -- Destroy all GUI holders.
        pcall(function() if self.Holder then self.Holder:Clean() end end)
        pcall(function() if self.OverlayHolder then self.OverlayHolder:Clean() end end)

        -- Destroy glass parts in camera.
        pcall(function()
            for Index, Child in next, workspace.CurrentCamera:GetChildren() do
                if Child:IsA("Part") and Child.Material == Enum.Material.Glass then
                    Child:Destroy()
                end
            end
        end)

        -- Destroy DOF and blur in lighting.
        pcall(function()
            for Index, Child in next, game:GetService("Lighting"):GetChildren() do
                if Child:IsA("DepthOfFieldEffect") or (Child:IsA("BlurEffect") and Child.Name:find("__EP_")) then
                    Child:Destroy()
                end
            end
        end)

        -- Destroy hitbox simulation parts.
        pcall(function()
            for Index, Child in next, workspace:GetChildren() do
                if Child:IsA("Part") and Child.Name == "__EP_HitboxSim" then
                    Child:Destroy()
                end
            end
        end)

        -- Destroy info logger.
        pcall(function()
            local CoreGuiRef = game:GetService("CoreGui")
            local Prev = CoreGuiRef:FindFirstChild("__EP_InfoLogger")
            if Prev then Prev:Destroy() end
        end)
        pcall(function()
            local Prev = game.Players.LocalPlayer.PlayerGui:FindFirstChild("__EP_InfoLogger")
            if Prev then Prev:Destroy() end
        end)

        -- Stop music.
        pcall(function()
            for Index, SoundObj in next, game:GetService("SoundService"):GetChildren() do
                if SoundObj:IsA("Sound") and SoundObj.Name == "__epiphyllum_bgm_0xCAFE" then
                    SoundObj:Stop()
                    SoundObj:Destroy()
                end
            end
        end)

        -- Destroy animation visualizer.
        pcall(function()
            local CoreGuiRef = game:GetService("CoreGui")
            for Index, Child in next, CoreGuiRef:GetChildren() do
                if Child:IsA("ScreenGui") and Child.Name == "AnimationVisualizer" then
                    Child:Destroy()
                end
            end
        end)

        self.InfoLogger = nil
        Library = nil
        getgenv().Library = nil
        getgenv()._EpiphyllumLib = nil
    end

