                    Name = "\0",
                    Visible = false,
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(1, 0),
                    BackgroundTransparency = 0.15,
                    Position = UDim2New(0, 0, 0, 0),
                    Size = UDim2New(0, 225, 1, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["LeftTabs"]:AddToTheme({BackgroundColor3 = "Background"})

                Library:MakeBlurred(Items["LeftTabs"], Window)

                -- Content sub-frame inside LeftTabs (holds UIListLayout so profile can be outside it).
                Items["LeftContent"] = Instances:Create("Frame", {
                    Parent = Items["LeftTabs"].Instance,
                    Name = "\0",
                    BackgroundTransparency = 1,
                    Size = UDim2New(1, 0, 1, -65),
                    Position = UDim2New(0, 0, 0, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    ClipsDescendants = true,
                })

                Items["RightTabs"] = Instances:Create("Frame", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    Visible = false,
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0, 0),
                    BackgroundTransparency = 0.15,
                    Position = UDim2New(1, 0, 0, 0),
                    Size = UDim2New(0, 225, 1, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["RightTabs"]:AddToTheme({BackgroundColor3 = "Background"})
                Instances:Create("UICorner", { Parent = Items["RightTabs"].Instance, Name = "\0", CornerRadius = UDimNew(0, 6) })
                Library:MakeBlurred(Items["RightTabs"], Window)

                -- Content sub-frame inside RightTabs.
                Items["RightContent"] = Instances:Create("Frame", {
                    Parent = Items["RightTabs"].Instance,
                    Name = "\0",
                    BackgroundTransparency = 1,
                    Size = UDim2New(1, 0, 1, -65),
                    Position = UDim2New(0, 0, 0, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    ClipsDescendants = true,
                })

                Items["TopTabs"] = Instances:Create("Frame", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    Visible = false,
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0, 1),
                    BackgroundTransparency = 0.15,
                    Position = UDim2New(0, 0, 0, 0),
                    Size = UDim2New(1, 0, 0, 80),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["TopTabs"]:AddToTheme({BackgroundColor3 = "Background"})
                Instances:Create("UICorner", { Parent = Items["TopTabs"].Instance, Name = "\0", CornerRadius = UDimNew(0, 6) })
                Library:MakeBlurred(Items["TopTabs"], Window)

                Items["BottomTabs"] = Instances:Create("Frame", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    Visible = true,
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0, 0),
                    BackgroundTransparency = 0.15,
                    Position = UDim2New(0, 0, 1, 0),
                    Size = UDim2New(1, 0, 0, 90),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["BottomTabs"]:AddToTheme({BackgroundColor3 = "Background"})
                Instances:Create("UICorner", { Parent = Items["BottomTabs"].Instance, Name = "\0", CornerRadius = UDimNew(0, 6) })
                Library:MakeBlurred(Items["BottomTabs"], Window)

                local Gui = Items["MainFrame"].Instance
                local TabDockDragging = false

                local Dragging = false
                local MfDragOffset
                local DragInputChanged
                local MfGuiInsetY = game:GetService("GuiService"):GetGuiInset().Y

                local Set = function(Input)
                    local NewX = Mouse.X - MfDragOffset.X
                    local NewY = Mouse.Y - MfDragOffset.Y

                    local ScreenSize = Gui.Parent.AbsoluteSize
                    local GuiSize = Gui.AbsoluteSize

                    -- Calculate actual visual bounds including overflow children (tabs, profile, sidebars).
                    local LeftExt, RightExt, TopExt, BottomExt = 0, 0, 0, 0
                    for Index, Child in next, Gui:GetChildren() do
                        if Child:IsA("GuiObject") and Child.Visible then
                            local RelX = Child.AbsolutePosition.X - Gui.AbsolutePosition.X
                            local RelY = Child.AbsolutePosition.Y - Gui.AbsolutePosition.Y
                            local ChildRight = RelX + Child.AbsoluteSize.X - GuiSize.X
                            local ChildBottom = RelY + Child.AbsoluteSize.Y - GuiSize.Y
                            local ChildLeft = -RelX
                            local ChildTop = -RelY
                            if ChildRight > RightExt then RightExt = ChildRight end
                            if ChildBottom > BottomExt then BottomExt = ChildBottom end
                            if ChildLeft > LeftExt then LeftExt = ChildLeft end
                            if ChildTop > TopExt then TopExt = ChildTop end
                        end
                    end

                    NewX = MathClamp(NewX, LeftExt, ScreenSize.X - GuiSize.X - RightExt)
                    NewY = MathClamp(NewY, TopExt - MfGuiInsetY, ScreenSize.Y - GuiSize.Y - BottomExt - MfGuiInsetY)

                    local Anchor = Gui.AnchorPoint
                    Items["MainFrame"]:Tween(TweenInfo.new(0.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2New(0, NewX + Anchor.X * GuiSize.X, 0, NewY + MfGuiInsetY + Anchor.Y * GuiSize.Y)})
                end

                local function StartDrag(Input)
                    if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then return end
                    -- Defer so overlapping draggable handlers fire first and claim DragLock.
                    task.defer(function()
                        if TabDockDragging or Library.DragLock then return end
                        Dragging = true
                        MfDragOffset = Vector2New(Mouse.X - Gui.AbsolutePosition.X, Mouse.Y - Gui.AbsolutePosition.Y)

                        if DragInputChanged then return end
                        DragInputChanged = Input.Changed:Connect(function()
                            if Input.UserInputState == Enum.UserInputState.End then
                                Dragging = false
                                DragInputChanged:Disconnect()
                                DragInputChanged = nil
                            end
                        end)
                    end)
                end

                Items["MainFrame"]:Connect("InputBegan", StartDrag)

                Library:Connect(UserInputService.InputChanged, function(Input)
                    if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
                        if Dragging then
                            Set(Input)
                        end
                    end
                end)

