                local function ClearSearchResults()
                    for Index, Child in next, Items["SearchResultHolder"].Instance:GetChildren() do
                        if Child:IsA("GuiObject") then
                            Child:Destroy()
                        end
                    end
                end

                local function SetSearchResultsVisible(Visible, Height)
                    if Visible then
                        Items["SearchResultBox"].Instance.Visible = true
                    end

                    Items["SearchResultBox"]:Tween(TweenInfo.new(0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        Size = UDim2New(0, SearchOpenWidth, 0, Visible and Height or 0),
                        BackgroundTransparency = Visible and 0.02 or 1,
                    })

                    if not Visible then
                        task.delay(0.18, function()
                            if not SearchOpen then
                                Items["SearchResultBox"].Instance.Visible = false
                            end
                        end)
                    end
                end

                local function MakeSearchResult(Entry, Index)
                    local Button = Instances:Create("TextButton", {
                        Parent = Items["SearchResultHolder"].Instance,
                        Name = "\0",
                        AutoButtonColor = false,
                        BackgroundColor3 = FromRGB(0, 0, 0),
                        BackgroundTransparency = 1,
                        BorderColor3 = FromRGB(0, 0, 0),
                        BorderSizePixel = 0,
                        FontFace = Library.Font,
                        LayoutOrder = Index,
                        Size = UDim2New(1, 0, 0, SearchResultHeight),
                        Text = "",
                        TextColor3 = FromRGB(240, 240, 240),
                        TextSize = 14,
                        ZIndex = 42,
                    })

                    Instances:Create("UICorner", {
                        Parent = Button.Instance,
                        Name = "\0",
                        CornerRadius = UDimNew(0, 5),
                    })

                    local LabelClip = Instances:Create("Frame", {
                        Parent = Button.Instance,
                        Name = "\0",
                        BackgroundTransparency = 1,
                        BorderColor3 = FromRGB(0, 0, 0),
                        BorderSizePixel = 0,
                        ClipsDescendants = true,
                        Position = UDim2New(0, 9, 0, 0),
                        Size = UDim2New(1, -18, 1, 0),
                        ZIndex = 43,
                    })

                    local Label = Instances:Create("TextLabel", {
                        Parent = LabelClip.Instance,
                        Name = "\0",
                        AnchorPoint = Vector2New(0, 0.5),
                        AutomaticSize = Enum.AutomaticSize.X,
                        BackgroundTransparency = 1,
                        BorderColor3 = FromRGB(0, 0, 0),
                        BorderSizePixel = 0,
                        FontFace = Library.Font,
                        Position = UDim2New(0, 0, 0.5, 0),
                        Size = UDim2New(0, 0, 0, 15),
                        Text = Entry.Path or Entry.Name,
                        TextColor3 = FromRGB(240, 240, 240),
                        TextSize = 13,
                        TextTransparency = 0.05,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        ZIndex = 43,
                    })  Label:AddToTheme({TextColor3 = "Text"})

                    Library:MakeMarquee(LabelClip.Instance, Label.Instance, function()
                        return SearchOpen
                    end)

                    Button:OnHover(function()
                        Button:Tween(TweenInfo.new(0.14, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            BackgroundColor3 = Library.Theme.Accent,
                            BackgroundTransparency = 0,
                        })
                        Label:Tween(TweenInfo.new(0.14, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            TextColor3 = FromRGB(0, 0, 0),
                        })
                    end)

                    Button:OnHoverLeave(function()
                        Button:Tween(TweenInfo.new(0.14, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            BackgroundColor3 = FromRGB(0, 0, 0),
                            BackgroundTransparency = 1,
                        })
                        Label:Tween(TweenInfo.new(0.14, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            TextColor3 = Library.Theme.Text,
                        })
                    end)

                    Button:Connect("MouseButton1Down", function()
                        ActivateSearchResult(Entry)
                    end)
                end

                local function UpdateSearchResults()
                    if not SearchOpen then
                        return
                    end

                    local Query = Items["SearchInput"].Instance.Text
                    ClearSearchResults()
                    SearchResults = Library:CollectSearchEntries(Window, Query)

                    if Query == "" then
                        SetSearchResultsVisible(false, 0)
                        return
                    end

                    if #SearchResults == 0 then
                        local Empty = Instances:Create("TextLabel", {
                            Parent = Items["SearchResultHolder"].Instance,
                            Name = "\0",
                            BackgroundTransparency = 1,
                            BorderColor3 = FromRGB(0, 0, 0),
                            BorderSizePixel = 0,
                            FontFace = Library.Font,
                            LayoutOrder = 1,
                            Size = UDim2New(1, 0, 0, SearchResultHeight),
                            Text = "No results",
                            TextColor3 = FromRGB(185, 185, 185),
                            TextSize = 13,
                            TextTransparency = 0.25,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            ZIndex = 42,
                        })

                        Instances:Create("UIPadding", {
                            Parent = Empty.Instance,
                            Name = "\0",
                            PaddingLeft = UDimNew(0, 9),
                        })

                        SetSearchResultsVisible(true, 44)
                        return
                    end

                    local VisibleCount = math.min(#SearchResults, SearchResultLimit)
                    for Index = 1, VisibleCount do
                        MakeSearchResult(SearchResults[Index], Index)
                    end

                    SetSearchResultsVisible(true, 16 + (VisibleCount * SearchResultHeight) + ((VisibleCount - 1) * 4))
                end

                function SetSearchOpen(Bool)
                    SearchOpen = Bool

                    if Bool then
                        Items["SearchIconAccent"]:Tween(TweenInfo.new(0.15, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            Size = UDim2New(0, 0, 0, 0),
                            BackgroundTransparency = 1,
                        })
                        Items["SearchIcon"]:Tween(TweenInfo.new(0.15, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            ImageColor3 = Library.Theme.Text,
                        })
                        Items["SearchInput"].Instance.Visible = true
                        Items["SearchInput"]:Tween(TweenInfo.new(0.15, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            TextTransparency = 0,
                        })
                        Items["SearchButton"]:Tween(TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            Size = UDim2New(0, SearchOpenWidth, 0, 32),
                        })
                        task.defer(function()
                            Items["SearchInput"].Instance:CaptureFocus()
                        end)
                        UpdateSearchResults()
                    else
                        Items["SearchInput"].Instance:ReleaseFocus()
                        Items["SearchInput"].Instance.Text = ""
                        SearchResults = {}
                        ClearSearchResults()
                        Items["SearchInput"]:Tween(TweenInfo.new(0.12, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            TextTransparency = 1,
                        })
                        Items["SearchButton"]:Tween(TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                            Size = UDim2New(0, SearchClosedWidth, 0, 32),
                        })
                        SetSearchResultsVisible(false, 0)
                        task.delay(0.12, function()
                            if not SearchOpen then
                                Items["SearchInput"].Instance.Visible = false
                            end
                        end)
                    end
                end

                Items["SearchButton"]:OnHover(function()
                    if SearchOpen then
                        return
                    end

                    Items["SearchIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(1, 0, 1, 0),
                        BackgroundTransparency = 0,
                    })
                    Items["SearchIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = FromRGB(0, 0, 0),
                    })
                end)

                Items["SearchButton"]:OnHoverLeave(function()
                    Items["SearchIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(0, 0, 0, 0),
                        BackgroundTransparency = 1,
                    })
                    Items["SearchIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = Library.Theme.Text,
                    })
                end)

                Items["SearchButton"]:Connect("MouseButton1Down", function()
                    if not SearchOpen then
                        SetSearchOpen(true)
                    else
                        Items["SearchInput"].Instance:CaptureFocus()
                    end
                end)

                Library:Connect(Items["SearchInput"].Instance:GetPropertyChangedSignal("Text"), UpdateSearchResults)

                Items["SearchInput"]:Connect("FocusLost", function(EnterPressed)
                    if EnterPressed and SearchResults[1] then
                        ActivateSearchResult(SearchResults[1])
                        return
                    end

                    task.delay(0.12, function()
                        if not SearchOpen then
                            return
                        end

                        if Library:IsMouseOverFrame(Items["SearchButton"]) then
                            return
                        end

                        if Items["SearchResultBox"].Instance.Visible and Library:IsMouseOverFrame(Items["SearchResultBox"]) then
                            return
                        end

                        SetSearchOpen(false)
                    end)
                end)

                Library:Connect(UserInputService.InputBegan, function(Input)
                    if not SearchOpen then
                        return
                    end

                    if Input.KeyCode == Enum.KeyCode.Escape then
                        SetSearchOpen(false)
                        return
                    end

                    if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                        if Library:IsMouseOverFrame(Items["SearchButton"]) then
                            return
                        end

                        if Items["SearchResultBox"].Instance.Visible and Library:IsMouseOverFrame(Items["SearchResultBox"]) then
                            return
                        end

                        SetSearchOpen(false)
                    end
                end)

                -- Minimize button.
                Items["MinimizeButton"] = Instances:Create("TextButton", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    FontFace = Library.Font,
                    TextColor3 = FromRGB(0, 0, 0),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Text = "",
                    AutoButtonColor = false,
                    AnchorPoint = Vector2New(1, 0),
                    BorderSizePixel = 0,
                    BackgroundTransparency = 0.2,
                    Position = UDim2New(1, -52, 0, 11),
                    Size = UDim2New(0, 32, 0, 32),
                    ZIndex = 2,
                    TextSize = 14,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["MinimizeButton"]:AddToTheme({BackgroundColor3 = "Element"})

                Instances:Create("UICorner", {
                    Parent = Items["MinimizeButton"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 7)
                })

                Items["MinimizeIcon"] = Instances:Create("ImageLabel", {
                    Parent = Items["MinimizeButton"].Instance,
                    Name = "\0",
                    Image = Library.Icons["minimize"] or "",
                    ImageColor3 = FromRGB(240, 240, 240),
                    ImageTransparency = 0.15,
                    BackgroundTransparency = 1,
                    Size = UDim2New(0, 14, 0, 14),
                    AnchorPoint = Vector2New(0.5, 0.5),
                    Position = UDim2New(0.5, 0, 0.5, 0),
                    ZIndex = 3,
                    BorderSizePixel = 0,
                    ScaleType = Enum.ScaleType.Fit,
                })  Items["MinimizeIcon"]:AddToTheme({ImageColor3 = "Text"})

                Items["MinimizeIconAccent"] = Instances:Create("Frame", {
                    Parent = Items["MinimizeButton"].Instance,
                    Name = "\0",
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0.5, 0.5),
                    BorderSizePixel = 0,
                    Position = UDim2New(0.5, 0, 0.5, 0),
                    Size = UDim2New(0, 0, 0, 0),
                    ZIndex = 2,
                    BackgroundTransparency = 1,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })

                Instances:Create("UICorner", {
                    Parent = Items["MinimizeIconAccent"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 7)
                })

                Instances:Create("UIGradient", {
                    Parent = Items["MinimizeIconAccent"].Instance,
                    Name = "\0",
                    Color = RGBSequence{RGBSequenceKeypoint(0, FromRGB(255, 255, 255)), RGBSequenceKeypoint(1, FromRGB(143, 143, 143))},
                    Rotation = -115
                }):AddToTheme({Color = function()
                    return RGBSequence{RGBSequenceKeypoint(0, Library.Theme.Accent), RGBSequenceKeypoint(1, Library.Theme.AccentGradient)}
                end})

                Items["MinimizeButton"]:OnHover(function()
                    Items["MinimizeIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(1, 0, 1, 0),
                        BackgroundTransparency = 0
                    })
                    Items["MinimizeIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = FromRGB(0, 0, 0)
                    })
                end)

                Items["MinimizeButton"]:OnHoverLeave(function()
                    Items["MinimizeIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(0, 0, 0, 0),
                        BackgroundTransparency = 1
                    })
                    Items["MinimizeIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = Library.Theme.Text
                    })
                end)

                Items["MinimizeButton"]:Connect("MouseButton1Down", function()
                    if Window.SetOpen then
                        Window:SetOpen(false)
                    end
                end)

                -- Close button.
                Items["CloseButton"] = Instances:Create("TextButton", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    FontFace = Library.Font,
                    TextColor3 = FromRGB(0, 0, 0),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Text = "",
                    AutoButtonColor = false,
                    AnchorPoint = Vector2New(1, 0),
                    BorderSizePixel = 0,
                    BackgroundTransparency = 0.2,
                    Position = UDim2New(1, -14, 0, 11),
                    Size = UDim2New(0, 32, 0, 32),
                    ZIndex = 2,
                    TextSize = 14,
                    BackgroundColor3 = FromRGB(27, 25, 29)
                })  Items["CloseButton"]:AddToTheme({BackgroundColor3 = "Element"})

                Instances:Create("UICorner", {
                    Parent = Items["CloseButton"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 7)
                })

                Items["CloseIcon"] = Instances:Create("ImageLabel", {
                    Parent = Items["CloseButton"].Instance,
                    Name = "\0",
                    Image = Library.Icons["x"] or "",
                    ImageColor3 = FromRGB(240, 240, 240),
                    ImageTransparency = 0.15,
                    BackgroundTransparency = 1,
                    Size = UDim2New(0, 14, 0, 14),
                    AnchorPoint = Vector2New(0.5, 0.5),
                    Position = UDim2New(0.5, 0, 0.5, 0),
                    ZIndex = 3,
                    BorderSizePixel = 0,
                    ScaleType = Enum.ScaleType.Fit,
                })  Items["CloseIcon"]:AddToTheme({ImageColor3 = "Text"})

                Items["CloseButton"]:Connect("MouseButton1Down", function()
                    Library:Unload()
                end)

                Items["CloseIconAccent"] = Instances:Create("Frame", {
                    Parent = Items["CloseButton"].Instance,
                    Name = "\0",
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0.5, 0.5),
                    BorderSizePixel = 0,
                    Position = UDim2New(0.5, 0, 0.5, 0),
                    Size = UDim2New(0, 0, 0, 0),
                    ZIndex = 2,
                    BackgroundTransparency = 1,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })

                Instances:Create("UICorner", {
                    Parent = Items["CloseIconAccent"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 7)
                })

                Instances:Create("UICorner", {
                    Parent = Items["MainFrame"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 4)
                })

                Instances:Create("UICorner", {
                    Parent = Items["LeftTabs"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 4)
                })


                function Window:SetTransparency()
                    Items["MainFrame"].Instance.BackgroundTransparency = Library.Flags["BackgroundTransparency"]
                    Items["LeftTabs"].Instance.BackgroundTransparency = Library.Flags["BackgroundTransparency"]
                    if IsMobile then
                        Items["FloatingButton"].Instance.BackgroundTransparency = Library.Flags["BackgroundTransparency"]
                    end

                    for Index, Value in next, Items do
                        if Index:find("___") then
                            Value.Instance.BackgroundTransparency = tonumber(Library.Flags["BackgroundTransparency"])
                        end
                    end
                end

                Instances:Create("UIGradient", {
                    Parent = Items["CloseIconAccent"].Instance,
                    Name = "\0",
                    Color = RGBSequence{RGBSequenceKeypoint(0, FromRGB(255, 255, 255)), RGBSequenceKeypoint(1, FromRGB(143, 143, 143))},
                    Rotation = -115
                }):AddToTheme({Color = function()
                    return RGBSequence{RGBSequenceKeypoint(0, Library.Theme.Accent), RGBSequenceKeypoint(1, Library.Theme.AccentGradient)}
                end})

                Items["CloseButton"]:OnHover(function()
                    Items["CloseIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(1, 0, 1, 0),
                        BackgroundTransparency = 0
                    })
                    Items["CloseIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = FromRGB(0, 0, 0)
                    })
                end)

                Items["CloseButton"]:OnHoverLeave(function()
                    Items["CloseIconAccent"]:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        Size = UDim2New(0, 0, 0, 0),
                        BackgroundTransparency = 1
                    })
                    Items["CloseIcon"]:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                        ImageColor3 = Library.Theme.Text
                    })
                end)

                Window.Items = Items
            end

            local Debounce = false

            function Window:SetCenter()
                local CenterPosition = Items["MainFrame"].Instance.AbsolutePosition
                task.wait()
                Items["MainFrame"].Instance.AnchorPoint = Vector2New(0, 0)

                Items["MainFrame"].Instance.Position = UDim2New(0, CenterPosition.X, 0, CenterPosition.Y)
            end

            Window._onStateChanged = {}

            function Window:OnStateChanged(Fn)
                Window._onStateChanged[#Window._onStateChanged + 1] = Fn
            end

            local WindowDebounce = false

            function Window:SetOpen(Bool)
                if Bool and IsLaunchMenuLocked() then
                    Window.IsOpen = false
                    Items["MainFrame"].Instance.Visible = false
                    return false
                end

                if WindowDebounce then
                    if not Bool then
                        task.delay(Library.FadeSpeed + 0.05, function()
                            if Window.IsOpen then
                                Window:SetOpen(false)
                            else
                                Items["MainFrame"].Instance.Visible = false
                            end
                        end)
                    end

                    return
                end


                if Window.IsOpen == Bool then
                    if not Bool then
                        Items["MainFrame"].Instance.Visible = false
                    end

                    return
                end

                Window.IsOpen = Bool
                WindowDebounce = true

                -- Close any open dropdowns/frames before fading.
                if not Window.IsOpen then
                    for Index, Frame in next, Library.OpenFrames do
                        pcall(Frame.SetOpen, Frame, false)
                    end
                end

                -- Notify listeners.
                for Index, Fn in next, Window._onStateChanged do
                    pcall(Fn, Bool)
                end

                if Window.IsOpen then
                    Items["MainFrame"].Instance.Visible = true
                end

                local Descendants = Items["MainFrame"].Instance:GetDescendants()
                TableInsert(Descendants, Items["MainFrame"].Instance)

                local NewTween
                local OriginalTransparencies = {}

                for Index, Value in next, Descendants do
                    local TransparencyProperty = Tween:GetProperty(Value)

                    if TransparencyProperty then
                        if type(TransparencyProperty) == "table" then
                            for Index, Property in next, TransparencyProperty do
                                if not OriginalTransparencies[Value] then OriginalTransparencies[Value] = {} end
                                OriginalTransparencies[Value][Property] = Value[Property]
                                NewTween = Tween:FadeItem(Value, Property, Bool, Library.FadeSpeed)
                            end
                        else
                            OriginalTransparencies[Value] = { [TransparencyProperty] = Value[TransparencyProperty] }
                            NewTween = Tween:FadeItem(Value, TransparencyProperty, Bool, Library.FadeSpeed)
                        end
                    end
                end

                ---Finish fade state.
                local function FinishFade()
                    WindowDebounce = false
                    Items["MainFrame"].Instance.Visible = Window.IsOpen

                    -- Restore original transparencies while hidden so next open works.
                    if not Window.IsOpen then
                        for Item, Properties in next, OriginalTransparencies do
                            for Property, Value in next, Properties do
                                Item[Property] = Value
                            end
                        end
                    end
                end

                if NewTween then
                    Library:Connect(NewTween.Tween.Completed, FinishFade)
                else
                    FinishFade()
                end
            end

            if IsMobile then
                Items["FloatingButton"]:Connect("InputBegan", function(Input)
                    if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                        Window:SetOpen(not Window.IsOpen)
                    end
                end)
            end

            function Window:GetContentParent(Alignment)
                if Alignment == "LeftTabs" then return Items["LeftContent"]
                elseif Alignment == "RightTabs" then return Items["RightContent"]
                else return Items[Alignment]
                end
            end

            function Window:GetClosestFrame(Position)
                -- Edge-based detection: find which edge of MainFrame the mouse is closest to.
                local Mf = Items["MainFrame"].Instance
                local MfPos = Mf.AbsolutePosition
                local MfSize = Mf.AbsoluteSize

                local DistLeft = Position.X - MfPos.X
                local DistRight = (MfPos.X + MfSize.X) - Position.X
                local DistTop = Position.Y - MfPos.Y
                local DistBottom = (MfPos.Y + MfSize.Y) - Position.Y

                local MinDist = math.min(DistLeft, DistRight, DistTop, DistBottom)

                if MinDist == DistLeft then return "LeftTabs"
                elseif MinDist == DistRight then return "RightTabs"
                elseif MinDist == DistTop then return "TopTabs"
                else return "BottomTabs" end
            end

            function Window:UpdateTabs(NewAlignment)
                local TargetFrame = Items[NewAlignment]
                if not TargetFrame then return end
                local ContentParent = self:GetContentParent(NewAlignment)

                local IsHorizontal = NewAlignment == "TopTabs" or NewAlignment == "BottomTabs"

                local IsRight = NewAlignment == "RightTabs"

                -- Hide category labels for top/bottom, show for left/right.
                local SearchFrame = IsHorizontal and TargetFrame or ContentParent
                for Index, Child in next, SearchFrame.Instance:GetChildren() do
                    if Child:IsA("TextLabel") then
                        Child.Visible = not IsHorizontal
                        if not IsHorizontal then
                            Child.TextXAlignment = Enum.TextXAlignment.Left
                            Child.Size = UDim2New(1, 0, 0, 15)
                        end
                    end
                end

                -- Manage the horizontal icons wrapper for top/bottom.
                if IsHorizontal then
                    -- Create icons wrapper if it doesn't exist.
                    if not Items["IconsWrapper"] then
                        Items["IconsWrapper"] = Instances:Create("Frame", {
                            Parent = TargetFrame.Instance,
                            Name = "\0",
                            BackgroundTransparency = 1,
                            Size = UDim2New(1, -220, 1, 0),
                            Position = UDim2New(0, 0, 0, 0),
                            ZIndex = 2,
                            BorderSizePixel = 0,
                        })

                        Instances:Create("UIListLayout", {
                            Parent = Items["IconsWrapper"].Instance,
                            Name = "\0",
                            FillDirection = Enum.FillDirection.Horizontal,
                            HorizontalAlignment = Enum.HorizontalAlignment.Center,
                            VerticalAlignment = Enum.VerticalAlignment.Center,
                            Padding = UDimNew(0, 4),
                            SortOrder = Enum.SortOrder.LayoutOrder,
                        })

                    end

                    Items["IconsWrapper"].Instance.Parent = TargetFrame.Instance
                    Items["IconsWrapper"].Instance.Visible = true

                    for Index, Value in next, Window.Pages do
                        Value.Items.Inactive.Instance.Parent = Items["IconsWrapper"].Instance
                        Value.Items.Inactive.Instance.Size = UDim2New(0, 60, 0, 60)

                        Value.Items.Text.Instance.TextTransparency = 1
                        Value.Items.Icon.Instance.AnchorPoint = Vector2New(0.5, 0.5)
                        Value.Items.Icon.Instance.Position = UDim2New(0.5, 0, 0.5, 0)
                        Value.Items.Icon.Instance.Size = UDim2New(0, 24, 0, 24)
                        Value.Items.Gradient.Instance.Rotation = NewAlignment == "TopTabs" and 90 or -90
                    end
                else
                    -- Hide wrapper and separator for vertical layout.
                    if Items["IconsWrapper"] then
                        Items["IconsWrapper"].Instance.Visible = false
                    end

                    for Index, Value in next, Window.Pages do
                        Value.Items.Inactive.Instance.Parent = ContentParent.Instance
                        Value.Items.Inactive.Instance.Size = UDim2New(0, 200, 0, 40)

                        Value.Items.Text.Instance.TextTransparency = 0.15
                        Value.Items.Text.Instance.TextXAlignment = Enum.TextXAlignment.Left
                        Value.Items.Text.Instance.AnchorPoint = Vector2New(0, 0.5)
                        Value.Items.Text.Instance.Position = UDim2New(0, 45, 0.5, 0)
                        Value.Items.Icon.Instance.AnchorPoint = Vector2New(0, 0.5)
                        Value.Items.Icon.Instance.Position = UDim2New(0, 16, 0.5, 0)
                        Value.Items.Icon.Instance.Size = UDim2New(0, 18, 0, 18)
                        -- Only difference for right: gradient goes right-to-left.
                        Value.Items.Gradient.Instance.Rotation = IsRight and 180 or 0
                    end
                end
            end

            function Window:UpdateFrameSide(OldAlignment, NewAlignment)
                local OldContent = self:GetContentParent(OldAlignment)
                local NewContent = self:GetContentParent(NewAlignment)
                local OldFrame = Items[OldAlignment]
                local NewFrame = Items[NewAlignment]

                -- Transfer content children (categories, tabs) from old to new.
                local IconsInst = Items["IconsWrapper"] and Items["IconsWrapper"].Instance
                local SepInst = nil
                local ProfileInst = Items["UserProfile"] and Items["UserProfile"].Instance

                local Children = OldContent.Instance:GetChildren()
                for I = 1, #Children do
                    local Child = Children[I]
                    if not Child:IsA("UIListLayout") and not Child:IsA("UIPadding") and not Child:IsA("UICorner") and not Child:IsA("UIGradient")
                        and Child ~= IconsInst and Child ~= SepInst and Child ~= ProfileInst then
                        Child.Parent = NewContent.Instance
                    end
                end

                -- Reparent old tab frame back to MainFrame (hidden).
                OldFrame.Instance.Parent = Items["MainFrame"].Instance
                OldFrame.Instance.Visible = false

                -- Show new tab frame.
                NewFrame.Instance.Parent = Items["MainFrame"].Instance
                NewFrame.Instance.Visible = true

                Window:UpdateTabs(NewAlignment)
                Window:UpdateUserProfile(NewAlignment)
            end

            local HighlightGeneration = 0

            function Window:UpdateHighlight(CurrentFrame, Bool)
                if Bool then
                    HighlightGeneration = HighlightGeneration + 1
                    CurrentFrame.Instance.Visible = false
                    Items["PagePlaceholder"].Instance.Visible = true
                    Items["PagePlaceholder"].Instance.BackgroundTransparency = 0.3
                else
                    -- Let the placeholder fade out naturally. Generation guard prevents stale delays.
                    local Gen = HighlightGeneration
                    Items["PagePlaceholder"]:Tween(TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1})
                    task.delay(0.3, function()
                        if HighlightGeneration == Gen then
                            Items["PagePlaceholder"].Instance.Visible = false
                        end
                    end)
                end
            end

            function Window:UpdateUserProfile(Alignment)
                local Up = Items["UserProfile"]
                if not Up then return end
                local TabFrame = Items[Alignment]

                Up.Instance.Parent = TabFrame.Instance

                -- Reset to left-aligned layout (same for left and right — right just shifts via padding).
                Items["AvatarImage"].Instance.AnchorPoint = Vector2New(0, 0.5)
                Items["AvatarImage"].Instance.Position = UDim2New(0, 0, 0.5, 0)
                Items["DisplayName"].Instance.AnchorPoint = Vector2New(0, 0)
                Items["DisplayName"].Instance.Position = UDim2New(0, 52, 0, 5)
                Items["DisplayName"].Instance.TextXAlignment = Enum.TextXAlignment.Left
                Items["Username"].Instance.AnchorPoint = Vector2New(0, 0)
                Items["Username"].Instance.Position = UDim2New(0, 52, 0, 27)
                Items["Username"].Instance.TextXAlignment = Enum.TextXAlignment.Left

                local Sep = Items["ProfileSeparator"]
                if Alignment == "LeftTabs" or Alignment == "RightTabs" then
                    Up.Instance.AnchorPoint = Vector2New(0.5, 1)
                    Up.Instance.Position = UDim2New(0.5, 0, 1, -10)
                    Up.Instance.AutomaticSize = Enum.AutomaticSize.None
                    Up.Instance.Size = UDim2New(1, -30, 0, 52)

                    -- Horizontal separator above profile.
                    Sep.Instance.AnchorPoint = Vector2New(0.5, 0)
                    Sep.Instance.Size = UDim2New(1, 0, 0, 1)
                    Sep.Instance.Position = UDim2New(0.5, 0, 0, -8)
                else
                    Up.Instance.AnchorPoint = Vector2New(1, 0.5)
                    Up.Instance.Position = UDim2New(1, -10, 0.5, 0)
                    Up.Instance.AutomaticSize = Enum.AutomaticSize.None
                    Up.Instance.Size = UDim2New(0, 195, 0, 52)

                    -- Vertical separator left of profile (same position as old TabSeparator: 215px from right edge).
                    -- UserProfile is at (1, -10) anchored right, 195px wide → left edge at tabWidth-205.
                    -- TabSeparator was at tabWidth-215. Offset from UserProfile left = -10px.
                    Sep.Instance.AnchorPoint = Vector2New(0.5, 0.5)
                    Sep.Instance.Size = UDim2New(0, 1, 0, 40)
                    Sep.Instance.Position = UDim2New(0, -10, 0.5, 0)

                end
            end


            for Index, Value in next, {"Left", "Top", "Bottom", "Right"} do
                local TabDragging = false
                local TabItem = Items[Value.."Tabs"]
                local SelectedParent

                TabItem:Connect("InputBegan", function(Input)
                    if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                        if Library.DragLock then return end
                        -- Don't start dock drag if clicking on content (buttons/icons).
                        local ContentKey = Value .. "Content"
                        if Items[ContentKey] then
                            -- Vertical (Left/Right): check content frame with actual layout height.
                            local Cf = Items[ContentKey].Instance
                            local MouseX, MouseY = Mouse.X, Mouse.Y
                            local CfPos = Cf.AbsolutePosition
                            local CfSizeX = Cf.AbsoluteSize.X
                            if MouseX >= CfPos.X and MouseX <= CfPos.X + CfSizeX and MouseY >= CfPos.Y then
                                local Layout = Cf:FindFirstChildWhichIsA("UIListLayout")
                                local ContentH = Layout and Layout.AbsoluteContentSize.Y or Cf.AbsoluteSize.Y
                                if MouseY <= CfPos.Y + ContentH then return end
                            end
                        else
                            -- Horizontal (Top/Bottom): check IconsWrapper.
                            if Items["IconsWrapper"] and Items["IconsWrapper"].Instance.Visible and Library:IsMouseOverFrame(Items["IconsWrapper"]) then return end
                        end
                        TabDockDragging = true
                        TabItem.Instance.Parent = Library.Holder.Instance
                        Window:UpdateHighlight(TabItem, true)
                        Items["PagePlaceholder"]:Tween(nil, {BackgroundTransparency = 0.3})
                        TabDragging = true
                    end
                end)

                TabItem:Connect("InputEnded", function(Input)
                    if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                        TabDragging = false
                        TabDockDragging = false

                        if SelectedParent then
                            Items["PagePlaceholder"]:Tween(nil, {BackgroundTransparency = 1})
                            Window:UpdateHighlight(TabItem, false)
                            local OldAlignment = Window.CurrentAlignment
                            Window.CurrentAlignment = SelectedParent
                            Window:UpdateFrameSide(OldAlignment, SelectedParent)
                        else
                            -- Dropped without a valid target — put back.
                            TabItem.Instance.Parent = Items["MainFrame"].Instance
                            TabItem.Instance.Visible = true
                            Items["PagePlaceholder"].Instance.Visible = false
                        end
                        SelectedParent = nil
                    end
                end)

                Library:Connect(UserInputService.InputChanged, function(Input)
                    if Input.UserInputType == Enum.UserInputType.MouseMovement and TabDragging then
                        SelectedParent = Window:GetClosestFrame(Vector2New(Input.Position.X, Input.Position.Y - 36))
                        local TargetSize
                        local TargetPosition
                        local TargetAnchorPoint

                        if SelectedParent == "LeftTabs" then
                            TargetSize = UDim2New(0, 225, 1, 0)
                            TargetPosition = UDim2New(0, 0, 0, 0)
                            TargetAnchorPoint = Vector2New(1, 0)
                        elseif SelectedParent == "RightTabs" then
                            TargetSize = UDim2New(0, 225, 1, 0)
                            TargetPosition = UDim2New(1, 0, 0, 0)
                            TargetAnchorPoint = Vector2New(0, 0)
                        elseif SelectedParent == "TopTabs" then
                            TargetSize = UDim2New(1, 0, 0, 80)
                            TargetPosition = UDim2New(0, 0, 0, 0)
                            TargetAnchorPoint = Vector2New(0, 1)
                        elseif SelectedParent == "BottomTabs" then
                            TargetSize = UDim2New(1, 0, 0, 90)
                            TargetPosition = UDim2New(0, 0, 1, 0)
                            TargetAnchorPoint = Vector2New(0, 0)
                        end

                        Items["PagePlaceholder"].Instance.AnchorPoint = TargetAnchorPoint
                        Items["PagePlaceholder"]:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = TargetSize})
                        Items["PagePlaceholder"]:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = TargetPosition})
                    end
                end)
            end

            function Window:Init()
                -- Initialize layout for default alignment (must happen after all pages are added).
                Window:UpdateTabs(Window.CurrentAlignment)
                Window:UpdateUserProfile(Window.CurrentAlignment)

                for __, Value in next, Window.Pages do
                    if Value.Active then
                        for Index, Value2 in next, Value.Sections do
                            task.spawn(function()
                                Value2:TweenElements(true)
                            end)
                        end
                    end
                end
            end

            -- Menu keybind toggle (LeftAlt by default).
            Library:Connect(UserInputService.InputBegan, function(Input)
                if tostring(Input.KeyCode) == Library.MenuKeybind or tostring(Input.UserInputType) == Library.MenuKeybind then
                    if Library:ShouldIgnorePointerKeybind(Input, Window) then
                        return
                    end

                    Window:SetOpen(not Window.IsOpen)
                end
            end)

            Window:SetCenter()
            task.wait()
            if IsLaunchMenuLocked() or getgenv().EpiphyllumSilentMode or getgenv().EpiphyllumShowMenuOnLaunch == false then
                Items["MainFrame"].Instance.Visible = false
            else
                Window:SetOpen(true)
            end
            return setmetatable(Window, Library)
        end

