                })

                Instances:Create("UIListLayout", {
                    Parent = Items["Page"].Instance,
                    Name = "\0",
                    FillDirection = Enum.FillDirection.Horizontal,
                    HorizontalFlex = Enum.UIFlexAlignment.Fill,
                    Padding = UDimNew(0, 10),
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    VerticalFlex = Enum.UIFlexAlignment.Fill
                })

                Instances:Create("UIPadding", {
                    Parent = Items["Page"].Instance,
                    Name = "\0",
                    PaddingTop = UDimNew(0, 10),
                    PaddingBottom = UDimNew(0, 10),
                    PaddingRight = UDimNew(0, 10),
                    PaddingLeft = UDimNew(0, 10)
                })

                for Index = 1, Page.Columns do
                    local NewColumn = Instances:Create("ScrollingFrame", {
                        Parent = Items["Page"].Instance,
                        Name = "\0",
                        ScrollBarImageColor3 = FromRGB(0, 0, 0),
                        Active = true,
                        AutomaticCanvasSize = Enum.AutomaticSize.Y,
                        ScrollBarThickness = 0,
                        BorderColor3 = FromRGB(0, 0, 0),
                        BackgroundTransparency = 1,
                        Size = UDim2New(0, 100, 0, 100),
                        BackgroundColor3 = FromRGB(255, 255, 255),
                        ZIndex = 2,
                        BorderSizePixel = 0,
                        CanvasSize = UDim2New(0, 0, 0, 0)
                    })

                    Instances:Create("UIListLayout", {
                        Parent = NewColumn.Instance,
                        Name = "\0",
                        Padding = UDimNew(0, 5),
                        SortOrder = Enum.SortOrder.LayoutOrder
                    })

                    Page.ColumnsData[Index] = NewColumn
                end

                Page.Items = Items
                Page.UiItems = Items
            end

            local Debounce = false

            function Page:Turn(Bool, CompleteCallback)
                if Debounce or Page.Switching then
                    return false
                end

                if Page.Active == Bool then
                    return false
                end

                Page.Active = Bool

                Debounce = true
                Page.Switching = true
                Items["Page"].Instance.Visible = Bool
                Items["Page"].Instance.Parent = Bool and Page.Window.Items["Content"].Instance or Library.UnusedHolder.Instance

                local PageInstance = Items["Page"].Instance
                local PageTween = nil

                ---Check if an instance is in a visible page subtree.
                local function ShouldFadeInstance(Instance)
                    local Current = Instance

                    while Current and Current ~= PageInstance do
                        if Current:IsA("GuiObject") and not Current.Visible then
                            return false
                        end

                        Current = Current.Parent
                    end

                    return true
                end

                if Page.Active then
                    Items["Inactive"]:Tween(nil, {BackgroundTransparency = 0.25})
                    PageTween = Items["Page"]:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 0)})

                    for Index, Value in next, Page.Sections do
                        task.spawn(function()
                            Value:TweenElements(true)
                        end)
                    end
                else
                    Items["Inactive"]:Tween(nil, {BackgroundTransparency = 1})
                    PageTween = Items["Page"]:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 60)})
                end

                local NewTween

                if Bool then
                    local AllInstances = PageInstance:GetDescendants()
                    TableInsert(AllInstances, PageInstance)

                    for Index, Value in next, AllInstances do
                        if ShouldFadeInstance(Value) then
                            local TransparencyProperty = Tween:GetProperty(Value)

                            if TransparencyProperty then
                                if type(TransparencyProperty) == "table" then
                                    for Index, Property in next, TransparencyProperty do
                                        NewTween = Tween:FadeItem(Value, Property, Bool, Library.FadeSpeed)
                                    end
                                else
                                    NewTween = Tween:FadeItem(Value, TransparencyProperty, Bool, Library.FadeSpeed)
                                end
                            end
                        end
                    end
                end

                local CompletionTween = PageTween or NewTween

                if not CompletionTween then
                    Debounce = false
                    Page.Switching = false
                    if CompleteCallback then
                        task.defer(CompleteCallback)
                    end
                    return true
                end

                Library:Connect(CompletionTween.Tween.Completed, function()
                    Debounce = false
                    Page.Switching = false

                    if not Page.Active then
                        for Index, Value in next, Page.Sections do
                            task.spawn(function()
                                Value:TweenElements(false, true)
                            end)
                        end
                    end

                    if CompleteCallback then
                        CompleteCallback()
                    end
                end)

                return true
            end

            -- Subtle hover on inactive tab.
            Items["Inactive"]:OnHover(function()
                if not Page.Active then
                    Items["Inactive"]:Tween(TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.85})
                end
            end)

            Items["Inactive"]:OnHoverLeave(function()
                if not Page.Active then
                    Items["Inactive"]:Tween(TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 1})
                end
            end)

            Items["Inactive"]:Connect("MouseButton1Down", function()
                if Page.Window.PageSwitchLocked or Page.Active then
                    return
                end

                for Index, Value in next, Page.Window.Pages do
                    if Value.Switching then
                        return
                    end
                end

                Page.Window.PageSwitchLocked = true
                local Pending = 0

                local function ReleasePageSwitch()
                    Pending = Pending - 1
                    if Pending > 0 then
                        return
                    end

                    Page.Window.PageSwitchLocked = false
                end

                for Index, Value in next, Page.Window.Pages do
                    local Started = Value:Turn(Value == Page, ReleasePageSwitch)
                    if Started then
                        Pending = Pending + 1
                    end
                end

                if Pending == 0 then
                    Page.Window.PageSwitchLocked = false
                end
            end)

            if #Page.Window.Pages == 0 then
                Page:Turn(true)
            end

            TableInsert(Page.Window.Pages, Page)
            return setmetatable(Page, Library.Pages)
        end

