                })
            end

            if Keybind.Section.Items["Fade"] then Keybind.Section.Items["Fade"].Instance.Size = UDim2New(1, 0, 0, math.max(0, Keybind.Section.Items["Content"].Instance.AbsoluteSize.Y - 180)) end

            local KeyListItem

            local function UpdateModesVisibility()
                local HasKey = Keybind.Value ~= "" and Keybind.Value ~= "None"
                Items["Modes"].Instance.Visible = HasKey
                -- Shrink key button when modes visible so it doesn't overlap, full width when hidden.
                Items["KeyButton"].Instance.Size = HasKey and UDim2New(1, -118, 1, 0) or UDim2New(1, 0, 1, 0)
            end

            local Update = function()
                local HasKey = Keybind.Value ~= "" and Keybind.Value ~= "None"

                if HasKey and not KeyListItem and Library.KeyList then
                    KeyListItem = Library.KeyList:Add("", "")
                end

                if not HasKey and KeyListItem then
                    KeyListItem:Clean()
                    KeyListItem = nil
                end

                if KeyListItem then
                    KeyListItem:Set(Data.Name, Keybind.Value)
                    KeyListItem:SetStatus(Keybind.Toggled)
                end
                UpdateModesVisibility()
            end

            function Keybind:SyncToggled(State)
                Keybind.Toggled = State
                Library.Flags[Keybind.Flag] = {
                    Mode = Keybind.ModeSelected,
                    Key = Keybind.Key,
                    Toggled = Keybind.Toggled
                }
                Update()
            end

            function Keybind:RefreshPosition(Bool)
                if Bool then
                    Items["Text"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 5)})
                    Items["SubElements"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 30)})
                else
                    Items["Text"].Instance.Position = UDim2New(0, 30, 0, 5)
                    Items["SubElements"].Instance.Position = UDim2New(0, 30, 0, 30)
                end
            end

            local function ApplyModeVisuals(Mode, Instant)
                local Positions = { Toggle = 0, Hold = 0.5 }
                local Buttons = { "Toggle", "Hold" }

                if Instant then
                    Items["Background"].Instance.Position = UDim2New(Positions[Mode] or 0, 0, 0, 0)
                    Items["Background"].Instance.Size = UDim2New(0.5, 0, 1, 0)
                else
                    Items["Background"]:Tween(TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2New(Positions[Mode] or 0, 0, 0, 0), Size = UDim2New(0.5, 0, 1, 0)})
                end

                for Index, Name in next, Buttons do
                    local Color = (Name == Mode) and FromRGB(0, 0, 0) or Library.Theme.Text
                    if Instant then
                        Items[Name].Instance.TextColor3 = Color
                    else
                        Items[Name]:Tween(nil, {TextColor3 = Color})
                    end
                end
            end

            function Keybind:SetMode(Mode)
                ApplyModeVisuals(Mode, false)

                Library.Flags[Keybind.Flag] = {
                    Mode = Keybind.ModeSelected,
                    Key = Keybind.Key,
                    Toggled = Keybind.Toggled
                }
            end

            function Keybind:Press(Bool)
                local Prev = Keybind.Toggled

                if Keybind.ModeSelected == "Toggle" then
                    Keybind.Toggled = not Keybind.Toggled
                elseif Keybind.ModeSelected == "Hold" then
                    Keybind.Toggled = Bool
                end

                if Prev == Keybind.Toggled then return end

                -- Fire callback. If it returns false, revert state.
                if Data.Callback then
                    local Ok, Result = pcall(Data.Callback, Keybind.Toggled, true)
                    if Ok and Result == false then
                        Keybind.Toggled = Prev
                        return
                    end
                end

                Library.Flags[Keybind.Flag] = {
                    Mode = Keybind.ModeSelected,
                    Key = Keybind.Key,
                    Toggled = Keybind.Toggled
                }

                Update()
            end

            function Keybind:Get()
                return Keybind.Key, Keybind.ModeSelected, Keybind.Toggled
            end

            local function SyncLibraryMenuKeybind()
                if Keybind.Flag == "EP_MenuKeybind" or Keybind.Flag == "MenuKeybind" then
                    Library.MenuKeybind = Keybind.Key
                end
            end

            local function NormalizeKeybindInput(Key)
                local RawKey = Key
                if type(Key) == "table" then
                    RawKey = Key.Key
                end

                if RawKey == nil or RawKey == "" then
                    return nil, "None"
                end

                if typeof(RawKey) == "EnumItem" then
                    if RawKey.Name == "Backspace" then
                        return "None", "None"
                    end

                    return tostring(RawKey), RawKey.Name
                end

                local KeyText = tostring(RawKey)
                if KeyText == "Backspace" then
                    return "None", "None"
                end

                local MouseAliases = {
                    left = "MouseButton1",
                    leftclick = "MouseButton1",
                    leftmouse = "MouseButton1",
                    leftbutton = "MouseButton1",
                    lmb = "MouseButton1",
                    mb1 = "MouseButton1",
                    mouse1 = "MouseButton1",
                    m1 = "MouseButton1",
                    mousebutton1 = "MouseButton1",

                    right = "MouseButton2",
                    rightclick = "MouseButton2",
                    rightmouse = "MouseButton2",
                    rightbutton = "MouseButton2",
                    rmb = "MouseButton2",
                    mb2 = "MouseButton2",
                    mouse2 = "MouseButton2",
                    m2 = "MouseButton2",
                    mousebutton2 = "MouseButton2",

                    middle = "MouseButton3",
                    middleclick = "MouseButton3",
                    middlemouse = "MouseButton3",
                    middlebutton = "MouseButton3",
                    mmb = "MouseButton3",
                    mb3 = "MouseButton3",
                    mouse3 = "MouseButton3",
                    m3 = "MouseButton3",
                    mousebutton3 = "MouseButton3",
                    wheelclick = "MouseButton3",
                }

                local CleanKey = StringLower(KeyText):gsub("^enum%.userinputtype%.", ""):gsub("[%s_%-]", "")
                local MouseName = MouseAliases[CleanKey]
                if MouseName then
                    return "Enum.UserInputType." .. MouseName, MouseName
                end

                local KeyAliases = {
                    spacebar = "Space",
                    space = "Space",
                    ctrl = "LeftControl",
                    control = "LeftControl",
                    leftctrl = "LeftControl",
                    leftcontrol = "LeftControl",
                    rightctrl = "RightControl",
                    rightcontrol = "RightControl",
                    shift = "LeftShift",
                    leftshift = "LeftShift",
                    rightshift = "RightShift",
                    alt = "LeftAlt",
                    leftalt = "LeftAlt",
                    rightalt = "RightAlt",
                }

                local KeyName = KeyText
                if StringLower(KeyName):find("^enum%.keycode%.") then
                    KeyName = KeyName:sub(14)
                end

                local CleanKeyName = StringLower(KeyName):gsub("[%s_%-]", "")
                KeyName = KeyAliases[CleanKeyName] or KeyName
                if #KeyName == 1 then
                    KeyName = StringLower(KeyName):upper()
                else
                    KeyName = KeyName:sub(1, 1):upper() .. KeyName:sub(2)
                end

                local Success, KeyCode = pcall(function()
                    return Enum.KeyCode[KeyName]
                end)

                if Success and KeyCode then
                    return tostring(KeyCode), KeyCode.Name
                end

                local DisplayKey = KeyText:gsub("^Enum%.", "")
                DisplayKey = StringGSub(StringGSub(DisplayKey, "KeyCode.", ""), "UserInputType.", "")

                return KeyText, DisplayKey
            end

            function Keybind:Set(Key)
                if type(Key) == "table" then
                    local NormalizedKey, TextToDisplay = NormalizeKeybindInput(Key)
                    if not NormalizedKey then return end

                    Keybind.Key = NormalizedKey
                    SyncLibraryMenuKeybind()
                    Keybind.ModeSelected = Key.Mode or Key.ModeSelected or "Toggle"
                    if Key.Toggled ~= nil then
                        Keybind.Toggled = Key.Toggled == true
                    end
                    Keybind:SetMode(Keybind.ModeSelected)

                    Keybind.Value = TextToDisplay
                    Items["KeyButton"].Instance.Text = TextToDisplay

                    if Data.Callback then
                        Library:SafeCall(Data.Callback, Keybind.Toggled, false)
                    end

                    Update()
                elseif TableFind({"Toggle", "Hold"}, Key) then
                    Keybind.ModeSelected = Key
                    Keybind:SetMode(Key)

                    if Data.Callback then
                        Library:SafeCall(Data.Callback, Keybind.Toggled, false)
                    end

                    Update()
                elseif StringFind(tostring(Key), "Enum") or type(Key) == "string" then
                    local NormalizedKey, TextToDisplay = NormalizeKeybindInput(Key)
                    if not NormalizedKey then return end

                    Keybind.Key = NormalizedKey
                    SyncLibraryMenuKeybind()
                    Keybind.Value = TextToDisplay
                    Items["KeyButton"].Instance.Text = TextToDisplay

                    Library.Flags[Keybind.Flag] = {
                        Mode = Keybind.ModeSelected,
                        Key = Keybind.Key,
                        Toggled = Keybind.Toggled
                    }

                    if Data.Callback then
                        Library:SafeCall(Data.Callback, Keybind.Toggled, false)
                    end

                    Update()
                end

                Keybind.Picking = false
            end

            Items["KeyButton"]:Connect("MouseButton1Click", function()
                Keybind.Picking = true

                Items["KeyButton"].Instance.Text = "."
                Library:Thread(function()
                    local Count = 1

                    while true do
                        if not Keybind.Picking then
                            break
                        end

                        if Count == 4 then
                            Count = 1
                        end

                        Items["KeyButton"].Instance.Text = Count == 1 and "." or Count == 2 and ".." or Count == 3 and "..."
                        Count = Count + 1
                        task.wait(0.35)
                    end
                end)

                local InputBegan
                InputBegan = UserInputService.InputBegan:Connect(function(Input)
                    if Input.UserInputType == Enum.UserInputType.Keyboard then
                        Keybind:Set(Input.KeyCode)
                    else
                        Keybind:Set(Input.UserInputType)
                    end

                    InputBegan:Disconnect()
                    InputBegan = nil
                end)
            end)

            local IgnoredInput = nil

            Library:Connect(UserInputService.InputBegan, function(Input)
                if Keybind.Value == "None" then
                    return
                end

                if tostring(Input.KeyCode) == Keybind.Key then
                    if Library:ShouldIgnorePointerKeybind(Input, Keybind.Window) then
                        IgnoredInput = Input
                    elseif Keybind.ModeSelected == "Toggle" then
                        Keybind:Press()
                    elseif Keybind.ModeSelected == "Hold" then
                        Keybind:Press(true)
                    end
                elseif tostring(Input.UserInputType) == Keybind.Key then
                    if Library:ShouldIgnorePointerKeybind(Input, Keybind.Window) then
                        IgnoredInput = Input
                    elseif Keybind.ModeSelected == "Toggle" then
                        Keybind:Press()
                    elseif Keybind.ModeSelected == "Hold" then
                        Keybind:Press(true)
                    end
                end

                if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                    if not Keybind.IsOpen then
                        return
                    end

                    if Library:IsMouseOverFrame(Items["KeybindWindow"]) or Library:IsMouseOverFrame(Items["OptionHolder"]) then
                        return
                    end

                    Keybind:SetOpen(false)
                end
            end)

            Library:Connect(UserInputService.InputEnded, function(Input)
                if Keybind.Value == "None" then
                    return
                end

                if IgnoredInput == Input then
                    IgnoredInput = nil
                    return
                end

                if tostring(Input.KeyCode) == Keybind.Key then
                    if Keybind.ModeSelected == "Hold" then
                        Keybind:Press(false)
                    end
                elseif tostring(Input.UserInputType) == Keybind.Key then
                    if Keybind.ModeSelected == "Hold" then
                        Keybind:Press(false)
                    end
                end
            end)

            local function SwitchMode(Mode)
                Keybind.ModeSelected = Mode
                Keybind:SetMode(Mode)
                -- Never fire callback on mode switch. Only Press() fires callbacks.
            end

            Items["Toggle"]:Connect("MouseButton1Down", function()
                SwitchMode("Toggle")
            end)

            Items["Hold"]:Connect("MouseButton1Down", function()
                SwitchMode("Hold")
            end)

            -- Set mode before anything else so ModeSelected is populated.
            Keybind.ModeSelected = Keybind.Mode or "Toggle"

            if Keybind.Default then
                Keybind:Set({
                    Mode = Keybind.ModeSelected,
                    Key = Keybind.Default,
                })
            end

            -- Apply mode colors instantly (no tween) so they're correct from the start.
            -- Use task.defer to ensure any tween from Set() doesn't override.
            task.defer(function()
                ApplyModeVisuals(Keybind.ModeSelected or "Toggle", true)
            end)

            -- Re-apply mode colors when theme changes.
            if not Library._themeCallbacks then Library._themeCallbacks = {} end
            Library._themeCallbacks[#Library._themeCallbacks + 1] = function()
                ApplyModeVisuals(Keybind.ModeSelected or "Toggle", true)
            end

            -- Ensure keybind list reflects initial toggled state.
            Update()

            Library.SetFlags[Keybind.Flag] = function(Value)
                Keybind:Set(Value)
            end

            Keybind.Items = Items
            Keybind.UiItems = Items
            Keybind.Section.Elements[#Keybind.Section.Elements+1] = Keybind
            return Keybind
        end

        Library.Sections.Textbox = function(self, Data)
            Data = Data or { }

            local Textbox = {
                Window = self.Window,
                Page = self.Page,
                Section = self,

                Name = Data.Name or Data.name or Data.Placeholder or Data.placeholder or "Textbox",
                Flag = Data.Flag or Data.flag or Library:NextFlag(),
                Default = Data.Default or Data.default or "",
                Callback = Data.Callback or Data.callback or function() end,
                Placeholder = Data.Placeholder or Data.placeholder or "Placeholder",
                Numeric = Data.Numeric or Data.numeric or false,
                Finished = Data.Finished or Data.finished or false,

                Value = ""
            }

            local Items = { } do
                Items["Textbox"] = Instances:Create("Frame", {
                    Parent = Textbox.Section.Items["Content"].Instance,
                    Name = "\0",
                    Active = true,
                    BorderColor3 = FromRGB(0, 0, 0),
                    BackgroundTransparency = 1,
                    Selectable = true,
                    Size = UDim2New(1, 0, 0, 32),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 26, 29)
                })

                Instances:Create("UICorner", {
                    Parent = Items["Textbox"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 4)
                })

                Items["Background"] = Instances:Create("Frame", {
                    Parent = Items["Textbox"].Instance,
                    Name = "\0",
                    Active = true,
                    BorderColor3 = FromRGB(0, 0, 0),
                    Size = UDim2New(1, 0, 1, 0),
                    Selectable = true,
                    ZIndex = 2,
                    ClipsDescendants = true,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 26, 29)
                })  Items["Background"]:AddToTheme({BackgroundColor3 = "Element"})

                Instances:Create("UICorner", {
                    Parent = Items["Background"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 4)
                })

                Items["Input"] = Instances:Create("TextBox", {
                    Parent = Items["Background"].Instance,
                    Name = "\0",
                    FontFace = Library.Font,
                    TextColor3 = FromRGB(240, 240, 240),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Text = "",
                    ZIndex = 2,
                    Size = UDim2New(1, -20, 0, 15),
                    Position = UDim2New(0, 10, 0, 8),
                    BorderSizePixel = 0,
                    BackgroundTransparency = 1,
                    PlaceholderColor3 = FromRGB(185, 185, 185),
                    TextXAlignment = Enum.TextXAlignment.Left,
                    PlaceholderText = Textbox.Placeholder,
                    TextSize = 14,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })  Items["Input"]:AddToTheme({TextColor3 = "Text"})
            end

            function Textbox:Get()
                return Textbox.Value
            end

            function Textbox:SetVisibility(Bool)
                Items["Textbox"].Instance.Visible = Bool
            end

            function Textbox:RefreshPosition(Bool)
                if Bool then
                    Items["Background"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 0)})
                else
                    Items["Background"].Instance.Position = UDim2New(0, 30, 0, 0)
                end
            end

            local function IsIncompleteNumericText(Value)
                Value = tostring(Value)
                return Value == "-" or Value == "." or Value == "-."
            end

            function Textbox:Set(Value)
                local InputInstance = Items["Input"].Instance

                if Textbox.Numeric then
                    local TextValue = tostring(Value)
                    if (not tonumber(TextValue)) and StringLen(TextValue) > 0 then
                        if InputInstance:IsFocused() and IsIncompleteNumericText(TextValue) then
                            InputInstance.Text = TextValue
                            return
                        end

                        Value = Textbox.Value
                    end
                end

                Textbox.Value = Value
                InputInstance.Text = Value
                Library.Flags[Textbox.Flag] = Value

                if Textbox.Callback then
                    Library:SafeCall(Textbox.Callback, Value)
                end
            end

            if Textbox.Finished then
                Items["Input"]:Connect("FocusLost", function()
                    Textbox:Set(Items["Input"].Instance.Text)
                end)
            else
                Library:Connect(Items["Input"].Instance:GetPropertyChangedSignal("Text"), function()
                    Textbox:Set(Items["Input"].Instance.Text)
                end)
            end

            if Textbox.Default then
                Textbox:Set(Textbox.Default)
            end

            Library.SetFlags[Textbox.Flag] = function(Value)
                Textbox:Set(Value)
            end

            Textbox.Items = Items
            Textbox.UiItems = Items
            Textbox.Section.Elements[#Textbox.Section.Elements+1] = Textbox
            return Textbox
        end

        Library.Sections.Listbox = function(self, Data)
            -- basically just dropdowns so i jsut copied dropdowns
            Data = Data or { }

            local Dropdown = {
                Window = self.Window,
                Page = self.Page,
                Section = self,

                Name = Data.Name or Data.name or "Listbox",
