                })  Items["Search"]:AddToTheme({TextColor3 = "Text", BackgroundColor3 = "Element"})

                Instances:Create("UICorner", {
                    Parent = Items["Search"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 6)
                })

                Instances:Create("UIPadding", {
                    Parent = Items["Search"].Instance,
                    Name = "\0",
                    PaddingTop = UDimNew(0, 4),
                    PaddingLeft = UDimNew(0, 8)
                })

                Items["Background"] = Instances:Create("Frame", {
                    Parent = Items["Listbox"].Instance,
                    Name = "\0",
                    Active = true,
                    Size = UDim2New(1, 0, 1, -30),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Position = UDim2New(0, 0, 0, 30),
                    BackgroundColor3 = FromRGB(27, 26, 29),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                })  Items["Background"]:AddToTheme({BackgroundColor3 = "Element"})

                Items["Holder"] = Instances:Create("ScrollingFrame", {
                    Parent = Items["Background"].Instance,
                    Name = "\0",
                    ScrollBarImageColor3 = FromRGB(0, 0, 0),
                    Active = true,
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    ScrollBarThickness = 2,
                    Size = UDim2New(1, -4, 1, -8),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Position = UDim2New(0, 0, 0, 4),
                    BackgroundColor3 = FromRGB(27, 26, 29),
                    ZIndex = 2,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    CanvasSize = UDim2New(0, 0, 0, 0)
                })  Items["Holder"]:AddToTheme({ScrollBarImageColor3 = "Accent"})

                Instances:Create("UICorner", {
                    Parent = Items["Background"].Instance,
                    Name = "\0",
                    CornerRadius = UDimNew(0, 6)
                })

                Instances:Create("UIListLayout", {
                    Parent = Items["Holder"].Instance,
                    Name = "\0",
                    Padding = UDimNew(0, 4),
                    SortOrder = Enum.SortOrder.LayoutOrder
                })

                Instances:Create("UIPadding", {
                    Parent = Items["Holder"].Instance,
                    Name = "\0",
                    PaddingTop = UDimNew(0, 8),
                    PaddingBottom = UDimNew(0, 8),
                    PaddingRight = UDimNew(0, 12),
                    PaddingLeft = UDimNew(0, 8)
                })

                Items["_"] = Instances:Create("Frame", {
                    Parent = Items["Listbox"].Instance,
                    Name = "\0",
                    Size = UDim2New(1, 0, 0, 10),
                    Position = UDim2New(0, 0, 0, 25),
                    BorderColor3 = FromRGB(0, 0, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 26, 29)
                })  Items["_"]:AddToTheme({BackgroundColor3 = "Element"})

                Instances:Create("Frame", {
                    Parent = Items["_"].Instance,
                    Name = "\0",
                    Size = UDim2New(1, 0, 0, 1),
                    Position = UDim2New(0, 0, 1, -3),
                    AnchorPoint = Vector2New(0, 1),
                    BorderColor3 = FromRGB(0, 0, 0),
                    ZIndex = 2,
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(27, 26, 29),
                }):AddToTheme({BackgroundColor3 = "Outline"})
            end

            function Dropdown:Get()
                return Dropdown.Value
            end

            function Dropdown:SetVisibility(Bool)
                Items["Listbox"].Instance.Visible = Bool
            end

            function Dropdown:RefreshPosition(Bool)
                if Bool then
                    Items["Background"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 30)})
                    Items["Search"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 0)})
                    Items["_"]:Tween(TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 25)})
                else
                    Items["Background"].Instance.Position = UDim2New(0, 30, 0, 30)
                    Items["Search"].Instance.Position = UDim2New(0, 30, 0, 0)
                    Items["_"].Instance.Position = UDim2New(0, 30, 0, 25)
                end
            end

            function Dropdown:Set(Option)
                if Dropdown.Multi then
                    if type(Option) ~= "table" then
                        return
                    end

                    Dropdown.Value = Option
                    Library.Flags[Dropdown.Flag] = Option

                    for Index, Value in next, Option do
                        local OptionData = Dropdown.Options[Value]

                        if OptionData then
                            OptionData.Selected = true
                            OptionData:Toggle("Active")
                        end
                    end
                else
                    if not Dropdown.Options[Option] then
                        return
                    end

                    local OptionData = Dropdown.Options[Option]

                    Dropdown.Value = Option
                    Library.Flags[Dropdown.Flag] = Option

                    for Index, Value in next, Dropdown.Options do
                        if Value ~= OptionData then
                            Value.Selected = false
                            Value:Toggle("Inactive")
                        else
                            Value.Selected = true
                            Value:Toggle("Active")
                        end
                    end
                end

                if Dropdown.Callback then
                    Library:SafeCall(Dropdown.Callback, Dropdown.Value)
                end
            end

            function Dropdown:Add(Option)
                local OptionButton = Instances:Create("TextButton", {
                    Parent = Items["Holder"].Instance,
                    Name = "\0",
                    FontFace = Library.Font,
                    TextColor3 = FromRGB(0, 0, 0),
                    BorderColor3 = FromRGB(0, 0, 0),
                    Text = "",
                    AutoButtonColor = false,
                    BackgroundTransparency = 1,
                    Size = UDim2New(1, 0, 0, 20),
                    BorderSizePixel = 0,
                    ZIndex = 2,
                    TextSize = 14,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })

                local OptionAccent = Instances:Create("Frame", {
                    Parent = OptionButton.Instance,
                    Name = "\0",
                    BorderColor3 = FromRGB(0, 0, 0),
                    AnchorPoint = Vector2New(0, 0.5),
                    BackgroundTransparency = 1,
                    ZIndex = 2,
                    Position = UDim2New(0, 0, 0.5, 0),
                    Size = UDim2New(0, 6, 0, 6),
                    BorderSizePixel = 0,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })  --OptionAccent:AddToTheme({BackgroundColor3 = "Accent"})

                Instances:Create("UIGradient", {
                    Parent = OptionAccent.Instance,
                    Name = "\0",
                    Enabled = true,
                    Rotation = -115,
                    Color = RGBSequence{RGBSequenceKeypoint(0, FromRGB(255, 255, 255)), RGBSequenceKeypoint(1, FromRGB(143, 143, 143))}
                }):AddToTheme({Color = function()
                    return RGBSequence{RGBSequenceKeypoint(0, Library.Theme.Accent), RGBSequenceKeypoint(1, Library.Theme.AccentGradient)}
                end})

                Instances:Create("UICorner", {
                    Parent = OptionAccent.Instance,
                    Name = "\0"
                })

                local OptionText = Instances:Create("TextLabel", {
                    Parent = OptionButton.Instance,
                    Name = "\0",
                    FontFace = Library.Font,
                    TextColor3 = FromRGB(255, 255, 255),
                    TextTransparency = 0.3,
                    Text = Option,
                    Size = UDim2New(0, 0, 0, 15),
                    AnchorPoint = Vector2New(0, 0.5),
                    BorderSizePixel = 0,
                    ZIndex = 2,
                    BackgroundTransparency = 1,
                    Position = UDim2New(0, 0, 0.5, 0),
                    BorderColor3 = FromRGB(0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.X,
                    TextSize = 14,
                    BackgroundColor3 = FromRGB(255, 255, 255)
                })  OptionText:AddToTheme({TextColor3 = "Text"})

                local OptionData = {
                    Button = OptionButton,
                    Name = Option,
                    OptionText = OptionText,
                    IsSearching = false,
                    OptionAccent = OptionAccent,
                    Selected = false
                }

                function OptionData:Toggle(Value)
                    if Value == "Active" then
                        OptionText:Tween(nil, {TextTransparency = 0, Position = UDim2New(0, 15, 0.5, 0)})
                        OptionAccent:Tween(nil, {BackgroundTransparency = 0})
                    else
                        OptionText:Tween(nil, {TextTransparency = 0.3, Position = UDim2New(0, 0, 0.5, 0)})
                        OptionAccent:Tween(nil, {BackgroundTransparency = 1})
                    end
                end

                function OptionData:Search(Bool)
                    Library:Thread(function()
                        if Bool then
                            OptionData.IsSearching = true
                            OptionText:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1})
                            task.wait(0.08)
                            OptionButton:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2New(1, 0, 0, 0)})

                            if OptionData.Selected then
                                OptionAccent:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1})
                            end
                        else
                            OptionData.IsSearching = false
                            OptionText:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = OptionData.Selected and 0 or 0.3})
                            task.wait(0.08)
                            OptionButton:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Size = UDim2New(1, 0, 0, 20)})

                            if OptionData.Selected then
                                OptionAccent:Tween(TweenInfo.new(0.5, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0})
                            end
                        end
                    end)
                end

                function OptionData:Set()
                    OptionData.Selected = not OptionData.Selected

                    if Dropdown.Multi then
                        local Index = TableFind(Dropdown.Value, OptionData.Name)

                        if Index then
                            TableRemove(Dropdown.Value, Index)
                        else
                            TableInsert(Dropdown.Value, OptionData.Name)
                        end

                        OptionData:Toggle(Index and "Inactive" or "Active")

                        Library.Flags[Dropdown.Flag] = Dropdown.Value
                    else
                        if OptionData.Selected then
                            Dropdown.Value = OptionData.Name
                            Library.Flags[Dropdown.Flag] = OptionData.Name

                            OptionData.Selected = true
                            OptionData:Toggle("Active")

                            for Index, Value in next, Dropdown.Options do
                                if Value ~= OptionData and not Value.IsSearching then
                                    Value.Selected = false
                                    Value:Toggle("Inactive")
                                end
                            end
                        else
                            Dropdown.Value = nil
                            Library.Flags[Dropdown.Flag] = nil

                            OptionData.Selected = false
                            OptionData:Toggle("Inactive")
                        end
                    end

                    if Dropdown.Callback then
                        Library:SafeCall(Dropdown.Callback, Dropdown.Value)
                    end
                end

                OptionData.Button:Connect("MouseButton1Down", function()
                    OptionData:Set()
                end)

                -- Apply marquee if enabled — clip frame tracks text start position.
                if Dropdown.Marquee then
                    local ClipFrame = Instance.new("Frame")
                    ClipFrame.Name = "MarqueeClip"
                    ClipFrame.BackgroundTransparency = 1
                    ClipFrame.ClipsDescendants = true
                    ClipFrame.Size = UDim2New(1, 0, 1, 0)
                    ClipFrame.Position = UDim2New(0, 0, 0, 0)
                    ClipFrame.ZIndex = 2
                    ClipFrame.Parent = OptionButton.Instance

                    OptionText.Instance.Parent = ClipFrame
                    -- Text is now at (0, X, 0.5, 0) inside ClipFrame. Reset to 0 and move ClipFrame instead.
                    OptionText.Instance.Position = UDim2New(0, 0, 0.5, 0)

                    -- Override Toggle to move ClipFrame instead of text position.
                    local OrigToggle = OptionData.Toggle
                    function OptionData:Toggle(Value)
                        if Value == "Active" then
                            OptionText:Tween(nil, {TextTransparency = 0})
                            OptionAccent:Tween(nil, {BackgroundTransparency = 0})
                            TweenService:Create(ClipFrame, TweenInfo.new(Library.Tween and Library.Tween.Time or 0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 15, 0, 0), Size = UDim2New(1, -15, 1, 0)}):Play()
                        else
                            OptionText:Tween(nil, {TextTransparency = 0.3})
                            OptionAccent:Tween(nil, {BackgroundTransparency = 1})
                            TweenService:Create(ClipFrame, TweenInfo.new(Library.Tween and Library.Tween.Time or 0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Position = UDim2New(0, 0, 0, 0), Size = UDim2New(1, 0, 1, 0)}):Play()
                        end
                    end

                    Library:MakeMarquee(ClipFrame, OptionText.Instance)
                end

                Dropdown.Options[OptionData.Name] = OptionData
                return OptionData
            end

            function Dropdown:Remove(Option)
                if Dropdown.Options[Option] then
                    Dropdown.Options[Option].Button:Clean()
                    Dropdown.Options[Option] = nil
                end
            end

            function Dropdown:Refresh(List)
                for Index, Value in next, Dropdown.Options do
                    Dropdown:Remove(Value.Name)
                end

                for Index, Value in next, List do
                    Dropdown:Add(Value)
                end
            end

            Library:Connect(Items["Search"].Instance:GetPropertyChangedSignal("Text"), function()
                Library:Thread(function()
                    for Index, Value in next, Dropdown.Options do
                        local InputText = Items["Search"].Instance.Text
                        if InputText ~= "" then
                            if StringFind(StringLower(Value.Name), Library:EscapePattern(StringLower(InputText))) then
                                Value.Button.Instance.Visible = true
                                Value:Search(false)
                            else
                                Value:Search(true)
                                Value.Button.Instance.Visible = false
                            end
                        else
                            Value:Search(false)
                            Value.Button.Instance.Visible = true
                        end
                    end
                end)
            end)


            for Index, Value in next, Dropdown.Items do
                Dropdown:Add(Value)
            end

            if Dropdown.Default then
                Dropdown:Set(Dropdown.Default)
            end

            Library.SetFlags[Dropdown.Flag] = function(Value)
                Dropdown:Set(Value)
            end

            Dropdown.UiItems = Items
            Dropdown.Section.Elements[#Dropdown.Section.Elements+1] = Dropdown
            return Dropdown
        end
    end

    -- DependencyBox: container with conditional visibility based on flag values.
    Library.Sections.DependencyBox = function(self)
        local DepBox = {
            Window = self.Window,
            Page = self.Page,
            Section = self,
            Items = {},
            Elements = {},
            Dependencies = {},
        }

        local Items = {} do
            Items["DepBox"] = Instances:Create("Frame", {
                Parent = DepBox.Section.Items and DepBox.Section.Items["Content"] and DepBox.Section.Items["Content"].Instance or DepBox.Section.Instance,
                Name = "\0",
                BackgroundTransparency = 1,
                Size = UDim2New(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BorderSizePixel = 0,
                ClipsDescendants = true,
            })

            Items["Content"] = Instances:Create("Frame", {
                Parent = Items["DepBox"].Instance,
                Name = "\0",
                BackgroundTransparency = 1,
                Size = UDim2New(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BorderSizePixel = 0,
            })

            Instances:Create("UIListLayout", {
                Parent = Items["Content"].Instance,
                Name = "\0",
                Padding = UDimNew(0, 5),
                SortOrder = Enum.SortOrder.LayoutOrder,
            })
        end

        DepBox.Items = Items
        DepBox.UiItems = Items
        DepBox.Instance = Items["DepBox"].Instance

        function DepBox:SetVisible(Visible)
            Items["DepBox"].Instance.Visible = Visible
            if Visible then
                for Index, Element in next, DepBox.Elements do
                    if Element.RefreshPosition then
                        Element:RefreshPosition(true)
                    end
                end
            end
        end

        function DepBox:RefreshPosition()
        end

        function DepBox:SetOpen()
        end

        function DepBox:SetupDependencies(Dependencies)
            DepBox.Dependencies = Dependencies

            local function GetDepValue(Dep)
                local Source = Dep[1]
                -- String flag name.
                if type(Source) == "string" then
                    return Library.Flags[Source]
                end
                -- Virtual toggle object ({ Type = "Toggle", Value = bool }).
                if type(Source) == "table" and Source.Value ~= nil then
                    return Source.Value
                end
                -- Toggle/element object with .Value property.
                if type(Source) == "table" and type(Source.Flag) == "string" then
                    return Library.Flags[Source.Flag]
                end
                return nil
            end

            local function Update()
                local Visible = true
                for Index, Dep in next, Dependencies do
                    if GetDepValue(Dep) ~= Dep[2] then
                        Visible = false
                        break
                    end
                end
                DepBox:SetVisible(Visible)
            end

            -- Listen for flag changes via polling on heartbeat.
            local LastValues = {}
            Library:Connect(RunService.Heartbeat, function()
                local Changed = false
                for Index, Dep in next, Dependencies do
                    local Key = type(Dep[1]) == "string" and Dep[1]
                        or (type(Dep[1]) == "table" and Dep[1].Flag)
                        or tostring(Dep[1])
                    local CurrentValue = GetDepValue(Dep)
                    if LastValues[Key] ~= CurrentValue then
                        LastValues[Key] = CurrentValue
                        Changed = true
                    end
                end
                if Changed then
                    Update()
                end
            end, "DepBox_" .. tostring(Items["DepBox"].Instance))

            Update()
        end

        -- Forward element methods so depbox acts like a section.
        setmetatable(DepBox, {__index = Library.Sections})

        DepBox.Section = DepBox
        if self.Elements then
            self.Elements[#self.Elements + 1] = DepBox
        end

        return DepBox
    end

    -- Divider: horizontal separator line.
    Library.Sections.Divider = function(self)
        local Divider = {
            Section = self,
        }

        local DividerFrame = Instances:Create("Frame", {
            Parent = Divider.Section.Items["Content"].Instance,
            Name = "\0",
            BackgroundTransparency = 0.7,
            Size = UDim2New(1, 0, 0, 1),
            BorderSizePixel = 0,
            BackgroundColor3 = FromRGB(60, 60, 65),
        })

        DividerFrame:AddToTheme({ BackgroundColor3 = "Outline" })

        Divider.Items = { ["Divider"] = DividerFrame }
        Divider.UiItems = Divider.Items
        Divider.Instance = DividerFrame.Instance

        function Divider:RefreshPosition()
        end

        function Divider:SetOpen()
        end

        if self.Elements then
            self.Elements[#self.Elements + 1] = Divider
        end

        return Divider
    end

    -- TabBox: tabbed container within a section.
    Library.Sections.TabBox = function(self)
        local TabBox = {
            Window = self.Window,
            Page = self.Page,
            Section = self,
            Tabs = {},
            TabOrder = {},
            ActiveTab = nil,
            Items = {},
            Elements = {},
        }

        local Items = {} do
            Items["TabBox"] = Instances:Create("Frame", {
                Parent = TabBox.Section.Items["Content"].Instance,
                Name = "\0",
                BackgroundTransparency = 1,
                Size = UDim2New(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BorderSizePixel = 0,
            })

            -- Tab header (same style as Keybind Modes).
            Items["TabHeader"] = Instances:Create("Frame", {
                Parent = Items["TabBox"].Instance,
                Name = "\0",
                BackgroundTransparency = 0,
                Size = UDim2New(1, 0, 0, 25),
                BorderSizePixel = 0,
                ZIndex = 3,
                BackgroundColor3 = FromRGB(27, 26, 29),
            })

            Items["TabHeader"]:AddToTheme({ BackgroundColor3 = "Element" })

            Instances:Create("UICorner", {
                Parent = Items["TabHeader"].Instance,
                Name = "\0",
                CornerRadius = UDimNew(0, 5),
            })

            -- Sliding accent background (same as Keybind Background).
            Items["TabAccent"] = Instances:Create("Frame", {
                Parent = Items["TabHeader"].Instance,
                Name = "\0",
                Size = UDim2New(0.33, 0, 1, 0),
                Position = UDim2New(0, 0, 0, 0),
                BorderSizePixel = 0,
                ZIndex = 3,
                BackgroundTransparency = 0,
                BackgroundColor3 = FromRGB(255, 255, 255),
            })

            Instances:Create("UICorner", {
                Parent = Items["TabAccent"].Instance,
                Name = "\0",
                CornerRadius = UDimNew(0, 5),
            })

            Instances:Create("UIGradient", {
                Parent = Items["TabAccent"].Instance,
                Name = "\0",
                Rotation = -115,
                Color = RGBSequence{RGBSequenceKeypoint(0, FromRGB(255, 255, 255)), RGBSequenceKeypoint(1, FromRGB(166, 166, 166))},
            }):AddToTheme({Color = function()
                return RGBSequence{RGBSequenceKeypoint(0, Library.Theme.Accent), RGBSequenceKeypoint(1, Library.Theme.AccentGradient)}
            end})

            -- Tab content area.
            Items["TabContent"] = Instances:Create("Frame", {
                Parent = Items["TabBox"].Instance,
                Name = "\0",
                BackgroundTransparency = 1,
                Size = UDim2New(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                Position = UDim2New(0, 0, 0, 30),
                BorderSizePixel = 0,
            })
        end

        TabBox.Items = Items
        TabBox.UiItems = Items
        TabBox.Instance = Items["TabBox"].Instance

        function TabBox:AddTab(Name)
            local Tab = {
                Window = TabBox.Window,
                Page = TabBox.Page,
                Section = nil,
                Name = Name,
                Items = {},
                Elements = {},
                Active = false,
            }

            -- Track insertion order.
            local TabIndex = #TabBox.TabOrder
            TableInsert(TabBox.TabOrder, Name)
            local TotalTabs = #TabBox.TabOrder

            -- Calculate position (absolute, no UIListLayout).
            local TabWidth = 1 / TotalTabs

            local TabButton = Instances:Create("TextButton", {
                Parent = Items["TabHeader"].Instance,
                Name = "\0",
                Text = Name,
                FontFace = Library.Font,
                TextSize = 14,
                TextColor3 = FromRGB(240, 240, 240),
                TextTransparency = 0.2,
                BackgroundTransparency = 1,
                Size = UDim2New(TabWidth, 0, 1, 0),
                Position = UDim2New(TabWidth * TabIndex, 0, 0, -1),
                BorderSizePixel = 0,
                AutoButtonColor = false,
                ZIndex = 4,
            })

            TabButton:AddToTheme({ TextColor3 = function()
                return Library.Theme.Text
            end })

            -- Tab content frame.
            local TabContentFrame = Instances:Create("Frame", {
                Parent = Items["TabContent"].Instance,
                Name = "\0",
                BackgroundTransparency = 1,
                Size = UDim2New(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BorderSizePixel = 0,
                Visible = false,
            })

            Instances:Create("UIListLayout", {
                Parent = TabContentFrame.Instance,
                Name = "\0",
                Padding = UDimNew(0, 5),
                SortOrder = Enum.SortOrder.LayoutOrder,
            })

            Tab.Items = {
                ["Button"] = TabButton,
                ["Content"] = TabContentFrame,
            }
            Tab.Section = Tab
            Tab.Instance = TabContentFrame.Instance

            setmetatable(Tab, { __index = Library.Sections })

            TabButton:Connect("MouseButton1Down", function()
                TabBox:SwitchTab(Name)
            end)

            TabBox.Tabs[Name] = Tab

            -- Reposition all existing buttons for new total.
            for i, TabName in next, TabBox.TabOrder do
                local T = TabBox.Tabs[TabName]
                if T then
                    local TabW = 1 / TotalTabs
                    T.Items["Button"].Instance.Size = UDim2New(TabW, 0, 1, 0)
                    T.Items["Button"].Instance.Position = UDim2New(TabW * (i - 1), 0, 0, -1)
                end
            end

            if not TabBox.ActiveTab then
                TabBox:SwitchTab(Name, true)
            else
                -- Re-switch to active tab to recalculate accent size with new total.
                TabBox:SwitchTab(TabBox.ActiveTab, true)
            end

            return Tab
        end

        function TabBox:RefreshPosition()
        end

        function TabBox:SetOpen()
        end

        function TabBox:SwitchTab(Name, Instant)
            local TotalTabs = #TabBox.TabOrder
            local TabIndex = 0

            for i, TabName in next, TabBox.TabOrder do
                if TabName == Name then
                    TabIndex = i - 1
                    break
                end
            end

            local TabWidth = 1 / MathClamp(TotalTabs, 1, 100)

            if Instant then
                -- Set instantly (used during AddTab to avoid stale tween).
                Items["TabAccent"].Instance.Position = UDim2New(TabWidth * TabIndex, 0, 0, 0)
                Items["TabAccent"].Instance.Size = UDim2New(TabWidth, 0, 1, 0)
            else
                -- Slide accent (same as Keybind SetMode).
                Items["TabAccent"]:Tween(TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                    Position = UDim2New(TabWidth * TabIndex, 0, 0, 0),
                    Size = UDim2New(TabWidth, 0, 1, 0),
                })
            end

            -- Update button colors (same as Keybind SetMode).
            for Index, TabName in next, TabBox.TabOrder do
                local Tab = TabBox.Tabs[TabName]
                local IsActive = TabName == Name
                Tab.Active = IsActive
                Tab.Items["Content"].Instance.Visible = IsActive

                if IsActive then
                    Tab.Items["Button"]:ChangeItemTheme({TextColor3 = function()
                        return FromRGB(0, 0, 0)
                    end})
                    if Instant then
                        Tab.Items["Button"].Instance.TextColor3 = FromRGB(0, 0, 0)
                    else
                        Tab.Items["Button"]:Tween(nil, {TextColor3 = FromRGB(0, 0, 0)})
                    end
                else
                    Tab.Items["Button"]:ChangeItemTheme({TextColor3 = function()
                        return Library.Theme.Text
                    end})
                    if Instant then
                        Tab.Items["Button"].Instance.TextColor3 = Library.Theme.Text
                    else
                        Tab.Items["Button"]:Tween(nil, {TextColor3 = Library.Theme.Text})
                    end
                end
            end

            TabBox.ActiveTab = Name
        end

        if self.Elements then
            self.Elements[#self.Elements + 1] = TabBox
        end

        return TabBox
    end

    -- Button chaining: add a side-by-side button to an existing button.
    local OriginalButton = Library.Sections.Button
    Library.Sections.Button = function(self, Data)
        local Button = OriginalButton(self, Data)

        function Button:AddButton(SubData)
            -- Find the button frame and convert to horizontal layout.
            local ButtonFrame = Button.Items and Button.Items["Button"]
            if not ButtonFrame then return Button end

            local ParentFrame = ButtonFrame.Instance.Parent

            -- Create a container for side-by-side buttons if not already done.
            if not Button._ChainContainer then
                local Container = Instances:Create("Frame", {
                    Parent = ParentFrame,
                    Name = "\0",
                    BackgroundTransparency = 1,
                    Size = UDim2New(1, 0, 0, 35),
                    BorderSizePixel = 0,
                })

                Instances:Create("UIListLayout", {
                    Parent = Container.Instance,
                    Name = "\0",
                    FillDirection = Enum.FillDirection.Horizontal,
                    Padding = UDimNew(0, 5),
                    SortOrder = Enum.SortOrder.LayoutOrder,
                })

                -- Reparent original button.
                ButtonFrame.Instance.Parent = Container.Instance
                ButtonFrame.Instance.Size = UDim2New(0.5, -3, 1, 0)

                Button._ChainContainer = Container
            end

            -- Create sub-button inside container (exact same structure as primary button).
            local SubButton = Instances:Create("TextButton", {
                Parent = Button._ChainContainer.Instance,
                Name = "\0",
                FontFace = Library.Font,
                TextColor3 = FromRGB(0, 0, 0),
                BorderColor3 = FromRGB(0, 0, 0),
                Text = "",
                AutoButtonColor = false,
                BorderSizePixel = 0,
                Size = UDim2New(0.5, -3, 1, 0),
                ZIndex = 2,
                TextSize = 14,
                BackgroundColor3 = FromRGB(27, 26, 29),
            })
            SubButton:AddToTheme({ BackgroundColor3 = "Element" })

            local SubAccent = Instances:Create("Frame", {
                Parent = SubButton.Instance,
                Name = "\0",
                Size = UDim2New(0, 0, 0, 0),
                BorderColor3 = FromRGB(0, 0, 0),
                ZIndex = 2,
                BorderSizePixel = 0,
                BackgroundTransparency = 1,
                BackgroundColor3 = FromRGB(255, 255, 255),
                AnchorPoint = Vector2New(0.5, 0.5),
                Position = UDim2New(0.5, 0, 0.5, 0),
            })

            local SubGradient = Instances:Create("UIGradient", {
                Parent = SubAccent.Instance,
                Name = "\0",
                Enabled = true,
                Rotation = -115,
                Color = RGBSequence{RGBSequenceKeypoint(0, FromRGB(255, 255, 255)), RGBSequenceKeypoint(1, FromRGB(143, 143, 143))},
            })
            SubGradient:AddToTheme({Color = function()
                return RGBSequence{RGBSequenceKeypoint(0, Library.Theme.Accent), RGBSequenceKeypoint(1, Library.Theme.AccentGradient)}
            end})

            Instances:Create("UICorner", {
                Parent = SubAccent.Instance,
                Name = "\0",
                CornerRadius = UDimNew(0, 4),
            })

            Instances:Create("UICorner", {
                Parent = SubButton.Instance,
                Name = "\0",
                CornerRadius = UDimNew(0, 4),
            })

            local SubText = Instances:Create("TextLabel", {
                Parent = SubButton.Instance,
                Name = "\0",
                FontFace = Library.Font,
                TextColor3 = Library.Theme.Text,
                TextTransparency = 0.3,
                Text = SubData.Name or "Button",
                AutomaticSize = Enum.AutomaticSize.X,
                Size = UDim2New(0, 0, 0, 15),
                AnchorPoint = Vector2New(0.5, 0.5),
                BorderSizePixel = 0,
                BackgroundTransparency = 1,
                Position = UDim2New(0.5, 0, 0.5, 0),
                BorderColor3 = FromRGB(0, 0, 0),
                ZIndex = 2,
                TextSize = 14,
                BackgroundColor3 = FromRGB(255, 255, 255),
            })
            SubText:AddToTheme({ TextColor3 = "Text" })

            -- Hover.
            SubButton:OnHover(function()
                SubAccent:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2New(1, 0, 1, 0), BackgroundTransparency = 0})
                SubText:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextColor3 = FromRGB(0, 0, 0), TextTransparency = 0})
            end)

            SubButton:OnHoverLeave(function()
                SubAccent:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2New(0, 0, 0, 0), BackgroundTransparency = 1})
                SubText:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextColor3 = Library.Theme.Text, TextTransparency = 0.3})
            end)

            -- Press.
            SubButton:Connect("MouseButton1Down", function()
                SubButton:ChangeItemTheme({BackgroundColor3 = "Accent"})
                SubButton:Tween(nil, {BackgroundColor3 = Library.Theme.Accent})
                SubText:Tween(nil, {TextColor3 = Library.Theme.Text, TextTransparency = 0})

                task.wait(0.2)

                Library:SafeCall(SubData.Callback or SubData.callback or function() end)
                SubButton:ChangeItemTheme({BackgroundColor3 = "Element"})
                SubButton:Tween(nil, {BackgroundColor3 = Library.Theme.Element})

                local StillHovering = SubButton.Instance.GuiState == Enum.GuiState.Hover
                if StillHovering then
                    SubAccent:Tween(TweenInfo.new(Library.Tween.Time + 0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Size = UDim2New(1, 0, 1, 0), BackgroundTransparency = 0})
                    SubText:Tween(TweenInfo.new(Library.Tween.Time, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextColor3 = FromRGB(0, 0, 0), TextTransparency = 0})
                else
                    SubText:Tween(nil, {TextColor3 = Library.Theme.Text, TextTransparency = 0.3})
                end
            end)

            local SubButtonObj = {
                Window = Button.Window,
                Page = Button.Page,
                Section = Button.Section,
                Name = SubData.Name or SubData.name or "Button",
                Items = { ["Button"] = SubButton },
                UiItems = { ["Button"] = SubButton },
            }
            SubButtonObj.AddButton = Button.AddButton
            SubButtonObj._ChainContainer = Button._ChainContainer

            if Button.Section and Button.Section.Elements then
                Button.Section.Elements[#Button.Section.Elements + 1] = SubButtonObj
            end

            return SubButtonObj
        end

        return Button
    end

    Library.CreateSettingsPage = function(self, Window, KeybindList)
        local Page = Window:Page({Name = "Settings", Icon = "122669828593160"})

        local ConfigsSection = Page:Section({Name = "Configs", Side = 2}) do
            local ConfigName
            local ConfigSelected

            local ConfigsDropdown = ConfigsSection:Listbox({
                Flag = "ConfigsList",
                Items = { },
                Multi = false,
                Callback = function(Value)
                    ConfigSelected = Value
                end
            })

            ConfigsSection:Textbox({
                Flag = "ConfigsName",
                Placeholder = "Name",
                Numeric = false,
                Finished = true,
                Callback = function(Value)
                    ConfigName = Value
                end
            })

            ConfigsSection:Button({
                Name = "Create",
                Callback = function()
                    if ConfigName and ConfigName ~= "" then
                        if not isfile(Library.Folders.Configs .. "/" .. ConfigName .. ".json") then
                            writefile(Library.Folders.Configs .. "/" .. ConfigName .. ".json", Library:GetConfig())
                            Library:RefreshConfigsList(ConfigsDropdown)
                        end
                    end
                end
            })

            ConfigsSection:Button({
                Name = "Delete",
                Callback = function()
                    if ConfigSelected then
                        Library:DeleteConfig(ConfigSelected)
                        Library:RefreshConfigsList(ConfigsDropdown)
                    end
                end
            })

            ConfigsSection:Button({
                Name = "Load",
                Callback = function()
                    if ConfigSelected then
                        Library:LoadConfig(readfile(Library.Folders.Configs .. "/" .. ConfigSelected))
                    end
                end
            })

            ConfigsSection:Button({
                Name = "Save",
                Callback = function()
                    if ConfigSelected then
                        writefile(Library.Folders.Configs .. "/" .. ConfigSelected, Library:GetConfig())
                    end
                end
            })

            ConfigsSection:Button({
                Name = "Refresh",
                Callback = function()
                    Library:RefreshConfigsList(ConfigsDropdown)
                end
            })
        end

        return Page
    end
end

getgenv().Library = Library
return Library
end)
__bundle_register("Modules/ModuleManager", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Module manager.
---@note: All globals get executed first but never ran. This gets set in the global environment of every future module after.
local ModuleManager = { Modules = {}, Globals = {} }

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- State.
local Fs, Gfs
local Tdetach = {}

---Initialize module filesystem.
---@param FolderName string
function ModuleManager.Init(FolderName)
	local Filesystem = require("Utility/Filesystem")
	local BaseFs = Filesystem.new(FolderName)
	Fs = Filesystem.new(BaseFs:Append("Modules"))
	Gfs = Filesystem.new(Fs:Append("Globals"))
end

---Execute module function.
---@param Lf function
---@param Id string
---@param File string?
---@param Global boolean
function ModuleManager.Execute(Lf, Id, File, Global)
	-- Lazy-load dependencies to avoid circular requires.
	local Action = require("Timings/Action")
	local Timing = require("Timings/Timing")
	local PartTiming = require("Timings/PartTiming")
	local Task = require("Defenders/Task")
	local Maid = require("Utility/Maid")
	local Signal = require("Utility/Signal")
	local TaskSpawner = require("Utility/TaskSpawner")
	local HitboxOptions = require("Defenders/HitboxOptions")
	local RepeatInfo = require("Defenders/RepeatInfo")
	local Latency = require("Core/Latency")
	local Configuration = require("Utility/Configuration")
	local Remotes = require("Core/Remotes")
	local StateChecker = require("Core/StateChecker")

	-- Lazy-load Defense to avoid cyclic dependency.
	local Defense = require("Core/Defense")

	-- Set function environment to allow for internal modules.
	getfenv(Lf).Timing = Timing
	getfenv(Lf).PartTiming = PartTiming
	getfenv(Lf).Defense = Defense
	getfenv(Lf).Action = Action
	getfenv(Lf).Task = Task
	getfenv(Lf).Maid = Maid
	getfenv(Lf).Signal = Signal
	getfenv(Lf).TaskSpawner = TaskSpawner
	getfenv(Lf).Logger = Logger
	getfenv(Lf).HitboxOptions = HitboxOptions
	getfenv(Lf).RepeatInfo = RepeatInfo
	getfenv(Lf).Latency = Latency
	getfenv(Lf).Configuration = Configuration
	getfenv(Lf).Remotes = Remotes
	getfenv(Lf).StateChecker = StateChecker

	-- Load globals if we should.
	for Name, Entry in next, (not Global) and ModuleManager.Globals or {} do
		getfenv(Lf)[Name] = Entry
	end

	-- Run executable function to initialize it.
	local Success, Result = pcall(Lf)
	if not Success then
		return Logger.Warn("Module '%s' failed to load due to error '%s' while executing.", File or Id, Result)
	end

	if Global and typeof(Result) ~= "table" then
		return Logger.Warn("Global module '%s' is invalid because it does not return a table.", File or Id)
	end

	-- Output table.
	local Output = Global and ModuleManager.Globals or ModuleManager.Modules

	-- Get the result as a function.
	Output[Id] = Result

	-- If this is a global, the result is a table, and it has a detach function, store it for later.
	if typeof(Result) == "table" and typeof(Result.Detach) == "function" then
		Tdetach[#Tdetach + 1] = Result.Detach
	end
end

---Load file modules from filesystem.
---@param Tfs table The filesystem to load from.
---@param Global boolean Whether we're loading global modules or not.
function ModuleManager.Load(Tfs, Global)
	for Index, File in next, Tfs:List(false) do
		-- Check if it is .lua.
		if string.sub(File, #File - 3, #File) ~= ".lua" then
			continue
		end

		-- Get string to load.
		local Ls = Tfs:Read(File)

		-- Get function that we can execute.
		local Lf, Lr = loadstring(Ls)
		if not Lf then
			Logger.Warn("Module file '%s' failed to load due to error '%s' while loading.", File, Lr)
			continue
		end

		ModuleManager.Execute(Lf, string.sub(File, 1, #File - 4), File, Global)
	end
end

---Load a single global module from filesystem.
---@param Id string
---@param SearchGameFolders boolean?
---@return boolean
function ModuleManager.LoadGlobal(Id, SearchGameFolders)
	if not Gfs then
		Logger.Warn("ModuleManager.LoadGlobal - Not initialized. Call ModuleManager.Init() first.")
		return false
	end

	local File = string.sub(Id, #Id - 3, #Id) == ".lua" and Id or Id .. ".lua"
	local Ls = Gfs:TryRead(File)

	if not Ls and SearchGameFolders then
		local BasePath = Gfs._Path:match("^(.-)[/\\][^/\\]+[/\\]Modules[/\\]Globals$")
		if BasePath and isfolder(BasePath) then
			local Success, Folders = pcall(listfiles, BasePath)
			if Success and Folders then
				table.sort(Folders)

				for Pass = 1, 2 do
					for Index, FolderPath in next, Folders do
						if not isfolder(FolderPath) then
							continue
						end

						local FolderPlaceId = tostring(FolderPath):match("%- (%d+)$")
						local MatchesCurrentPlace = FolderPlaceId == tostring(game.PlaceId)
						if Pass == 1 and not MatchesCurrentPlace then
							continue
						end

						if Pass == 2 and MatchesCurrentPlace then
							continue
						end

						local Candidate = FolderPath .. "\\Modules\\Globals\\" .. File
						local ReadSuccess, Content = pcall(readfile, Candidate)
						if not ReadSuccess or not Content then
							continue
						end

						Ls = Content
						break
					end

					if Ls then
						break
					end
				end
			end
		end
	end

	if not Ls then
		return false
	end

	-- Get function that we can execute.
	local Lf, Lr = loadstring(Ls)
	if not Lf then
		Logger.Warn("Module file '%s' failed to load due to error '%s' while loading.", File, Lr)
		return false
	end

	ModuleManager.Execute(Lf, string.sub(File, 1, #File - 4), File, true)
	return ModuleManager.Globals[string.sub(File, 1, #File - 4)] ~= nil
end

---List loaded modules.
---@return string[]
function ModuleManager.Loaded()
	local Out = {}

	for File, _ in next, ModuleManager.Modules do
		table.insert(Out, File)
	end

	return Out
end

---Detach functions.
function ModuleManager.Detach()
	for Index, DetachFn in next, Tdetach do
		DetachFn()
	end

	-- Clear detach table.
	Tdetach = {}
end

---Refresh ModuleManager.
function ModuleManager.Refresh()
	if not Fs or not Gfs then
		return Logger.Warn("ModuleManager.Refresh - Not initialized. Call ModuleManager.Init() first.")
	end

	local Timestamp = os.clock()

	-- Detach all modules.
	ModuleManager.Detach()

	-- Reset current list.
	ModuleManager.Modules = {}
	ModuleManager.Globals = {}

	-- Load all globals in our filesystem.
	ModuleManager.Load(Gfs, true)

	-- Load all modules in our filesystem.
	ModuleManager.Load(Fs, false)

	-- Count modules and globals.
	local ModuleCount = 0
	local GlobalCount = 0

	for _ in next, ModuleManager.Modules do
		ModuleCount = ModuleCount + 1
	end

	for _ in next, ModuleManager.Globals do
		GlobalCount = GlobalCount + 1
	end

	Logger.Notify(
		"Modules refreshed with %i modules and %i globals in %.2f seconds.",
		ModuleCount,
		GlobalCount,
		os.clock() - Timestamp
	)
end

-- Return ModuleManager module.
return ModuleManager
end)
__bundle_register("Timings/Action", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Action
---@field _type string
---@field _when number When the action will occur in miliseconds. Never access directly.
---@field hitbox Vector3 The hitbox of the action.
---@field ihbc boolean Ignore hitbox check.
---@field name string The name of the action.
---@field tp number Time position. Never accessible unless inside of a module or inside of real code. This is never serialized.
local Action = {}
Action.__index = Action

---Getter for when in seconds.
---@return number
function Action:When()
	return self._when / 1000
end

---Load from partial values.
---@param Values table
function Action:Load(Values)
	if typeof(Values._type) == "string" then
		self._type = Values._type
	end

	if typeof(Values.when) == "number" then
		self._when = Values.when
	end

	if typeof(Values.name) == "string" then
		self.name = Values.name
	end

	if typeof(Values.hitbox) == "table" then
		self.hitbox = Vector3.new(Values.hitbox.X, Values.hitbox.Y, Values.hitbox.Z)
	end

	if typeof(Values.ihbc) == "boolean" then
		self.ihbc = Values.ihbc
	end
end

---Equals check.
---@param Other Action
---@return boolean
function Action:Equals(Other)
	if self._type ~= Other._type then
		return false
	end

	if self._when ~= Other._when then
		return false
	end

	if self.name ~= Other.name then
		return false
	end

	if self.hitbox ~= Other.hitbox then
		return false
	end

	if self.ihbc ~= Other.ihbc then
		return false
	end

	return true
end

---Clone action.
---@return Action
function Action:Clone()
	local ClonedAction = Action.new()

	ClonedAction._type = self._type
	ClonedAction._when = self._when
	ClonedAction.name = self.name
	ClonedAction.hitbox = self.hitbox
	ClonedAction.ihbc = self.ihbc

	return ClonedAction
end

---Return a serializable table.
---@return table
function Action:Serialize()
	return {
		_type = self._type,
		when = self._when,
		name = self.name,
		hitbox = {
			X = self.hitbox.X,
			Y = self.hitbox.Y,
			Z = self.hitbox.Z,
		},
		ihbc = self.ihbc,
	}
end

---Create new Action object.
---@param Values table?
---@return Action
function Action.new(Values)
	local Self = setmetatable({}, Action)

	Self._type = "N/A"
	Self._when = 0
	Self.name = ""
	Self.hitbox = Vector3.zero
	Self.ihbc = false
	Self.tp = 0

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return Action module.
return Action
end)
__bundle_register("Timings/ActionContainer", function(require, _LOADED, __bundle_register, __bundle_modules)
local Action = require("Timings/Action")

---@class ActionContainer
---@field _Data table<string, Action>
local ActionContainer = {}
ActionContainer.__index = ActionContainer

---Clone action container.
---@return ActionContainer
function ActionContainer:Clone()
	local ClonedContainer = ActionContainer.new()

	for Index, ActionRef in next, self._Data do
		ClonedContainer:Push(ActionRef:Clone())
	end

	return ClonedContainer
end

---Equal check.
---@param Other ActionContainer
---@return boolean
function ActionContainer:Equals(Other)
	if self:Count() ~= Other:Count() then
		return false
	end

	for Name, ActionRef in next, self._Data do
		local OtherAction = Other:Find(Name)
		if not OtherAction then
			return false
		end

		if not ActionRef:Equals(OtherAction) then
			return false
		end
	end

	return true
end

---Find a action from name.
---@param Name string
---@return Action?
function ActionContainer:Find(Name)
	return self._Data[Name]
end

---Remove a action from the list.
---@param ActionRef Action
function ActionContainer:Remove(ActionRef)
	self._Data[ActionRef.name] = nil

	local Idx = table.find(self._Stack, ActionRef)
	if not Idx then
		return
	end

	table.remove(self._Stack, Idx)
end

---Push a action to the list.
---@param ActionRef Action
function ActionContainer:Push(ActionRef)
	local Name = ActionRef.name

	---@note: Action array keys must all be unique.
	if self._Data[Name] then
		return error(string.format("Action name '%s' already exists in container.", Name))
	end

	self._Data[Name] = ActionRef

	table.insert(self._Stack, ActionRef)
end

---Load from partial values.
---@param Values table
function ActionContainer:Load(Values)
	for Index, Data in next, Values do
		self:Push(Action.new(Data))
	end
end

---List all action names.
---@return string[]
function ActionContainer:Names()
	local NameList = {}

	for Name, _ in next, self._Data do
		table.insert(NameList, Name)
	end

	return NameList
end

---Get action stack.
---@return Action[]
function ActionContainer:Stack()
	return self._Stack
end

---Get action count.
---@return number
function ActionContainer:Count()
	return #self._Stack
end

---Clear actions.
function ActionContainer:Clear()
	self._Data = {}
	self._Stack = {}
end

---Get action data.
---@return table<string, Action>
function ActionContainer:Get()
	return self._Data
end

---Return a serializable table.
---@return table
function ActionContainer:Serialize()
	local Data = {}

	for I = 1, #self._Stack do
		Data[I] = self._Stack[I]:Serialize()
	end

	return Data
end

---Create new ActionContainer object.
---@param Values table?
---@return ActionContainer
function ActionContainer.new(Values)
	local Self = setmetatable({}, ActionContainer)

	Self._Data = {}
	Self._Stack = {}

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return ActionContainer module.
return ActionContainer
end)
__bundle_register("Timings/AnimationTiming", function(require, _LOADED, __bundle_register, __bundle_modules)
local Timing = require("Timings/Timing")

---@class AnimationTiming: Timing
---@field _id string Animation ID.
---@field ha boolean Flag to see whether or not this timing can be cancelled by a hit.
---@field iae boolean Flag to see whether or not this timing should ignore animation end.
---@field phd boolean Past hitbox detection.
---@field pfh boolean Predict hitboxes facing.
---@field phds number History seconds for past hitbox detection.
---@field pfht number Extrapolation time for hitbox prediction.
---@field ieae boolean Flag to see whether or not this timing should ignore early animation end.
---@field mat number Max animation timeout in milliseconds.
---@field dp boolean Disable prediction.
---@field imb boolean Ignore block. Hidden option.
---@field ffh boolean Force facing hitbox to the user. Hidden option.
local AnimationTiming = setmetatable({}, { __index = Timing })
AnimationTiming.__index = AnimationTiming

---Timing ID.
---@return string
function AnimationTiming:Id()
	return self._id
end

---Equals check.
---@param Other AnimationTiming
function AnimationTiming:Equals(Other)
	if not Timing.Equals(self, Other) then return false end
	if self.ha ~= Other.ha then return false end
	if self.iae ~= Other.iae then return false end
	if self.ieae ~= Other.ieae then return false end
	if self.mat ~= Other.mat then return false end
	if self.phd ~= Other.phd then return false end
	if self.pfh ~= Other.pfh then return false end
	if self.phds ~= Other.phds then return false end
	if self.pfht ~= Other.pfht then return false end
	if self.dp ~= Other.dp then return false end
	if self.imb ~= Other.imb then return false end
	return true
end

---Load from partial values.
---@param Values table
function AnimationTiming:Load(Values)
	Timing.Load(self, Values)

	if typeof(Values._id) == "string" then
		self._id = Values._id
	end

	if typeof(Values.ha) == "boolean" then
		self.ha = Values.ha
	end

	if typeof(Values.iae) == "boolean" then
		self.iae = Values.iae
	end

	if typeof(Values.ieae) == "boolean" then
		self.ieae = Values.ieae
	end

	if typeof(Values.mat) == "number" then
		self.mat = Values.mat
	end

	if typeof(Values.phd) == "boolean" then
		self.phd = Values.phd
	end

	if typeof(Values.pfh) == "boolean" then
		self.pfh = Values.pfh
	end

	if typeof(Values.phds) == "number" then
		self.phds = Values.phds
	end

	if typeof(Values.pfht) == "number" then
		self.pfht = Values.pfht
	end

	if typeof(Values.dp) == "boolean" then
		self.dp = Values.dp
	end

	if typeof(Values.imb) == "boolean" then
		self.imb = Values.imb
	end
end

---Clone timing.
---@return AnimationTiming
function AnimationTiming:Clone()
	local ClonedTiming = setmetatable(Timing.Clone(self), AnimationTiming)

	ClonedTiming._id = self._id
	ClonedTiming.ha = self.ha
	ClonedTiming.iae = self.iae
	ClonedTiming.ieae = self.ieae
	ClonedTiming.mat = self.mat
	ClonedTiming.phd = self.phd
	ClonedTiming.pfh = self.pfh
	ClonedTiming.phds = self.phds
	ClonedTiming.pfht = self.pfht
	ClonedTiming.dp = self.dp
	ClonedTiming.imb = self.imb

	return ClonedTiming
end

---Return a serializable table.
---@return AnimationTiming
function AnimationTiming:Serialize()
	local Serializable = Timing.Serialize(self)

	Serializable._id = self._id
	Serializable.ha = self.ha
	Serializable.iae = self.iae
	Serializable.ieae = self.ieae
	Serializable.mat = self.mat
	Serializable.phd = self.phd
	Serializable.pfh = self.pfh
	Serializable.phds = self.phds
	Serializable.pfht = self.pfht
	Serializable.dp = self.dp
	Serializable.imb = self.imb

	return Serializable
end

---Create a new animation timing.
---@param Values table?
---@return AnimationTiming
function AnimationTiming.new(Values)
	local Self = setmetatable(Timing.new(), AnimationTiming)

	Self.dp = false
	Self._id = ""
	Self.ha = false
	Self.iae = false
	Self.ieae = false
	Self.mat = 2000
	Self.phd = false
	Self.pfh = false
	Self.phds = 0
	Self.pfht = 0.15
	Self.imb = false

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return AnimationTiming module.
return AnimationTiming
end)
