__bundle_register("Timings/PartTiming", function(require, _LOADED, __bundle_register, __bundle_modules)
local Timing = require("Timings/Timing")

---@class PartTiming: Timing
---@field pname string Part name.
---@field uhc boolean Use hitbox CFrame.
local PartTiming = setmetatable({}, { __index = Timing })
PartTiming.__index = PartTiming

---Timing ID.
---@return string
function PartTiming:Id()
	return self.pname
end

---Load from partial values.
---@param Values table
function PartTiming:Load(Values)
	Timing.Load(self, Values)

	if typeof(Values.pname) == "string" then
		self.pname = Values.pname
	end

	if typeof(Values.uhc) == "boolean" then
		self.uhc = Values.uhc
	end
end

---Equals check.
---@param Other PartTiming
---@return boolean
function PartTiming:Equals(Other)
	if not Timing.Equals(self, Other) then return false end
	if self.pname ~= Other.pname then return false end
	if self.uhc ~= Other.uhc then return false end
	return true
end

---Clone timing.
---@return PartTiming
function PartTiming:Clone()
	local ClonedTiming = setmetatable(Timing.Clone(self), PartTiming)

	ClonedTiming.pname = self.pname
	ClonedTiming.uhc = self.uhc

	return ClonedTiming
end

---Return a serializable table.
---@return PartTiming
function PartTiming:Serialize()
	local Serializable = Timing.Serialize(self)

	Serializable.pname = self.pname
	Serializable.uhc = self.uhc

	return Serializable
end

---Create a new part timing.
---@param Values table?
---@return PartTiming
function PartTiming.new(Values)
	local Self = setmetatable(Timing.new(), PartTiming)

	Self.pname = ""
	Self.uhc = false

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return PartTiming module.
return PartTiming
end)
__bundle_register("Timings/SaveManager", function(require, _LOADED, __bundle_register, __bundle_modules)
-- SaveManager module. Per-file JSON timing saves.
local TimingSave = require("Timings/TimingSave")
local TimingContainerPair = require("Timings/TimingContainerPair")
local TimingContainer = require("Timings/TimingContainer")
local AnimationTiming = require("Timings/AnimationTiming")
local PartTiming = require("Timings/PartTiming")
local SoundTiming = require("Timings/SoundTiming")
local EmbeddedTimings = require("Timings/EmbeddedTimings")
local Maid = require("Utility/Maid")
local Signal = require("Utility/Signal")
local Configuration = require("Utility/Configuration")
local Filesystem = require("Utility/Filesystem")
local Logger = require("Utility/Logger")

-- Services.
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")

-- SaveManager module.
local SaveManager = { Lct = nil }

-- Manager filesystems (set during init).
local FsAnimation = nil
local FsSound = nil
local FsPart = nil
local CurrentGamePath = nil

-- Current timing save.
local Config = TimingSave.new()

-- Snapshot of last saved state (serialized JSON strings keyed by timing name).
local LastSaved = { animation = {}, sound = {}, part = {} }
local QueuedAutoSave = false
local AutoSaveToken = 0
local TimingTypes = {
	{ Key = "animation", Folder = "Animation" },
	{ Key = "sound", Folder = "Sound" },
	{ Key = "part", Folder = "Part" },
}

-- Maids.
local SaveMaid = Maid.new()

---Sanitize timing name for use as filename.
---@param Name string
---@return string
local function SanitizeFilename(Name)
	return Name:gsub("[/\\:*?\"<>|]", "_"):sub(1, 80)
end

---Normalize a filesystem path for comparisons.
---@param Path string
---@return string
local function NormalizePath(Path)
	return tostring(Path or ""):gsub("\\", "/")
end

---Get the base folder from a game path.
---@param Path string
---@return string
local function BasePathFromGamePath(Path)
	return tostring(Path or "Epiphyllum"):match("^(.*)[/\\][^/\\]+$") or "Epiphyllum"
end

---Get a folder's trailing Place ID.
---@param Path string
---@return string?
local function FolderPlaceId(Path)
	return tostring(Path or ""):match("%- (%d+)$")
end

---Read aliases from a game folder.
---@param Path string
---@return table
local function ReadAliasList(Path)
	local AliasFile = tostring(Path or "") .. "/aliases.json"
	if not isfile(AliasFile) then return {} end

	local ReadOk, Content = pcall(readfile, AliasFile)
	if not ReadOk or not Content then return {} end

	local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
	if not DecodeOk or typeof(Data) ~= "table" then return {} end

	local Aliases = {}
	for Index, Id in next, Data do
		Aliases[#Aliases + 1] = tostring(Id)
	end

	return Aliases
end

---Collect alias sync target paths.
---@return table
local function AliasSyncPaths()
	if not CurrentGamePath then return {} end

	local BasePath = BasePathFromGamePath(CurrentGamePath)
	if not isfolder(BasePath) then return {} end

	local ListOk, FolderList = pcall(listfiles, BasePath)
	if not ListOk or not FolderList then return {} end

	local CurrentPathKey = NormalizePath(CurrentGamePath)
	local PlaceIds = {}
	local FolderAliases = {}
	local FolderPlaceIds = {}
	local FolderPaths = {}

	local CurrentPlaceId = FolderPlaceId(CurrentGamePath)
	if CurrentPlaceId then
		PlaceIds[CurrentPlaceId] = true
	end

	for Index, AliasId in next, ReadAliasList(CurrentGamePath) do
		PlaceIds[AliasId] = true
	end

	for Index, FolderPath in next, FolderList do
		if not isfolder(FolderPath) then continue end

		local FolderPathKey = NormalizePath(FolderPath)
		FolderPaths[#FolderPaths + 1] = FolderPath
		FolderPlaceIds[FolderPathKey] = FolderPlaceId(FolderPath)
		FolderAliases[FolderPathKey] = ReadAliasList(FolderPath)
	end

	local Changed = true
	while Changed do
		Changed = false

		for Index, FolderPath in next, FolderPaths do
			local FolderPathKey = NormalizePath(FolderPath)
			local PlaceId = FolderPlaceIds[FolderPathKey]
			local Aliases = FolderAliases[FolderPathKey] or {}
			local Connected = PlaceId and PlaceIds[PlaceId] == true

			if not Connected then
				for AliasIndex, AliasId in next, Aliases do
					if PlaceIds[AliasId] then
						Connected = true
						break
					end
				end
			end

			if Connected then
				if PlaceId and not PlaceIds[PlaceId] then
					PlaceIds[PlaceId] = true
					Changed = true
				end

				for AliasIndex, AliasId in next, Aliases do
					if not PlaceIds[AliasId] then
						PlaceIds[AliasId] = true
						Changed = true
					end
				end
			end
		end
	end

	local Targets = {}
	local Seen = {}
	for Index, FolderPath in next, FolderPaths do
		local FolderPathKey = NormalizePath(FolderPath)
		local PlaceId = FolderPlaceIds[FolderPathKey]

		if FolderPathKey ~= CurrentPathKey and PlaceId and PlaceIds[PlaceId] and not Seen[FolderPathKey] then
			Targets[#Targets + 1] = FolderPath
			Seen[FolderPathKey] = true
		end
	end

	return Targets
end

---Create timing filesystems for a game path.
---@param Path string
---@return table
local function TimingFilesystems(Path)
	return {
		animation = Filesystem.new(Path .. "/Timings/Animation"),
		sound = Filesystem.new(Path .. "/Timings/Sound"),
		part = Filesystem.new(Path .. "/Timings/Part"),
	}
end

---Create timing folders for a game path.
---@param Path string
local function EnsureTimingFolders(Path)
	if not isfolder(Path) then makefolder(Path) end
	if not isfolder(Path .. "/Timings") then makefolder(Path .. "/Timings") end

	for Index, TimingType in next, TimingTypes do
		local TypePath = Path .. "/Timings/" .. TimingType.Folder
		if not isfolder(TypePath) then makefolder(TypePath) end
	end
end

---Merge embedded default timings into disk data (disk takes precedence by name).
---@param DiskData table Array of timing tables read from disk.
---@param EmbeddedList table Array of embedded default timing tables.
---@return table
local function MergeEmbedded(DiskData, EmbeddedList)
	local Result = {}
	local SeenNames = {}

	-- Disk timings first (the user's own edits win).
	for Index, Timing in next, DiskData do
		if type(Timing) == "table" and Timing.name then
			SeenNames[Timing.name] = true
		end
		Result[#Result + 1] = Timing
	end

	-- Embedded defaults fill in anything missing.
	for Index, Timing in next, (EmbeddedList or {}) do
		if type(Timing) == "table" and Timing.name and not SeenNames[Timing.name] then
			SeenNames[Timing.name] = true
			Result[#Result + 1] = Timing
		end
	end

	return Result
end

---Read all JSON timing files from a type folder.
---@param TypeFs Filesystem
---@return table
local function ReadTypeFolder(TypeFs)
	local Timings = {}
	local Success, Files = pcall(TypeFs.List, TypeFs)
	if not Success or not Files then return Timings end

	for I = 1, #Files do
		local File = Files[I]
		if File:sub(-5) ~= ".json" then continue end

		local ReadOk, Content = pcall(TypeFs.Read, TypeFs, File)
		if not ReadOk or not Content then continue end

		local DecodeOk, Data = pcall(HttpService.JSONDecode, HttpService, Content)
		if not DecodeOk or typeof(Data) ~= "table" then continue end

		Timings[#Timings + 1] = Data
	end

	return Timings
end

---Delete stale JSON files from a timing folder.
---@param TypeFs Filesystem
---@param CurrentFiles table<string, boolean>
local function DeleteStaleTypeFiles(TypeFs, CurrentFiles)
	local ListOk, Files = pcall(TypeFs.List, TypeFs)
	if ListOk and Files then
		for Index, File in next, Files do
			if File:sub(-5) == ".json" and not CurrentFiles[File] then
				pcall(TypeFs.Delete, TypeFs, File)
			end
		end
	end
end

---Sync a timing folder to the current active timings.
---@param TypeFs Filesystem
---@param Container TimingContainer
---@return number
local function SyncTypeFolder(TypeFs, Container)
	local Count = 0
	local CurrentFiles = {}

	for Index, TimingObj in next, Container.Timings do
		local Serialized = TimingObj:Serialize()
		local EncodeOk, Json = pcall(HttpService.JSONEncode, HttpService, Serialized)
		if not EncodeOk then continue end

		local Filename = SanitizeFilename(Serialized.name or "unnamed") .. ".json"
		CurrentFiles[Filename] = true

		if pcall(TypeFs.Write, TypeFs, Filename, Json) then
			Count = Count + 1
		end
	end

	DeleteStaleTypeFiles(TypeFs, CurrentFiles)

	return Count
end

---Sync all alias timing folders to the current active timings.
---@return number
local function SyncAliasTimings()
	local Count = 0
	local Data = Config:Get()

	for Index, Path in next, AliasSyncPaths() do
		EnsureTimingFolders(Path)
		local Filesystems = TimingFilesystems(Path)

		Count = Count + SyncTypeFolder(Filesystems.animation, Data.animation)
		Count = Count + SyncTypeFolder(Filesystems.sound, Data.sound)
		Count = Count + SyncTypeFolder(Filesystems.part, Data.part)
	end

	return Count
end

---Delete a timing file from its type folder.
---@param TypeFs Filesystem
---@param Name string
---@return boolean
local function DeleteTimingFile(TypeFs, Name)
	local Filename = SanitizeFilename(Name) .. ".json"
	if not TypeFs:File(Filename) then return false end
	local Ok = pcall(TypeFs.Delete, TypeFs, Filename)
	return Ok
end

---Build snapshot of current state (serialized JSON per timing name).
---@return table
local function BuildSnapshot()
	local Snap = { animation = {}, sound = {}, part = {} }

	for Index, TimingObj in next, Config:Get().animation.Timings do
		local Ok, Json = pcall(HttpService.JSONEncode, HttpService, TimingObj:Serialize())
		if Ok then Snap.animation[TimingObj.name] = Json end
	end

	for Index, TimingObj in next, Config:Get().sound.Timings do
		local Ok, Json = pcall(HttpService.JSONEncode, HttpService, TimingObj:Serialize())
		if Ok then Snap.sound[TimingObj.name] = Json end
	end

	for Index, TimingObj in next, Config:Get().part.Timings do
		local Ok, Json = pcall(HttpService.JSONEncode, HttpService, TimingObj:Serialize())
		if Ok then Snap.part[TimingObj.name] = Json end
	end

	return Snap
end

---Delete a timing file by name from a specific type.
---@param Type string "animation", "sound", or "part"
---@param Name string
function SaveManager.Delete(Type, Name)
	local TypeMap = { animation = FsAnimation, sound = FsSound, part = FsPart }
	local TypeFs = TypeMap[Type]
	if TypeFs then
		DeleteTimingFile(TypeFs, Name)
	end

	for Index, Path in next, AliasSyncPaths() do
		local Filesystems = TimingFilesystems(Path)
		local AliasTypeFs = Filesystems[Type]
		if AliasTypeFs then
			DeleteTimingFile(AliasTypeFs, Name)
		end
	end
end

---Save all timings to disk.
---@param Silent boolean? Suppress notification.
---@return number
function SaveManager.SaveAll(Silent)
	local Data = Config:Get()
	local Count = SyncTypeFolder(FsAnimation, Data.animation)
	Count = Count + SyncTypeFolder(FsSound, Data.sound)
	Count = Count + SyncTypeFolder(FsPart, Data.part)
	SyncAliasTimings()

	LastSaved = BuildSnapshot()

	if not Silent then
		Logger.Notify("Saved %d timing(s) to disk.", Count)
	end

	return Count
end

---Save only changed timings since last snapshot.
---@return number
local function SaveChanged()
	local Current = BuildSnapshot()
	local Changed = 0

	-- Type map for iteration.
	local TypeMap = {
		{ Key = "animation", Fs = FsAnimation },
		{ Key = "sound", Fs = FsSound },
		{ Key = "part", Fs = FsPart },
	}

	for I = 1, #TypeMap do
		local Entry = TypeMap[I]
		local CurSnap = Current[Entry.Key]
		local OldSnap = LastSaved[Entry.Key]
		local CurrentFiles = {}

		-- Write new or modified timings.
		for Name, Json in next, CurSnap do
			CurrentFiles[SanitizeFilename(Name) .. ".json"] = true

			if OldSnap[Name] ~= Json then
				local Filename = SanitizeFilename(Name) .. ".json"
				if pcall(Entry.Fs.Write, Entry.Fs, Filename, Json) then
					Changed = Changed + 1
				end
			end
		end

		-- Delete removed timings.
		for Name in next, OldSnap do
			if not CurSnap[Name] then
				DeleteTimingFile(Entry.Fs, Name)
				Changed = Changed + 1
			end
		end

		DeleteStaleTypeFiles(Entry.Fs, CurrentFiles)
	end

	LastSaved = Current
	if Changed > 0 then
		SyncAliasTimings()
	end
	return Changed
end

---Queue a short debounced autosave after a timing edit.
---@param Delay number?
function SaveManager.QueueAutoSave(Delay)
	if Configuration.ExpectToggleValue("EP_PeriodicAutoSave") == false then
		return
	end

	if QueuedAutoSave then
		return
	end

	QueuedAutoSave = true
	AutoSaveToken = AutoSaveToken + 1
	local Token = AutoSaveToken

	task.delay(Delay or 2.0, function()
		if Token ~= AutoSaveToken then
			return
		end

		QueuedAutoSave = false
		local Count = SaveChanged()
		if Count > 0 then
			SaveManager.Lct = os.clock()
			Logger.Notify("Auto-saved %d timing change(s).", Count)
		end
	end)
end

---Get alias sync target paths.
---@return table
function SaveManager.AliasSyncPaths()
	return AliasSyncPaths()
end

---Refresh: re-read all timings from disk.
function SaveManager.Refresh()
	local Timestamp = os.clock()

	local AnimData = MergeEmbedded(ReadTypeFolder(FsAnimation), EmbeddedTimings.animation)
	local SoundData = MergeEmbedded(ReadTypeFolder(FsSound), EmbeddedTimings.sound)
	local PartData = MergeEmbedded(ReadTypeFolder(FsPart), EmbeddedTimings.part)

	Config:Clear()

	pcall(Config.Load, Config, {
		animation = AnimData,
		sound = SoundData,
		part = PartData,
	})

	LastSaved = BuildSnapshot()

	Logger.Notify("Loaded %d timing(s) from disk in %.2fs.", Config:Count(), os.clock() - Timestamp)
end

---Initialize SaveManager.
---@param GamePath string
function SaveManager.Init(GamePath)
	AutoSaveToken = AutoSaveToken + 1
	QueuedAutoSave = false
	SaveManager.Lct = nil
	SaveMaid:Clean()
	Config:Clear()

	-- Set up per-type filesystems.
	local BasePath = GamePath or "Epiphyllum"
	CurrentGamePath = BasePath
	FsAnimation = Filesystem.new(BasePath .. "/Timings/Animation")
	FsSound = Filesystem.new(BasePath .. "/Timings/Sound")
	FsPart = Filesystem.new(BasePath .. "/Timings/Part")

	local PreRenderSignal = Signal.new(RunService.PreRender)

	-- Create internal timing containers (empty by default).
	local InternalAnimationContainer = TimingContainer.new(AnimationTiming)
	InternalAnimationContainer:Load({})

	local InternalPartContainer = TimingContainer.new(PartTiming)
	InternalPartContainer:Load({})

	local InternalSoundContainer = TimingContainer.new(SoundTiming)
	InternalSoundContainer:Load({})

	-- Load all timings from disk, merged with embedded defaults (disk wins).
	local AnimData = MergeEmbedded(ReadTypeFolder(FsAnimation), EmbeddedTimings.animation)
	local SoundData = MergeEmbedded(ReadTypeFolder(FsSound), EmbeddedTimings.sound)
	local PartData = MergeEmbedded(ReadTypeFolder(FsPart), EmbeddedTimings.part)

	pcall(Config.Load, Config, {
		animation = AnimData,
		sound = SoundData,
		part = PartData,
	})

	LastSaved = BuildSnapshot()

	Logger.Warn("SaveManager loaded %d timing(s) (disk + embedded).", Config:Count())

	-- Animation stack.
	SaveManager.As = TimingContainerPair.new(InternalAnimationContainer, Config:Get().animation)

	-- Part stack.
	SaveManager.Ps = TimingContainerPair.new(InternalPartContainer, Config:Get().part)

	-- Sound stack.
	SaveManager.Ss = TimingContainerPair.new(InternalSoundContainer, Config:Get().sound)

	-- Run auto save.
	SaveMaid:Add(PreRenderSignal:Connect("SaveManager_AutoSave", function()
		if not Configuration.ExpectToggleValue("EP_PeriodicAutoSave") then
			return
		end

		if
			SaveManager.Lct
			and os.clock() - SaveManager.Lct < (Configuration.ExpectOptionValue("EP_PeriodicAutoSaveInterval") or 60)
		then
			return
		end

		SaveManager.Lct = os.clock()

		local Count = SaveChanged()
		if Count > 0 then
			Logger.Notify("Auto-saved %d timing change(s).", Count)
		end
	end))
end

---Detach SaveManager.
function SaveManager.Detach()
	AutoSaveToken = AutoSaveToken + 1
	QueuedAutoSave = false

	if Configuration.ExpectToggleValue("EP_PeriodicAutoSave") ~= false then
		SaveChanged()
	end

	SaveMaid:Clean()
end

-- Return SaveManager module.
return SaveManager
end)
__bundle_register("Timings/SoundTiming", function(require, _LOADED, __bundle_register, __bundle_modules)
local Timing = require("Timings/Timing")

---@class SoundTiming: Timing
---@field _id string Sound ID.
---@field alp boolean Allow local player to be hit.
local SoundTiming = setmetatable({}, { __index = Timing })
SoundTiming.__index = SoundTiming

---Timing ID.
---@return string
function SoundTiming:Id()
	return self._id
end

---Equals check.
---@param Other SoundTiming
function SoundTiming:Equals(Other)
	if not Timing.Equals(self, Other) then return false end
	if self._id ~= Other._id then return false end
	if self.alp ~= Other.alp then return false end
	return true
end

---Load from partial values.
---@param Values table
function SoundTiming:Load(Values)
	Timing.Load(self, Values)

	if typeof(Values._id) == "string" then
		self._id = Values._id
	end

	if typeof(Values.alp) == "boolean" then
		self.alp = Values.alp
	end
end

---Clone timing.
---@return SoundTiming
function SoundTiming:Clone()
	local ClonedTiming = setmetatable(Timing.Clone(self), SoundTiming)

	ClonedTiming._id = self._id
	ClonedTiming.alp = self.alp

	return ClonedTiming
end

---Return a serializable table.
---@return SoundTiming
function SoundTiming:Serialize()
	local Serializable = Timing.Serialize(self)

	Serializable._id = self._id
	Serializable.alp = self.alp

	return Serializable
end

---Create a new sound timing.
---@param Values table?
---@return SoundTiming
function SoundTiming.new(Values)
	local Self = setmetatable(Timing.new(), SoundTiming)

	Self._id = ""
	Self.rpue = false
	Self._rsd = 0
	Self._rpd = 0
	Self.alp = false

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return SoundTiming module.
return SoundTiming
end)
__bundle_register("Timings/Timing", function(require, _LOADED, __bundle_register, __bundle_modules)
local ActionContainer = require("Timings/ActionContainer")

---@class Timing
---@field name string
---@field tag string
---@field imdd number Initial minimum distance from position.
---@field imxd number Initial maximum distance from position.
---@field punishable number Punishable window in seconds.
---@field after number After window in seconds.
---@field duih boolean Delay until in hitbox.
---@field actions ActionContainer
---@field hitbox Vector3
---@field umoa boolean Use module over actions.
---@field smn boolean Skip module notification.
---@field srpn boolean Skip repeat notification.
---@field smod string Selected module string.
---@field aatk boolean Allow attacking.
---@field fhb boolean Hitbox facing offset.
---@field hso number Hitbox shift offset. Positive is backwards, negative is forwards.
---@field ndfb boolean No dash fallback.
---@field cbm boolean A non-saved field to indicate whether this was non-part-timing created by a module.
---@field nvfb boolean No vent fallback.
---@field bfht number Block fallback hold time.
---@field pbfb boolean Prefer block fallback.
---@field forced boolean Hidden field which allows us to force tasks to go through.
---@field htype Enum.PartType Shape of hitbox. Never serialized.
---@field rpue boolean Prefer repeat usage.
---@field _rsd number Repeat start delay. Never access directly.
---@field _rpd number Repeat parry delay. Never access directly.
---@field nbfb boolean No block fallback.
local Timing = {}
Timing.__index = Timing

---Getter for repeat start delay in seconds.
---@return number
function Timing:Rsd()
	return self._rsd / 1000
end

---Getter for repeat parry delay in seconds.
---@return number
function Timing:Rpd()
	return self._rpd / 1000
end

---Timing ID. Override me.
---@return string
function Timing:Id()
	return self.name
end

---Set timing ID. Override me.
---@param TimingId string
function Timing:Set(TimingId)
	self.name = TimingId
end

---Load from partial values.
---@param Values table
function Timing:Load(Values)
	if typeof(Values.name) == "string" then
		self.name = Values.name
	end

	if typeof(Values.tag) == "string" then
		self.tag = Values.tag
	end

	if typeof(Values.imdd) == "number" then
		self.imdd = Values.imdd
	end

	if typeof(Values.imxd) == "number" then
		self.imxd = Values.imxd
	end

	if typeof(Values.duih) == "boolean" then
		self.duih = Values.duih
	end

	if typeof(Values.punishable) == "number" then
		self.punishable = Values.punishable
	end

	if typeof(Values.after) == "number" then
		self.after = Values.after
	end

	if typeof(Values.actions) == "table" then
		self.actions:Load(Values.actions)
	end

	if typeof(Values.smn) == "boolean" then
		self.smn = Values.smn
	end

	if typeof(Values.hitbox) == "table" then
		self.hitbox = Vector3.new(Values.hitbox.X or 0, Values.hitbox.Y or 0, Values.hitbox.Z or 0)
	end

	if typeof(Values.umoa) == "boolean" then
		self.umoa = Values.umoa
	end

	if typeof(Values.srpn) == "boolean" then
		self.srpn = Values.srpn
	end

	if typeof(Values.smod) == "string" then
		self.smod = Values.smod
	end

	if typeof(Values.aatk) == "boolean" then
		self.aatk = Values.aatk
	end

	if typeof(Values.fhb) == "boolean" then
		self.fhb = Values.fhb
	end

	if typeof(Values.hso) == "number" then
		self.hso = Values.hso
	end

	if typeof(Values.ndfb) == "boolean" then
		self.ndfb = Values.ndfb
	end

	if typeof(Values.nvfb) == "boolean" then
		self.nvfb = Values.nvfb
	end

	if typeof(Values.bfht) == "number" then
		self.bfht = Values.bfht
	end

	if typeof(Values.rsd) == "string" then
		self._rsd = tonumber(Values.rsd) or 0.0
	end

	if typeof(Values.rpd) == "string" then
		self._rpd = tonumber(Values.rpd) or 0.0
	end

	if typeof(Values.rsd) == "number" then
		self._rsd = Values.rsd
	end

	if typeof(Values.rpd) == "number" then
		self._rpd = Values.rpd
	end

	if typeof(Values.rpue) == "boolean" then
		self.rpue = Values.rpue
	end

	if typeof(Values.nbfb) == "boolean" then
		self.nbfb = Values.nbfb
	end

	if typeof(Values.pbfb) == "boolean" then
		self.pbfb = Values.pbfb
	end
end

---Equals check.
---@param Other Timing
---@return boolean
function Timing:Equals(Other)
	if self.name ~= Other.name then return false end
	if self.tag ~= Other.tag then return false end
	if self.imdd ~= Other.imdd then return false end
	if self.imxd ~= Other.imxd then return false end
	if self.duih ~= Other.duih then return false end
	if self.punishable ~= Other.punishable then return false end
	if self.after ~= Other.after then return false end
	if not self.actions:Equals(Other.actions) then return false end
	if self.smn ~= Other.smn then return false end
	if self.hitbox ~= Other.hitbox then return false end
	if self.umoa ~= Other.umoa then return false end
	if self.hso ~= Other.hso then return false end
	if self.srpn ~= Other.srpn then return false end
	if self.smod ~= Other.smod then return false end
	if self.aatk ~= Other.aatk then return false end
	if self.fhb ~= Other.fhb then return false end
	if self.ndfb ~= Other.ndfb then return false end
	if self.nvfb ~= Other.nvfb then return false end
	if self.bfht ~= Other.bfht then return false end
	if self.rpue ~= Other.rpue then return false end
	if self._rsd ~= Other._rsd then return false end
	if self._rpd ~= Other._rpd then return false end
	if self.nbfb ~= Other.nbfb then return false end
	if self.pbfb ~= Other.pbfb then return false end
	return true
end

---Clone timing.
---@return Timing
function Timing:Clone()
	local ClonedTiming = Timing.new()

	ClonedTiming.name = self.name
	ClonedTiming.tag = self.tag
	ClonedTiming.duih = self.duih
	ClonedTiming.imdd = self.imdd
	ClonedTiming.imxd = self.imxd
	ClonedTiming.smn = self.smn
	ClonedTiming.punishable = self.punishable
	ClonedTiming.after = self.after
	ClonedTiming.actions = self.actions:Clone()
	ClonedTiming.hitbox = self.hitbox
	ClonedTiming.umoa = self.umoa
	ClonedTiming.srpn = self.srpn
	ClonedTiming.smod = self.smod
	ClonedTiming.aatk = self.aatk
	ClonedTiming.fhb = self.fhb
	ClonedTiming.ndfb = self.ndfb
	ClonedTiming.hso = self.hso
	ClonedTiming.nvfb = self.nvfb
	ClonedTiming.bfht = self.bfht
	ClonedTiming.rpue = self.rpue
	ClonedTiming._rsd = self._rsd
	ClonedTiming._rpd = self._rpd
	ClonedTiming.nbfb = self.nbfb
	ClonedTiming.pbfb = self.pbfb

	return ClonedTiming
end

---Return a serializable table.
---@return table
function Timing:Serialize()
	return {
		name = self.name,
		tag = self.tag,
		imdd = self.imdd,
		imxd = self.imxd,
		duih = self.duih,
		punishable = self.punishable,
		smn = self.smn,
		after = self.after,
		actions = self.actions:Serialize(),
		hitbox = {
			X = self.hitbox.X,
			Y = self.hitbox.Y,
			Z = self.hitbox.Z,
		},
		srpn = self.srpn,
		umoa = self.umoa,
		smod = self.smod,
		aatk = self.aatk,
		fhb = self.fhb,
		ndfb = self.ndfb,
		phd = self.phd,
		pfh = self.pfh,
		hso = self.hso,
		nvfb = self.nvfb,
		bfht = self.bfht,
		rpue = self.rpue,
		rsd = self._rsd,
		rpd = self._rpd,
		nbfb = self.nbfb,
		pbfb = self.pbfb,
	}
end

---Create new Timing object.
---@param Values table?
---@return Timing
function Timing.new(Values)
	local Self = setmetatable({}, Timing)

	Self.tag = "Undefined"
	Self.name = "N/A"
	Self.imdd = 0
	Self.imxd = 0
	Self.smn = false
	Self.punishable = 0
	Self.after = 0
	Self.rpue = false
	Self._rsd = 0
	Self._rpd = 0
	Self.duih = false
	Self.actions = ActionContainer.new()
	Self.hitbox = Vector3.zero
	Self.umoa = false
	Self.srpn = false
	Self.smod = "N/A"
	Self.aatk = false
	Self.fhb = true
	Self.ndfb = false
	Self.hso = 0
	Self.nvfb = false
	Self.bfht = 0.3
	Self.nbfb = false
	Self.pbfb = false

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return Timing module.
return Timing
end)
__bundle_register("Timings/TimingContainer", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class TimingContainer
---@field Timings table<string, Timing>
---@field Module Timing
local TimingContainer = {}
TimingContainer.__index = TimingContainer

---Find a timing from name.
---@param Name string
---@return Timing?
function TimingContainer:Find(Name)
	for Index, TimingObj in next, self.Timings do
		if TimingObj.name ~= Name then
			continue
		end

		return TimingObj
	end
end

---List all timings.
---@return Timing[]
function TimingContainer:List()
	local TimingList = {}

	for Index, TimingObj in next, self.Timings do
		TimingList[#TimingList + 1] = TimingObj
	end

	return TimingList
end

---Get names of all timings.
---@return string[]
function TimingContainer:Names()
	local NameList = {}

	for Index, TimingObj in next, self.Timings do
		NameList[#NameList + 1] = TimingObj.name
	end

	table.sort(NameList)

	return NameList
end

---Remove a timing from the list.
---@param TimingObj Timing
function TimingContainer:Remove(TimingObj)
	local Id = TimingObj:Id()
	if not Id then
		return
	end

	self.Timings[Id] = nil
end

---Equals check.
---@param Other TimingContainer
---@return boolean
function TimingContainer:Equals(Other)
	if self:Count() ~= Other:Count() then
		return false
	end

	for Id, TimingObj in next, self.Timings do
		local OtherTiming = Other.Timings[Id]
		if not OtherTiming then
			return false
		end

		if not TimingObj:Equals(OtherTiming) then
			return false
		end
	end

	return true
end

---Clone timing container.
---@return TimingContainer
function TimingContainer:Clone()
	local Container = TimingContainer.new(self.Module)

	for Index, TimingObj in next, self.Timings do
		Container:Push(TimingObj:Clone())
	end

	return Container
end

---Push a timing to the list.
---@param TimingObj Timing
function TimingContainer:Push(TimingObj)
	local Id = TimingObj:Id()
	if not Id then
		return
	end

	---@note: Timing array keys must all be unique.
	if self.Timings[Id] then
		return error(string.format("Timing identifier '%s' already exists in container.", Id))
	end

	---@note: Every timing must have unique names.
	if self:Find(TimingObj.name) then
		return error(string.format("Timing name '%s' already exists in container.", TimingObj.name))
	end

	self.Timings[Id] = TimingObj
end

---Clear all timings.
function TimingContainer:Clear()
	self.Timings = {}
end

---Get timing count.
---@return number
function TimingContainer:Count()
	local CountVal = 0

	for _ in next, self.Timings do
		CountVal = CountVal + 1
	end

	return CountVal
end

---Load from partial values.
---@param Values table
function TimingContainer:Load(Values)
	for Index, Value in next, Values do
		local TimingObj = self.Module.new(Value)
		if not TimingObj then
			continue
		end

		local Id = TimingObj:Id()
		if not Id then
			continue
		end

		---@note: Timing array keys must all be unique. Skip duplicates.
		if self.Timings[Id] then
			continue
		end

		---@note: Every timing must have unique names. Skip duplicates.
		if self:Find(TimingObj.name) then
			continue
		end

		self.Timings[Id] = TimingObj
	end
end

---Return a serializable table.
---@return table
function TimingContainer:Serialize()
	local Out = {}

	for Index, TimingObj in next, self.Timings do
		Out[#Out + 1] = TimingObj:Serialize()
	end

	return Out
end

---Create new TimingContainer object.
---@param Module Timing
---@return TimingContainer
function TimingContainer.new(Module)
	local Self = setmetatable({}, TimingContainer)
	Self.Timings = {}
	Self.Module = Module
	return Self
end

-- Return TimingContainer module.
return TimingContainer
end)
__bundle_register("Timings/TimingContainerPair", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class TimingContainerPair
---@note The configs are always prioritized over the internal timings.
---@field Internal TimingContainer
---@field Config TimingContainer
local TimingContainerPair = {}
TimingContainerPair.__index = TimingContainerPair

---Create new TimingContainerPair object.
---@param Internal TimingContainer
---@param Config TimingContainer
---@return TimingContainerPair
function TimingContainerPair.new(Internal, Config)
	local Self = setmetatable({}, TimingContainerPair)
	Self.Internal = Internal
	Self.Config = Config
	return Self
end

---Index timing container.
---@param Key any?
---@return Timing?
function TimingContainerPair:Index(Key)
	return self.Config.Timings[Key] or self.Internal.Timings[Key]
end

---Find timing from name.
---@param Name string
---@return Timing?
function TimingContainerPair:Find(Name)
	return self.Config:Find(Name) or self.Internal:Find(Name)
end

---List all timings.
---@return Timing[]
function TimingContainerPair:List()
	local TimingList = {}

	for Index, TimingObj in next, self.Config:List() do
		table.insert(TimingList, TimingObj)
	end

	for Index, TimingObj in next, self.Internal:List() do
		table.insert(TimingList, TimingObj)
	end

	return TimingList
end

-- Return TimingContainerPair module.
return TimingContainerPair
end)
__bundle_register("Timings/TimingSave", function(require, _LOADED, __bundle_register, __bundle_modules)
local TimingContainer = require("Timings/TimingContainer")
local AnimationTiming = require("Timings/AnimationTiming")
local PartTiming = require("Timings/PartTiming")
local SoundTiming = require("Timings/SoundTiming")

---@class TimingSave
---@field _Data TimingContainer[]
local TimingSave = {}
TimingSave.__index = TimingSave

-- Timing save version constant.
local TimingSaveVersion = 1

---Get timing save.
---@return TimingContainer[]
function TimingSave:Get()
	return self._Data
end

---Clear timing containers.
function TimingSave:Clear()
	for Index, Container in next, self._Data do
		Container:Clear()
	end
end

---Load from partial values.
---@param Values table
function TimingSave:Load(Values)
	local Data = self._Data

	if typeof(Values.animation) == "table" then
		Data.animation:Load(Values.animation)
	end

	if typeof(Values.part) == "table" then
		Data.part:Load(Values.part)
	end

	if typeof(Values.sound) == "table" then
		Data.sound:Load(Values.sound)
	end
end

---Clone timing save.
---@return TimingSave
function TimingSave:Clone()
	local Save = TimingSave.new()

	for Idx, Container in next, self._Data do
		Save._Data[Idx] = Container:Clone()
	end

	return Save
end

---Equal timing saves.
---@param Other TimingSave
---@return boolean
function TimingSave:Equals(Other)
	if not Other or typeof(Other) ~= "table" then
		return false
	end

	for Idx, Container in next, self._Data do
		local OtherContainer = Other._Data[Idx]
		if not OtherContainer then
			return false
		end

		if not Container:Equals(OtherContainer) then
			return false
		end
	end

	return true
end

---Get timing save count.
---@return number
function TimingSave:Count()
	local CountVal = 0

	for Index, Container in next, self._Data do
		CountVal = CountVal + Container:Count()
	end

	return CountVal
end

---Return a serializable table.
---@return table
function TimingSave:Serialize()
	local Data = self._Data

	return {
		version = TimingSaveVersion,
		animation = Data.animation:Serialize(),
		part = Data.part:Serialize(),
		sound = Data.sound:Serialize(),
	}
end

---Create new TimingSave object.
---@param Values table?
---@return TimingSave
function TimingSave.new(Values)
	local Self = setmetatable({}, TimingSave)

	Self._Data = {
		animation = TimingContainer.new(AnimationTiming),
		part = TimingContainer.new(PartTiming),
		sound = TimingContainer.new(SoundTiming),
	}

	if Values then
		Self:Load(Values)
	end

	return Self
end

-- Return TimingSave module.
return TimingSave
end)
