__bundle_register("Utility/ControlModule", function(require, _LOADED, __bundle_register, __bundle_modules)
-- ControlModule — ported from type-soul-rewrite (1:1 with Aztup). Provides the
-- proper fly input move vector via ContextActionService binds (W/A/S/D with
-- ContextActionResult.Pass so normal movement keeps working). Adapted to
-- kenduap (PascalCase Logger/Maid, no Profiler dependency).

local LPH_NO_VIRTUALIZE = LPH_NO_VIRTUALIZE or function(F)
	return F
end

return LPH_NO_VIRTUALIZE(function()
	-- This module is used for getting the proper input fly values - 1:1 with Aztup.
	local ControlModule = {
		forwardValue = 0,
		backwardValue = 0,
		leftValue = 0,
		rightValue = 0,
	}

	---@module Utility.Logger
	local Logger = require("Utility/Logger")

	---@module Utility.Maid
	local Maid = require("Utility/Maid")

	-- Maids.
	local controlMaid = Maid.new()

	-- Services.
	local ContextActionService = game:GetService("ContextActionService")

	---Bind action safely with maid + error handling.
	---@param actionName string
	---@param callback function
	---@param createTouchButton boolean
	local function bindActionWrapper(actionName, callback, createTouchButton, ...)
		---Log bind action errors.
		---@param err string
		local function onBindActionWrapperError(err)
			Logger.Trace("onBindActionWrapperError - (%s) - %s", actionName, err)
		end

		local actionWrapperCallback = callback
			and function(...)
				local success, result = xpcall(callback, onBindActionWrapperError, ...)
				if not success then
					return nil
				end
				return result
			end

		controlMaid:Add(function()
			ContextActionService:UnbindAction(actionName)
		end)

		ContextActionService:BindAction(actionName, actionWrapperCallback, createTouchButton, ...)
	end

	---Initialize control module.
	function ControlModule.init()
		bindActionWrapper("EP_ControlModule_ForwardValue", function(_, inputState, _)
			ControlModule.forwardValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.W)

		bindActionWrapper("EP_ControlModule_LeftValue", function(_, inputState, _)
			ControlModule.leftValue = (inputState == Enum.UserInputState.Begin) and -1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.A)

		bindActionWrapper("EP_ControlModule_BackwardValue", function(_, inputState, _)
			ControlModule.backwardValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.S)

		bindActionWrapper("EP_ControlModule_RightValue", function(_, inputState, _)
			ControlModule.rightValue = (inputState == Enum.UserInputState.Begin) and 1 or 0
			return Enum.ContextActionResult.Pass
		end, false, Enum.KeyCode.D)

		Logger.Warn("ControlModule initialized.")
	end

	---Detach control module.
	function ControlModule.detach()
		controlMaid:Clean()
		ControlModule.forwardValue = 0
		ControlModule.backwardValue = 0
		ControlModule.leftValue = 0
		ControlModule.rightValue = 0
		Logger.Warn("ControlModule detached.")
	end

	---Get move vector.
	---@return Vector3
	function ControlModule.getMoveVector()
		return Vector3.new(
			ControlModule.leftValue + ControlModule.rightValue,
			0,
			ControlModule.forwardValue + ControlModule.backwardValue
		)
	end

	-- Return control module.
	return ControlModule
end)()
end)
__bundle_register("Utility/Filesystem", function(require, _LOADED, __bundle_register, __bundle_modules)
---@class Filesystem
---@field _Path string
local Filesystem = {}
Filesystem.__index = Filesystem

---Create and get the current path.
---@return string
function Filesystem:Path()
	if not isfolder(self._Path) then
		makefolder(self._Path)
	end

	return self._Path
end

---Append path to current path.
---@param Path string
---@return string
function Filesystem:Append(Path)
	return self:Path() .. "\\" .. Path
end

---Check if filename is a file.
---@param Filename string
---@return boolean
function Filesystem:File(Filename)
	return isfile(self:Append(Filename))
end

---Read file from path.
---@param Filename string
---@return string
function Filesystem:Read(Filename)
	if not self:File(Filename) then
		return error("File does not exist or is a folder.", 2)
	end

	return readfile(self:Append(Filename))
end

---Try to read file from path without isfile or isfolder check.
---@param Filename string
---@return string?
function Filesystem:TryRead(Filename)
	local FilePath = self._Path .. "\\" .. Filename
	local Success, Content = pcall(readfile, FilePath)
	if Success and Content then
		return Content
	end
	return nil
end

---Delete file.
---@param Filename string
---@return string
function Filesystem:Delete(Filename)
	if not self:File(Filename) then
		return error("File does not exist or is a folder.", 2)
	end

	return delfile(self:Append(Filename))
end

---Write file to workspace folder.
---@param Filename string
---@param Contents string?
function Filesystem:Write(Filename, Contents)
	writefile(self:Append(Filename), Contents and Contents or "")
end

---List files.
---@param Raw boolean?
---@return table
function Filesystem:List(Raw)
	local FileList = listfiles(self:Path())
	if not FileList then
		return error("File list does not exist.", 2)
	end

	local New = {}

	for Idx, FilePath in next, FileList do
		New[Idx] = Raw and FilePath or string.sub(FilePath, #(self:Path() .. "\\") + 1, #FilePath)
	end

	return New
end

---Create new Filesystem object.
---@param Path string
---@return Filesystem
function Filesystem.new(Path)
	local Self = setmetatable({}, Filesystem)
	Self._Path = Path
	return Self
end

-- Return Filesystem module.
return Filesystem
end)
__bundle_register("Utility/InstanceWrapper", function(require, _LOADED, __bundle_register, __bundle_modules)
-- InstanceWrapper — ported from type-soul-rewrite. Creates/caches an instance in
-- a maid, auto-uncaching it when it leaves the DataModel. BodyVelocity instances
-- are tagged "AllowedBM" (CollectionService) to match the game's body-mover
-- allow-list. Adapted to kenduap's Signal (:Connect) and Maid (:Add/:RemoveTask).

local LPH_NO_VIRTUALIZE = LPH_NO_VIRTUALIZE or function(F)
	return F
end

-- Instance wrapper module.
local InstanceWrapper = {}

-- Services.
local collectionService = game:GetService("CollectionService")
local tweenService = game:GetService("TweenService")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---Create & cache a tween, cleaned up through a maid, auto-uncached on deletion.
---@param instanceMaid Maid
---@param identifier any
---@return Tween
InstanceWrapper.tween = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, ...)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local instance = tweenService:Create(...)
	local onAncestorChange = Signal.new(instance.AncestryChanged)

	instanceMaid[identifier] = instance
	instanceMaid:Add(onAncestorChange:Connect("EpInstance_OnAncestorChange", function(_)
		if instance:IsDescendantOf(game) then
			return
		end
		instanceMaid:RemoveTask(identifier)
	end))

	return instance
end)

---Cache an existing instance, cleaned up through a maid, auto-uncached on deletion.
---@param instanceMaid Maid
---@param identifier any
---@param inst Instance
---@return Instance
InstanceWrapper.mark = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, inst)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local onAncestorChange = Signal.new(inst.AncestryChanged)

	if inst:IsA("BodyVelocity") then
		collectionService:AddTag(inst, "AllowedBM")
	end

	instanceMaid[identifier] = inst
	instanceMaid:Add(onAncestorChange:Connect("EpInstance_OnAncestorChange", function(_)
		if inst:IsDescendantOf(game) then
			return
		end
		instanceMaid:RemoveTask(identifier)
	end))

	return inst
end)

---Create & cache an instance, cleaned up through a maid, auto-uncached on deletion.
---@param instanceMaid Maid
---@param identifier any
---@param className string
---@param parent Instance?
---@return Instance
InstanceWrapper.create = LPH_NO_VIRTUALIZE(function(instanceMaid, identifier, className, parent)
	local maidInstance = instanceMaid[identifier]
	if maidInstance then
		return maidInstance
	end

	local newInstance = Instance.new(className, parent)
	local onAncestorChange = Signal.new(newInstance.AncestryChanged)

	if newInstance:IsA("BodyVelocity") then
		collectionService:AddTag(newInstance, "AllowedBM")
	end

	instanceMaid[identifier] = newInstance
	instanceMaid:Add(onAncestorChange:Connect("EpInstance_OnAncestorChange", function(_)
		if newInstance:IsDescendantOf(game) then
			return
		end
		instanceMaid:RemoveTask(identifier)
	end))

	return newInstance
end)

-- Return InstanceWrapper module.
return InstanceWrapper
end)
__bundle_register("Utility/Logger", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Logger module.
local Logger = {}
Logger.__index = Logger

-- State.
local NotifyCallback = nil

---Check if silent mode is enabled.
---@return boolean
local function IsSilent()
	return getgenv().EpiphyllumSilentMode == true
end

---Build a string with a prefix.
---@param Str string
---@return string
local function BuildPrefixString(Str)
	return string.format("[%s %s] [Epiphyllum]: %s", os.date("%x"), os.date("%X"), Str)
end

---Set notification callback.
---@param Callback function
function Logger.SetNotifyCallback(Callback)
	NotifyCallback = Callback
end

---Notify message with a default short cooldown.
---@param Str string
function Logger.Notify(Str, ...)
	if IsSilent() then return end

	local Formatted = string.format(Str, ...)
	if NotifyCallback then
		local Success, Err = pcall(NotifyCallback, Formatted, 3.0)
		if not Success then
			warn("[Epiphyllum Notify] " .. Formatted)
		end
	else
		warn("[Epiphyllum Notify] " .. Formatted)
	end
end

---Quick notify message.
---@param Str string
function Logger.QNotify(Str, ...)
	if IsSilent() then return end

	local Formatted = string.format(Str, ...)
	if NotifyCallback then
		pcall(NotifyCallback, Formatted, 0.5)
	else
		warn("[Epiphyllum QNotify] " .. Formatted)
	end
end

---Long notify message.
---@param Str string
function Logger.LongNotify(Str, ...)
	if IsSilent() then return end

	local Formatted = string.format(Str, ...)
	if NotifyCallback then
		pcall(NotifyCallback, Formatted, 5.0)
	else
		warn("[Epiphyllum LNotify] " .. Formatted)
	end
end

---Warn message.
---@param Str string
function Logger.Warn(Str, ...)
	if IsSilent() then return end

	warn(string.format(BuildPrefixString(Str), ...))
end

---Trace & warn message.
---@param Str string
function Logger.Trace(Str, ...)
	if IsSilent() then return end

	Logger.Warn(Str, ...)
	warn(debug.traceback(2))
end

---Info/debug message.
---@param Str string
function Logger.Info(Str, ...)
	if IsSilent() then return end

	print(string.format(BuildPrefixString(Str), ...))
end

-- Return Logger module.
return Logger
end)
__bundle_register("Utility/Maid", function(require, _LOADED, __bundle_register, __bundle_modules)
-- https://github.com/Quenty/NevermoreEngine/blob/version2/Modules/Shared/Events/Maid.lua
---@class Maid
local Maid = {}
Maid.__type = "maid"

---Create new Maid object.
---@return Maid
function Maid.new()
	return setmetatable({
		_Tasks = {},
	}, Maid)
end

---Return maid[key] - if not, it's not apart of the maid metatable - so we return the relevant task.
-- @return value
Maid.__index = function(Self, Index)
	if Maid[Index] then
		return Maid[Index]
	else
		return Self._Tasks[Index]
	end
end

---Clean or add a task with a specific key.
---@param Index any
---@param NewTask any
Maid.__newindex = function(Self, Index, NewTask)
	if Maid[Index] ~= nil then
		return warn(("'%s' is reserved"):format(tostring(Index)), 2)
	end

	local Tasks = Self._Tasks
	local OldTask = Tasks[Index]

	if OldTask == NewTask then
		return
	end

	Tasks[Index] = NewTask

	if OldTask then
		if typeof(OldTask) == "thread" then
			return coroutine.status(OldTask) == "suspended" and task.cancel(OldTask) or nil
		end

		if type(OldTask) == "function" then
			OldTask()
		elseif typeof(OldTask) == "RBXScriptConnection" then
			OldTask:Disconnect()
		elseif typeof(OldTask) == "Instance" and OldTask:IsA("Tween") then
			OldTask:Pause()
			OldTask:Cancel()
			OldTask:Destroy()
		elseif OldTask.Destroy then
			OldTask:Destroy()
		elseif OldTask.Detach then
			OldTask:Detach()
		end
	end
end

---Add a task without a specific ID and return the task.
---@param Task any
---@return any
function Maid:Mark(Task)
	self:Add(Task)
	return Task
end

---Add a task without a specific ID.
---@param Task any
---@return number
function Maid:Add(Task)
	if not Task then
		return error("task cannot be false or nil", 2)
	end

	local TaskId = #self._Tasks + 1
	self[TaskId] = Task

	return TaskId
end

---Remove task without cleaning it.
---@param TaskId number
function Maid:RemoveTask(TaskId)
	local Tasks = self._Tasks
	Tasks[TaskId] = nil
end

---Clean up all tasks.
function Maid:Clean()
	local Tasks = self._Tasks

	-- Disconnect all events first - as we know this is safe.
	for Index, _Task in next, Tasks do
		if typeof(_Task) == "RBXScriptConnection" then
			Tasks[Index] = nil
			_Task:Disconnect()
		end
	end

	-- Clear out tasks table completely, even if clean up tasks add more tasks to the maid.
	local Index, _Task = next(Tasks)

	while _Task ~= nil do
		Tasks[Index] = nil

		if typeof(_Task) == "thread" then
			if coroutine.status(_Task) == "suspended" then
				task.cancel(_Task)
			end
		else
			if type(_Task) == "function" then
				_Task()
			elseif typeof(_Task) == "RBXScriptConnection" then
				_Task:Disconnect()
			elseif typeof(_Task) == "Instance" and _Task:IsA("Tween") then
				_Task:Pause()
				_Task:Cancel()
				_Task:Destroy()
			elseif _Task.Destroy then
				_Task:Destroy()
			elseif _Task.Detach then
				_Task:Detach()
			end
		end

		Index, _Task = next(Tasks)
	end
end

-- Return Maid module.
return Maid
end)
__bundle_register("Utility/OriginalStore", function(require, _LOADED, __bundle_register, __bundle_modules)
-- OriginalStore module. Temporarily swaps a property, runs a callback, restores.
---@class OriginalStore
---@field Data table|Instance?
---@field Index any?
---@field Value any?
---@field Stored boolean
local OriginalStore = {}
OriginalStore.__index = OriginalStore

---Get stored data value.
---@return any
function OriginalStore:Get()
	if not self.Stored then
		return nil
	end

	return self.Value
end

---Set something, run a callback, and then restore.
---@param Data table|Instance
---@param Index any
---@param Value any
---@param Callback fun(): any
function OriginalStore:Run(Data, Index, Value, Callback)
	self:Set(Data, Index, Value)
	Callback()
	self:Restore()
end

---Mark data value.
---@param Data table|Instance
---@param Index any
function OriginalStore:Mark(Data, Index)
	if self.Stored and self.Data ~= Data then
		self:Restore()
	end

	if not self.Stored then
		local Success, Val = pcall(function()
			return Data[Index]
		end)
		if not Success then
			return
		end

		self.Data = Data
		self.Index = Index
		self.Value = Val
		self.Stored = true
	end
end

---Set data value.
---@param Data table|Instance
---@param Index any
---@param Value any
function OriginalStore:Set(Data, Index, Value)
	self:Mark(Data, Index)

	if self.Stored then
		pcall(function()
			Data[Index] = Value
		end)
	end
end

---Restore data value.
function OriginalStore:Restore()
	if not self.Stored then
		return
	end

	pcall(function()
		self.Data[self.Index] = self.Value
	end)

	self.Stored = false
end

---Detach OriginalStore object.
function OriginalStore:Detach()
	self:Restore()
	self.Data = nil
	self.Index = nil
	self.Value = nil
	self.Stored = false
end

---Create new OriginalStore object.
---@return OriginalStore
function OriginalStore.new()
	local Self = setmetatable({}, OriginalStore)
	Self.Data = nil
	Self.Index = nil
	Self.Value = nil
	Self.Stored = false
	return Self
end

-- Return OriginalStore module.
return OriginalStore
end)
__bundle_register("Utility/OriginalStoreManager", function(require, _LOADED, __bundle_register, __bundle_modules)
-- OriginalStoreManager — ported from type-soul-rewrite. Manages a map of
-- OriginalStore objects (one per instance) so many properties can be swapped and
-- restored at once. Adapted to kenduap's PascalCase OriginalStore API.

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@class OriginalStoreManager
---@field inner OriginalStore[]
local OriginalStoreManager = {}
OriginalStoreManager.__index = OriginalStoreManager

---Forget data value.
---@param data table|Instance
function OriginalStoreManager:forget(data)
	self.inner[data] = nil
end

---Mark data value.
---@param data table|Instance
---@param index any
function OriginalStoreManager:mark(data, index)
	local object = self.inner[data] or OriginalStore.new()
	object:Mark(data, index)
	self.inner[data] = object
end

---Add (set) a data value, remembering the original.
---@param data table|Instance
---@param index any
---@param value any
function OriginalStoreManager:add(data, index, value)
	local object = self.inner[data] or OriginalStore.new()
	object:Set(data, index, value)
	self.inner[data] = object
end

---Get all stores.
---@return OriginalStore[]
function OriginalStoreManager:data()
	return self.inner
end

---Get a store by data.
---@param data table|Instance
---@return OriginalStore
function OriginalStoreManager:get(data)
	return self.inner[data]
end

---Restore all stored values.
function OriginalStoreManager:restore()
	for _, store in next, self.inner do
		store:Restore()
	end
end

---Detach (restore + clear). PascalCase so kenduap's Maid can clean it too.
function OriginalStoreManager:Detach()
	for _, store in next, self.inner do
		store:Detach()
	end
	self.inner = {}
end

---Create new OriginalStoreManager object.
---@return OriginalStoreManager
function OriginalStoreManager.new()
	local self = setmetatable({}, OriginalStoreManager)
	self.inner = {}
	return self
end

-- Return OriginalStoreManager module.
return OriginalStoreManager
end)
__bundle_register("Utility/Scripts/Cobalt Medal", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Cobalt Medal — loadstring wrapper with full unload support.
local ScriptTracker = require("Utility/Scripts/ScriptTracker")
local Module = {}

local Tracker = ScriptTracker.new()
local Thread = nil
local Loaded = false

local Source = [===[
--[[
    Cobalt
    A runtime developer tool to monitor and intercept network traffic
    coming from the roblox game engine.

    This script is NOT intended to be modified.
    To view the source code, see the 'Src' folder on the official GitHub repository!

    Authors: deivid, upio
    GitHub: https://github.com/notpoiu/cobalt/
--]]

-- Shiny/Medal Decompiler Setup
local SHINY_SERVER_URL = "http://localhost:8080"
local SHINY_ENCODE_KEY = 203

local shinyBase64 = (function()
    local a='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local function b(c)
        return(c:gsub('.',function(d)
            local e,a='',d:byte()
            for f=8,1,-1 do e=e..(a%2^f-a%2^(f-1)>0 and'1'or'0')end
            return e
        end)..'0000'):gsub('%d%d%d?%d?%d?%d?',function(d)
            if#d<6 then return''end
            local g=0
            for f=1,6 do g=g+(d:sub(f,f)=='1'and 2^(6-f)or 0)end
            return a:sub(g+1,g+1)
        end)..({'','==','='})[#c%3+1]
    end
    return{encode=b}
end)()

local function shinyDecompile(s)
    local requestFunc = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
    if not requestFunc or not getscriptbytecode then
        return "-- Shiny: Missing request or getscriptbytecode function"
    end

    local success, bytecode = pcall(getscriptbytecode, s)
    if not success or not bytecode then
        return "-- Shiny: Failed to get script bytecode"
    end

    local encoded = shinyBase64.encode(bytecode)
    local url = SHINY_SERVER_URL .. "/luau/decompile?encode_key=" .. tostring(SHINY_ENCODE_KEY)

    local ok, response = pcall(requestFunc, {
        Url = url,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/octet-stream",
        },
        Body = encoded,
    })

    if not ok then
        return "-- Shiny: Request failed - " .. tostring(response)
    end

    if response.StatusCode == 200 then
        return response.Body
    elseif response.StatusCode == 400 then
        return "-- Shiny: Invalid bytecode"
    else
        return "-- Shiny: Decompilation failed (HTTP " .. tostring(response.StatusCode) .. ")"
    end
end

-- Override global decompile
decompile = shinyDecompile
-- End Shiny/Medal Decompiler Setup


-- ++++++++ WAX BUNDLED DATA BELOW ++++++++ --

-- Will be used later for getting flattened globals
local ImportGlobals

-- Holds direct closure data (defining this before the DOM tree for line debugging etc)
local ClosureBindings = {
    function()local wax,script,require=ImportGlobals(1)local ImportGlobals return (function(...)wax.shared.CobaltStartTime = tick()

local FileLogger = require(script.Utils.FileLog)

-- Environment
for _, Service in pairs({
	"ContentProvider",
	"CoreGui",
	"TweenService",
	"Players",
	"RunService",
	"HttpService",
	"UserInputService",
	"TextService",
	"StarterGui",
}) do
	wax.shared[Service] = cloneref(game:GetService(Service))
end

wax.shared.CobaltVerificationToken = wax.shared.HttpService:GenerateGUID()
wax.shared.SaveManager = require(script.Utils.SaveManager)
wax.shared.Settings = {}

wax.shared.Hooks = {}

-- Executor Support
wax.shared.ExecutorName = identifyexecutor()
wax.shared.ExecutorSupport = require(script.ExecutorSupport)

-- Utils
require(script.Utils.Connect)
wax.shared.Hooking = require(script.Utils.Hooking)

-- UI
wax.shared.Sonner = require(script.Utils.UI.Sonner)

-- Code Generation
local LuaEncode = require(script.Utils.Serializer.LuaEncode)
wax.shared.LuaEncode = LuaEncode

local CodeGen = require(script.Utils.CodeGen.Generator)

-- Variables
if not wax.shared.Players.LocalPlayer then
	wax.shared.Players.PlayerAdded:Wait()
end
wax.shared.LocalPlayer = wax.shared.Players.LocalPlayer
wax.shared.PlayerScripts = cloneref(wax.shared.LocalPlayer:WaitForChild("PlayerScripts"))

-- Functions
wax.shared.gethui = gethui or function()
	return wax.shared.CoreGui
end
wax.shared.checkcaller = checkcaller or function()
	return nil
end
wax.shared.restorefunction = function(Function: (...any) -> ...any, Silent: boolean?)
	local Original = wax.shared.Hooks[Function]

	if Silent and not Original then
		return
	end

	assert(Original, "Function not hooked")

	if restorefunction and isfunctionhooked(Function) then
		restorefunction(Function)
	else
		wax.shared.Hooking.HookFunction(Function, Original)
	end

	wax.shared.Hooks[Function] = nil
end
wax.shared.getrawmetatable = wax.shared.ExecutorSupport["getrawmetatable"].IsWorking
		and (getrawmetatable or debug.getmetatable)
	or function()
		return setmetatable({}, {
			__index = function()
				return function() end
			end,
		})
	end

wax.shared.newcclosure = wax.shared.ExecutorName == "AWP"
		and function(f, name)
			local env = getfenv(f)
			local x = setmetatable({
				__F = f,
			}, {
				__index = env,
				__newindex = env,
			})

			local nf = function(...)
				return __F(...)
			end

			setfenv(nf, x) -- set func env (env of nf gets deoptimized)
			return newcclosure(nf, name)
		end
	or newcclosure
wax.shared.queue_on_teleport = queue_on_teleport or queueonteleport or function(...) end

wax.shared.IsPlayerModule = function(Origin: LocalScript | ModuleScript, Instance: Instance): boolean
	if Instance and Instance.ClassName ~= "BindableEvent" then
		return false
	end

	if not Origin or typeof(Origin) ~= "Instance" or not Origin.IsA(Origin, "LuaSourceContainer") then
		return false
	end

	local PlayerModule = Origin and Origin.FindFirstAncestor(Origin, "PlayerModule") or nil
	if not PlayerModule then
		return false
	end

	if PlayerModule.Parent == nil then
