		return OldNamecall(...)
	end)

	local Result = table.pack(Bindable:Invoke())
	pcall(oth.unhook, getrawmetatable(game).__namecall)
	Bindable:Destroy()

	assert(SuccededInsideHook, InsideError)
	assert(CheckInvokeResult(
		Result,
		"Result corruption post oth hook and pcall"
	))
