        local Log = wax.shared.Logs[Type][Instance] or wax.shared.NewLog(Instance, Type, Method, nil)

        if Log.Blocked or Log.Ignored then
            return
        end

        Log:Call(Data)
        wax.shared.Communicator:Fire(Instance, Type, #Log.Calls)
