getgenv().decompile = function(scr) -- Medal
    local ok, bytecode = pcall(getscriptbytecode, scr)
    if not ok then
        return "-- failed to read script bytecode\n--[[\n" .. tostring(bytecode) .. "\n--]]"
    end

    local encoder = base64_encode
    if not encoder then
        encoder = function(data)
            local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            return ((data:gsub('.', function(x)
                local r,byte = '',x:byte()
                for i=8,1,-1 do
                    r = r .. (byte % 2^i - byte % 2^(i-1) > 0 and '1' or '0')
                end
                return r
            end)..'0000'):gsub('%d%d%d?%d?%d?%d?', function(x)
                if #x < 6 then return '' end
                local c = 0
                for i=1,6 do
                    c = c + (x:sub(i,i) == '1' and 2^(6-i) or 0)
                end
                return b:sub(c+1,c+1)
            end)..({ '', '==', '=' })[#data % 3 + 1])
        end
    end

    local requestFunc = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
    if not requestFunc then
        return "-- medal request error\n--[[\nmissing request function\n--]]"
    end

    local res = requestFunc({
        Url = "http://localhost:8080/luau/decompile?encode_key=203",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/octet-stream"
        },
        Body = encoder(bytecode)
    })

    if not res or res.StatusCode ~= 200 then
        return "-- medal request error\n--[[\n" .. (res and res.Body or "no response") .. "\n--]]"
    end

    return string.gsub(res.Body, string.char(0x00CD), " ")
end
