function Module.Load()
	if Loaded then return end
	Loaded = true
	Tracker:Start()
	Thread = task.spawn(function()
		local Fn, Err = loadstring(Source)
		if not Fn then
			Loaded = false
			warn(string.format("[Epiphyllum] VEX Explorer failed to compile: %s", tostring(Err)))
			return
		end

		local Success, RunErr = pcall(Fn)
		if not Success then
			Loaded = false
			warn(string.format("[Epiphyllum] VEX Explorer failed to run: %s", tostring(RunErr)))
		end
	end)
	Tracker:TrackThread(Thread)
end

function Module.Unload()
	if not Loaded then return end
	Loaded = false
	pcall(function() getgenv().VexExecutedCheck = false end)
	Tracker:Unload()
end

Module.Load()
return Module
end)
