function Module.Load()
	if Loaded then return end
	Loaded = true
	Active = true
	Tracker:Start()
	if RealQueueTeleport then
		getgenv().queueteleport = function(...)
			if not Active then return end
			return RealQueueTeleport(...)
		end
	end
	Thread = task.spawn(function()
		local Fn, Err = loadstring(Source)
		if not Fn then
			Loaded = false
			Active = false
			warn(string.format("[Epiphyllum] Infinite Yield failed to compile: %s", tostring(Err)))
			return
		end

		local Success, RunErr = pcall(Fn)
		if not Success then
			Loaded = false
			Active = false
			warn(string.format("[Epiphyllum] Infinite Yield failed to run: %s", tostring(RunErr)))
		end
	end)
	Tracker:TrackThread(Thread)
end

function Module.Unload()
	if not Loaded then return end
	Loaded = false
	Active = false
	if RealQueueTeleport then pcall(RealQueueTeleport, "") end
	if OriginalQueueTeleport then getgenv().queueteleport = OriginalQueueTeleport end
	pcall(function() getgenv().IY_LOADED = nil end)
	Tracker:Unload()
end

Module.Load()
return Module
end)
__bundle_register("Utility/Scripts/MCP Connector", function(require, _LOADED, __bundle_register, __bundle_modules)
-- MCP Connector — loadstring wrapper with full unload support.
local ScriptTracker = require("Utility/Scripts/ScriptTracker")
