--// Base Bridge Class \\--
local BaseBridge = {}; do
    BaseBridge.__index = BaseBridge

    function BaseBridge:BindToType(type, callback)
        self.Callbacks[type] = callback
    end

    function BaseBridge:BindToTypeRaw(type, callback)
        self.Callbacks[type] = callback
        self.RawCallbacks = self.RawCallbacks or {}
        self.RawCallbacks[type] = true
    end

    function BaseBridge:CreateAlias(type, aliases)
        for _, alias in aliases do
            self.Callbacks[alias] = self.Callbacks[type]
            if self.RawCallbacks and self.RawCallbacks[type] then
                self.RawCallbacks[alias] = true
            end
        end
    end

    function BaseBridge:HandleMessage(data)
        if self.Callbacks[data.type] then
            local success, result = pcall(function()
                return self.Callbacks[data.type](data)
            end)

            if success and result == nil then
                return nil
            end

            if not success then
                return self:FormatResponse(result, data.id, true)
            end

            if self.RawCallbacks and self.RawCallbacks[data.type] then
                return {
                    output = tostring(result),
                    success = true,
                    id = data.id
                }
            end

            return self:FormatResponse(result, data.id, false)
        end
        return nil
    end

    function BaseBridge:FormatResponse(message, id, isError)
        if isError then
            return {
                error = tostring(message),
                success = false,
                id = id
            }
        end

        local output = message
        if typeof(output) ~= "table" then
            output = { output }
        end

        return {
            output = LuaEncode(output, {
                Prettify = true
            }),
            success = true,
            id = id
        }
    end

    function BaseBridge:IsAlive()
        local success, result = pcall(function()
            local response
            local thread = task.spawn(function()
                local success, data = pcall(request, {
                    Url = "http://" .. BridgeURL,
                    Method = "GET"
                })

                if success then
                    response = data
                end
            end)

            local start = os.clock()
            repeat task.wait(0.05) until response ~= nil or os.clock() - start > 5

            if response == nil then
                task.cancel(thread)
                return false
            end

            -- 426 = Upgrade Required (WebSocket), 200 = HTTP mode
            if response.StatusCode == 426 or response.StatusCode == 200 then
                return true
            end

            return false
        end)

        if not success then
            return false
        end

        return result
    end
end

--// WebSocket Bridge \\--
local WebSocketBridge = setmetatable({}, {__index = BaseBridge}); do
    WebSocketBridge.__index = WebSocketBridge

    function WebSocketBridge.new()
        local self = setmetatable({}, WebSocketBridge)

        --// Yield until the server is alive with exponential backoff \\--
        local retryDelay = 0.5
        local maxRetryDelay = 5
        local maxAttempts = 10
        local attempts = 0

        while not self:IsAlive() do
            attempts += 1
            if attempts >= maxAttempts then
                error("Failed to connect to bridge server after " .. maxAttempts .. " attempts")
            end
            task.wait(retryDelay)
            retryDelay = math.min(retryDelay * 1.5, maxRetryDelay)
        end

        --// Connect to the server with timeout \\--
        local wsConnection = nil
        local connectionThread = task.spawn(function()
            local success, result = pcall(function()
                return WebSocket.connect("ws://" .. BridgeURL)
            end)
            if success then
                wsConnection = result
            end
        end)

        local connectionStart = os.clock()
        repeat task.wait(0.05) until wsConnection ~= nil or os.clock() - connectionStart > 5

        if wsConnection == nil then
            task.cancel(connectionThread)
            error("WebSocket connection timed out after 5 seconds")
        end

        self.WebSocket = wsConnection
        self.Connected = true
        self.Callbacks = {}
        self.Connections = {}
        self.ClientId = nil

        --// Send registration \\--
        self.WebSocket:Send(HttpService:JSONEncode(GetRegistrationInfo()))

        self.AliveThread = task.spawn(function()
            local consecutiveFailures = 0
            while task.wait(1) do
                if not self.Connected then
                    continue
                end

                if self:IsAlive() then
                    consecutiveFailures = 0
                    continue
                end

                consecutiveFailures += 1
                if consecutiveFailures < 3 then
                    continue
                end

                self.Connected = false
                break
            end

            pcall(function()
                self.WebSocket:Close()
            end)
        end)

        --// On Message \\--
        self.Connections[#self.Connections + 1] = self.WebSocket.OnMessage:Connect(function(message)
            local data = HttpService:JSONDecode(message)

            --// Handle registration response \\--
            if data.type == "registered" then
                self.ClientId = data.clientId
                return
            end

            local response = self:HandleMessage(data)
            if response then
                self.WebSocket:Send(HttpService:JSONEncode(response))
            end
        end)

        --// On Close \\--
        self.Connections[#self.Connections + 1] = self.WebSocket.OnClose:Connect(function()
            self.Connected = false
        end)

        return self
    end

    function WebSocketBridge:Destroy()
        self.Connected = false

        if self.AliveThread then
            pcall(task.cancel, self.AliveThread)
            self.AliveThread = nil
        end

        if self.Connections then
            for Index, Connection in next, self.Connections do
                pcall(function()
                    Connection:Disconnect()
                end)
                self.Connections[Index] = nil
            end
        end

        pcall(function()
            if self.WebSocket then
                self.WebSocket:Close()
            end
        end)
    end

    function WebSocketBridge:WaitForDisconnect()
        while self.Connected do
            task.wait(0.1)
        end
    end
end

--// HTTP Polling Bridge \\--
local HTTPBridge = setmetatable({}, {__index = BaseBridge}); do
    HTTPBridge.__index = HTTPBridge

    function HTTPBridge.new()
        local self = setmetatable({}, HTTPBridge)

        --// Yield until the server is alive with exponential backoff \\--
        local retryDelay = 0.5
        local maxRetryDelay = 5
        local maxAttempts = 10
        local attempts = 0

        while not self:IsAlive() do
            attempts += 1
            if attempts >= maxAttempts then
                error("Failed to connect to bridge server after " .. maxAttempts .. " attempts")
            end
            task.wait(retryDelay)
            retryDelay = math.min(retryDelay * 1.5, maxRetryDelay)
        end

        self.Connected = true
        self.Callbacks = {}
        self.PollInterval = 0.1
        self.ClientId = nil

        --// Register with the server \\--
        pcall(function()
            local regResponse = request({
                Url = "http://" .. BridgeURL .. "/register",
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode(GetRegistrationInfo()),
            })
            if regResponse.StatusCode == 200 and regResponse.Body then
                local regData = HttpService:JSONDecode(regResponse.Body)
                self.ClientId = regData.clientId
            end
        end)

        --// Start polling thread \\--
        self.PollThread = task.spawn(function()
            local consecutiveFailures = 0

            while self.Connected do
                local success, _ = pcall(function()
                    local pollUrl = "http://" .. BridgeURL .. "/poll"
                    if self.ClientId then
                        pollUrl = pollUrl .. "?clientId=" .. self.ClientId
                    end
                    local response = request({
                        Url = pollUrl,
                        Method = "GET"
                    })

                    --// Server might be down \\--
                    if response.StatusCode ~= 204 and response.StatusCode ~= 200 then
                        consecutiveFailures += 1
                        if consecutiveFailures >= 3 then
                            self.Connected = false
                        end

                        return
                    end

                    consecutiveFailures = 0

                    --// Handle response \\--
                    if response.Body and response.Body ~= "" then
                        local data = HttpService:JSONDecode(response.Body)
                        if data == nil or data.type == nil then return end

                        task.spawn(function()
                            local result = self:HandleMessage(data)
                            if result == nil then return end

                            --// Send response back \\--
                            request({
                                Url = "http://" .. BridgeURL .. "/respond",
                                Method = "POST",
                                Headers = {
                                    ["Content-Type"] = "application/json"
                                },
                                Body = HttpService:JSONEncode(result)
                            })
                        end)
                    end
                end)

                if not success then
                    consecutiveFailures += 1
                    if consecutiveFailures >= 3 then
                        self.Connected = false
                    end
                end

                task.wait(self.PollInterval)
            end
        end)

        return self
    end

    function HTTPBridge:Destroy()
        self.Connected = false

        if self.PollThread then
            pcall(task.cancel, self.PollThread)
            self.PollThread = nil
        end
    end

    function HTTPBridge:WaitForDisconnect()
        while self.Connected do
            task.wait(0.1)
        end
    end
end

--// Create Bridge \\--
local function CreateBridge()
    if WebSocketAvailable then
        local success, bridge = pcall(function()
            return WebSocketBridge.new()
        end)

        if success then
            return bridge
        end
    end

    return HTTPBridge.new()
end

--// Ratelimiter \\--

local Ratelimiter = {}
do
    type RatelimiterOptions = {
        Burst: {
            Time: number,
            Max: number
        },

        PeriodicInterval: number?,
        MainCallback: ((...any) -> ...any),
    }

    Ratelimiter.__index = Ratelimiter

    Ratelimiter.new = function(options: RatelimiterOptions)
        local self = setmetatable(options, Ratelimiter)
        self.Bucket = {}
        self.Queue = {}

        self.IsDestroyed = false
        self.ManagerThread = nil
        self.PeriodicThread = nil

        self:SetupManagerThread()

        return self
    end

    Ratelimiter.QueueOperation = function(self, ...: any)
        if self.IsDestroyed then return end
        table.insert(self.Queue, table.pack(...))
    end

    Ratelimiter.SetupManagerThread = function(self)
        if self.IsDestroyed then return end

        self.Bucket = {}
        self.Queue = {}

        if self.ManagerThread then
            task.cancel(self.ManagerThread)
            self.ManagerThread = nil
        end

        if self.PeriodicThread then
            task.cancel(self.PeriodicThread)
            self.PeriodicThread = nil
        end

        self.ManagerThread = task.spawn(function()
            while not self.IsDestroyed do
                local currentTime = tick()

                --// Clean bucket (efficient rebuild instead of O(n) removal) \\--
                if #self.Bucket > 0 then
                    local newBucket = {}
                    for _, time in self.Bucket do
                        if currentTime - time < self.Burst.Time then
                            table.insert(newBucket, time)
                        end
                    end

                    self.Bucket = newBucket
                end

                --// Process queue \\--
                while #self.Bucket < self.Burst.Max and #self.Queue > 0 do
                    local taskData = table.remove(self.Queue, 1)
                    if taskData then
                        table.insert(self.Bucket, tick())

                        task.defer(function()
                            if self.IsDestroyed then return end
                            self.MainCallback(table.unpack(taskData, 1, taskData.n))
                        end)
                    end
                end

                task.wait()
            end
        end)

        if not self.PeriodicInterval then return end
        self.PeriodicThread = task.spawn(function()
            while not self.IsDestroyed do
                self:QueueOperation()

                task.wait(self.PeriodicInterval)
            end
        end)
    end

    Ratelimiter.Destroy = function(self)
        if self.IsDestroyed then return end
        self.IsDestroyed = true

        if self.ManagerThread then
            task.cancel(self.ManagerThread)
            self.ManagerThread = nil
        end

        if self.PeriodicThread then
            task.cancel(self.PeriodicThread)
            self.PeriodicThread = nil
        end

        table.clear(self.Bucket)
        table.clear(self.Queue)
    end

    Ratelimiter.Stop = Ratelimiter.Destroy
end

--// Script Source Mapping \\--
local MappedScriptIds = {}
local QueuedScriptIds = {}
local ScriptInstanceMap = setmetatable({}, { __mode = "v" })
local SourcesToMap, SourcesProcessed, MappedSources = 0, 0, 0
local HasStartedMapping = false
local ScriptMappingFinished = false
local ScriptSourceUploadClientId = nil
local MappedSourceLimiter
local ScriptDescendantAddedConnection = nil
local UploadQueue = {}
local UploadQueueDebugIds = {}
local UploadQueueThread = nil
local UploadBatchMax = 8
local UploadFlushInterval = 0.5
local UploadMaxAttempts = 3
local BytecodeTimeoutSeconds = 3
local DecompileTimeoutSeconds = 12
local MarkScriptProcessed
local ActiveBridge = nil

local function ShutdownConnector()
    if ShutdownRequested then return end
    ShutdownRequested = true

    if ActiveBridge then
        if ActiveBridge.Destroy then
            pcall(function()
                ActiveBridge:Destroy()
            end)
        else
            ActiveBridge.Connected = false
            pcall(function()
                if ActiveBridge.WebSocket then
                    ActiveBridge.WebSocket:Close()
                end
            end)
        end
        ActiveBridge = nil
    end

    if ScriptDescendantAddedConnection then
        pcall(function()
            ScriptDescendantAddedConnection:Disconnect()
        end)
        ScriptDescendantAddedConnection = nil
    end

    if UploadQueueThread then
        pcall(task.cancel, UploadQueueThread)
        UploadQueueThread = nil
    end

    if MappedSourceLimiter then
        pcall(function()
            MappedSourceLimiter:Destroy()
        end)
    end

    table.clear(UploadQueue)
    table.clear(UploadQueueDebugIds)
    getgenv().__EpiphyllumMCPConnectorShutdown = nil
end

getgenv().__EpiphyllumMCPConnectorShutdown = ShutdownConnector

local function IsScriptMappingTransportReady(clientId)
    return (
        ActiveBridge ~= nil and
        ActiveBridge.Connected == true and
        ActiveBridge.ClientId ~= nil and
        ActiveBridge.ClientId == clientId
    )
end

local function UploadScriptSourceBatch(clientId, scripts, hasFinishedMapping)
    if not clientId then return false end
    if not IsScriptMappingTransportReady(clientId) then return false end

    local ok, response = pcall(request, {
        Url = "http://" .. BridgeURL .. "/script-sources",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = HttpService:JSONEncode({
            clientId = clientId,
            scripts = scripts or {},
            hasFinishedMapping = hasFinishedMapping,
            sourcesToMap = SourcesToMap,
            processedSources = SourcesProcessed,
            skippedSources = math.max(0, SourcesProcessed - MappedSources),
        })
    })

    return ok and response and response.StatusCode == 200
end

local function PublishScriptMappingStatus(hasFinishedMapping)
    if hasFinishedMapping ~= nil then
        ScriptMappingFinished = hasFinishedMapping
    end

    return UploadScriptSourceBatch(ScriptSourceUploadClientId, {}, ScriptMappingFinished)
end

local function StartUploadQueue()
    if UploadQueueThread then return end

    UploadQueueThread = task.spawn(function()
        while not ShutdownRequested do
            if #UploadQueue == 0 or not IsScriptMappingTransportReady(ScriptSourceUploadClientId) then
                task.wait(UploadFlushInterval)
                continue
            end

            local batch = {}
            local debugIds = {}
            while #UploadQueue > 0 and #batch < UploadBatchMax do
                local item = table.remove(UploadQueue, 1)
                table.insert(batch, item)
                table.insert(debugIds, item.debugId)
                UploadQueueDebugIds[item.debugId] = nil
            end

            local uploaded = UploadScriptSourceBatch(ScriptSourceUploadClientId, batch, false)
            if uploaded then
                for _, debugId in debugIds do
                    MarkScriptProcessed(debugId, true)
                end
            else
                for idx = #batch, 1, -1 do
                    local item = batch[idx]
                    item.attempts = (item.attempts or 0) + 1
                    if item.attempts >= UploadMaxAttempts then
                        MarkScriptProcessed(item.debugId, false)
                    else
                        UploadQueueDebugIds[item.debugId] = item.debugId
                        table.insert(UploadQueue, 1, item)
                    end
                end
                task.wait(1)
            end

            task.wait()
        end
    end)
end

local function RunWithTimeout(timeoutSeconds, callback)
    local completed = false
    local success = false
    local result = nil

    local worker = task.spawn(function()
        success, result = pcall(callback)
        completed = true
    end)

    local deadline = os.clock() + timeoutSeconds
    while not completed and os.clock() < deadline do
        task.wait(0.05)
    end

    if not completed then
        pcall(task.cancel, worker)
        return false, "Timed out after " .. tostring(timeoutSeconds) .. "s."
    end

    if not success then
        return false, result
    end

    return true, result
end

local function DecompileScriptSource(script)
    local success, bytecode = RunWithTimeout(BytecodeTimeoutSeconds, function()
        return getscriptbytecode(script)
    end)
    if not success then return nil, bytecode end

    for attempt = 1, 3 do
        local success, decompOutput = RunWithTimeout(DecompileTimeoutSeconds, function()
            return decompile(script)
        end)
        if not success then
            if type(decompOutput) == "string" and string.find(decompOutput, "Timed out", 1, true) then
                return nil, decompOutput
            end

            task.wait(0.5)
            continue
        end

        return decompOutput
    end

    return nil, "Failed to decompile script after 3 attempts."
end

MarkScriptProcessed = function(debugId, uploaded)
    if MappedScriptIds[debugId] then return end

    MappedScriptIds[debugId] = true
    QueuedScriptIds[debugId] = nil
    SourcesProcessed += 1
    if uploaded then
        MappedSources += 1
    end

    if SourcesProcessed >= SourcesToMap then
        PublishScriptMappingStatus(true)
    end
end

local function MapScriptSource(script)
    local debugId = script:GetDebugId()
    if MappedScriptIds[debugId] then return end
    if not IsScriptMappingTransportReady(ScriptSourceUploadClientId) then return end

    local source = DecompileScriptSource(script)
    if not source then
        MarkScriptProcessed(debugId, false)
        return
    end

    ScriptInstanceMap[debugId] = script
    script.Destroying:Once(function()
        ScriptInstanceMap[debugId] = nil
    end)

    if UploadQueueDebugIds[debugId] then return end
    UploadQueueDebugIds[debugId] = debugId
    table.insert(UploadQueue, {
        debugId = debugId,
        path = script:GetFullName(),
        source = source,
        attempts = 0,
    })
end

MappedSourceLimiter = Ratelimiter.new({
    Burst = {
        Time = 0.5,
        Max = 4,
    },

    MainCallback = MapScriptSource
})
MappedSourceLimiter:SetupManagerThread()

local function GetScriptByDebugId(debugId)
    local CachedInstance = ScriptInstanceMap[debugId]
    if CachedInstance then
        return CachedInstance
    end

    for _, script in game:QueryDescendants("LuaSourceContainer") do
        if script:IsA("Script") and script.RunContext == Enum.RunContext.Server then continue end
        if script:GetDebugId() ~= debugId then continue end

        ScriptInstanceMap[debugId] = script
        return script
    end

    for _, script in getnilinstances() do
        if not script:IsA("LuaSourceContainer") then continue end

        if script:IsA("Script") and script.RunContext ~= Enum.RunContext.Client then continue end
        if script:GetDebugId() ~= debugId then continue end

        ScriptInstanceMap[debugId] = script
        return script
    end

    return nil
end

local function ShouldMapScript(script)
    local IsServerScript = (
        script:IsA("Script") and (
            script.RunContext == Enum.RunContext.Server or
            script.RunContext == Enum.RunContext.Legacy
        )
    )
    if IsServerScript then return false end

    local IsRobloxScript = (
        script.RobloxLocked or
        script:IsDescendantOf(CoreGui) or
        script:IsDescendantOf(CorePackages) or
        script:IsDescendantOf(ScriptContext)
    )
    if IsRobloxScript then return false end

    local debugId = script:GetDebugId()
    local IsAlreadyMapped = MappedScriptIds[debugId]
    if IsAlreadyMapped then return false end

    local IsAlreadyQueued = QueuedScriptIds[debugId]
    if IsAlreadyQueued then return false end

    local Success, Bytecode = pcall(getscriptbytecode, script)
    if not Success or Bytecode == nil then return false end

    return true
end

local function QueueScriptForMapping(script)
    if not IsScriptMappingTransportReady(ScriptSourceUploadClientId) then return end

    local debugId = script:GetDebugId()
    if MappedScriptIds[debugId] or QueuedScriptIds[debugId] then return end

    QueuedScriptIds[debugId] = true
    SourcesToMap += 1
    ScriptMappingFinished = false
    PublishScriptMappingStatus(false)
    MappedSourceLimiter:QueueOperation(script)
end

local function StartScriptMapping(clientId)
    if HasStartedMapping then return end
    if not IsScriptMappingTransportReady(clientId) then return end

    HasStartedMapping = true
    ScriptSourceUploadClientId = clientId

    ScriptDescendantAddedConnection = game.DescendantAdded:Connect(function(script)
        if not script:IsA("LuaSourceContainer") then
            return
        end

        if not ShouldMapScript(script) then return end
        QueueScriptForMapping(script)
    end)

    local CategoriesToMap = {
        game:QueryDescendants("LuaSourceContainer"),
        getnilinstances()
    }

    --// Map script sources \\--
    task.spawn(function()
        if not IsScriptMappingTransportReady(clientId) then return end

        local ValidScripts = {}
        for _, category in CategoriesToMap do
            for _, script in category do
                if not script:IsA("LuaSourceContainer") then continue end
                if not ShouldMapScript(script) then continue end

                QueuedScriptIds[script:GetDebugId()] = true
                table.insert(ValidScripts, script)
            end
        end

        SourcesToMap += #ValidScripts
        PublishScriptMappingStatus(false)

        for idx, scriptObject in ValidScripts do
            task.defer(MappedSourceLimiter.QueueOperation, MappedSourceLimiter, scriptObject)
            if idx % 250 == 0 then task.wait(0.1) end
        end

        if SourcesToMap == 0 then
            PublishScriptMappingStatus(true)
        end
    end)
end

local function ResetScriptMappingState(clientId)
    MappedScriptIds = {}
    QueuedScriptIds = {}
    SourcesToMap = 0
    SourcesProcessed = 0
    MappedSources = 0
    HasStartedMapping = false
    ScriptMappingFinished = false
    ScriptSourceUploadClientId = clientId

    if ScriptDescendantAddedConnection then
        ScriptDescendantAddedConnection:Disconnect()
        ScriptDescendantAddedConnection = nil
    end

    if MappedSourceLimiter then
        MappedSourceLimiter:SetupManagerThread()
    end

    table.clear(UploadQueue)
    table.clear(UploadQueueDebugIds)
end

local function WaitForBridgeClientId(Bridge)
    local deadline = os.clock() + 5
    repeat
        if Bridge.ClientId then
            return Bridge.ClientId
        end
        if not Bridge.Connected then
            return nil
        end
        task.wait(0.05)
    until os.clock() > deadline

    return nil
end

--// Main Loop \\--
while not ShutdownRequested do
    local success, Bridge = pcall(CreateBridge)

    if not success then
        if ShutdownRequested then break end
        task.wait(3)
        continue
    end

    ActiveBridge = Bridge

    local clientId = WaitForBridgeClientId(Bridge)
    if clientId then
        StartUploadQueue()

        if ScriptSourceUploadClientId ~= clientId then
            ResetScriptMappingState(clientId)
        end

        if not getgenv().DisableInitialScriptDecompMapping then
            StartScriptMapping(clientId)
        else
            HasStartedMapping = true
            ScriptSourceUploadClientId = clientId
            PublishScriptMappingStatus(true)
        end
    end

    Bridge:BindToType("execute", function(data)
        setthreadidentity(8)
        loadstring(data.source)()
    end)

    Bridge:BindToType("get-console-output", function(data)
        local limit = data.limit or 50
        local logsOrder = data.logsOrder or "NewestFirst"

        local logs = LogService:GetLogHistory()
        local results = {}

        if logsOrder == "NewestFirst" then
            for i = #logs, 1, -1 do
                if #results >= limit then break end
                table.insert(results, logs[i])
            end
        else
            for _, log in logs do
                if #results >= limit then break end
                table.insert(results, log)
            end
        end

        return { count = #LogService:GetLogHistory(), limited = #LogService:GetLogHistory() > limit, results = results }
    end)

    Bridge:BindToType("get-data-by-code", function(data)
        setthreadidentity(8)
        local dataOutput = table.pack(loadstring(data.source)())

        return dataOutput
    end)

    Bridge:BindToTypeRaw("get-script-content", function(data)
        local source
        local scriptInstance

        --// Handle GC'd script proxies: debugId is passed directly, skip loadstring \\--
        if data.debugId then
            scriptInstance = GetScriptByDebugId(data.debugId)
            assert(scriptInstance, "No live script instance found for ScriptProxy with DebugId: " .. tostring(data.debugId))
        else
            setthreadidentity(8)
            scriptInstance = loadstring(data.source)()

            assert(typeof(scriptInstance) == "Instance", "Script instance is not an instance.")
            assert(scriptInstance:IsA("LuaSourceContainer"), "Script instance is not a LuaSourceContainer (Script, LocalScript, or ModuleScript).")
            assert(not (scriptInstance:IsA("Script") and scriptInstance.RunContext == Enum.RunContext.Server), "Script instance is a Server Script.")
        end

        source = DecompileScriptSource(scriptInstance)
        assert(source, "Failed to decompile script.")

        local debugId = scriptInstance:GetDebugId()
        if ScriptSourceUploadClientId and not MappedScriptIds[debugId] then
            local uploaded = UploadScriptSourceBatch(ScriptSourceUploadClientId, {
                {
                    debugId = debugId,
                    path = scriptInstance:GetFullName(),
                    source = source,
                }
            }, ScriptMappingFinished)

            if uploaded then
                MappedScriptIds[debugId] = true
            end
        end

        --// Line range support \\--
        if data.startLine then
            local lines = {}
            local pos = 1
            local len = #source
            while pos <= len do
                local newlinePos = source:find("\n", pos, true)
                if newlinePos then
                    table.insert(lines, source:sub(pos, newlinePos - 1))
                    pos = newlinePos + 1
                else
                    table.insert(lines, source:sub(pos))
                    break
                end
            end

            local totalLines = #lines
            local startLine = math.max(1, math.min(data.startLine, totalLines))
            local endLine = data.endLine and math.max(startLine, math.min(data.endLine, totalLines)) or totalLines

            local sliced = {}
            for i = startLine, endLine do
                table.insert(sliced, lines[i])
            end

            return "-- Lines " .. startLine .. "-" .. endLine .. " of " .. totalLines .. "\n" .. table.concat(sliced, "\n")
        end

        return source
    end)

    Bridge:BindToType("search-instances", function(data)
        local rootInstance = loadstring("return " .. data.root)()
        local instances = rootInstance:QueryDescendants(data.selector)

        local limit = data.limit or 50
        local results = {}

        for i, instance in instances do
            if i > limit then break end

            table.insert(results, {
                Name = instance.Name,
                ClassName = instance.ClassName,
                InstancePath = instance,
                DebugId = instance:GetDebugId()
            })
        end

        return {
            count = #instances,
            limited = #instances > limit,
            results = results
        }
    end)

    Bridge:BindToType("get-game-info", function(data)
        local productInfo = MarketplaceService:GetProductInfo(game.PlaceId)

        return {
            PlaceId = game.PlaceId,
            GameId = game.GameId,
            PlaceVersion = game.PlaceVersion,
            PlaceName = productInfo.Name,
            PlaceDescription = productInfo.Description,
            Creator = productInfo.Creator.Name,
            CreatorType = tostring(productInfo.Creator.CreatorType),
            CreatorId = productInfo.Creator.CreatorTargetId,
            JobId = game.JobId,
            ServerType = RobloxReplicatedStorage.GetServerType:InvokeServer()
        }
    end)

    Bridge:BindToType("get-descendants-tree", function(data)
        local rootInstance = loadstring("return " .. data.root)()
        assert(typeof(rootInstance) == "Instance", "Root path did not resolve to a valid Instance.")

        local maxDepth = data.maxDepth or 3
        local maxChildren = data.maxChildren or 50
        local classFilter = data.classFilter or ""
        local hasFilter = classFilter ~= ""

        local function buildTree(instance, depth)
            if depth > maxDepth then
                return nil
            end

            local children = instance:GetChildren()
            local childNodes = {}
            local shown = 0
            local total = #children

            for _, child in children do
                if shown >= maxChildren then break end

                if hasFilter and not child:IsA(classFilter) then
                    -- Even if this child doesn't match, check if any descendant might
                    -- Only skip if we're at max depth anyway
                    if depth < maxDepth then
                        local subtree = buildTree(child, depth + 1)
                        if subtree and subtree.Children and #subtree.Children > 0 then
                            table.insert(childNodes, subtree)
                            shown += 1
                        end
                    end
                    continue
                end

                local node = {
                    Name = child.Name,
                    ClassName = child.ClassName,
                    ChildCount = #child:GetChildren()
                }

                if depth < maxDepth and node.ChildCount > 0 then
                    local subtree = buildTree(child, depth + 1)
                    if subtree then
                        node.Children = subtree.Children
                    end
                end

                table.insert(childNodes, node)
                shown += 1
            end

            return {
                Name = instance.Name,
                ClassName = instance.ClassName,
                ChildCount = total,
                TruncatedAt = if shown < total then shown else nil,
                Children = childNodes
            }
        end

        return buildTree(rootInstance, 0)
    end)

    Bridge:BindToType("ensure-remote-spy", function(data)
        if getgenv().Cobalt then
            return {
                status = "already_loaded",
                message = "Cobalt remote spy is already running."
            }
        end

        -- Load Cobalt
        local success, err = pcall(function()
            loadstring(game:HttpGet("https://github.com/notpoiu/cobalt/releases/latest/download/Cobalt.luau"))()
        end)

        if not success then
            error("Failed to load Cobalt: " .. tostring(err))
        end

        -- Wait for Cobalt to initialize
        local waitStart = os.clock()
        while not getgenv().Cobalt and os.clock() - waitStart < 10 do
            task.wait(0.1)
        end

        return {
            status = "loaded",
            message = "Cobalt remote spy loaded successfully."
        }
    end)

    Bridge:BindToType("get-remote-spy-logs", function(data)
        local Cobalt = getgenv().Cobalt
        assert(Cobalt and Cobalt.shared and Cobalt.shared.Logs, "Cobalt remote spy is not loaded. Call ensure-remote-spy first.")

        local direction = data.direction or "Both"
        local nameFilter = data.remoteNameFilter or ""
        local limit = data.limit or 50
        local maxCallsPerRemote = data.maxCallsPerRemote or 5
        local hasNameFilter = nameFilter ~= ""

        local function ProcessLogs(logTable, directionLabel)
            local results = {}

            for instance, log in logTable do
                if typeof(instance) ~= "Instance" then continue end
                if #results >= limit then break end

                local remoteName = ""
                local remoteClass = ""
                pcall(function()
                    remoteName = instance.Name
                    remoteClass = instance.ClassName
                end)

                -- Apply name filter
                if hasNameFilter and not string.find(string.lower(remoteName), string.lower(nameFilter), 1, true) then
                    continue
                end

                -- Get recent calls (raw — LuaEncode handles serialization)
                local recentCalls = {}
                local totalCalls = #log.Calls
                local startIdx = math.max(1, totalCalls - maxCallsPerRemote + 1)

                for i = startIdx, totalCalls do
                    local call = log.Calls[i]
                    if not call then continue end

                    table.insert(recentCalls, {
                        Index = i,
                        Arguments = call.Arguments,
                        Origin = call.Origin,
                        IsExecutor = call.IsExecutor or false,
                        IsActor = call.IsActor or false,
                        Line = call.Line,
                    })
                end

                table.insert(results, {
                    RemoteName = remoteName,
                    RemoteClass = remoteClass,
                    Direction = directionLabel,
                    Method = log.Method,
                    TotalCalls = totalCalls,
                    Ignored = log.Ignored,
                    Blocked = log.Blocked,
                    RecentCalls = recentCalls,
                })
            end

            return results
        end

        local allResults = {}

        if direction == "Outgoing" or direction == "Both" then
            local outgoing = ProcessLogs(Cobalt.shared.Logs.Outgoing, "Outgoing")
            for _, r in outgoing do
                table.insert(allResults, r)
            end
        end

        if direction == "Incoming" or direction == "Both" then
            local incoming = ProcessLogs(Cobalt.shared.Logs.Incoming, "Incoming")
            for _, r in incoming do
                table.insert(allResults, r)
            end
        end

        -- Sort by total calls descending (most active remotes first)
        table.sort(allResults, function(a, b)
            return a.TotalCalls > b.TotalCalls
        end)

        -- Trim to limit
        if #allResults > limit then
            local trimmed = {}
            for i = 1, limit do
                trimmed[i] = allResults[i]
            end
            allResults = trimmed
        end

        return {
            count = #allResults,
            results = allResults
        }
    end)

    Bridge:BindToType("clear-remote-spy-logs", function(data)
        local Cobalt = getgenv().Cobalt
        assert(Cobalt and Cobalt.shared and Cobalt.shared.ClearLogs, "Cobalt remote spy is not loaded. Call ensure-remote-spy first.")

        Cobalt.shared.ClearLogs()

        return {
            status = "cleared",
            message = "All remote spy logs have been cleared."
        }
    end)

    Bridge:BindToType("block-remote", function(data)
        local Cobalt = getgenv().Cobalt
        assert(Cobalt and Cobalt.shared and Cobalt.shared.Logs, "Cobalt remote spy is not loaded. Call ensure-remote-spy first.")

        local remoteName = data.remoteName
        local direction = data.direction
        local shouldBlock = data.shouldBlock

        local logTable = Cobalt.shared.Logs[direction]
        assert(logTable, "Invalid direction: " .. tostring(direction))

        for instance, log in logTable do
            if typeof(instance) ~= "Instance" then continue end

            local name = ""
            pcall(function() name = instance.Name end)

            if name == remoteName then
                if shouldBlock and not log.Blocked then
                    log:Block()
                elseif not shouldBlock and log.Blocked then
                    log:Block() -- toggles
                end

                return {
                    status = "success",
                    message = (shouldBlock and "Blocked" or "Unblocked") .. " remote: " .. remoteName,
                    blocked = log.Blocked
                }
            end
        end

        error("Remote not found: " .. remoteName .. " in " .. direction .. " logs. Make sure the remote has been logged at least once.")
    end)

    Bridge:BindToType("ignore-remote", function(data)
        local Cobalt = getgenv().Cobalt
        assert(Cobalt and Cobalt.shared and Cobalt.shared.Logs, "Cobalt remote spy is not loaded. Call ensure-remote-spy first.")

        local remoteName = data.remoteName
        local direction = data.direction
        local shouldIgnore = data.shouldIgnore

        local logTable = Cobalt.shared.Logs[direction]
        assert(logTable, "Invalid direction: " .. tostring(direction))

        for instance, log in logTable do
            if typeof(instance) ~= "Instance" then continue end

            local name = ""
            pcall(function() name = instance.Name end)

            if name == remoteName then
                if shouldIgnore and not log.Ignored then
                    log:Ignore()
                elseif not shouldIgnore and log.Ignored then
                    log:Ignore() -- toggles
                end

                return {
                    status = "success",
                    message = (shouldIgnore and "Ignoring" or "Unignored") .. " remote: " .. remoteName,
                    ignored = log.Ignored
                }
            end
        end

        error("Remote not found: " .. remoteName .. " in " .. direction .. " logs. Make sure the remote has been logged at least once.")
    end)

    Bridge:BindToType("type-text-box", function(data)
        local path = data.path
        local text = data.string or data.text
        local enter = data.enter
        local useKeyPress = data.useKeyPress

        local textBox
        if typeof(path) == "string" then
            textBox = loadstring("return " .. path)()
        else
            textBox = path
        end

        assert(typeof(textBox) == "Instance", "Path did not resolve to a valid Instance.")
        assert(textBox:IsA("TextBox"), "Resolved Instance is not a TextBox.")

        textBox:CaptureFocus()
        task.wait(0.05)

        if useKeyPress then
            local success = pcall(function()
                for i = 1, #text do
                    VirtualInputManager:SendTextInput(text:sub(i, i), nil, game)
                    task.wait(0.01)
                end
            end)

            if not success and type(keypress) == "function" then
                for i = 1, #text do
                    local char = text:sub(i, i):upper()
                    local byte = char:byte()
                    if byte then
                        keypress(byte)
                        task.wait(0.01)
                        if type(keyrelease) == "function" then
                            keyrelease(byte)
                        end
                    end
                end
            end
        else
            textBox.Text = text
        end

        if enter then
            if useKeyPress then
                if type(keypress) == "function" then
                    keypress(0x0D)
                    task.wait(0.01)
                    if type(keyrelease) == "function" then
                        keyrelease(0x0D)
                    end
                else
                    pcall(function()
                        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
                        task.wait(0.01)
                        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
                    end)
                end
            end
            textBox:ReleaseFocus(true)
        else
            textBox:ReleaseFocus(false)
        end

        return {
            status = "success",
            message = "Successfully typed into TextBox."
        }
    end)

    Bridge:BindToType("click-button", function(data)
        local path = data.path
        local action = data.Action or data.action

        local button
        if typeof(path) == "string" then
            button = loadstring("return " .. path)()
        else
            button = path
        end

        assert(typeof(button) == "Instance", "Path did not resolve to a valid Instance.")
        assert(button:IsA("GuiButton"), "Resolved Instance is not a GuiButton (e.g., TextButton or ImageButton).")
        assert(typeof(firesignal) == "function", "Your executor does not support 'firesignal', which is required for this command.")

        local Signals = {"Activated", "MouseButton1Down", "MouseButton2Down", "MouseButton1Click", "MouseButton2Click"}

        if action then
            assert(table.find(Signals, action), "Invalid action provided. Valid actions are: " .. table.concat(Signals, ", "))
            firesignal(button[action])
        else
            for _, signalName in pairs(Signals) do
                pcall(function() firesignal(button[signalName]) end)
            end
        end

        return {
            status = "success",
            message = "Successfully fired click signals on Button."
        }
    end)

    Bridge:WaitForDisconnect()

    if ActiveBridge == Bridge then
        ActiveBridge = nil
    end

    if ShutdownRequested then break end
    task.wait(1)
end
]===]

function Module.Load()
	if Loaded then return end
	Loaded = true
	Tracker:Start()
	Thread = task.spawn(function()
		local Fn, Err = loadstring(Source)
		if not Fn then
			Loaded = false
			warn(string.format("[Epiphyllum] MCP Connector failed to compile: %s", tostring(Err)))
			return
		end

		local Success, RunErr = pcall(Fn)
		if not Success then
			Loaded = false
			warn(string.format("[Epiphyllum] MCP Connector failed to run: %s", tostring(RunErr)))
		end
	end)
	Tracker:TrackThread(Thread)
end

function Module.Unload()
	if not Loaded then return end
	Loaded = false
	pcall(function()
		local Shutdown = getgenv().__EpiphyllumMCPConnectorShutdown
		if Shutdown then
			Shutdown()
		end
	end)
	Tracker:Unload()
end

Module.Load()
return Module
end)
__bundle_register("Utility/Scripts/ScriptTracker", function(require, _LOADED, __bundle_register, __bundle_modules)
-- ScriptTracker — tracks all GUIs, connections, and threads a script creates.
-- Uses ChildAdded listeners on CoreGui/PlayerGui to capture GUIs in real-time.
local ScriptTracker = {}
ScriptTracker.__index = ScriptTracker

function ScriptTracker.new()
	local Self = setmetatable({}, ScriptTracker)
	Self.Connections = {}
	Self.Instances = {}
	Self.Threads = {}
	Self.Active = false
	Self._Listeners = {}
	return Self
end

---Start tracking. Call before loading the script.
---Snapshots existing children and listens for new ones.
function ScriptTracker:Start()
	self.Active = true

	-- Snapshot existing children so we don't destroy them.
	local PreExisting = {}

	-- Collect all GUI containers: CoreGui, gethui(), PlayerGui.
	local Containers = {}
	Containers[#Containers + 1] = game:GetService("CoreGui")
	pcall(function()
		local Hui = gethui()
		if Hui and Hui ~= Containers[1] then
			Containers[#Containers + 1] = Hui
		end
	end)
	pcall(function()
		local PlayerGui = game:GetService("Players").LocalPlayer:FindFirstChildWhichIsA("PlayerGui")
		if PlayerGui then
			Containers[#Containers + 1] = PlayerGui
		end
	end)

	-- Snapshot all existing children across all containers.
	for _, Container in next, Containers do
		pcall(function()
			for _, Child in next, Container:GetChildren() do
				PreExisting[Child] = true
			end
		end)
	end

	-- Listen for new ScreenGuis in all containers.
	for _, Container in next, Containers do
		pcall(function()
			local Conn = Container.ChildAdded:Connect(function(Child)
				if not self.Active then return end
				if PreExisting[Child] then return end
				if Child:IsA("ScreenGui") then
					self.Instances[#self.Instances + 1] = Child
				end
			end)
			self._Listeners[#self._Listeners + 1] = Conn
		end)
	end
end

---Track a connection manually.
---@param Connection RBXScriptConnection
function ScriptTracker:TrackConnection(Connection)
	if not self.Active then return end
	self.Connections[#self.Connections + 1] = Connection
end

---Track an instance manually (GUI etc).
---@param Inst Instance
function ScriptTracker:TrackInstance(Inst)
	if not self.Active then return end
	self.Instances[#self.Instances + 1] = Inst
end

---Track a thread manually.
---@param Thread thread
function ScriptTracker:TrackThread(Thread)
	if not self.Active then return end
	self.Threads[#self.Threads + 1] = Thread
end

---Unload everything tracked.
function ScriptTracker:Unload()
	self.Active = false

	-- Disconnect ChildAdded listeners first.
	for I = #self._Listeners, 1, -1 do
		pcall(function() self._Listeners[I]:Disconnect() end)
		self._Listeners[I] = nil
	end

	-- Disconnect all tracked connections.
	for I = #self.Connections, 1, -1 do
		pcall(function()
			local Conn = self.Connections[I]
			if Conn and typeof(Conn) == "RBXScriptConnection" then
				Conn:Disconnect()
			end
		end)
		self.Connections[I] = nil
	end

	-- Destroy all tracked instances.
	for I = #self.Instances, 1, -1 do
		pcall(function()
			local Inst = self.Instances[I]
			if Inst and typeof(Inst) == "Instance" then
				Inst:Destroy()
			end
		end)
		self.Instances[I] = nil
	end

	-- Cancel all tracked threads.
	for I = #self.Threads, 1, -1 do
		pcall(task.cancel, self.Threads[I])
		self.Threads[I] = nil
	end
end

return ScriptTracker
end)
__bundle_register("Utility/Signal", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Wrapper for Roblox's signals for safe connections to signals.
---@class Signal
---@field Signal RBXScriptSignal Underlying roblox script signal
local Signal = {}
Signal.__index = Signal

---Safely connect to Roblox's signal.
---@param Label string
---@param EventFunction function
---@return RBXScriptConnection
function Signal:Connect(Label, EventFunction)
	---Log event errors.
	---@param Error string
	local function OnEventFunctionError(Error)
		warn(string.format("[Epiphyllum] onEventFunctionError - (%s) - %s", Label, Error))
	end

	-- Connect to signal.
	local Connection = self.Signal:Connect(function(...)
		return xpcall(EventFunction, OnEventFunctionError, ...)
	end)

	-- Return connection.
	return Connection
end

---Create new wrapper signal object.
---@param RobloxSignal RBXScriptSignal
---@return Signal
function Signal.new(RobloxSignal)
	local Self = setmetatable({}, Signal)
	Self.Signal = RobloxSignal
	return Self
end

-- Return Signal module.
return Signal
end)
__bundle_register("Utility/TaskSpawner", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Task spawner module.
local TaskSpawner = {}

-- Services.
local RunService = game:GetService("RunService")

---Spawn delayed task where the delay can be variable.
---@param Label string
---@param Delay function
---@param Callback function
---@vararg any
function TaskSpawner.Delay(Label, Delay, Callback, ...)
	---Log task errors.
	---@param Error string
	local function OnTaskFunctionError(Error)
		warn(string.format("[Epiphyllum] onTaskFunctionError - (%s) - %s", Label, Error))
	end

	-- Wrap callback in error handling and delay handling.
	local TaskFunction = function(...)
		local Timestamp = os.clock()

		while os.clock() - Timestamp < Delay() do
			RunService.RenderStepped:Wait()
		end

		return xpcall(Callback, OnTaskFunctionError, ...)
	end

	return task.spawn(TaskFunction, ...)
end

---Spawn task.
---@param Label string
---@param Callback function
---@vararg any
function TaskSpawner.Spawn(Label, Callback, ...)
	---Log task errors.
	---@param Error string
	local function OnTaskFunctionError(Error)
		warn(string.format("[Epiphyllum] onTaskFunctionError - (%s) - %s", Label, Error))
	end

	-- Wrap callback in error handling.
	local TaskFunction = function(...)
		return xpcall(Callback, OnTaskFunctionError, ...)
	end

	-- Return reference.
	return task.spawn(TaskFunction, ...)
end

-- Return TaskSpawner module.
return TaskSpawner
end)
__bundle_register("Visuals/Movement", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Movement engine.
--   * Speedhack -> rootPart.AssemblyLinearVelocity += MoveDirection.Unit * speed
--                  (same method as type-soul-rewrite)
--   * Fly       -> iy.lua-style: BodyGyro + BodyVelocity, character aligns to the
--                  camera, PlatformStand on, iy's exact velocity formula. Q/E or
--                  Space/Shift for vertical. The Fly Speed slider replaces iy's
--                  hardcoded SPEED = 50.
--   * Noclip    -> OriginalStoreManager remembers/restores each part's CanCollide
--                  (same method as type-soul-rewrite)
-- Adapted to kenduap's module APIs and session-guarded (__EP_MovementSession).

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.OriginalStoreManager
local OriginalStoreManager = require("Utility/OriginalStoreManager")

---@module Utility.InstanceWrapper
local InstanceWrapper = require("Utility/InstanceWrapper")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

-- Movement module.
local Movement = {}

-- Maids + state.
local movementMaid = Maid.new()
local noClipMap = OriginalStoreManager.new()
local MySession = nil

---Update speed hack.
---@param rootPart BasePart
---@param humanoid Humanoid
local function updateSpeedHack(rootPart, humanoid)
	if Configuration.ExpectToggleValue("EP_Move_Fly_Enable") then
		return
	end

	rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity * Vector3.new(0, 1, 0)

	local moveDirection = humanoid.MoveDirection
	if moveDirection.Magnitude <= 0.001 then
		return
	end

	local speed = Configuration.ExpectOptionValue("EP_Move_WalkSpeed") or 50
	if type(speed) ~= "number" or speed ~= speed or speed == math.huge or speed == -math.huge then
		speed = 50
	end

	rootPart.AssemblyLinearVelocity = rootPart.AssemblyLinearVelocity + moveDirection.Unit * speed
end

---Stop fly: drop the body movers and release PlatformStand.
---@param humanoid Humanoid?
local function stopFly(humanoid)
	movementMaid["flyBodyVelocity"] = nil
	movementMaid["flyBodyGyro"] = nil
	if humanoid then
		humanoid.PlatformStand = false
	end
end

---Update fly hack (iy.lua method).
---@param rootPart BasePart
---@param humanoid Humanoid
local function updateFlyHack(rootPart, humanoid)
	local camera = workspace.CurrentCamera
	if not camera then
		return
	end

	-- Body movers (cached in the maid, tagged AllowedBM for the BodyVelocity).
	local bodyGyro = InstanceWrapper.create(movementMaid, "flyBodyGyro", "BodyGyro", rootPart)
	bodyGyro.P = 9e4
	bodyGyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)

	local bodyVelocity = InstanceWrapper.create(movementMaid, "flyBodyVelocity", "BodyVelocity", rootPart)
	bodyVelocity.MaxForce = Vector3.new(9e9, 9e9, 9e9)

	if humanoid then
		humanoid.PlatformStand = true
	end

	-- iy CONTROL values from current key state (F/B/L/R, plus Q up / E down).
	local F, B, L, R, Q, E = 0, 0, 0, 0, 0, 0
	if not UserInputService:GetFocusedTextBox() then
		if UserInputService:IsKeyDown(Enum.KeyCode.W) then
			F = 1
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.S) then
			B = -1
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.A) then
			L = -1
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.D) then
			R = 1
		end
		if UserInputService:IsKeyDown(Enum.KeyCode.E) or UserInputService:IsKeyDown(Enum.KeyCode.Space) then
			Q = 2
		end
		if
			UserInputService:IsKeyDown(Enum.KeyCode.Q)
			or UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
			or UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
		then
			E = -2
		end
	end

	local speed = Configuration.ExpectOptionValue("EP_Move_Fly_Speed") or 50
	-- Guard against NaN/inf (e.g. a bad flag value) so we never fling at light speed.
	if type(speed) ~= "number" or speed ~= speed or speed == math.huge or speed == -math.huge then
		speed = 50
	end

	if (L + R) ~= 0 or (F + B) ~= 0 or (Q + E) ~= 0 then
		bodyVelocity.Velocity = (
			(camera.CFrame.LookVector * (F + B))
			+ ((camera.CFrame * CFrame.new(L + R, (F + B + Q + E) * 0.2, 0).Position) - camera.CFrame.Position)
		) * speed
	else
		bodyVelocity.Velocity = Vector3.new(0, 0, 0)
	end

	bodyGyro.CFrame = camera.CFrame
end

---Update noclip.
---@param character Model
---@param rootPart BasePart
local function updateNoClip(character, rootPart)
	for _, instance in pairs(character:GetChildren()) do
		if instance:IsA("BasePart") then
			noClipMap:add(instance, "CanCollide", false)
		end
	end
end

---Update movement.
local function updateMovement()
	local localPlayer = Players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	if not character then
		return
	end

	local rootPart = character:FindFirstChild("HumanoidRootPart")
	if not rootPart then
		return
	end

	local humanoid = character:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	if Configuration.ExpectToggleValue("EP_Move_Fly_Enable") then
		updateFlyHack(rootPart, humanoid)
	else
		stopFly(humanoid)
	end

	if Configuration.ExpectToggleValue("EP_Move_Noclip_Enable") then
		updateNoClip(character, rootPart)
	else
		noClipMap:restore()
	end

	if Configuration.ExpectToggleValue("EP_Move_WalkSpeed_Enable") then
		updateSpeedHack(rootPart, humanoid)
	end
end

---Initialize movement.
function Movement.Init()
	Movement.Detach()

	MySession = getgenv().__EP_MovementSession

	movementMaid:Add(RunService.PreSimulation:Connect(function()
		-- Self-cancel if a newer instance took over.
		if getgenv().__EP_MovementSession ~= MySession then
			Movement.Detach()
			return
		end
		updateMovement()
	end))

	Logger.Warn("Movement initialized.")
end

---Detach movement and restore everything.
function Movement.Detach()
	-- Release PlatformStand on the current character before dropping movers.
	local localPlayer = Players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if humanoid then
		humanoid.PlatformStand = false
	end

	noClipMap:Detach()
	movementMaid:Clean()
	Logger.Warn("Movement detached.")
end

-- Return Movement module.
return Movement
end)
__bundle_register("Visuals/PlayerESP", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Player ESP engine — Infinite Yield method:
--   * BoxHandleAdornment on every BasePart (the bright "chams" boxes), colored by
--     team (green ally / red enemy) or a custom color.
--   * BillboardGui + TextLabel on the Head showing Name | Health | Studs.
-- Every element is individually toggleable. Session-guarded (__EP_ESPSession).

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

-- Services.
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local CoreGui = game:GetService("CoreGui")

local LocalPlayer = Players.LocalPlayer

-- Container name (so previous runs can be cleaned up).
local CONTAINER_NAME = "__EP_PlayerESP"

-- iy-style team colors.
local ALLY_COLOR = Color3.fromRGB(0, 255, 0)
local ENEMY_COLOR = Color3.fromRGB(255, 0, 0)

---Extract a Color3 from a colorpicker flag value (the library stores the
---colorpicker object, whose actual Color3 lives in `.Color`).
---@param Value any
---@param Fallback Color3
---@return Color3
local function ToColor3(Value, Fallback)
	if typeof(Value) == "Color3" then
		return Value
	end
	if type(Value) == "table" and typeof(Value.Color) == "Color3" then
		return Value.Color
	end
	return Fallback
end

-- Player ESP module.
local PlayerESP = {}

-- player -> ESPObject registry.
local Objects = {}

-- Engine maid + session guard.
local EngineMaid = Maid.new()
local MySession = nil
local GuiContainer = nil

---Resolve the gethui() container if the executor exposes it.
---@return Instance?
local function TryGetHui()
	local Ok, Hui = pcall(function()
		return gethui()
	end)
	if Ok then
		return Hui
	end
	return nil
end

---Create the ESP ScreenGui using the same robust parenting sequence as the
---script's working modules (CoreGui -> PlayerGui fallback -> gethui()).
---@return ScreenGui
local function CreateGuiContainer()
	local ScreenGui = Instance.new("ScreenGui")
	ScreenGui.Name = CONTAINER_NAME
	ScreenGui.ResetOnSpawn = false
	ScreenGui.DisplayOrder = 10

	pcall(function()
		ScreenGui.Parent = CoreGui
	end)
	if not ScreenGui.Parent then
		ScreenGui.Parent = LocalPlayer:WaitForChild("PlayerGui")
	end
	pcall(function()
		ScreenGui.Parent = gethui()
	end)

	return ScreenGui
end

---Destroy leftover ESP containers from previous runs.
local function CleanupLeftover()
	local Parents = { CoreGui, TryGetHui() }
	pcall(function()
		Parents[#Parents + 1] = LocalPlayer:FindFirstChild("PlayerGui")
	end)

	for _, Parent in next, Parents do
		if Parent then
			local Old = Parent:FindFirstChild(CONTAINER_NAME)
			while Old do
				Old:Destroy()
				Old = Parent:FindFirstChild(CONTAINER_NAME)
			end
		end
	end
end

---@class ESPObject
local ESPObject = {}
ESPObject.__index = ESPObject

---Create an ESP object for a player.
---@param Player Player
---@return ESPObject
function ESPObject.new(Player)
	local self = setmetatable({}, ESPObject)
	self.Player = Player
	self.Maid = Maid.new()
	self.Adornments = {} -- part -> BoxHandleAdornment
	self.LastCharacter = nil

	local Folder = Instance.new("Folder")
	Folder.Name = Player.Name .. "_ESP"
	Folder.Parent = GuiContainer
	self.Folder = self.Maid:Mark(Folder)

	local Billboard = Instance.new("BillboardGui")
	Billboard.Name = "__EP_Label"
	Billboard.AlwaysOnTop = true
	Billboard.Size = UDim2.new(0, 200, 0, 60)
	Billboard.StudsOffset = Vector3.new(0, 2, 0)
	Billboard.Enabled = false
	Billboard.Parent = Folder

	local Label = Instance.new("TextLabel")
	Label.BackgroundTransparency = 1.0
	Label.Size = UDim2.new(1, 0, 1, 0)
	Label.Font = Enum.Font.SourceSansSemibold
	Label.TextSize = 16
	Label.TextColor3 = Color3.new(1, 1, 1)
	Label.TextStrokeTransparency = 0.0
	Label.TextYAlignment = Enum.TextYAlignment.Bottom
	Label.Parent = Billboard

	self.Billboard = Billboard
	self.Label = Label
	return self
end

---Resolve display name based on the configured name type.
---@param Character Model
---@return string
function ESPObject:ResolveName(Character)
	local NameType = Configuration.ExpectOptionValue("EP_ESP_Player_NameType") or "Username"

	if NameType == "Display Name" then
		return self.Player.DisplayName
	end
	if NameType == "Character Name" then
		return self.Player:GetAttribute("CharacterName") or Character.Name or self.Player.Name
	end
	return self.Player.Name
end

---Resolve box/text color (team logic or custom).
---@return Color3
function ESPObject:ResolveColor()
	if Configuration.ExpectToggleValue("EP_ESP_Player_TeamColor") then
		local LocalTeam = LocalPlayer and LocalPlayer.Team
		if LocalTeam and self.Player.Team == LocalTeam then
			return ALLY_COLOR
		end
		return ENEMY_COLOR
	end
	return ToColor3(Configuration.ExpectOptionValue("EP_ESP_Player_Color"), Color3.new(1, 1, 1))
end

---Destroy all box adornments.
function ESPObject:ClearAdornments()
	for Part, Adorn in next, self.Adornments do
		Adorn:Destroy()
		self.Adornments[Part] = nil
	end
end

---Create a box adornment for every BasePart that doesn't have one yet.
---@param Character Model
function ESPObject:BuildAdornments(Character)
	for _, Part in next, Character:GetChildren() do
		if Part:IsA("BasePart") and not self.Adornments[Part] then
			local Adorn = Instance.new("BoxHandleAdornment")
			Adorn.Name = "__EP_Box"
			Adorn.Adornee = Part
			Adorn.AlwaysOnTop = true
			Adorn.ZIndex = 10
			Adorn.Size = Part.Size
			Adorn.Parent = self.Folder
			self.Adornments[Part] = Adorn
		end
	end
end

---Hide everything (billboard + boxes).
function ESPObject:Hide()
	self.Billboard.Enabled = false
	if next(self.Adornments) ~= nil then
		self:ClearAdornments()
	end
end

---Update ESP object for this frame.
function ESPObject:Update()
	if not Configuration.ExpectToggleValue("EP_ESP_Player_Enable") then
		return self:Hide()
	end

	local Character = self.Player.Character
	if not Character then
		self.LastCharacter = nil
		return self:Hide()
	end

	local Root = Character:FindFirstChild("HumanoidRootPart")
		or Character:FindFirstChild("UpperTorso")
		or Character:FindFirstChild("Torso")
	local Head = Character:FindFirstChild("Head")
	local Humanoid = Character:FindFirstChildOfClass("Humanoid")

	-- Distance + max distance filter (0 = unlimited).
	local LocalCharacter = LocalPlayer and LocalPlayer.Character
	local LocalRoot = LocalCharacter and LocalCharacter:FindFirstChild("HumanoidRootPart")
	local Distance = nil
	if LocalRoot and Root then
		Distance = (LocalRoot.Position - Root.Position).Magnitude
	end

	local MaxDistance = Configuration.ExpectOptionValue("EP_ESP_Player_MaxDistance")
	if MaxDistance and MaxDistance > 0 and Distance and Distance > MaxDistance then
		return self:Hide()
	end

	-- Rebuild boxes when the character respawned.
	if self.LastCharacter ~= Character then
		self:ClearAdornments()
		self.LastCharacter = Character
	end

	local Color = self:ResolveColor()

	-- Boxes / chams.
	if Configuration.ExpectToggleValue("EP_ESP_Player_Boxes") then
		self:BuildAdornments(Character)

		local Transparency = Configuration.ExpectOptionValue("EP_ESP_Player_BoxTransparency")
		if type(Transparency) ~= "number" or Transparency ~= Transparency then
			Transparency = 0.3
		end

		for Part, Adorn in next, self.Adornments do
			if Part and Part.Parent then
				Adorn.Color3 = Color
				Adorn.Transparency = Transparency
				Adorn.Visible = true
			end
		end
	elseif next(self.Adornments) ~= nil then
		self:ClearAdornments()
	end

	-- Text billboard (Name | Health | Studs).
	local Segments = {}

	if Configuration.ExpectToggleValue("EP_ESP_Player_ShowName") then
		Segments[#Segments + 1] = self:ResolveName(Character)
	end
	if Configuration.ExpectToggleValue("EP_ESP_Player_ShowHealth") and Humanoid then
		Segments[#Segments + 1] = "HP: " .. tostring(math.floor(Humanoid.Health + 0.5))
	end
	if Configuration.ExpectToggleValue("EP_ESP_Player_ShowDistance") and Distance then
		Segments[#Segments + 1] = math.floor(Distance) .. " studs"
	end

	if #Segments > 0 and Head then
		if self.Billboard.Adornee ~= Head then
			self.Billboard.Adornee = Head
		end
		self.Billboard.Enabled = true
		self.Label.Text = table.concat(Segments, " | ")
		self.Label.TextColor3 = Color
		self.Label.TextSize = Configuration.ExpectOptionValue("EP_ESP_FontSize") or 16

		local FontName = Configuration.ExpectOptionValue("EP_ESP_Font")
		self.Label.Font = (FontName and Enum.Font[FontName]) or Enum.Font.SourceSansSemibold
	else
		self.Billboard.Enabled = false
	end
end

---Detach ESP object.
function ESPObject:Detach()
	self:ClearAdornments()
	self.Maid:Clean()
end

---Add a player to the ESP registry.
---@param Player Player
local function AddPlayer(Player)
	if Player == LocalPlayer then
		return
	end
	if Objects[Player] then
		return
	end
	Objects[Player] = ESPObject.new(Player)
end

---Remove a player from the ESP registry.
---@param Player Player
local function RemovePlayer(Player)
	local Object = Objects[Player]
	if Object then
		Object:Detach()
		Objects[Player] = nil
	end
end

---Initialize the Player ESP engine.
function PlayerESP.Init()
	PlayerESP.Detach()
	CleanupLeftover()

	MySession = getgenv().__EP_ESPSession

	GuiContainer = Instance.new("Folder")
	GuiContainer.Name = CONTAINER_NAME
	GuiContainer.Parent = ResolveGuiParent()
	EngineMaid:Mark(GuiContainer)

	for _, Player in next, Players:GetPlayers() do
		AddPlayer(Player)
	end

	EngineMaid:Mark(Players.PlayerAdded:Connect(AddPlayer))
	EngineMaid:Mark(Players.PlayerRemoving:Connect(RemovePlayer))

	EngineMaid:Mark(RunService.RenderStepped:Connect(function()
		-- Self-cancel if a newer instance took over.
		if getgenv().__EP_ESPSession ~= MySession then
			PlayerESP.Detach()
			return
		end

		for _, Object in next, Objects do
			Object:Update()
		end
	end))

	Logger.Warn("Player ESP initialized.")
end

---Detach the Player ESP engine.
function PlayerESP.Detach()
	for Player, Object in next, Objects do
		Object:Detach()
		Objects[Player] = nil
	end

	EngineMaid:Clean()
	GuiContainer = nil
end

-- Return PlayerESP module.
return PlayerESP
end)
__bundle_register("Visuals/VisualsTab", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Visuals tab: Player ESP + Movement UI (kenduap/Epiphyllum library style).

