__bundle_register("init", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Epiphyllum entry point.

-- Default configuration.
local _Config = {
	BasePath = "Epiphyllum",
	SaveFolderName = "Epiphyllum",
	GamePath = "Epiphyllum",
	Remotes = {},
	Callbacks = {},
	StateChecks = {},
	Window = nil,
}

-- Define preprocessor identity functions.
PP_SCRAMBLE_NUM = function(X) return X end
PP_SCRAMBLE_STR = function(X) return X end
PP_SCRAMBLE_RE_NUM = function(X) return X end
LPH_NO_VIRTUALIZE = function(F) return F end

-- Epiphyllum module.
local Epiphyllum = {}

---Configure the Epiphyllum.
---@param Options table
function Epiphyllum.Configure(Options)
	for K, V in next, Options do
		_Config[K] = V
	end
end

---Initialize the Epiphyllum.
function Epiphyllum.Init()
	-- Set up Remotes with user-provided remotes and callbacks.
	local Remotes = require("Core/Remotes")
	Remotes.Configure(_Config.Remotes, _Config.Callbacks)

	-- Set up StateChecker with user-provided state checks.
	local StateChecker = require("Core/StateChecker")
	StateChecker.Configure(_Config.StateChecks)

	-- Initialize SaveManager with per-game timing folders.
	local SaveManager = require("Timings/SaveManager")
	SaveManager.Init(_Config.GamePath)

	-- Initialize ModuleManager with per-game modules path.
	local ModuleManager = require("Modules/ModuleManager")
	ModuleManager.Init(_Config.GamePath)
	ModuleManager.LoadGlobal("ForsakenHitboxes", true)

	-- Initialize Defense.
	local Defense = require("Core/Defense")
	Defense.Init()

	-- Initialize Builder UI if a window was provided.
	if _Config.Window then
		local BuilderTab = require("Builder/BuilderTab")
		BuilderTab.Init(_Config.Window, _Config.Icons, {
			GameFolderName = _Config.GameFolderName,
			GameName = _Config.GameName,
			GamePath = _Config.GamePath,
			OnAliasConfigImported = _Config.OnAliasConfigImported,
			PlaceId = _Config.PlaceId,
		})
	end
end

---Detach the Epiphyllum.
function Epiphyllum.Detach()
	-- Detach Defense.
	local Defense = require("Core/Defense")
	Defense.Detach()

	-- Detach ModuleManager.
	local ModuleManager = require("Modules/ModuleManager")
	ModuleManager.Detach()

	-- Detach SaveManager.
	local SaveManager = require("Timings/SaveManager")
	SaveManager.Detach()

	-- Detach BuilderTab.
	if _Config.Window then
		local BuilderTab = require("Builder/BuilderTab")
		BuilderTab.Detach()
	end
end

-- Return Epiphyllum module.
return Epiphyllum
end)
__bundle_register("__root", function(require, _LOADED, __bundle_register, __bundle_modules)
-- Hot reload: unload previous instance.
local Environment = getgenv()

do -- scope block: release locals at end to stay under Luau's 200-register chunk limit
---Unload script modules from a registry.
---@param ScriptModules table?
local function UnloadScriptModules(ScriptModules)
	if type(ScriptModules) ~= "table" then return end

	for Name, Module in next, ScriptModules do
		pcall(function()
			if Module and Module.Unload then
				Module.Unload()
			end
		end)
		ScriptModules[Name] = nil
	end
end

---Clean up MCP connector bridge tables from older wrappers.
local function CleanupMCPBridgeTables()
	if not getgc then return end

	for Index, Candidate in next, getgc(true) do
		if type(Candidate) ~= "table" then continue end

		local Callbacks = rawget(Candidate, "Callbacks")
		if type(Callbacks) ~= "table" then continue end
		if not rawget(Callbacks, "execute") or not rawget(Callbacks, "get-data-by-code") then continue end
		if rawget(Candidate, "EpiphyllumOwned") ~= true then continue end

		local Destroy = rawget(Candidate, "Destroy")
		if Destroy then
			pcall(Destroy, Candidate)
		else
			rawset(Candidate, "Connected", false)

			local AliveThread = rawget(Candidate, "AliveThread")
			if AliveThread then
				pcall(task.cancel, AliveThread)
			end

			local PollThread = rawget(Candidate, "PollThread")
			if PollThread then
				pcall(task.cancel, PollThread)
			end

			local Connections = rawget(Candidate, "Connections")
			if type(Connections) == "table" then
				for ConnectionIndex, Connection in next, Connections do
					pcall(function()
						Connection:Disconnect()
					end)
					Connections[ConnectionIndex] = nil
				end
			end

			local WebSocket = rawget(Candidate, "WebSocket")
			if WebSocket then
				pcall(function()
					WebSocket:Close()
				end)
			end
		end
	end
end

---Clean up standalone utility globals from older runs.
local function CleanupScriptGlobals()
	pcall(function()
		local Shutdown = Environment.__EpiphyllumMCPConnectorShutdown
		if Shutdown then
			Shutdown()
		end
	end)
	Environment.__EpiphyllumMCPConnectorShutdown = nil

	pcall(CleanupMCPBridgeTables)

	pcall(function()
		local Cobalt = Environment.Cobalt
		if Cobalt and Cobalt.shared and Cobalt.shared.Unload then
			Cobalt.shared.Unload()
		end
	end)
	Environment.Cobalt = nil
	Environment.CobaltInitialized = nil
	Environment.CobaltAutoExecuted = nil

	Environment.IY_LOADED = nil
	Environment.VexExecutedCheck = false
end

---Fallback destroy for old libraries without Unload.
---@param Prev table
local function DestroyPreviousLibrary(Prev)
	if Prev.Holder and Prev.Holder.Instance then
		Prev.Holder.Instance:Destroy()
	end
	if Prev.UnusedHolder and Prev.UnusedHolder.Instance then
		Prev.UnusedHolder.Instance:Destroy()
	end
	if Prev.OverlayHolder and Prev.OverlayHolder.Instance then
		Prev.OverlayHolder.Instance:Destroy()
	end

	if Prev.Connections then
		for Index, Conn in next, Prev.Connections do
			pcall(function() Conn:Disconnect() end)
		end
	end
end

---Unload previous runtime.
local function UnloadPreviousRuntime()
	local Prev = Environment._EpiphyllumLib
	local PrevRuntime = Environment._EpiphyllumRuntime

	UnloadScriptModules(Environment.__EpiphyllumScriptModules)
	if Prev then
		UnloadScriptModules(Prev._ScriptModules)
	end

	if PrevRuntime and PrevRuntime.Detach then
		pcall(PrevRuntime.Detach)
	end

	if Prev then
		pcall(function()
			if Prev.Unload then
				Prev:Unload()
			else
				DestroyPreviousLibrary(Prev)
			end
		end)
	end

	CleanupScriptGlobals()
	Environment.__EpiphyllumScriptModules = nil
	Environment._EpiphyllumLib = nil
	Environment._EpiphyllumRuntime = nil
end

if Environment._EpiphyllumLib or Environment._EpiphyllumRuntime or Environment.__EpiphyllumScriptModules then
	UnloadPreviousRuntime()
end
end -- scope block

-- Clean up leftover UI from previous runs (search all possible parents).
pcall(function()
	local Names = {"__EP_InfoLogger", "AnimationVisualizer"}
	local Parents = {game:GetService("CoreGui"), game.Players.LocalPlayer:FindFirstChild("PlayerGui")}
	pcall(function() Parents[#Parents + 1] = gethui() end)
	for Index, Parent in next, Parents do
		if Parent then
			for Index, Name in next, Names do
				local Prev = Parent:FindFirstChild(Name)
				if Prev then Prev:Destroy() end
			end
		end
	end
end)

-- Kill previous hitbox simulation loop and clean up parts.
local EpSessionId = game:GetService("HttpService"):GenerateGUID(false)
getgenv().__EP_SimulationSession = EpSessionId
getgenv().__EP_MusicSession = EpSessionId
getgenv().__EP_ESPSession = EpSessionId
getgenv().__EP_MovementSession = EpSessionId
task.wait()
pcall(function()
	for Index, Child in next, workspace:GetChildren() do
		if Child:IsA("Part") and Child.Name == "__EP_HitboxSim" then
			Child:Destroy()
		end
	end
end)

-- Clean up leftover glass parts and DepthOfField from previous runs.
pcall(function()
	local Camera = workspace.CurrentCamera
	for Index, Child in next, Camera:GetChildren() do
		if Child:IsA("Part") and Child.Material == Enum.Material.Glass then
			Child:Destroy()
		end
	end
	local Lighting = game:GetService("Lighting")
	for Index, Child in next, Lighting:GetChildren() do
		if Child:IsA("DepthOfFieldEffect") or (Child:IsA("BlurEffect") and Child.Name:find("__EP_")) then
			Child:Destroy()
		end
	end
end)

-- Clean up leftover music from previous runs.
pcall(function()
	for Index, Sound in next, game:GetService("SoundService"):GetChildren() do
		if Sound:IsA("Sound") and Sound.Name:find("__epiphyllum_bgm_0xCAFE", 1, true) == 1 then
			Sound:Stop()
			Sound:Destroy()
		end
	end
end)

-- Epiphyllum auto-execution entry point.
local Epiphyllum = require("init")
local Remotes = require("Core/Remotes")
local InfoLogger = require("Core/InfoLogger")
local AnimationVisualizer = require("Core/AnimationVisualizer")
local MusicResolver = require("Audio/MusicResolver")
local Logger = require("Utility/Logger")
local Configuration = require("Utility/Configuration")
local Library = require("GUI/Library")
local SaveManager = require("Timings/SaveManager")
local VisualsTab = require("Visuals/VisualsTab")
local DefaultConfig = require("GUI/DefaultConfig")
local BuildDefaultRemotes = require("Core/DefaultRemotes")

-- Set library reference for Configuration.
Configuration.SetLibrary(Library)

-- Services.
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")
local Stats = game:GetService("Stats")

-- Workspace folder name.
local FolderName = "Epiphyllum"
local PlaceId = game.PlaceId

-- Get game name dynamically.
local GameName = "Unknown"
pcall(function()
	local MarketplaceService = game:GetService("MarketplaceService")
	local ProductInfo = MarketplaceService:GetProductInfo(PlaceId)
	GameName = ProductInfo.Name or "Unknown"
end)

---Sanitize a string for filesystem use.
local function SanitizeFolderName(Name)
	return Name:gsub("[/\\:*?\"<>|]", "_"):sub(1, 50)
end

-- Per-game folder: "Epiphyllum/GameName - PlaceId/".
local GameFolderName = SanitizeFolderName(GameName) .. " - " .. tostring(PlaceId)
local GamePath = FolderName .. "/" .. GameFolderName

-- Startup marker files.
local SilentMarkerFile = "smarker.txt"
local SkipIntroMarkerFile = "skipintro.txt"
local MusicDisabledMarkerFile = "musicdisabled.txt"

---Check whether a marker file exists.
---@param FilePath string
---@return boolean
local function HasMarkerFile(FilePath)
	return isfile and isfile(FilePath) or false
end

---Set marker file state.
---@param FilePath string
---@param Value boolean
---@param Content string
local function SetMarkerFile(FilePath, Value, Content)
	if Value then
		if writefile then writefile(FilePath, Content) end
	elseif isfile and delfile and isfile(FilePath) then
		delfile(FilePath)
	end
end

---Read a boolean-like config value.
---@param Value any
---@return boolean?
local function ReadConfigBoolean(Value)
	if Value == true or Value == false then
		return Value
	end

	if type(Value) == "string" then
		local Lower = Value:lower()
		if Lower == "true" then return true end
		if Lower == "false" then return false end
	end

	return nil
end

---Read startup config before UI config loading runs.
---@return table?
local function ReadStartupConfig()
	if not isfile or not readfile then
		return nil
	end

	local ConfigsPath = FolderName .. "/Configs"
	local AutoloadPath = ConfigsPath .. "/autoload.txt"
	if not isfile(AutoloadPath) then
		return nil
	end

	local AutoloadName = tostring(readfile(AutoloadPath) or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if AutoloadName == "" then
		return nil
	end

	local ConfigPath = ConfigsPath .. "/" .. AutoloadName
	if not isfile(ConfigPath) then
		return nil
	end

	local DecodeOk, Decoded = pcall(function()
		return HttpService:JSONDecode(readfile(ConfigPath))
	end)

	if not DecodeOk or type(Decoded) ~= "table" then
		return nil
	end

	return Decoded
end

-- Startup settings.
local StartupConfig = ReadStartupConfig()
local SilentMode = HasMarkerFile(SilentMarkerFile) or (type(StartupConfig) == "table" and StartupConfig.EP_SilentMode == true)
local SkipIntroAnimation = HasMarkerFile(SkipIntroMarkerFile) or (type(StartupConfig) == "table" and StartupConfig.EP_SkipIntroAnimation == true)
local MusicStartupDisabled = HasMarkerFile(MusicDisabledMarkerFile)
local StartupMusicEnabled = type(StartupConfig) == "table" and ReadConfigBoolean(StartupConfig.EP_MusicEnabled) or nil
if MusicStartupDisabled then
	StartupMusicEnabled = false
elseif StartupMusicEnabled == nil then
	StartupMusicEnabled = true
end
local MusicEnabled = StartupMusicEnabled
Library.Flags["EP_MusicEnabled"] = MusicEnabled
local StartupShowMenuOnLaunch = type(StartupConfig) == "table" and ReadConfigBoolean(StartupConfig.EP_ShowMenuOnLaunch) or nil
if StartupShowMenuOnLaunch == nil then
	StartupShowMenuOnLaunch = true
end
local ShowMenuOnLaunch = StartupShowMenuOnLaunch
Library.Flags["EP_ShowMenuOnLaunch"] = ShowMenuOnLaunch
local SilentModeRevealed = not SilentMode

---Check whether silent mode should currently suppress UI.
---@return boolean
local function IsSilentModeSuppressed()
	return SilentMode and not SilentModeRevealed
end

---Sync silent mode globals.
local function SyncSilentModeGlobals()
	getgenv().EpiphyllumSilentMode = IsSilentModeSuppressed()
	getgenv().EpiphyllumSilentModeEnabled = SilentMode
	getgenv().EpiphyllumSilentModeRevealed = SilentModeRevealed
end

---Sync show menu on launch global.
local function SyncShowMenuOnLaunchGlobal()
	getgenv().EpiphyllumShowMenuOnLaunch = ShowMenuOnLaunch
end

SyncSilentModeGlobals()
SyncShowMenuOnLaunchGlobal()
getgenv().EpiphyllumSkipIntroAnimation = SkipIntroAnimation
getgenv().EpiphyllumLaunchMenuLocked = true

-- Place ID alias resolution — scan game folders for aliases.json containing this PlaceId.
do -- scope block: release locals at end to stay under Luau's 200-register chunk limit
local PlaceIdStr = tostring(PlaceId)
local AliasGamePath = nil
local AliasGameFolderName = nil
local TimingFolderNames = { "Animation", "Sound", "Part" }

---Check if a game folder has saved timing files.
---@param Path string
---@return boolean
local function HasTimingFiles(Path)
	for Index, Folder in next, TimingFolderNames do
		local TimingPath = Path .. "/Timings/" .. Folder
		if not isfolder(TimingPath) then continue end

		local FileListOk, FileList = pcall(listfiles, TimingPath)
		if not FileListOk or not FileList then continue end

		for FileIndex, FilePath in next, FileList do
			if tostring(FilePath):sub(-5) == ".json" then
				return true
			end
		end
	end

	return false
end

if not HasTimingFiles(GamePath) and isfolder(FolderName) then
	local FolderListOk, FolderList = pcall(listfiles, FolderName)
	if FolderListOk and FolderList then
		table.sort(FolderList)

		for Index, FolderPath in next, FolderList do
			if AliasGamePath then break end
			if not isfolder(FolderPath) then continue end

			local FolderPlaceId = tostring(FolderPath):match("%- (%d+)$")
			if FolderPlaceId == PlaceIdStr then continue end
			if not HasTimingFiles(FolderPath) then continue end

			local AliasFile = FolderPath .. "/aliases.json"
			if not isfile(AliasFile) then continue end

			local AliasOk, AliasList = pcall(function()
				return HttpService:JSONDecode(readfile(AliasFile))
			end)
			if not AliasOk or type(AliasList) ~= "table" then continue end

			for AliasIndex, Id in next, AliasList do
				if tostring(Id) ~= PlaceIdStr then continue end

				AliasGamePath = FolderPath
				AliasGameFolderName = FolderPath:match("[^/\\]+$")
				break
			end
		end
	end
end

if AliasGamePath then
	GamePath = AliasGamePath
	GameFolderName = AliasGameFolderName
end
end -- scope block

-- Base64 decode lookup.
local Base64Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64Lookup = {}
for I = 1, #Base64Chars do
	B64Lookup[Base64Chars:sub(I, I)] = I - 1
end

---Decode a base64 string to raw bytes.
---@param Data string
---@return string
local function Base64Decode(Data)
	Data = Data:gsub("%s", "")

	local Out = {}
	local N = #Data

	for I = 1, N, 4 do
		local A = B64Lookup[Data:sub(I, I)] or 0
		local B = B64Lookup[Data:sub(I + 1, I + 1)] or 0
		local C = B64Lookup[Data:sub(I + 2, I + 2)] or 0
		local D = B64Lookup[Data:sub(I + 3, I + 3)] or 0

		local Combined = A * 262144 + B * 4096 + C * 64 + D

		Out[#Out + 1] = string.char(math.floor(Combined / 65536) % 256)

		if Data:sub(I + 2, I + 2) ~= "=" then
			Out[#Out + 1] = string.char(math.floor(Combined / 256) % 256)
		end

		if Data:sub(I + 3, I + 3) ~= "=" then
			Out[#Out + 1] = string.char(Combined % 256)
		end
	end

	return table.concat(Out)
end

-- Create workspace folders.
if not isfolder(FolderName) then makefolder(FolderName) end
if not isfolder(GamePath) then makefolder(GamePath) end
if not isfolder(GamePath .. "/Timings") then makefolder(GamePath .. "/Timings") end
if not isfolder(GamePath .. "/Timings/Animation") then makefolder(GamePath .. "/Timings/Animation") end
if not isfolder(GamePath .. "/Timings/Sound") then makefolder(GamePath .. "/Timings/Sound") end
if not isfolder(GamePath .. "/Timings/Part") then makefolder(GamePath .. "/Timings/Part") end
if not isfolder(GamePath .. "/Modules") then makefolder(GamePath .. "/Modules") end
if not isfolder(GamePath .. "/Modules/Globals") then makefolder(GamePath .. "/Modules/Globals") end

-- Music cache.
local MusicPath = FolderName .. "/Music"
if not isfolder(MusicPath) then makefolder(MusicPath) end

-- Icons (shared across games).
local IconsPath = FolderName .. "/Icons"
if not isfolder(IconsPath) then
	makefolder(IconsPath)
end

local IconAssets = {}
local IconData = require("GUI/Icons")
for Name, B64 in next, IconData do
	-- Content length as fingerprint — new content = new filename = cache bust.
	local FilePath = IconsPath .. "/" .. Name .. "_" .. #B64 .. ".png"
	if not isfile(FilePath) then
		writefile(FilePath, Base64Decode(B64))
	end
	IconAssets[Name] = getcustomasset(FilePath)
end

-- Background music.
local AudioFile = MusicPath .. "/snooze.mp3"
local MusicSoundName = "__epiphyllum_bgm_0xCAFE"
local DefaultMusicVolume = 0.3
local StartupMusicVolume = DefaultMusicVolume
local StartupConfigVolume = type(StartupConfig) == "table" and tonumber(StartupConfig.EP_MusicVolume) or nil
if StartupConfigVolume then
	if StartupConfigVolume < 0 then
		StartupConfigVolume = 0
	elseif StartupConfigVolume > 100 then
		StartupConfigVolume = 100
	end

	StartupMusicVolume = StartupConfigVolume / 100
end

if not isfile(AudioFile) then
	local AudioData = require("Audio/Music/SnoozeMusic")
	writefile(AudioFile, Base64Decode(AudioData))
end

local DefaultMusicAsset = getcustomasset(AudioFile)
local BgMusic = Instance.new("Sound")
BgMusic.Name = MusicSoundName
BgMusic.SoundId = DefaultMusicAsset
BgMusic.Volume = StartupMusicVolume
BgMusic.Looped = true
BgMusic.Parent = SoundService
if StartupMusicEnabled and not IsSilentModeSuppressed() then
	BgMusic:Play()
end

-- Music state.
local MusicRequestId = 0
local MusicSourceValue = ""
local MusicVolumeValue = StartupMusicVolume
local MusicStreamController = nil
local MusicSegmentSounds = {}
local MusicSessionId = Environment.__EP_MusicSession
local LastMusicResolveSource = nil
local LastMusicResolveAt = 0
local DuplicateMusicResolveWindow = 0.75
local MusicStreamQueueLimit = 1

---Trim text.
---@param Text string
---@return string
local function TrimText(Text)
	return tostring(Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

---Check if music should currently play.
---@return boolean
local function ShouldPlayMusic()
	return MusicEnabled and not IsSilentModeSuppressed()
end

---Check if a music stream worker should keep running.
---@param Controller table
---@param RequestId number
---@return boolean
local function ShouldContinueMusicStream(Controller, RequestId)
	return Controller.Active and RequestId == MusicRequestId and Environment.__EP_MusicSession == MusicSessionId
end

---Destroy a segmented music sound.
---@param Sound Sound
local function DestroyMusicSound(Sound)
	if not Sound then return end

	pcall(function()
		Sound:Stop()
		Sound:Destroy()
	end)

	for Index = 1, #MusicSegmentSounds do
		if MusicSegmentSounds[Index] == Sound then
			table.remove(MusicSegmentSounds, Index)
			break
		end
	end
end

---Stop segmented music playback.
local function StopMusicStream()
	if MusicStreamController then
		MusicStreamController.Active = false
	end

	MusicStreamController = nil

	for Index = 1, #MusicSegmentSounds do
		local Sound = MusicSegmentSounds[Index]
		if Sound then
			pcall(function()
				Sound:Stop()
				Sound:Destroy()
			end)
		end
	end

	MusicSegmentSounds = {}
end

---Apply current music volume.
local function ApplyMusicVolume()
	BgMusic.Volume = MusicVolumeValue

	for Index = 1, #MusicSegmentSounds do
		local Sound = MusicSegmentSounds[Index]
		if Sound then
			pcall(function()
				Sound.Volume = MusicVolumeValue
			end)
		end
	end
end

---Create a segmented music sound.
---@param Segment table
---@return Sound
local function CreateSegmentSound(Segment)
	local Sound = Instance.new("Sound")
	Sound.Name = string.format("%s_segment_%04d", MusicSoundName, Segment.Index or 0)
	Sound.SoundId = Segment.Asset
	Sound.Volume = MusicVolumeValue
	Sound.Looped = false
	Sound.Parent = SoundService
	MusicSegmentSounds[#MusicSegmentSounds + 1] = Sound
	return Sound
end

---Wait for a music sound to load.
---@param Sound Sound
---@param Controller table
---@param RequestId number
local function WaitForMusicSound(Sound, Controller, RequestId)
	local StartedAt = os.clock()

	while ShouldContinueMusicStream(Controller, RequestId) and not Sound.IsLoaded and os.clock() - StartedAt < 8 do
		task.wait(0.05)
	end
end

---Pause current music.
local function PauseMusic()
	if MusicStreamController and MusicStreamController.CurrentSound then
		pcall(function()
			MusicStreamController.CurrentSound:Pause()
		end)
	end

	BgMusic:Pause()
end

---Resume or start background music.
local function ResumeMusic()
	if MusicStreamController then
		local CurrentSound = MusicStreamController.CurrentSound
		if CurrentSound and not CurrentSound.IsPlaying then
			if CurrentSound.TimePosition > 0 and CurrentSound.TimeLength > 0 and CurrentSound.TimePosition < CurrentSound.TimeLength then
				CurrentSound:Resume()
			else
				CurrentSound:Play()
			end
		end

		return
	end

	if BgMusic.IsPlaying then return end

	if BgMusic.TimePosition > 0 and BgMusic.TimeLength > 0 and BgMusic.TimePosition < BgMusic.TimeLength then
		BgMusic:Resume()
	else
		BgMusic:Play()
	end
end

local PlayMusicSource = nil

---Start segmented YouTube music.
---@param Stream table
---@param RequestId number
---@param Source string
do -- scope block: release locals at end to stay under Luau's 200-register chunk limit
local function StartMusicStream(Stream, RequestId, Source)
	StopMusicStream()
	BgMusic:Stop()

	local Controller = {
		Active = true,
		Queue = {},
		Done = false,
		Error = nil,
		CurrentSound = nil,
		Started = false,
	}
	MusicStreamController = Controller

	task.spawn(function()
		while ShouldContinueMusicStream(Controller, RequestId) do
			if #Controller.Queue >= MusicStreamQueueLimit then
				task.wait(0.05)
				continue
			end

			local SegmentOk, Segment = Stream:ReadSegment(Stream.SegmentFrames)
			if not SegmentOk then
				Controller.Error = Segment
				Controller.Done = true
				break
			end

			if not Segment then
				Controller.Done = true
				break
			end

			if not ShouldContinueMusicStream(Controller, RequestId) then
				break
			end

			local Sound = CreateSegmentSound(Segment)
			Controller.Queue[#Controller.Queue + 1] = {
				Sound = Sound,
				Segment = Segment,
			}

			if Segment.Done then
				Controller.Done = true
				break
			end
		end
	end)

	task.spawn(function()
		while ShouldContinueMusicStream(Controller, RequestId) do
			if #Controller.Queue == 0 then
				if Controller.Done then
					break
				end

				task.wait(0.03)
				continue
			end

			local Item = table.remove(Controller.Queue, 1)
			local Sound = Item.Sound
			Controller.CurrentSound = Sound
			WaitForMusicSound(Sound, Controller, RequestId)

			while ShouldContinueMusicStream(Controller, RequestId) and not ShouldPlayMusic() do
				task.wait(0.05)
			end

			if not ShouldContinueMusicStream(Controller, RequestId) then
				break
			end

			Sound:Play()
			if not Controller.Started then
				Controller.Started = true
				Logger.Notify(
					"%s music source: %s",
					ShouldPlayMusic() and "Streaming" or "Loaded",
					tostring(Stream.Title or Stream.SourceType or "YouTube")
				)
			end

			while ShouldContinueMusicStream(Controller, RequestId) do
				if not ShouldPlayMusic() then
					Sound:Pause()

					while ShouldContinueMusicStream(Controller, RequestId) and not ShouldPlayMusic() do
						task.wait(0.05)
					end

					if not ShouldContinueMusicStream(Controller, RequestId) then
						break
					end

					if Sound.TimePosition > 0 and Sound.TimeLength > 0 and Sound.TimePosition < Sound.TimeLength then
						Sound:Resume()
					else
						Sound:Play()
					end
				end

				if not Sound.IsPlaying then
					break
				end

				task.wait()
			end

			Controller.CurrentSound = nil
			DestroyMusicSound(Sound)
		end

		if Environment.__EP_MusicSession == MusicSessionId and RequestId == MusicRequestId and Controller.Error then
			Logger.LongNotify("Music stream failed: %s", tostring(Controller.Error))
		end

		if Environment.__EP_MusicSession == MusicSessionId and RequestId == MusicRequestId and MusicStreamController == Controller then
			MusicStreamController = nil
		end

		if Environment.__EP_MusicSession == MusicSessionId and RequestId == MusicRequestId and Controller.Active and not Controller.Error and MusicSourceValue == Source then
			local PlaylistVideoIds = Stream.PlaylistVideoIds
			local PlaylistIndex = tonumber(Stream.PlaylistIndex) or 1
			local NextPlaylistIndex = PlaylistIndex + 1

			if type(PlaylistVideoIds) == "table" and #PlaylistVideoIds > 0 then
				if NextPlaylistIndex > #PlaylistVideoIds then
					NextPlaylistIndex = 1
				end
			else
				PlaylistVideoIds = nil
				NextPlaylistIndex = nil
			end

			task.defer(function()
				if Environment.__EP_MusicSession == MusicSessionId and RequestId == MusicRequestId and MusicSourceValue == Source then
					PlayMusicSource(Source, PlaylistVideoIds, NextPlaylistIndex)
				end
			end)
		end
	end)
end

---Apply resolved music result.
---@param Result table
local function ApplyMusicResult(Result)
	StopMusicStream()
	BgMusic:Stop()
	BgMusic.SoundId = Result.Asset
	BgMusic.Looped = true
	BgMusic.TimePosition = 0
	ApplyMusicVolume()

	if ShouldPlayMusic() then
		BgMusic:Play()
	end
end

---Play default music.
local function PlayDefaultMusic()
	MusicRequestId = MusicRequestId + 1
	local AlreadyDefault = not MusicStreamController and BgMusic.SoundId == DefaultMusicAsset
	if not AlreadyDefault then
		StopMusicStream()
		BgMusic:Stop()
		BgMusic.SoundId = DefaultMusicAsset
		BgMusic.Looped = true
		BgMusic.TimePosition = 0
	end

	ApplyMusicVolume()
	if ShouldPlayMusic() then
		ResumeMusic()
	else
		PauseMusic()
	end
end

---Play music source.
---@param Source string
---@param PlaylistVideoIds table?
---@param PlaylistIndex number?
function PlayMusicSource(Source, PlaylistVideoIds, PlaylistIndex)
	Source = TrimText(Source)
	local IsPlaylistStep = PlaylistVideoIds ~= nil or PlaylistIndex ~= nil
	local CurrentTime = os.clock()

	if not IsPlaylistStep and Source ~= "" and LastMusicResolveSource == Source and (CurrentTime - LastMusicResolveAt) <= DuplicateMusicResolveWindow then
		return
	end

	if not IsPlaylistStep and Source ~= "" then
		LastMusicResolveSource = Source
		LastMusicResolveAt = CurrentTime
	end

	local PreviousSource = MusicSourceValue
	MusicSourceValue = Source
	MusicRequestId = MusicRequestId + 1

	if Source == "" then
		PlayDefaultMusic()
		return
	end

	local RequestId = MusicRequestId
	local IsYoutubeSource = MusicResolver.IsYoutubeUrl(Source)
	if IsYoutubeSource and (Source ~= PreviousSource or PlaylistIndex ~= nil) then
		StopMusicStream()
		BgMusic:Stop()
		MusicResolver.ClearCache(MusicPath)
	end

	task.spawn(function()
		Logger.Notify("Resolving music source.")
		local Options = {
			CachePath = MusicPath,
			AudioFormat = "mp3",
			AudioBitrate = "128",
			YoutubePlaylistVideoIds = PlaylistVideoIds,
			YoutubePlaylistIndex = PlaylistIndex,
			ShouldContinue = function()
				return RequestId == MusicRequestId and Environment.__EP_MusicSession == MusicSessionId
			end,
		}

		if IsYoutubeSource then
			local StreamOk, Stream = MusicResolver.CreateYoutubeStream(Source, Options)
			if RequestId ~= MusicRequestId then return end

			if StreamOk then
				StartMusicStream(Stream, RequestId, Source)
				return
			end

			Logger.Notify("Native stream failed. Trying fallback resolver.")
		end

		local ResolveOk, Result = MusicResolver.Resolve(Source, Options)

		if RequestId ~= MusicRequestId then return end

		if not ResolveOk then
			Logger.LongNotify("Music source failed: %s", tostring(Result))
			return
		end

		ApplyMusicResult(Result)
		Logger.Notify(
			"%s music source: %s",
			ShouldPlayMusic() and "Playing" or "Loaded",
			tostring(Result.Title or Result.SourceType or "Audio")
		)
	end)
end

end -- scope block

-- Write global modules to workspace (per-game).
do -- scope block: release locals at end to stay under Luau's 200-register chunk limit
local GlobalsPath = GamePath .. "/Modules/Globals"

local GlobalModules = {
	["Waiter.lua"] = [==[---Waiter module.
local Waiter = {}

---@module Core.Latency
local Latency = getfenv().Latency

---Find a track.
---@param Aid string Animation ID to look for.
---@param Animator Animator The animator to search in.
---@return AnimationTrack?
function Waiter.Ftrack(Aid, Animator)
	for Index, Track in next, Animator:GetPlayingAnimationTracks() do
		local Animation = Track.Animation
		if not Animation then
			continue
		end

		if Animation.AnimationId ~= Aid then
			continue
		end

		return Track
	end
end

---Stepped wait.
---@param Defender Defender
---@param Time number The time to wait in seconds.
---@param Callback function The callback to run.
function Waiter.Stw(Defender, Time, Callback)
	local LastTimestamp = os.clock()
	local InitialPing = Latency.Rtt()

	while (os.clock() - LastTimestamp) <= (Time - InitialPing) do
		-- Wait.
		task.wait()

		-- Step.
		Callback()
	end
end

---Fetch a track.
---@param Aid string Animation ID to look for.
---@param Animator Animator The animator to search in.
---@return AnimationTrack?
function Waiter.Fet(Aid, Animator)
	while task.wait() do
		local Track = Waiter.Ftrack(Aid, Animator)
		if not Track then
			continue
		end

		return Track
	end
end

-- Return Waiter module.
return Waiter]==],
	["ProjectileTracker.lua"] = [==[---@type Signal
local Signal = getfenv().Signal

---@type Maid
local Maid = getfenv().Maid

---@note: The goal of this module is to track projectiles --
--- To be able to distribute each projectile to a specific, unique tracker which will handle it.

---@class ProjectileTracker
---@field Projectile Instance
local ProjectileTracker = {}
ProjectileTracker.__index = ProjectileTracker

-- Global list of projectiles that we need to skip.
local SeenProjectiles = {}

-- Object list.
local TrackerObjects = {}

-- Projectile tracker maid.
local PtMaid = Maid.new()

-- Initialize global signals.
local Thrown = workspace:WaitForChild("Thrown")
local ChildAdded = Signal.new(Thrown.ChildAdded)

---@note: Forced fully ordered from first to last projectile tracker.
PtMaid:Mark(ChildAdded:Connect("ProjectileTracker_ThrownChildAdded", function(Child)
	for Index, Tracker in next, TrackerObjects do
		if Tracker.Projectile then
			continue
		end

		if not Tracker.Callback(Child) then
			continue
		end

		if SeenProjectiles[Child] then
			continue
		end

		Tracker.Projectile = Child

		SeenProjectiles[Child] = true
	end
end))

---Wait for the first projectile that was found.
---@return Instance
function ProjectileTracker:Wait()
	repeat
		task.wait()
	until self.Projectile

	return self.Projectile
end

---Detach function. Module function. It is not related to the object itself.
function ProjectileTracker.Detach()
	PtMaid:Clean()
end

---Create new ProjectileTracker object.
---@param Callback fun(Candidate: Instance): boolean
---@return ProjectileTracker
function ProjectileTracker.new(Callback)
	local self = setmetatable({}, ProjectileTracker)
	self.Projectile = nil
	self.Callback = Callback
	TrackerObjects[#TrackerObjects + 1] = self
	return self
end

-- Return ProjectileTracker module.
return ProjectileTracker]==],
	["ProjectileListener.lua"] = [==[---@note: The goal of this module is to be able to not have duplicates of handling of a projectile.
--- Normal child added signals will not work with multiple-same modules running because they will all create their own listener.
--- This module will prioritize only the last created listener, which will be the one that is used to handle the projectile.

---@class Maid
local Maid = getfenv().Maid

---@class Signal
local Signal = getfenv().Signal

---@class ProjectileListener
---@field Maid Maid
