}

for Name, Content in next, GlobalModules do
	local Path = GlobalsPath .. "/" .. Name
	if not isfile(Path) then
		writefile(Path, Content)
	end
end
end -- scope block

-- Action types.
-- Action to internal name mapping.
local ActionToInternal = {
	Parry = "parry",
	Block = "block",
	Unblock = "unblock",
	Dodge = "dodge",
	["Dodge Cancel"] = "dodgecancel",
	["Forced Full Dodge"] = "forcedfulldodge",
	Jump = "jump",
	["Teleport Up"] = "teleportup",
	Slide = "slide",
	["Start Slide"] = "startslide",
	["End Slide"] = "endslide",
	Crouch = "crouch",
	["Start Crouch"] = "startcrouch",
	["End Crouch"] = "endcrouch",
	FlashStep = "flashstep",
}

-- Action to filter category mapping.
local ActionToCategory = {
	Parry = "Parry",
	Block = "Block",
	Unblock = "Block",
	Dodge = "Dodge",
	["Dodge Cancel"] = "Dodge",
	["Forced Full Dodge"] = "Dodge",
	Jump = "Jump",
	["Teleport Up"] = "Teleport Up",
	Slide = "Slide",
	["Start Slide"] = "Slide",
	["End Slide"] = "Slide",
	Crouch = "Crouch",
	["Start Crouch"] = "Crouch",
	["End Crouch"] = "Crouch",
	FlashStep = "FlashStep",
}

-- Internal action to filter category mapping.
local InternalToCategory = {
	parry = "Parry",
	block = "Block",
	unblock = "Block",
	dodge = "Dodge",
	dodgecancel = "Dodge",
	forcedfulldodge = "Dodge",
	jump = "Jump",
	teleportup = "Teleport Up",
	slide = "Slide",
	startslide = "Slide",
	endslide = "Slide",
	crouch = "Crouch",
	startcrouch = "Crouch",
	endcrouch = "Crouch",
	flashstep = "FlashStep",
}

---Normalize an action string.
---@param Action string
---@return string
local function NormalizeAction(Action)
	return tostring(Action or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

---Get internal name for an action (lowercase). Falls back to a compact lowercased input.
---@param Action string
---@return string
local function GetInternalName(Action)
	Action = NormalizeAction(Action)
	return ActionToInternal[Action] or Action:gsub("%s+", ""):lower()
end

---Format an action name for display.
---@param Action string
---@return string
local function FormatActionDisplay(Action)
	Action = NormalizeAction(Action)
	if Action == "" then return "" end
	if ActionToInternal[Action] or ActionToCategory[Action] then return Action end

	return (Action:gsub("%S+", function(Word)
		return Word:sub(1, 1):upper() .. Word:sub(2)
	end))
end

---Get filter category for an action. Falls back to the action name itself.
---@param Action string
---@return string
local function GetCategory(Action)
	Action = NormalizeAction(Action)
	return ActionToCategory[Action] or InternalToCategory[GetInternalName(Action)] or FormatActionDisplay(Action)
end

---Resolve an instance path string to an Instance.
---@param Path string
---@return Instance?
local function ResolvePath(Path)
	if not Path or Path == "" then return nil end

	local Current = game
	for Segment in string.gmatch(Path, "[^%.]+") do
		if Current == game and Segment == "game" then continue end
		Current = Current:FindFirstChild(Segment)
		if not Current then return nil end
	end

	return Current
end

---Load saved config from workspace.
---@return table
local function LoadConfig()
	local FilePath = GamePath .. "/remotes.json"

	if not isfile(FilePath) then
		-- No local dispatch config: force the baked-in default remotes/inputs.
		return BuildDefaultRemotes()
	end

	local Success, Result = pcall(function()
		return HttpService:JSONDecode(readfile(FilePath))
	end)

	if not Success then return { remotes = {}, inputs = {} } end

	-- New format: has remotes array.
	if Result.remotes then
		return Result
	end

	-- Old format: migrate keyed remotes to array entries.
	local Config = { remotes = {}, inputs = {} }

	for Name, Value in next, Result do
		if typeof(Value) == "string" and Value ~= "" then
			Config.remotes[#Config.remotes + 1] = {
				action = Name:sub(1, 1):upper() .. Name:sub(2),
				path = Value,
				args = {},
			}
		elseif typeof(Value) == "table" then
			for Index, Entry in next, Value do
				if Entry.path and Entry.path ~= "" then
					Config.remotes[#Config.remotes + 1] = {
						action = Name:sub(1, 1):upper() .. Name:sub(2),
						path = Entry.path,
						args = Entry.args or {},
					}
				end
			end
		end
	end

	-- Migrate old inputs file.
	local InputsPath = GamePath .. "/inputs.json"
	if isfile(InputsPath) then
		local ISuccess, IResult = pcall(function()
			return HttpService:JSONDecode(readfile(InputsPath))
		end)
		if ISuccess and IResult then
			for Name, Key in next, IResult do
				if typeof(Key) == "string" and Key ~= "" then
					Config.inputs[#Config.inputs + 1] = {
						action = Name:sub(1, 1):upper() .. Name:sub(2),
						key = Key,
					}
				end
			end
		end
	end

	return Config
end

---Save config to workspace.
---@param Config table
local function SaveConfig(Config)
	local EncodeOk, Json = pcall(HttpService.JSONEncode, HttpService, Config)
	if not EncodeOk then return end

	local WriteOk = pcall(writefile, GamePath .. "/remotes.json", Json)
	if not WriteOk then return end

	for Index, Path in next, SaveManager.AliasSyncPaths() do
		pcall(function()
			if not isfolder(Path) then makefolder(Path) end
			writefile(Path .. "/remotes.json", Json)
		end)
	end
end

---Evaluate an array of arg strings into a flat table of values.
---@param ArgStrings table
---@return table?
local function EvaluateArgStrings(ArgStrings)
	if not ArgStrings or #ArgStrings == 0 then return nil end

	local Joined = table.concat(ArgStrings, ", ")
	if Joined == "" then return nil end

	local Fn = loadstring("return {" .. Joined .. "}")
	if not Fn then return nil end

	local Success, Result = pcall(Fn)
	if not Success or typeof(Result) ~= "table" then return nil end

	return #Result > 0 and Result or nil
end

---Resolve a KeyCode name to an Enum.KeyCode value.
---@param Input string
---@return Enum.KeyCode?
local function ResolveKeyCode(Input)
	if not Input or Input == "" then return nil end

	-- Literal space character.
	if Input == " " then
		return Enum.KeyCode.Space
	end

	local KeyAliases = {
		spacebar = "Space",
		space = "Space",
		ctrl = "LeftControl",
		control = "LeftControl",
		leftctrl = "LeftControl",
		leftcontrol = "LeftControl",
		rightctrl = "RightControl",
		rightcontrol = "RightControl",
		shift = "LeftShift",
		leftshift = "LeftShift",
		rightshift = "RightShift",
		alt = "LeftAlt",
		leftalt = "LeftAlt",
		rightalt = "RightAlt",
	}

	-- Trim whitespace and enum prefixes.
	local KeyText = TrimText(Input)
	if KeyText:lower():find("^enum%.keycode%.") then
		KeyText = KeyText:sub(14)
	end
	if KeyText == "" then return nil end

	local Normalized = KeyText:lower():gsub("[%s_%-]", "")
	local KeyName = KeyAliases[Normalized] or KeyText

	if #KeyName == 1 then
		KeyName = KeyName:upper()
	else
		KeyName = KeyName:sub(1, 1):upper() .. KeyName:sub(2)
	end

	local Success, KeyCode = pcall(function()
		return Enum.KeyCode[KeyName]
	end)

	return Success and KeyCode or nil
end

---Resolve a mouse input alias to a VIM mouse button index.
---@param Input string
---@return number?
local function ResolveMouseButton(Input)
	if not Input or Input == "" then return nil end

	Input = TrimText(Input)
	local Normalized = Input:lower():gsub("^enum%.userinputtype%.", ""):gsub("[%s_%-]", "")

	local MouseAliases = {
		left = 0,
		leftclick = 0,
		leftmouse = 0,
		leftbutton = 0,
		lmb = 0,
		mb1 = 0,
		mouse1 = 0,
		m1 = 0,
		mousebutton1 = 0,

		right = 1,
		rightclick = 1,
		rightmouse = 1,
		rightbutton = 1,
		rmb = 1,
		mb2 = 1,
		mouse2 = 1,
		m2 = 1,
		mousebutton2 = 1,

		middle = 2,
		middleclick = 2,
		middlemouse = 2,
		middlebutton = 2,
		mmb = 2,
		mb3 = 2,
		mouse3 = 2,
		m3 = 2,
		mousebutton3 = 2,
		wheelclick = 2,
	}

	return MouseAliases[Normalized]
end

---Resolve a single input token to a VIM input spec.
---@param Input string
---@return table?
local function ResolveSingleInputSpec(Input)
	local MouseButton = ResolveMouseButton(Input)
	if MouseButton ~= nil then
		return { Kind = "Mouse", Button = MouseButton }
	end

	local KeyCode = ResolveKeyCode(Input)
	if KeyCode then
		return { Kind = "Key", KeyCode = KeyCode }
	end
end

---Resolve an input string to a VIM input combo spec.
---@param Input string
---@return table?
local function ResolveInputSpec(Input)
	if not Input or Input == "" then return nil end

	local Specs = {}
	for Token in string.gmatch(tostring(Input), "[^+]+") do
		Token = TrimText(Token)
		if Token == "" then continue end

		local Spec = ResolveSingleInputSpec(Token)
		if not Spec then return nil end
		Specs[#Specs + 1] = Spec
	end

	if #Specs == 0 then return nil end
	return { Kind = "Combo", Specs = Specs }
end

---Send mouse input.
---@param Vim VirtualInputManager
---@param Button number
---@param Pressed boolean
local function SendMouseInput(Vim, Button, Pressed)
	local Position = game:GetService("UserInputService"):GetMouseLocation()
	Vim:SendMouseButtonEvent(Position.X, Position.Y, Button, Pressed, game, 0)
end

---Send a single input spec.
---@param Vim VirtualInputManager
---@param InputSpec table
---@param Pressed boolean
local function SendSingleInputSpec(Vim, InputSpec, Pressed)
	if InputSpec.Kind == "Mouse" then
		SendMouseInput(Vim, InputSpec.Button, Pressed)
		return
	end

	Vim:SendKeyEvent(Pressed, InputSpec.KeyCode, false, game)
end

---Send a combo input spec.
---@param Vim VirtualInputManager
---@param ComboSpec table
---@param Pressed boolean
local function SendComboInputSpec(Vim, ComboSpec, Pressed)
	local Specs = ComboSpec.Specs

	if Pressed then
		for Index = 1, #Specs do
			SendSingleInputSpec(Vim, Specs[Index], true)
		end
		return
	end

	for Index = #Specs, 1, -1 do
		SendSingleInputSpec(Vim, Specs[Index], false)
	end
end

---Create a VIM callback for an action.
---@param Name string
---@param InputSpec table
---@return function
local function CreateVIMCallback(Name, InputSpec)
	local Vim = game:GetService("VirtualInputManager")
	local HoldActions = {
		block = true,
		startslide = true,
		startcrouch = true,
	}
	local ReleaseActions = {
		unblock = true,
		endslide = true,
		endcrouch = true,
	}

	if HoldActions[Name] then
		return function()
			SendComboInputSpec(Vim, InputSpec, true)
		end
	end

	if ReleaseActions[Name] then
		return function()
			SendComboInputSpec(Vim, InputSpec, false)
		end
	end

	-- Tap action (parry, dodge, jump, combo inputs).
	return function()
		SendComboInputSpec(Vim, InputSpec, true)
		task.wait(0.05)
		SendComboInputSpec(Vim, InputSpec, false)
	end
end

---Call a configured remote entry.
---@param Remote Instance?
---@param Args table?
---@return boolean
local function CallConfiguredRemote(Remote, Args)
	if not Remote then return false end

	if Remote:IsA("RemoteEvent") then
		if Args and #Args > 0 then
			return pcall(Remote.FireServer, Remote, unpack(Args))
		end

		return pcall(Remote.FireServer, Remote)
	end

	if Remote:IsA("RemoteFunction") then
		if Args and #Args > 0 then
			return pcall(Remote.InvokeServer, Remote, unpack(Args))
		end

		return pcall(Remote.InvokeServer, Remote)
	end

	return false
end

---Create a block tap callback that releases block after pressing.
---@return function
local function CreateBlockTapCallback()
	return function(Remote, ...)
		local Args = { ... }
		local Success = CallConfiguredRemote(Remote, Args)

		if Success and Args[1] == "Block" and Args[2] == true then
			task.delay(0.08, function()
				CallConfiguredRemote(Remote, { Args[1], false })
			end)
		end

		return Success
	end
end

---Resolve a game dash direction from Dash remote args.
---@param Args table?
---@return string
local function ResolveDashDirection(Args)
	local VectorName = Args and Args[1]
	local Speed = tonumber(Args and Args[2]) or 0

	if VectorName == "RightVector" then
		return Speed < 0 and "A" or "D"
	end

	return Speed < 0 and "S" or "W"
end

---Check if the current game is explicitly VV.
---@return boolean
local function IsVVGame()
	return game.GameId == 2309918273
end

-- Cached VV manager refs.
local CachedCharacterManagerModule = nil
local CachedCharacterManager = nil

---Get the VV character manager module.
---@return table?
local function GetCharacterManagerModule()
	if CachedCharacterManagerModule then
		return CachedCharacterManagerModule
	end

	local ModuleOk, CharacterManagerModule = pcall(function()
		local RuntimeRequire = getfenv().require
		return RuntimeRequire(game:GetService("ReplicatedStorage"):WaitForChild("SharedModules"):WaitForChild("LocalPlayer"):WaitForChild("CharacterManager"))
	end)
	if not ModuleOk then return nil end

	CachedCharacterManagerModule = CharacterManagerModule
	return CharacterManagerModule
end

---Get a connection callback function.
---@param Connection table
---@return function?
local function GetConnectionFunction(Connection)
	local Keys = { "Function", "Callback", "Func", "callback" }
	for Index = 1, #Keys do
		local Success, Value = pcall(function()
			return Connection[Keys[Index]]
		end)
		if Success and type(Value) == "function" then
			return Value
		end
	end
end

---Find the live VV character manager from CharacterAdded connection upvalues.
---@param Character Model
---@return table?
local function FindCharacterManagerFromConnections(Character)
	if not getconnections or not debug or not debug.getupvalues then return nil end

	local Player = game:GetService("Players").LocalPlayer
	local ConnectionsOk, Connections = pcall(getconnections, Player.CharacterAdded)
	if not ConnectionsOk or type(Connections) ~= "table" then return nil end

	for Index, Connection in next, Connections do
		local Function = GetConnectionFunction(Connection)
		if not Function then continue end

		local UpvaluesOk, Upvalues = pcall(debug.getupvalues, Function)
		if not UpvaluesOk or type(Upvalues) ~= "table" then continue end

		for UpvalueIndex = 1, #Upvalues do
			local Value = Upvalues[UpvalueIndex]
			if type(Value) == "table" and rawget(Value, "Character") == Character and type(Value.Dash) == "function" then
				return Value
			end
		end
	end
end

---Find the live VV character manager object.
---@return table?
local function FindCharacterManager()
	if not IsVVGame() then return nil end

	local Player = game:GetService("Players").LocalPlayer
	local Character = Player and Player.Character
	if not Character then
		CachedCharacterManager = nil
		return nil
	end

	if CachedCharacterManager and rawget(CachedCharacterManager, "Character") == Character then
		return CachedCharacterManager
	end

	local ConnectionManager = FindCharacterManagerFromConnections(Character)
	if ConnectionManager then
		CachedCharacterManager = ConnectionManager
		return ConnectionManager
	end

	if not getgc then return nil end

	local CharacterManagerModule = GetCharacterManagerModule()
	if not CharacterManagerModule then return nil end

	for Index, Value in next, getgc(true) do
		if type(Value) ~= "table" then continue end

		local Metatable = getmetatable(Value)
		local IndexTable = type(Metatable) == "table" and rawget(Metatable, "__index") or nil
		if IndexTable == CharacterManagerModule and rawget(Value, "Character") == Character then
			CachedCharacterManager = Value
			return Value
		end
	end
end

---Create a dash callback with VV-only client movement fallback.
---@param Direction string
---@return function
local function CreateDashCallback(Direction)
	return function(Remote, ...)
		local Manager = FindCharacterManager()
		if Manager and type(Manager.Dash) == "function" then
			local Success, Err = pcall(Manager.Dash, Manager, Direction)
			if Success then return true end

			Logger.Warn("Dash callback failed: %s", tostring(Err))
		end

		local Args = { ... }
		return CallConfiguredRemote(Remote, Args)
	end
end

-- Forward declarations.
local EnabledActionsDropdown
local TriggerRemoteDropdown
local TriggerInputDropdown
local RemoteContainer
local InputContainer
local RefreshDispatchConfiguration

-- Entry state arrays.
local RemoteEntries = {}
local InputEntries = {}
local EntryUID = 0

---Collect config from all UI entries.
---@return table
local function CollectConfig()
	local Config = { remotes = {}, inputs = {} }

	for Index, Entry in next, RemoteEntries do
		if Entry.Deleted then continue end
		local Args = {}
		for I, ArgInput in next, Entry.ArgInputs do
			-- Skip deleted extra args.
			if I > 1 then
				local Wrapper = Entry.ArgWrappers[I - 1]
				if Wrapper and not Wrapper.Visible.Value then continue end
			end
			local V = ArgInput.Value
			if V and V ~= "" then
				Args[#Args + 1] = V
			end
		end
		Config.remotes[#Config.remotes + 1] = {
			action = Entry.Action,
			path = Entry.PathInput.Value,
			args = Args,
		}
	end

	for Index, Entry in next, InputEntries do
		if Entry.Deleted then continue end
		Config.inputs[#Config.inputs + 1] = {
			action = Entry.Action,
			key = Entry.KeyInput.Value,
		}
	end

	return Config
end

---Check if a dispatch config entry has an actual path or input key.
---@param Entry table
---@param ValueKey string
---@return boolean
local function HasDispatchValue(Entry, ValueKey)
	local Value = Entry and Entry[ValueKey]
	if typeof(Value) == "table" and Value.Value ~= nil then
		Value = Value.Value
	end

	return Value ~= nil and tostring(Value) ~= ""
end

---Add a timing action type once.
---@param Values table
---@param Seen table
---@param ActionType string
local function AddTimingActionType(Values, Seen, ActionType)
	if Seen[ActionType] then return end

	Seen[ActionType] = true
	Values[#Values + 1] = ActionType
end

---Build timing action types from configured remotes and inputs.
---@return table
local function BuildTimingActionTypes()
	local Config = CollectConfig()
	local InternalActions = {}
	local InternalLabels = {}

	local function RegisterAction(Entry, ValueKey)
		if not Entry.action or Entry.action == "" or not HasDispatchValue(Entry, ValueKey) then return end

		local InternalName = GetInternalName(Entry.action)
		InternalActions[InternalName] = true
		InternalLabels[InternalName] = FormatActionDisplay(Entry.action)
	end

	for Index, Entry in next, Config.remotes do
		RegisterAction(Entry, "path")
	end

	for Index, Entry in next, Config.inputs do
		RegisterAction(Entry, "key")
	end

	local Values = {}
	local Seen = {}

	if InternalActions.parry then
		AddTimingActionType(Values, Seen, "Parry")
	end

	if InternalActions.dodge then
		AddTimingActionType(Values, Seen, "Dodge")
		AddTimingActionType(Values, Seen, "Forced Full Dodge")
	elseif InternalActions.forcedfulldodge then
		AddTimingActionType(Values, Seen, "Forced Full Dodge")
	end

	if InternalActions.jump then
		AddTimingActionType(Values, Seen, "Jump")
	end

	if InternalActions.teleportup then
		AddTimingActionType(Values, Seen, "Teleport Up")
	end

	if InternalActions.block or InternalActions.unblock then
		AddTimingActionType(Values, Seen, "Start Block")
		AddTimingActionType(Values, Seen, "End Block")
	end

	if InternalActions.slide or InternalActions.startslide or InternalActions.endslide then
		AddTimingActionType(Values, Seen, "Start Slide")
		AddTimingActionType(Values, Seen, "End Slide")
	end

	if InternalActions.crouch or InternalActions.startcrouch or InternalActions.endcrouch then
		AddTimingActionType(Values, Seen, "Start Crouch")
		AddTimingActionType(Values, Seen, "End Crouch")
	end

	if InternalActions.flashstep then
		AddTimingActionType(Values, Seen, "FlashStep")
	end

	local CoveredInternalActions = {
		parry = true,
		dodge = true,
		dodgecancel = true,
		forcedfulldodge = true,
		jump = true,
		teleportup = true,
		block = true,
		unblock = true,
		slide = true,
		startslide = true,
		endslide = true,
		crouch = true,
		startcrouch = true,
		endcrouch = true,
		flashstep = true,
	}

	local ExtraValues = {}
	for InternalName, Label in next, InternalLabels do
		if not CoveredInternalActions[InternalName] and Label ~= "" then
			ExtraValues[#ExtraValues + 1] = Label
		end
	end
	table.sort(ExtraValues)

	for Index = 1, #ExtraValues do
		AddTimingActionType(Values, Seen, ExtraValues[Index])
	end

	if #Values == 0 then
		Values[1] = "Parry"
	end

	return Values
end

---Refresh globally configured builder action types.
local function RefreshTimingActionTypes()
	local Values = BuildTimingActionTypes()
	Environment.__EP_TimingActionTypes = Values

	local RefreshBuilder = Environment.__EP_RefreshBuilderActionTypes
	if type(RefreshBuilder) == "function" then
		pcall(RefreshBuilder, Values)
	end
end

---Update the enabled actions filter dropdown based on current entries.
local function UpdateFilterDropdown()
	RefreshTimingActionTypes()

	if not EnabledActionsDropdown then return end

	local Cats = {}
	for Index, Entry in next, RemoteEntries do
		if not Entry.Deleted and Entry.Action ~= "" then
			Cats[GetCategory(Entry.Action)] = true
		end
	end
	for Index, Entry in next, InputEntries do
		if not Entry.Deleted and Entry.Action ~= "" then
			Cats[GetCategory(Entry.Action)] = true
		end
	end

	local Values = {}
	for Cat in next, Cats do
		Values[#Values + 1] = Cat
	end
	table.sort(Values)

	if #Values == 0 then return end

	-- Build set of previously selected categories.
	local OldSelected = {}
	local OldValue = EnabledActionsDropdown.Value
	if OldValue then
		for Index, V in next, OldValue do
			OldSelected[V] = true
		end
	end

	EnabledActionsDropdown:Refresh(Values)

	-- Enable newly added categories by default, preserve existing selections.
	local NewValue = {}
	for Index, V in next, Values do
		if OldSelected[V] ~= nil then
			-- Previously existed: keep its selected state.
			if OldSelected[V] then
				NewValue[#NewValue + 1] = V
			end
		else
			-- Newly added: enable by default.
			NewValue[#NewValue + 1] = V
		end
	end
	EnabledActionsDropdown:Set(NewValue)

	-- Refresh trigger dropdowns with unique actions from their respective entries.
	if TriggerRemoteDropdown then
		local Actions = {}
		local Seen = {}
		for Index, Entry in next, RemoteEntries do
			if not Entry.Deleted and Entry.Action ~= "" and not Seen[Entry.Action] then
				Seen[Entry.Action] = true
				Actions[#Actions + 1] = Entry.Action
			end
		end
		if #Actions > 0 then
			local Old = TriggerRemoteDropdown.Value
			TriggerRemoteDropdown:Refresh(Actions)
			local Valid = false
			for Index, V in next, Actions do
				if V == Old then Valid = true break end
			end
			TriggerRemoteDropdown:Set(Valid and Old or Actions[1])
		end
	end

	if TriggerInputDropdown then
		local Actions = {}
		local Seen = {}
		for Index, Entry in next, InputEntries do
			if not Entry.Deleted and Entry.Action ~= "" and not Seen[Entry.Action] then
				Seen[Entry.Action] = true
				Actions[#Actions + 1] = Entry.Action
			end
		end
		if #Actions > 0 then
			local Old = TriggerInputDropdown.Value
			TriggerInputDropdown:Refresh(Actions)
			local Valid = false
			for Index, V in next, Actions do
				if V == Old then Valid = true break end
			end
			TriggerInputDropdown:Set(Valid and Old or Actions[1])
		end
	end
end

---Create a remote entry in the given container.
---@param Container table Parent depbox.
---@param Action string Action type (PascalCase).
---@param Path string Remote path.
---@param Args table Array of arg strings.
---@return table
local function CreateRemoteEntry(Container, Action, Path, Args)
	EntryUID = EntryUID + 1
	local Uid = EntryUID

	local Entry = {
		Action = Action or "Parry",
		Deleted = false,
		ArgInputs = {},
		ArgWrappers = {},
	}

	-- Virtual toggle for visibility.
	local Visible = { Type = "Toggle", Value = true }
	local Depbox = Container:DependencyBox()
	Depbox:SetupDependencies({ { Visible, true } })
	Entry.Depbox = Depbox
	Entry.Visible = Visible

	-- Divider (inside depbox so it hides with the entry).
	Depbox:Divider()

	-- Action input.
	local ActionInput = Depbox:Textbox({
		Flag = "EP_RE_Action_" .. Uid,
		Placeholder = "Action",
		Default = Entry.Action,
		Callback = function(Value)
			Entry.Action = Value
			UpdateFilterDropdown()
		end,
	})
	Entry.ActionInput = ActionInput

	-- Remote path input.
	local PathInput = Depbox:Textbox({
		Flag = "EP_RE_Path_" .. Uid,
		Placeholder = "Remote Path",
		Default = Path or "",
	})
	Entry.PathInput = PathInput

	-- Args container (sub-depbox so new args stay above buttons).
	local ArgsContainer = Depbox:DependencyBox()
	local ArgsVisible = { Type = "Toggle", Value = true }
	ArgsContainer:SetupDependencies({ { ArgsVisible, true } })
	Entry.ArgsContainer = ArgsContainer

	-- Helper to add an extra arg with its own delete button.
	local function AddExtraArg(DefaultValue)
		EntryUID = EntryUID + 1
		local ArgWrapper = ArgsContainer:DependencyBox()
		local WrapperVisible = { Type = "Toggle", Value = true }
		ArgWrapper:SetupDependencies({ { WrapperVisible, true } })

		local ExtraArg = ArgWrapper:Textbox({
			Flag = "EP_RE_Arg_" .. EntryUID,
			Placeholder = "Arg",
			Default = DefaultValue or "",
		})

		ArgWrapper:Button({
			Name = "Delete Arg",
			Callback = function()
				WrapperVisible.Value = false
			end,
		})

		Entry.ArgInputs[#Entry.ArgInputs + 1] = ExtraArg
		Entry.ArgWrappers[#Entry.ArgWrappers + 1] = { Depbox = ArgWrapper, Visible = WrapperVisible }
	end

	-- First arg input (always visible).
	local BaseArgs = Args or {}
	EntryUID = EntryUID + 1
	local ArgInput = ArgsContainer:Textbox({
		Flag = "EP_RE_Arg_" .. EntryUID,
		Placeholder = "Arg",
		Default = BaseArgs[1] or "",
	})
	Entry.ArgInputs[1] = ArgInput

	-- Restore extra arg inputs.
	for I = 2, #BaseArgs do
		AddExtraArg(BaseArgs[I])
	end

	-- Add Arg + Delete entry buttons (side by side).
	local AddArgBtn = Depbox:Button({
		Name = "Add Arg",
		Callback = function()
			AddExtraArg("")
		end,
	})

	AddArgBtn:AddButton({
		Name = "Delete",
		Callback = function()
			Entry.Deleted = true
			Visible.Value = false
			UpdateFilterDropdown()
		end,
	})

	RemoteEntries[#RemoteEntries + 1] = Entry
	return Entry
end

---Create an input entry in the given container.
---@param Container table Parent depbox.
---@param Action string Action type (PascalCase).
---@param Key string Key name.
---@return table
local function CreateInputEntry(Container, Action, Key)
	EntryUID = EntryUID + 1
	local Uid = EntryUID

	local Entry = {
		Action = Action or "Parry",
		Deleted = false,
	}

	-- Virtual toggle for visibility.
	local Visible = { Type = "Toggle", Value = true }
	local Depbox = Container:DependencyBox()
	Depbox:SetupDependencies({ { Visible, true } })

	-- Divider (inside depbox so it hides with the entry).
	Depbox:Divider()
	Entry.Depbox = Depbox
	Entry.Visible = Visible

	-- Action input (no Flag — saved via remotes.json, not Mentality config).
	local ActionInput = Depbox:Textbox({
		Placeholder = "Action",
		Default = Entry.Action,
		Callback = function(Value)
			Entry.Action = Value
			UpdateFilterDropdown()
		end,
	})
	Entry.ActionInput = ActionInput

	-- Key input (no Flag — saved via remotes.json, not Mentality config).
	local KeyInput = Depbox:Textbox({
		Placeholder = "Key",
		Default = Key or "",
	})
	Entry.KeyInput = KeyInput

	-- Delete button.
	Depbox:Button({
		Name = "Delete",
		Callback = function()
			Entry.Deleted = true
			Visible.Value = false
			UpdateFilterDropdown()
		end,
	})

	InputEntries[#InputEntries + 1] = Entry
	return Entry
end

---Hide dispatch entries from the UI.
---@param Entries table
local function HideDispatchEntries(Entries)
	for Index, Entry in next, Entries do
		Entry.Deleted = true
		if Entry.Visible then
			Entry.Visible.Value = false
		end

		if Entry.Depbox and Entry.Depbox.SetVisible then
			Entry.Depbox:SetVisible(false)
		end
	end
end

---Reload dispatch UI and active configuration from disk.
---@return number
---@return number
local function ReloadDispatchConfigurationFromDisk()
	if not RemoteContainer or not InputContainer then
		return RefreshDispatchConfiguration()
	end

	HideDispatchEntries(RemoteEntries)
	HideDispatchEntries(InputEntries)

	RemoteEntries = {}
	InputEntries = {}

	local SavedConfig = LoadConfig()

	if #SavedConfig.remotes > 0 then
		for Index, Saved in next, SavedConfig.remotes do
			CreateRemoteEntry(RemoteContainer, Saved.action, Saved.path, Saved.args)
		end
	else
		CreateRemoteEntry(RemoteContainer, "Parry", "", {})
	end

	if #SavedConfig.inputs > 0 then
		for Index, Saved in next, SavedConfig.inputs do
			CreateInputEntry(InputContainer, Saved.action, Saved.key)
		end
	else
		CreateInputEntry(InputContainer, "Parry", "")
	end

	return RefreshDispatchConfiguration()
end

---Resolve and apply all remotes and input keys.
---@return number, number
local function ApplyAll()
	local Config = CollectConfig()

	local ResolvedRemotes = {}
	local ResolvedArgs = {}
	local Callbacks = {}
	local RemoteCount = 0
	local InputCount = 0

	-- Resolve remotes.
	for Index, Entry in next, Config.remotes do
		if not Entry.action or Entry.action == "" then continue end
		local Name = GetInternalName(Entry.action)

		local Path = Entry.path
		if not Path or Path == "" then continue end

		local Remote = ResolvePath(Path)
		if not Remote then continue end

		if not ResolvedRemotes[Name] then
			ResolvedRemotes[Name] = {}
			ResolvedArgs[Name] = {}
		end

		local Idx = #ResolvedRemotes[Name] + 1
		ResolvedRemotes[Name][Idx] = Remote
		ResolvedArgs[Name][Idx] = EvaluateArgStrings(Entry.args)
		RemoteCount = RemoteCount + 1
	end

	-- Collect input keys by action.
	local InputsByAction = {}
	for Index, Entry in next, Config.inputs do
		if not Entry.action or Entry.action == "" then continue end
		local Name = GetInternalName(Entry.action)
		if not Entry.key or Entry.key == "" then continue end
		InputsByAction[Name] = Entry.key
	end

	-- Auto-link paired hold/release keys.
	local function LinkInputPair(PressName, ReleaseName)
		if not InputsByAction[PressName] and InputsByAction[ReleaseName] then
			InputsByAction[PressName] = InputsByAction[ReleaseName]
		elseif not InputsByAction[ReleaseName] and InputsByAction[PressName] then
			InputsByAction[ReleaseName] = InputsByAction[PressName]
		end
	end

	local function LinkInputAlias(SourceName, PressName, ReleaseName)
		if not InputsByAction[SourceName] then return end
		if not InputsByAction[PressName] then InputsByAction[PressName] = InputsByAction[SourceName] end
		if not InputsByAction[ReleaseName] then InputsByAction[ReleaseName] = InputsByAction[SourceName] end
	end

	LinkInputPair("block", "unblock")
	LinkInputAlias("slide", "startslide", "endslide")
	LinkInputPair("startslide", "endslide")
	LinkInputAlias("crouch", "startcrouch", "endcrouch")
	LinkInputPair("startcrouch", "endcrouch")

	if InputsByAction["dodge"] and not InputsByAction["forcedfulldodge"] then
		InputsByAction["forcedfulldodge"] = InputsByAction["dodge"]
	end

	-- Create VIM callbacks for actions without remotes.
	for Name, KeyName in next, InputsByAction do
		local RemoteList = ResolvedRemotes[Name]
		if RemoteList and #RemoteList > 0 then continue end

		local InputSpec = ResolveInputSpec(KeyName)
		if not InputSpec then continue end

		Callbacks[Name] = CreateVIMCallback(Name, InputSpec)
		InputCount = InputCount + 1
	end

	if ResolvedRemotes.parry and #ResolvedRemotes.parry > 0 then
		Callbacks.parry = CreateBlockTapCallback()
	end

	if ResolvedRemotes.dodge and #ResolvedRemotes.dodge > 0 then
		local DashArgs = ResolvedArgs.dodge and ResolvedArgs.dodge[1]
		local DashCallback = CreateDashCallback(ResolveDashDirection(DashArgs))
		Callbacks.dodge = DashCallback
		Callbacks.forcedfulldodge = Callbacks.forcedfulldodge or DashCallback
	end

	Remotes.Configure(ResolvedRemotes, Callbacks, ResolvedArgs)
	return RemoteCount, InputCount
end

---Refresh action filters and apply current dispatch config.
---@return number, number
function RefreshDispatchConfiguration()
	UpdateFilterDropdown()
	return ApplyAll()
end

