-- ─── Intro Animation ────────────────────────────────────────────────────────────
if not IsSilentModeSuppressed() and not SkipIntroAnimation then
	local TweenService = game:GetService("TweenService")
	local Lighting = game:GetService("Lighting")
	local TextService = game:GetService("TextService")

	local IntroFont = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
	local IntroTextSize = 150
	local IntroHold = 1.5

	local function IntroTween(Inst, Time, Props, Style, Dir)
		local Ti = TweenInfo.new(Time, Style or Enum.EasingStyle.Quint, Dir or Enum.EasingDirection.Out)
		local T = TweenService:Create(Inst, Ti, Props)
		T:Play()
		return T
	end

	local function IntroTextWidth(Text)
		local Params = Instance.new("GetTextBoundsParams")
		Params.Text = Text
		Params.Font = IntroFont
		Params.Size = IntroTextSize
		Params.Width = 10000
		return TextService:GetTextBoundsAsync(Params).X
	end

	-- Clean previous.
	pcall(function() Lighting:FindFirstChild("__EP_IntroBlur"):Destroy() end)

	-- ScreenGui.
	local IntroGui = Instance.new("ScreenGui")
	IntroGui.Name = "__EP_Intro"
	IntroGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	IntroGui.IgnoreGuiInset = true
	IntroGui.ResetOnSpawn = false
	IntroGui.DisplayOrder = 100
	pcall(function() IntroGui.Parent = game:GetService("CoreGui") end)
	if not IntroGui.Parent then IntroGui.Parent = game.Players.LocalPlayer:WaitForChild("PlayerGui") end
	pcall(function() IntroGui.Parent = gethui() end)

	-- Overlay.
	local Overlay = Instance.new("Frame")
	Overlay.BackgroundColor3 = Color3.new(0, 0, 0)
	Overlay.BackgroundTransparency = 1
	Overlay.BorderSizePixel = 0
	Overlay.Size = UDim2.new(1, 0, 1, 0)
	Overlay.ZIndex = 1
	Overlay.Parent = IntroGui

	-- Blur.
	local IntroBlur = Instance.new("BlurEffect")
	IntroBlur.Name = "__EP_IntroBlur"
	IntroBlur.Size = 0
	IntroBlur.Parent = Lighting

	-- Measure.
	local FullText = "Epiphyllum"
	local FullWidth = IntroTextWidth(FullText)
	local EWidth = IntroTextWidth("E")

	-- Word container.
	local WordContainer = Instance.new("Frame")
	WordContainer.BackgroundTransparency = 1
	WordContainer.AnchorPoint = Vector2.new(0.5, 0.5)
	WordContainer.Position = UDim2.new(0.5, 0, 0.5, 0)
	WordContainer.Size = UDim2.new(1, 0, 0, 100)
	WordContainer.ZIndex = 5
	WordContainer.Parent = IntroGui

	-- Create letter labels.
	local StartX = -FullWidth / 2
	local Cursor = StartX

	local function AddIntroGradient(Inst)
		local Grad = Instance.new("UIGradient")
		Grad.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(130, 130, 130))
		Grad.Rotation = -115
		Grad.Parent = Inst
	end

	local function CreateLetter(Ch, XOff)
		local Label = Instance.new("TextLabel")
		Label.FontFace = IntroFont
		Label.Text = Ch
		Label.TextColor3 = Color3.new(1, 1, 1)
		Label.TextSize = IntroTextSize
		Label.BackgroundTransparency = 1
		Label.BorderSizePixel = 0
		Label.Size = UDim2.new(0, IntroTextWidth(Ch), 0, IntroTextSize + 10)
		Label.AnchorPoint = Vector2.new(0, 0.5)
		Label.Position = UDim2.new(0.5, XOff, 0.5, 0)
		Label.ZIndex = 6
		Label.TextTransparency = 1
		Label.Parent = WordContainer
		AddIntroGradient(Label)
		return Label
	end

	local ELabel = CreateLetter("E", Cursor)
	local ETargetX = Cursor
	Cursor = Cursor + EWidth

	local RestLabels = {}
	for I = 1, #"piphyllum" do
		local Ch = ("piphyllum"):sub(I, I)
		local W = IntroTextWidth(Ch)
		RestLabels[#RestLabels + 1] = CreateLetter(Ch, Cursor)
		Cursor = Cursor + W
	end

	-- Initial "E" (centered, 4x scale).
	local InitE = Instance.new("TextLabel")
	InitE.FontFace = IntroFont
	InitE.Text = "E"
	InitE.TextColor3 = Color3.new(1, 1, 1)
	AddIntroGradient(InitE)
	InitE.TextSize = IntroTextSize
	InitE.BackgroundTransparency = 1
	InitE.BorderSizePixel = 0
	InitE.Size = UDim2.new(0, EWidth, 0, IntroTextSize + 10)
	InitE.AnchorPoint = Vector2.new(0.5, 0.5)
	InitE.Position = UDim2.new(0.5, 0, 0.5, 0)
	InitE.ZIndex = 8
	InitE.TextTransparency = 1
	InitE.Parent = IntroGui

	local InitEScale = Instance.new("UIScale")
	InitEScale.Scale = 4
	InitEScale.Parent = InitE

	-- Step 1: Overlay + blur.
	IntroTween(Overlay, 0.8, { BackgroundTransparency = 0.6 })
	IntroTween(IntroBlur, 1, { Size = 50 })
	task.wait(0.6)

	-- Step 2: E appears centered, shrinks from 4x to 1x.
	IntroTween(InitE, 0.45, { TextTransparency = 0 })
	IntroTween(InitEScale, 0.5, { Scale = 1 })
	task.wait(0.45)

	-- Step 3: E slides to the absolute position of its slot in the word layout.
	local ELabelPos = ELabel.AbsolutePosition
	local ELabelSize = ELabel.AbsoluteSize
	local LoaderOffset = math.abs(IntroGui.AbsolutePosition.Y)
	IntroTween(InitE, 0.35, {
		Position = UDim2.fromOffset(
			ELabelPos.X + ELabelSize.X / 2,
			ELabelPos.Y + ELabelSize.Y / 2 + LoaderOffset
		)
	})
	task.wait(0.5)

	-- Step 4: Remaining letters fly up from below.
	for I, Label in next, RestLabels do
		local TargetX = Label.Position.X.Offset
		Label.Position = UDim2.new(0.5, TargetX, 0.5, 40)
		task.delay((I - 1) * 0.03, function()
			IntroTween(Label, 0.5, { TextTransparency = 0, Position = UDim2.new(0.5, TargetX, 0.5, 0) })
		end)
	end
	ELabel.TextTransparency = 0
	task.wait(0.6)

	-- Step 5: Hold.
	task.wait(IntroHold)

	-- Step 6: Fade out text first, then blur/overlay.
	IntroTween(InitE, 1.2, { TextTransparency = 1 })
	IntroTween(ELabel, 1.2, { TextTransparency = 1 })
	for Index, Label in next, RestLabels do IntroTween(Label, 1.2, { TextTransparency = 1 }) end
	task.wait(1.2)

	-- Start blur/overlay fade (deferred, don't block loading).
	IntroTween(IntroBlur, 1.5, { Size = 0 })
	IntroTween(Overlay, 1.5, { BackgroundTransparency = 1 })
	task.delay(1.5, function()
		IntroGui:Destroy()
		IntroBlur:Destroy()
	end)
end

