	Name = "Auto Defense",
	Flag = "EP_AutoDefenseKeybind",
	Default = nil,
	Callback = function(Toggled, FromPress)
		if not FromPress then
			if AutoDefenseKeybindObj and AutoDefenseKeybindObj.SyncToggled then
				AutoDefenseKeybindObj:SyncToggled(AutoDefenseSection.IsActive)
			end
			return
		end

		if AutoDefenseSection.IsActive ~= Toggled then
			AutoDefenseSection:ToggleBackground(true)
		end

		if AutoDefenseSection.IsActive ~= Toggled then return false end
	end,
})

