-- Trigger Remote test button.
TriggerRemoteDropdown = RemotesSection:Dropdown({
	Name = "Trigger Action",
	Flag = "EP_TriggerRemoteAction",
	Items = { "Parry" },
	Default = "Parry",
})

RemotesSection:Button({
	Name = "Trigger Remote",
	Callback = function()
		local Action = TriggerRemoteDropdown.Value
		if not Action or Action == "" then return end
		local Name = GetInternalName(Action)
		local Config = CollectConfig()

		for Index, Entry in next, Config.remotes do
			if not Entry.action or Entry.action == "" then continue end
			if GetInternalName(Entry.action) ~= Name then continue end

			local Remote = ResolvePath(Entry.path)
			if not Remote then continue end

			local Args = EvaluateArgStrings(Entry.args)
			local Success, Err
			if Args and #Args > 0 then
				Success, Err = pcall(Remote.FireServer, Remote, unpack(Args))
			else
				Success, Err = pcall(Remote.FireServer, Remote)
			end

			if Success then
				Library:Notification({ Title = "Notice", Description = string.format("Fired remote for '%s'.", Action), Duration = 2 })
			else
				Library:Notification({ Title = "Error", Description = string.format("Failed to fire '%s': %s", Action, tostring(Err)), Duration = 3 })
			end
			return
		end

		Library:Notification({ Title = "Error", Description = string.format("No remote configured for '%s'.", Action), Duration = 3 })
	end,
})

