		local Name = GetInternalName(Action)
		local Config = CollectConfig()

		for Index, Entry in next, Config.inputs do
			if not Entry.action or Entry.action == "" then continue end
			if GetInternalName(Entry.action) ~= Name then continue end
			if not Entry.key or Entry.key == "" then continue end

			local InputSpec = ResolveInputSpec(Entry.key)
			if not InputSpec then continue end

			local Callback = CreateVIMCallback(Name, InputSpec)
			Callback()
			Library:Notification({ Title = "Notice", Description = string.format("Triggered input '%s' (key: %s).", Action, Entry.key), Duration = 2 })
			return
		end

		Library:Notification({ Title = "Error", Description = string.format("No input configured for '%s'.", Action), Duration = 3 })
	end,
})
end -- scope block

