-- Sync section toggle to music playback and flag persistence.
Library.Flags["EP_MusicEnabled"] = MusicEnabled
local OrigMusicToggle = MusicSection.ToggleBackground
local function SyncMusicEnabledState()
	MusicEnabled = MusicSection.IsActive
	Library.Flags["EP_MusicEnabled"] = MusicEnabled
	SetMarkerFile(
		MusicDisabledMarkerFile,
		not MusicEnabled,
		"Hello, if you're reading this, that means Epiphyllum music is disabled. Deleting this file will let music play on startup."
	)

	if MusicEnabled and not IsSilentModeSuppressed() then
		ResumeMusic()
	else
		PauseMusic()
	end
end

MusicSection.ToggleBackground = function(self, Force)
	OrigMusicToggle(self, Force)
	SyncMusicEnabledState()
end

Library.SetFlags["EP_MusicEnabled"] = function(Value)
	if Value ~= MusicSection.IsActive then
		MusicSection:ToggleBackground(true)
	else
		SyncMusicEnabledState()
	end
end

if MusicSection.IsActive ~= MusicEnabled then
	MusicSection:ToggleBackground(true)
else
	SyncMusicEnabledState()
end

