-- Forward declarations for callbacks that reference later-created objects.
local Watermark
local WatermarkReady = false

---Apply silent-mode controlled UI visibility.
do -- scope block: release locals at end to stay under Luau's 200-register chunk limit
local function ApplySilentModeUi()
	local Suppressed = IsSilentModeSuppressed()

	if Watermark then
		if Suppressed then
			Watermark:SetVisibility(false)
			WatermarkReady = false
		else
			WatermarkReady = Library.Flags["EP_ShowWatermark"] ~= false
			if WatermarkReady then
				Watermark:PositionAboveWindow(Window)
				Watermark:SetVisibility(true)
			else
				Watermark:SetVisibility(false)
			end
		end
	end

	if KeybindList then
		KeybindList:SetVisibility(not Suppressed and Library.Flags["EP_ShowKeybindList"] ~= false)
	end

	InfoLogger.Visible(not Suppressed and Library.Flags["EP_ShowInfoLogger"] == true)
	AnimationVisualizer.Visible(not Suppressed and Library.Flags["EP_ShowAnimationVisualizer"] == true)
end

---Apply silent mode state.
---@param Value boolean
local function SetSilentMode(Value)
	SilentMode = Value == true
	if not SilentMode or Window.IsOpen then
		SilentModeRevealed = true
	else
		SilentModeRevealed = false
	end
	SyncSilentModeGlobals()
	SetMarkerFile(
		SilentMarkerFile,
		SilentMode,
		"Hello, if you're reading this, that means you have Epiphyllum silent mode turned on. Deleting this file will turn it off."
	)

	ApplySilentModeUi()

	if IsSilentModeSuppressed() then
		PauseMusic()
	elseif MusicSection.IsActive then
		ResumeMusic()
	end
end

---Apply skip intro animation state.
---@param Value boolean
local function SetSkipIntroAnimation(Value)
	SkipIntroAnimation = Value == true
	getgenv().EpiphyllumSkipIntroAnimation = SkipIntroAnimation
	SetMarkerFile(
		SkipIntroMarkerFile,
		SkipIntroAnimation,
		"Hello, if you're reading this, that means Epiphyllum will skip the intro animation. Deleting this file will turn it back on."
	)
end

---Apply show menu on launch state.
---@param Value boolean
local function SetShowMenuOnLaunch(Value)
	ShowMenuOnLaunch = Value == true
	Library.Flags["EP_ShowMenuOnLaunch"] = ShowMenuOnLaunch
	SyncShowMenuOnLaunchGlobal()
end

