local MenuKeybindObj = MenuSection:Keybind({
	Name = "Menu",
	Flag = "EP_MenuKeybind",
	Default = Enum.KeyCode.LeftAlt,
	InitialToggled = Window and Window.IsOpen == true,
	Callback = function(Toggled)
		if not Window or not Window.SetOpen then return false end

		-- Defer so the library menu keybind cannot immediately undo this state.
		task.defer(function()
			if Window and Window.SetOpen then
				Window:SetOpen(Toggled)
			end
		end)
	end,
})

-- Sync keybind state when window is opened/closed externally (minimize button, etc).
task.defer(function()
	if Window and Window.OnStateChanged then
		Window:OnStateChanged(function(IsOpen)
			if IsOpen and IsSilentModeSuppressed() then
				SilentModeRevealed = true
				SyncSilentModeGlobals()
				ApplySilentModeUi()
			end

			if MenuKeybindObj.Toggled ~= IsOpen then
				MenuKeybindObj:SyncToggled(IsOpen)
			end
		end)
	end
end)

