Watermark = Library:Watermark(WatermarkTitle)
Watermark:SetVisibility(false)

---Format current date time text.
---@param AnimateSeparator boolean?
---@return string
local function FormatDateTime(AnimateSeparator)
	local Separator = ":"
	if AnimateSeparator then
		Separator = math.floor(os.clock() * 2) % 2 == 0 and ":" or " "
	end

	return os.date("%I") .. Separator .. os.date("%M %p, %A, %d/%m/%Y")
end

-- Update watermark with ping/fps.
local LastWatermarkUpdate = os.clock()
RunService.RenderStepped:Connect(function()
	if not WatermarkReady then return end
	if os.clock() - LastWatermarkUpdate <= 0.5 then
		return
	end
	LastWatermarkUpdate = os.clock()

	local NetworkStats = Stats:FindFirstChild("Network")
	local WorkspaceStats = Stats:FindFirstChild("Workspace")
	local ServerStats = NetworkStats and NetworkStats:FindFirstChild("ServerStatsItem") or nil
	local PingData = ServerStats and ServerStats:FindFirstChild("Data Ping") or nil
	local HeartbeatData = WorkspaceStats and WorkspaceStats:FindFirstChild("Heartbeat") or nil

	local Ping = PingData and PingData:GetValue() or 0.0
	local Fps = HeartbeatData and HeartbeatData:GetValue() or 0.0

	Watermark:SetText(string.format("%s | %.0fms | %.0ffps | %s", WatermarkTitle, Ping, Fps, FormatDateTime(true)))
end)

-- Initialize window.
LoadAutoloadConfig()
Window:Init()
getgenv().EpiphyllumLaunchMenuLocked = false

if not IsSilentModeSuppressed() and ShowMenuOnLaunch then
	Window:SetOpen(true)
else
	Window:SetOpen(false)
end

-- Position watermark above window (handles visibility internally).
if not IsSilentModeSuppressed() and Library.Flags["EP_ShowWatermark"] ~= false then
	Watermark:PositionAboveWindow(Window)
	WatermarkReady = true
end

-- Hello notification.
if not IsSilentModeSuppressed() then
	Library:Notification({
		Title = string.format("Welcome, %s.", game.Players.LocalPlayer.DisplayName),
		Description = string.format("Session started at %s.", FormatDateTime()),
		Duration = 5,
	})
end
end)
return __bundle_require("__root")
